class UiManagerR:
    """
    Gerencia a interface do usuário, interagindo com um QTreeView para listar e gerenciar camadas de rasters no QGIS.
    """
    def __init__(self, iface, dialog):
        """
        Inicializa a instância da classe UiManagerO, responsável por gerenciar a interface do usuário
        que interage com um QTreeView para listar e gerenciar camadas de rasters no QGIS.

        :param iface: Interface do QGIS para interagir com o ambiente.
        :param dialog: Diálogo ou janela que esta classe gerenciará.

        Funções e Ações Desenvolvidas:
        - Configuração inicial das variáveis de instância.
        - Associação do modelo de dados com o QTreeView.
        - Inicialização da configuração do QTreeView.
        - Seleção automática da última camada no QTreeView.
        - Conexão dos sinais do QGIS e da interface do usuário com os métodos correspondentes.
        """
        # Salva as referências para a interface do QGIS e o diálogo fornecidos
        self.iface = iface
        self.dlg = dialog

        # Mantém referência da última mensagem exibida por este módulo.
        self._mensagem_atual = None

        # Mantém vivas as janelas 3D abertas, organizadas pelo ID da camada raster.
        self._visualizadores_raster_3d = {}

        # Aplica estilos CSS para aprimorar a interação visual com os itens do QTreeView
        self.dlg.treeViewListaRaster.setStyleSheet("""
            QTreeView::item:hover:!selected {
                background-color: #def2fc;
            }
            QTreeView::item:selected {
            }""")

        # Cria e configura o modelo de dados para o QTreeView
        self.treeViewModel = QStandardItemModel()
        self.dlg.treeViewListaRaster.setModel(self.treeViewModel)

        # Atualiza a visualização da lista de camadas no QTreeView
        self.atualizar_treeView_lista_raster()

        # Chama atualização dos botões após toda modificação
        self.atualizar_estado_botoes()

        # Adiciona o filtro de eventos ao treeView
        self.tree_view_event_filter = TreeViewEventFilter(self)
        self.dlg.treeViewListaRaster.viewport().installEventFilter(self.tree_view_event_filter)

        # Inicia a conexão de sinais para tratar a mudança de nome das camadas no projeto
        self.connect_name_changed_signals()

        # Conecta os sinais do QGIS e da interface do usuário para sincronizar ações e eventos
        self.connect_signals()

    def tr(self, message):
        """
        Traduz textos deste diálogo.
        O contexto precisa ser estável para o Qt Linguist encontrar as traduções.
        """
        return QCoreApplication.translate("UiManagerR", message)

    def connect_signals(self):
        """
        Conecta os sinais do QGIS e do QTreeView para sincronizar a interface com o estado atual do projeto.
        Este método garante que mudanças no ambiente do QGIS se reflitam na interface do usuário e que ações na
        interface desencadeiem reações apropriadas no QGIS.

        Funções e Ações Desenvolvidas:
        - Conexão com sinais de adição e remoção de camadas para atualizar a visualização da árvore.
        - Sincronização do modelo do QTreeView com mudanças de seleção e propriedades das camadas no QGIS.
        - Tratamento da mudança de nome das camadas para manter consistência entre a interface e o estado interno.
        """
        # Conecta sinais do QGIS para lidar com a adição e remoção de camadas no projeto
        self._tree_sync_depth = getattr(self, "_tree_sync_depth", 0)

        QgsProject.instance().layersAdded.connect(self.layers_added)

        try:
            self.treeViewModel.itemChanged.disconnect(self.on_item_changed)
        except TypeError:
            pass  # nosec B110
        # self.treeViewModel.itemChanged.connect(self.on_item_changed)

        root = QgsProject.instance().layerTreeRoot()
        try:
            root.visibilityChanged.connect(
                self._on_any_layer_tree_visibility_changed,
                type=Qt.ConnectionType.UniqueConnection)
        except TypeError:
            try:
                root.visibilityChanged.connect(self._on_any_layer_tree_visibility_changed)
            except Exception:
                pass  # nosec B110

        # Conecta o evento de mudança em um item do QTreeView para atualizar a visibilidade da camada no QGIS
        self.treeViewModel.itemChanged.connect(self.on_item_changed)

        # Sincroniza o estado das camadas no QGIS com o checkbox do QTreeView sempre que as camadas do mapa mudam
        self.iface.mapCanvas().layersChanged.connect(self.sync_from_qgis_to_treeview)

        # Conecta mudanças na seleção do QTreeView para atualizar a camada ativa no QGIS
        self.dlg.treeViewListaRaster.selectionModel().selectionChanged.connect(self.on_treeview_selection_changed)

        # Sincroniza a seleção no QGIS com a seleção no QTreeView quando a camada ativa no QGIS muda
        self.iface.currentLayerChanged.connect(self.on_current_layer_changed)

        # Define e aplica um delegado personalizado para customização da exibição de itens no QTreeView
        self.dlg.treeViewListaRaster.setItemDelegate(CustomDelegate(self.dlg.treeViewListaRaster))

        # Configura a política de menu de contexto para permitir menus personalizados em cliques com o botão direito
        self.dlg.treeViewListaRaster.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.dlg.treeViewListaRaster.customContextMenuRequested.connect(self.open_context_menu)

        # Conecte o botão pushButtonRasterKML à função export_raster_to_kml
        self.dlg.pushButtonRasterKML.clicked.connect(self.export_raster_to_kml)

        # Conecte o botão pushButtonRasterDXF à função export_raster_to_dxf
        self.dlg.pushButtonRasterDXF.clicked.connect(self.exportar_raster_dxf)

        # Conectando o botão pushButtonFecharR à função que fecha o diálogo
        self.dlg.pushButtonFecharR.clicked.connect(self.close_dialog)

        # Conecta para abrir o Qgis2threejs 
        self.dlg.pushButton3DRaster.clicked.connect(self.abrir_visualizador_raster_3d)

        # seleção via mouse (funciona mesmo com 1 raster)
        self.dlg.treeViewListaRaster.clicked.connect(lambda _: self.on_treeview_selection_changed(None, None))

        # Ação de controle ao remover Camadas de Rasters
        QgsProject.instance().layersRemoved.connect(self.on_layers_removed)

        # Conecta o botão para Zoom
        self.dlg.pushButtonVisualizarR.clicked.connect(self.visualizar_raster_selecionado)

        # Conectar o botão de renomear à função de renomear a camada
        self.dlg.pushButtonRenomeR.clicked.connect(self.renomear_camada_selecionada)

        # Conectar o botão de deletar à função de remover a camada
        self.dlg.pushButtonDelR.clicked.connect(self.remover_camada_selecionada)

        # Conectar o botão de salvar o raster
        self.dlg.pushButtonSalvarRaster.clicked.connect(self.salvar_raster_selecionado)

        # Conecta o botão de reprojetar
        self.dlg.pushButtonReprojetarR.clicked.connect(self.reprojetar_raster)

        # Conectar para clonar a camada
        self.dlg.pushButtonClonarRaster.clicked.connect(self.clonar_raster_selecionado)

        # Abrir diálogo de adição de camadas de imagens
        self.dlg.pushButtonAbrirR.clicked.connect(self.abrir_imagem_raster)

        # Salvar múltiplos rasters
        self.dlg.pushButtonSalvaMultiplosR.clicked.connect(self.abrir_salvar_multiplos_rasters)

    def abrir_imagem_raster(self):
        """
        Abre um diálogo para selecionar uma imagem raster
        e adiciona a camada ao projeto QGIS.
        """
        filtros = ";;".join([
            f"{self.tr('Imagens Raster')} (*.tif *.tiff *.asc *.jpg *.jpeg *.png)",
            f"{self.tr('Todos os Arquivos')} (*)"])

        file_path, _ = QFileDialog.getOpenFileName(self.dlg, self.tr("Abrir Imagem Raster"), "", filtros)

        if not file_path:
            return

        nome_camada = os.path.splitext(os.path.basename(file_path))[0]
        layer = QgsRasterLayer(file_path, nome_camada)

        if not layer.isValid():
            self.mostrar_mensagem(self.tr(
                    "Falha ao carregar a imagem raster.\n"
                    "Verifique se o formato é suportado."), "Erro")
            return

        QgsProject.instance().addMapLayer(layer)

        self.mostrar_mensagem(self.tr("Imagem raster '{nome_camada}' adicionada com sucesso!").format(nome_camada=nome_camada), "Sucesso")

    def abrir_salvar_multiplos_rasters(self):
        """
        Abre um diálogo com:
        - "Salvar todas as Camadas" (default)
        - "Salvar apenas as Camadas Visíveis"

        Ao confirmar (OK):
        - pede uma pasta (lembra via QSettings)
        - salva as camadas conforme a opção
        - mostra barra de progresso contando arquivos
        """
        dlg, rb_todas, rb_visiveis = self._criar_dialogo_salvar_multiplos_rasters()
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return

        apenas_visiveis = rb_visiveis.isChecked()

        layers = self._coletar_camadas_raster_treeview(apenas_visiveis=apenas_visiveis)
        if not layers:
            self.mostrar_mensagem(self.tr("Nenhuma camada raster para salvar."), "Aviso")
            return

        pasta = self._selecionar_pasta_saida_batch()
        if not pasta:
            return

        progressBar, progressMsg = self.iniciar_progress_bar(len(layers))

        ok_count = 0
        falhas = []

        for i, layer in enumerate(layers, start=1):
            try:
                path_saida = self._gerar_caminho_saida_unico(pasta, layer.name(), ext=".tif")

                # Local vs serviço
                if layer.providerType().lower() in ("wms", "xyz", "arcgismapserver", "arcgisfeatureserver"):
                    ok = self._salvar_raster_servico_renderizado(layer, path_saida)
                else:
                    ok = self._salvar_raster_bruto(layer, path_saida)

                if ok:
                    ok_count += 1
                else:
                    falhas.append(layer.name())

            except Exception as e:
                falhas.append(f"{layer.name()} ({e})")

            progressBar.setValue(i)
            QCoreApplication.processEvents()  # mantém UI “respirando”

        # remove o widget de progresso (sem limpar toda a messageBar)
        try:
            self.iface.messageBar().popWidget(progressMsg)
        except Exception:
            pass  # nosec B110

        if falhas:
            self.mostrar_mensagem(self.tr("Salvamento concluído com falhas: {ok_count}/{total}.\nFalharam: {falhas}{sufixo}").format(ok_count=ok_count, total=len(layers), falhas=", ".join(falhas[:8]), sufixo="..." if len(falhas) > 8 else ""), "Erro", duracao=3, caminho_pasta=pasta)
        else:
            self.mostrar_mensagem(self.tr("Salvamento concluído: {ok_count}/{total} arquivos.").format(ok_count=ok_count, total=len(layers)), "Sucesso", duracao=3, caminho_pasta=pasta)

    def _criar_dialogo_salvar_multiplos_rasters(self):
        """
        Cria o diálogo solicitado:
        - QFrame (Box + Raised)
        - 2 RadioButtons (um abaixo do outro)
        - Botões padrão OK/Cancelar centralizados e ocupando a largura do diálogo
        """
        dlg = QDialog(self.dlg)
        dlg.setWindowTitle(self.tr("Salvar Múltiplos Rasters"))

        layout = QVBoxLayout(dlg)

        frame = QFrame(dlg)
        frame.setFrameShape(QFrame.Shape.Box)
        frame.setFrameShadow(QFrame.Shadow.Raised)

        frame_layout = QVBoxLayout(frame)

        rb_todas = QRadioButton(self.tr("Salvar todas as Camadas"), frame)
        rb_visiveis = QRadioButton(self.tr("Salvar apenas as Camadas Visíveis"), frame)
        rb_todas.setChecked(True)

        frame_layout.addWidget(rb_todas)
        frame_layout.addWidget(rb_visiveis)

        layout.addWidget(frame)

        buttonBox = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel, dlg)

        # ✅ centraliza os botões e faz a "barra" ocupar toda a largura até as bordas do layout
        buttonBox.setCenterButtons(True)
        buttonBox.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)

        buttonBox.accepted.connect(dlg.accept)
        buttonBox.rejected.connect(dlg.reject)

        layout.addWidget(buttonBox)

        return dlg, rb_todas, rb_visiveis

    def _selecionar_pasta_saida_batch(self) -> str | None:
        """
        Abre um diálogo de pasta e guarda em QSettings a última pasta.
        Reutiliza a mesma chave 'lastDir' que você já usa em escolher_local_para_salvar().
        """
        settings = QSettings()
        lastDir = settings.value("lastDir", "")

        pasta = QFileDialog.getExistingDirectory(self.dlg, self.tr("Selecione a pasta de destino"), lastDir)
        if not pasta:
            return None

        settings.setValue("lastDir", pasta)
        return pasta

    def _coletar_camadas_raster_treeview(self, *, apenas_visiveis: bool) -> list:
        """
        Pega as camadas raster listadas no treeViewModel.
        Se 'apenas_visiveis' for True, filtra pelo checkState (visibilidade).
        """
        layers = []
        for row in range(self.treeViewModel.rowCount()):
            item = self.treeViewModel.item(row)
            if not item:
                continue

            if apenas_visiveis and item.checkState() != Qt.CheckState.Checked:
                continue

            layer_id = item.data(Qt.ItemDataRole.UserRole)
            layer = QgsProject.instance().mapLayer(layer_id)

            if isinstance(layer, QgsRasterLayer) and layer.isValid():
                layers.append(layer)

        return layers

    def _gerar_caminho_saida_unico(self, pasta: str, base_name: str, *, ext: str = ".tif") -> str:
        """
        Gera um caminho único na pasta (evita sobrescrever):
        Nome.tif, Nome_1.tif, Nome_2.tif...
        """
        safe = self._sanitizar_nome_arquivo(base_name)
        path = os.path.join(pasta, safe + ext)

        i = 1
        while os.path.exists(path):
            path = os.path.join(pasta, f"{safe}_{i}{ext}")
            i += 1

        return path

    def _sanitizar_nome_arquivo(self, name: str) -> str:
        """
        Remove caracteres ruins para nome de arquivo no Windows.
        """
        if not name:
            return "raster"
        permitido = " _-()[]{}."
        out = []
        for ch in name:
            if ch.isalnum() or ch in permitido:
                out.append(ch)
            else:
                out.append("_")
        safe = "".join(out).strip()
        return safe or "raster"

    def clonar_raster_selecionado(self):
        """
        Clona a camada raster selecionada no treeViewListaRaster, criando uma camada idêntica
        (inclusive estilo) como camada temporária/memória no QGIS.
        Não funciona para rasters de provedores (WMS, XYZ etc).
        """
        idxs = self.dlg.treeViewListaRaster.selectedIndexes()
        if not idxs:
            self.mostrar_mensagem(self.tr("Nenhuma camada selecionada."), "Aviso")
            return

        layer_id = self.treeViewModel.itemFromIndex(idxs[0]).data(Qt.ItemDataRole.UserRole)
        layer = QgsProject.instance().mapLayer(layer_id)
        if not layer or layer.type() != QgsMapLayer.LayerType.RasterLayer:
            self.mostrar_mensagem(self.tr("Selecione uma camada raster válida."), "Erro")
            return

        # Verifica se é camada de provedor (serviço online)
        provider_types_nao_clonaveis = ("wms", "xyz", "arcgismapserver", "arcgisfeatureserver")
        if layer.providerType().lower() in provider_types_nao_clonaveis:
            self.mostrar_mensagem(self.tr("Não é possível clonar rasters de provedores online (WMS, XYZ, ArcGIS, etc).\nSomente rasters locais (arquivos no disco) podem ser clonados."), "Aviso")
            return

        # Gera nome do clone
        clone_name = self.tr("{layer_name}_Clone").format(layer_name=layer.name())

        # Cria arquivo temporário VRT
        tmp_dir = tempfile.mkdtemp()
        clone_path = os.path.join(tmp_dir, f"{clone_name}.vrt")

        # Usa GDAL para gerar VRT (virtual raster)
        ds = gdal.Open(layer.source())
        if ds is None:
            self.mostrar_mensagem(self.tr("Falha ao abrir o arquivo raster original.\nVerifique se o arquivo existe e está acessível."), "Erro")
            shutil.rmtree(tmp_dir)
            return

        gdal.GetDriverByName("VRT").CreateCopy(clone_path, ds)

        # Cria nova camada raster no QGIS usando o arquivo VRT
        clone_layer = QgsRasterLayer(clone_path, clone_name, "gdal")

        if clone_layer.isValid():
            # Copia o estilo da camada original (inclui simbologia, colormap, etc.)
            clone_layer.setRenderer(layer.renderer().clone())
            clone_layer.setCrs(layer.crs())
            QgsProject.instance().addMapLayer(clone_layer)
            self.mostrar_mensagem(self.tr("Clone criado com sucesso!"), "Sucesso")
        else:
            self.mostrar_mensagem(self.tr("Erro ao criar o clone!"), "Erro")
            shutil.rmtree(tmp_dir)  # Limpa temp

    def reprojetar_raster(self):
        """
        Permite ao usuário reprojetar o raster selecionado usando o GDAL (warp/reproject),
        método Bilinear.

        Regras:
        - Se o raster não tem SRC (CRS inválido), pede para definir antes de reprojetar.
        - Remove a duplicidade de 'NODATA' no dicionário de parâmetros.
        - Define o NODATA de saída assim:
            * se o raster já tiver NODATA na banda 1, reutiliza;
            * senão, usa -9999.0 como fallback.
        """
        # Seleciona camada raster
        idxs = self.dlg.treeViewListaRaster.selectedIndexes()
        if not idxs:
            self.mostrar_mensagem(self.tr("Nenhuma camada selecionada."), "Aviso")
            return

        layer_id = self.treeViewModel.itemFromIndex(idxs[0]).data(Qt.ItemDataRole.UserRole)
        layer = QgsProject.instance().mapLayer(layer_id)
        if not layer or layer.type() != QgsMapLayer.LayerType.RasterLayer:
            self.mostrar_mensagem(self.tr("Selecione uma camada raster válida."), "Erro")
            return

        # Se a camada não tem SRC, pede para definir
        if not layer.crs().isValid():
            crs = self.selecionar_crs_dialogo(self.tr("Definir SRC para a camada"))
            if not crs:
                self.mostrar_mensagem(self.tr("SRC não definido!"), "Erro")
                return
            layer.setCrs(crs)
            self.mostrar_mensagem(self.tr("SRC definido. Agora escolha o SRC de destino."), "Informação")

        # Escolhe o SRC de destino (diálogo)
        crs_destino = self.selecionar_crs_dialogo(self.tr("Selecione o SRC de destino"))
        if not crs_destino:
            return

        # Decide NODATA de saída: usa o NODATA original (se existir); senão, -9999
        nodata_out = None
        prov = layer.dataProvider()
        try:
            # banda 1 (padrão)
            if prov and prov.sourceHasNoDataValue(1):
                v = prov.sourceNoDataValue(1)
                if v is not None:
                    nodata_out = float(v)
        except Exception:
            nodata_out = None

        if nodata_out is None:
            nodata_out = -9999.0

        # Executa o algoritmo de reprojeção GDAL (método Bilinear, RESAMPLING=1)
        params = {
            'INPUT': layer.source(),
            'SOURCE_CRS': layer.crs().authid(),
            'TARGET_CRS': crs_destino.authid(),
            'RESAMPLING': 1,  # Bilinear
            'NODATA': nodata_out,
            'TARGET_RESOLUTION': None,
            'OPTIONS': '',
            'DATA_TYPE': 0,
            'TARGET_EXTENT': None,
            'TARGET_EXTENT_CRS': None,
            'MULTITHREADING': False,
            'EXTRA': '',
            'OUTPUT': 'TEMPORARY_OUTPUT'}

        resultado = processing.run("gdal:warpreproject", params)
        output_raster = resultado.get('OUTPUT')

        if output_raster:
            nome_reprojetado = self.tr("{layer_name}_reprojetado").format(layer_name=layer.name())

            rlayer = QgsRasterLayer(output_raster, nome_reprojetado, "gdal")

            if rlayer.isValid():
                QgsProject.instance().addMapLayer(rlayer)
                self.mostrar_mensagem(self.tr("Raster reprojetado com sucesso!"), "Sucesso")
            else:
                self.mostrar_mensagem(self.tr("Falha ao carregar raster reprojetado!"), "Erro")
        else:
            self.mostrar_mensagem(self.tr("Erro na reprojeção GDAL!"), "Erro")

    def selecionar_crs_dialogo(self, titulo=None):
        """
        Abre o diálogo padrão do QGIS para seleção de SRC.
        """
        dlg = QgsProjectionSelectionDialog(self.dlg)

        dlg.setWindowTitle(titulo or self.tr("Selecionar SRC"))

        crs_atual = QgsProject.instance().crs()

        if crs_atual.isValid():
            dlg.setCrs(crs_atual)

        if dlg.exec() != QDialog.DialogCode.Accepted:
            return None

        crs = dlg.crs()

        if not crs.isValid():
            return None

        return QgsCoordinateReferenceSystem(crs)

    def salvar_raster_selecionado(self):
        """
        Salva o raster selecionado em GeoTIFF.

        Comportamento:
        - Quando o salvamento normal for possível:
            * remove a camada original do projeto;
            * adiciona o raster salvo na mesma posição;
            * mantém visibilidade e estilo;
            * usa o nome do arquivo salvo na lista de camadas.

        - Quando o arquivo estiver em uso ou for o próprio arquivo carregado:
            * salva com o sufixo "_copia";
            * mantém a camada original;
            * adiciona a cópia ao projeto;
            * usa o nome acrescido de "_copia".
        """
        idxs = self.dlg.treeViewListaRaster.selectedIndexes()
        if not idxs:
            self.mostrar_mensagem(
                self.tr("Nenhuma camada selecionada."),
                "Erro")
            return

        item = self.treeViewModel.itemFromIndex(idxs[0])
        layer_id = item.data(Qt.ItemDataRole.UserRole)
        layer = QgsProject.instance().mapLayer(layer_id)

        if not isinstance(layer, QgsRasterLayer) or not layer.isValid():
            self.mostrar_mensagem(
                self.tr("Camada raster inválida."),
                "Erro")
            return

        path_saida = self.escolher_local_para_salvar(
            layer.name() + ".tif",
            self.tr("GeoTIFF (*.tif)"))

        if not path_saida:
            return

        path_saida = os.path.abspath(path_saida)
        source_path = self._obter_caminho_local_raster(layer)

        # O nome que aparecerá no painel e no treeView será o nome do arquivo.
        nome_saida = os.path.splitext(os.path.basename(path_saida))[0]

        # Se o usuário escolheu o mesmo arquivo que está carregado no QGIS,
        # ele provavelmente estará bloqueado. Nesse caso cria uma cópia.
        salvar_como_copia = (
            source_path
            and os.path.normcase(source_path) == os.path.normcase(path_saida))

        if salvar_como_copia:
            path_saida = self._gerar_caminho_copia(path_saida)
            nome_saida = os.path.splitext(os.path.basename(path_saida))[0]

        provider_online = layer.providerType().lower() in (
            "wms",
            "xyz",
            "arcgismapserver",
            "arcgisfeatureserver")

        try:
            if provider_online:
                ok = self._salvar_raster_servico_renderizado(layer, path_saida)
            else:
                ok = self._salvar_raster_bruto(layer, path_saida)

        except PermissionError:
            ok = False
        except OSError:
            ok = False
        except Exception as e:
            self.mostrar_mensagem(self.tr("Não foi possível salvar o raster: {error}").format(error=str(e)), "Erro")
            return

        # Caso o arquivo escolhido esteja bloqueado por outro programa,
        # tenta novamente usando um novo nome com "_copia".
        if not ok and not salvar_como_copia:
            path_copia = self._gerar_caminho_copia(path_saida)
            nome_copia = os.path.splitext(
                os.path.basename(path_copia))[0]

            try:
                if provider_online:
                    ok = self._salvar_raster_servico_renderizado(layer, path_copia)
                else:
                    ok = self._salvar_raster_bruto(layer, path_copia)
            except Exception:
                ok = False

            if ok:
                path_saida = path_copia
                nome_saida = nome_copia
                salvar_como_copia = True

        if not ok:
            self.mostrar_mensagem(self.tr(
                    "Não foi possível salvar o raster. "
                    "Verifique se o arquivo ou a pasta estão em uso."), "Erro")
            return

        nova_layer = QgsRasterLayer(path_saida, nome_saida, "gdal")

        if not nova_layer.isValid():
            self.mostrar_mensagem(
                self.tr(
                    "O arquivo foi salvo, mas não pôde ser carregado "
                    "novamente no projeto."), "Erro",
                caminho_arquivo=path_saida,
                caminho_pasta=os.path.dirname(path_saida))
            return

        # Copia a aparência da camada original.
        try:
            if layer.renderer():
                nova_layer.setRenderer(layer.renderer().clone())
        except Exception:
            pass # nosec B110

        try:
            nova_layer.setBlendMode(layer.blendMode())
        except Exception:
            pass # nosec B110

        try:
            nova_layer.setMapTipTemplate(layer.mapTipTemplate())
        except Exception:
            pass # nosec B110

        if salvar_como_copia:
            # Mantém a camada original e adiciona a cópia logo acima dela.
            self._adicionar_copia_raster_ao_projeto(
                layer,
                nova_layer)
        else:
            # Substitui a camada original pela camada salva.
            self._substituir_raster_no_projeto(
                layer,
                nova_layer)

        self.atualizar_treeView_lista_raster()
        self.iface.setActiveLayer(nova_layer)
        self.iface.mapCanvas().refresh()

        # Seleciona a nova camada no treeView do plugin.
        for row in range(self.treeViewModel.rowCount()):
            item = self.treeViewModel.item(row)

            if (item
                and item.data(Qt.ItemDataRole.UserRole)
                == nova_layer.id()):
                index = self.treeViewModel.indexFromItem(item)
                self.dlg.treeViewListaRaster.setCurrentIndex(index)
                self.dlg.treeViewListaRaster.scrollTo(index)
                break

        if salvar_como_copia:
            mensagem = self.tr(
                "O raster estava em uso. Uma cópia foi salva como "
                "'{nome}' e adicionada ao projeto.").format(nome=nome_saida)
        else:
            mensagem = self.tr("Raster salvo e substituído no projeto como '{nome}'.").format(nome=nome_saida)

        self.mostrar_mensagem( mensagem, "Sucesso", caminho_arquivo=path_saida, caminho_pasta=os.path.dirname(path_saida))

    def _obter_caminho_local_raster(self, layer):
        """
        Retorna o caminho absoluto do arquivo associado ao raster.

        Para serviços online, VRTs complexos ou fontes que não representam
        diretamente um arquivo local, retorna None.
        """
        if not layer:
            return None

        if layer.providerType().lower() in (
            "wms",
            "xyz",
            "arcgismapserver",
            "arcgisfeatureserver"):
            return None

        source = layer.source()
        if not source:
            return None

        # Algumas fontes GDAL podem possuir opções depois de "|".
        source = source.split("|", 1)[0]

        # Remove prefixos GDAL simples.
        if source.startswith("file://"):
            source = QUrl(source).toLocalFile()

        try:
            return os.path.abspath(os.path.normpath(source))
        except Exception:
            return None

    def _gerar_caminho_copia(self, path_original):
        """
        Gera um caminho disponível usando:
        arquivo_copia.tif
        arquivo_copia_1.tif
        arquivo_copia_2.tif
        """
        pasta = os.path.dirname(path_original)
        nome, extensao = os.path.splitext(
            os.path.basename(path_original))

        if not extensao:
            extensao = ".tif"

        base_copia = self.tr("{nome}_copia").format(nome=nome)
        path_copia = os.path.join(pasta, base_copia + extensao)

        contador = 1

        while os.path.exists(path_copia):
            path_copia = os.path.join( pasta, f"{base_copia}_{contador}{extensao}")
            contador += 1

        return path_copia

    def _substituir_raster_no_projeto(self, layer_original, nova_layer):
        """
        Substitui a camada original pela camada salva, preservando:
        - grupo;
        - posição na árvore;
        - visibilidade.
        """
        projeto = QgsProject.instance()
        root = projeto.layerTreeRoot()
        node_original = root.findLayer(layer_original.id())

        parent_node = root
        indice_original = 0
        visivel = True
        expandido = True

        if node_original:
            parent_node = node_original.parent() or root

            try:
                indice_original = parent_node.children().index(
                    node_original)
            except Exception:
                indice_original = 0

            try:
                visivel = node_original.itemVisibilityChecked()
            except Exception:
                visivel = True

            try:
                expandido = node_original.isExpanded()
            except Exception:
                expandido = True

        # Adiciona sem inserir automaticamente no final da árvore.
        projeto.addMapLayer(
            nova_layer,
            False)

        novo_node = QgsLayerTreeLayer(nova_layer)
        parent_node.insertChildNode(
            indice_original,
            novo_node)

        novo_node.setItemVisibilityChecked(visivel)
        novo_node.setExpanded(expandido)

        # Remove apenas depois que a nova camada já está posicionada.
        projeto.removeMapLayer(layer_original.id())

    def _adicionar_copia_raster_ao_projeto(self, layer_original, nova_layer):
        """
        Adiciona a cópia logo acima da camada original, mantendo o original.
        """
        projeto = QgsProject.instance()
        root = projeto.layerTreeRoot()
        node_original = root.findLayer(layer_original.id())

        parent_node = root
        indice = 0
        visivel = True

        if node_original:
            parent_node = node_original.parent() or root

            try:
                indice = parent_node.children().index(
                    node_original)
            except Exception:
                indice = 0

            try:
                visivel = node_original.itemVisibilityChecked()
            except Exception:
                visivel = True

        projeto.addMapLayer(
            nova_layer,
            False)

        novo_node = QgsLayerTreeLayer(nova_layer)
        parent_node.insertChildNode(
            indice,
            novo_node)

        novo_node.setItemVisibilityChecked(visivel)

    def _salvar_raster_bruto(self, layer: QgsRasterLayer, path_saida: str) -> bool:
        """
        Salva um raster local (não-serviço) como um arquivo GeoTIFF bruto, mantendo o SRC original da camada.
        
        Detalhamento do processo:
        1. Determina o sistema de referência de coordenadas (SRC) de saída:
           - Usa o SRC da camada, se estiver definido e válido.
           - Se o SRC não estiver definido, utiliza o SRC do projeto e informa o usuário.
        2. Cria um QgsRasterPipe e clona o provedor de dados do raster:
           - O QgsRasterPipe permite conectar as etapas de leitura, renderização e gravação dos dados raster.
        3. Instancia o QgsRasterFileWriter para escrever o arquivo GeoTIFF no caminho informado.
        4. Escreve o raster no arquivo de saída usando as dimensões, extensão espacial e SRC determinados.
        5. Se houver erro na escrita, informa ao usuário e retorna False.
        6. Se tudo ocorrer normalmente, retorna True.
        
        Parâmetros:
        - layer: QgsRasterLayer, camada raster a ser salva.
        - path_saida: str, caminho completo do arquivo GeoTIFF a ser criado.
        
        Retorno:
        - True se o raster foi salvo com sucesso.
        - False se houve qualquer falha no processo.
        """
        crs_out = layer.crs() if layer.crs().isValid() else QgsProject.instance().crs()
        if not layer.crs().isValid():
            self.mostrar_mensagem(self.tr("SRC da camada não definido – usando SRC do projeto."), "Erro", duracao=4)

        pipe = QgsRasterPipe()
        # Clone apenas o provider: NÃO inclua o renderer!
        if not pipe.set(layer.dataProvider().clone()):
            self.mostrar_mensagem(self.tr("Falha ao clonar provider"), "Erro")
            return False

        # NÃO use pipe.set(layer.renderer().clone())

        writer = QgsRasterFileWriter(path_saida)
        res = writer.writeRaster(pipe, layer.width(), layer.height(), layer.extent(), crs_out)

        if res != QgsRasterFileWriter.WriterError.NoError:
            self.mostrar_mensagem(self.tr("Erro ao gravar GeoTIFF"), "Erro")
            return False

        return True

    def _salvar_raster_servico_renderizado(self, layer: QgsRasterLayer, path_saida: str) -> bool:
        """
        Para rasters de serviço (WMS/XYZ/ArcGIS):
        - Renderiza a camada isoladamente usando o renderer do QGIS
        - Grava um GeoTIFF RGB georreferenciado na extensão da camada

        Obs: serviço não tem "pixel grid original" para copiar 1:1, então isso é um “snapshot georreferenciado”.
        """
        try:
            extent = layer.extent()
            if extent.isEmpty():
                self.mostrar_mensagem(self.tr("Extensão vazia: {layer_name}").format(layer_name=layer.name()), "Erro")
                return False

            canvas = self.iface.mapCanvas()
            w = max(256, canvas.size().width())
            h = max(256, canvas.size().height())

            crs_out = layer.crs() if layer.crs().isValid() else QgsProject.instance().crs()

            ms = QgsMapSettings()
            ms.setLayers([layer])
            ms.setExtent(extent)
            ms.setDestinationCrs(crs_out)
            ms.setOutputSize(QSize(w, h))

            img = QImage(w, h, QImage.Format.Format_ARGB32_Premultiplied)
            img.fill(Qt.GlobalColor.white)

            painter = QPainter(img)
            job = QgsMapRendererCustomPainterJob(ms, painter)
            job.start()
            job.waitForFinished()
            painter.end()

            # QImage -> numpy (RGB) | Qt6
            img2 = img.convertToFormat(QImage.Format.Format_RGBA8888)
            ptr = img2.bits()
            ptr.setsize(img2.sizeInBytes())
            arr = np.array(ptr).reshape((h, w, 4))[:, :, :3]
            arr = np.moveaxis(arr, 2, 0)

            drv = gdal.GetDriverByName("GTiff")
            ds = drv.Create(path_saida, w, h, 3, gdal.GDT_Byte, options=["COMPRESS=LZW"])
            for b in range(3):
                ds.GetRasterBand(b + 1).WriteArray(arr[b])

            gt = (extent.xMinimum(), extent.width() / w, 0, extent.yMaximum(), 0, -extent.height() / h)
            ds.SetGeoTransform(gt)

            srs = osr.SpatialReference()
            srs.ImportFromWkt(crs_out.toWkt())
            ds.SetProjection(srs.ExportToWkt())
            ds = None

            return True

        except Exception as e:
            self.mostrar_mensagem(self.tr("Falha ao salvar serviço '{layer_name}': {error}").format(layer_name=layer.name(), error=e), "Erro")
            return False

    def salvar_visualizacao_canvas_geotiff(self, path_saida: str) -> bool:
        """
        Salva a visualização atual do canvas em GeoTIFF georreferenciado.
        Retorna True se tudo correr bem, False caso contrário.
        """
        try:
            canvas = self.iface.mapCanvas()
            rect   = canvas.extent()
            width  = canvas.size().width()
            height = canvas.size().height()
            crs    = QgsProject.instance().crs()

            img = QImage(width, height, QImage.Format.Format_ARGB32)
            img.fill(Qt.GlobalColor.white)
            painter = QPainter(img)
            canvas.render(painter)
            painter.end()

            # QImage -> numpy (RGB) | Qt6
            img = img.convertToFormat(QImage.Format.Format_RGBA8888)
            ptr = img.bits()
            ptr.setsize(img.sizeInBytes())
            arr = np.array(ptr).reshape((height, width, 4))[:, :, :3]
            arr = np.moveaxis(arr, 2, 0)

            drv = gdal.GetDriverByName('GTiff')
            ds = drv.Create(path_saida, width, height, 3, gdal.GDT_Byte, options=['COMPRESS=LZW'])
            for b in range(3):
                ds.GetRasterBand(b + 1).WriteArray(arr[b])

            gt = (rect.xMinimum(), rect.width()/width, 0, rect.yMaximum(), 0, -rect.height()/height)
            ds.SetGeoTransform(gt)

            srs = osr.SpatialReference()
            srs.ImportFromWkt(crs.toWkt())
            ds.SetProjection(srs.ExportToWkt())
            ds = None

            self.mostrar_mensagem(self.tr("Visualização do canvas salva em GeoTIFF!"), "Sucesso", caminho_arquivo=path_saida, caminho_pasta=os.path.dirname(path_saida))
            return True

        except Exception as e:
            self.mostrar_mensagem(self.tr("Falha ao salvar GeoTIFF: {error}").format(error=e), "Erro")
            return False

    def _node_checkbox_checked(self, node):
        """
        Retorna o estado do checkbox do nó na árvore de camadas,
        sem confundir com a visibilidade herdada de grupos.
        """
        if node is None:
            return False

        try:
            return bool(node.itemVisibilityChecked())
        except Exception:
            try:
                return bool(node.isVisible())
            except Exception:
                return False

    def _on_any_layer_tree_visibility_changed(self, node):
        """
        Mantém o treeView sincronizado quando o checkbox muda no painel do QGIS.
        """
        if isinstance(node, QgsLayerTreeLayer):
            self.atualizar_item_visibilidade(node)
        else:
            self.sync_from_qgis_to_treeview()

    def camada_esta_visivel(self, layer):
        """
        Retorna o estado do checkbox da camada na árvore do QGIS.
        """
        layer_tree_layer = QgsProject.instance().layerTreeRoot().findLayer(layer.id())
        return self._node_checkbox_checked(layer_tree_layer)

    def atualizar_item_visibilidade(self, layer_tree_layer):
        """
        Atualiza o checkbox do item correspondente no treeView.
        """
        if not isinstance(layer_tree_layer, QgsLayerTreeLayer):
            self.sync_from_qgis_to_treeview()
            return

        model = self.dlg.treeViewListaRaster.model()
        if model is None:
            return

        target_id = layer_tree_layer.layerId()
        desired = (
            Qt.CheckState.Checked
            if self._node_checkbox_checked(layer_tree_layer)
            else Qt.CheckState.Unchecked)

        self._tree_sync_depth = getattr(self, "_tree_sync_depth", 0) + 1
        try:
            for row in range(model.rowCount()):
                item = model.item(row)
                if not item:
                    continue
                if item.data(Qt.ItemDataRole.UserRole) != target_id:
                    continue

                if item.checkState() != desired:
                    item.setCheckState(desired)
                break
        finally:
            self._tree_sync_depth = max(0, getattr(self, "_tree_sync_depth", 1) - 1)

    def on_treeview_item_clicked(self, index):
        """
        Fallback para garantir a aplicação da visibilidade no QGIS
        quando o clique no checkbox não disparar itemChanged como esperado.
        """
        if not index.isValid():
            return

        item = self.treeViewModel.itemFromIndex(index)
        if item is None:
            return

        self.on_item_changed(item)

    def on_item_changed(self, item):
        """
        Atualiza a visibilidade da camada no QGIS quando o checkbox do treeView muda.
        """
        if item is None:
            return

        if getattr(self, "_tree_sync_depth", 0) > 0:
            return

        layer_id = item.data(Qt.ItemDataRole.UserRole)
        if not layer_id:
            return

        root = QgsProject.instance().layerTreeRoot()
        node = root.findLayer(layer_id)
        if node is None:
            return

        desired = (item.checkState() == Qt.CheckState.Checked)

        try:
            current = bool(node.itemVisibilityChecked())
        except Exception:
            try:
                current = bool(node.isVisible())
            except Exception:
                current = None

        if current != desired:
            node.setItemVisibilityChecked(desired)

    def sync_from_qgis_to_treeview(self):
        """
        Sincroniza o checkbox do treeView com o checkbox real da árvore do QGIS.
        """
        root = QgsProject.instance().layerTreeRoot()

        self._tree_sync_depth = getattr(self, "_tree_sync_depth", 0) + 1
        try:
            for i in range(self.treeViewModel.rowCount()):
                item = self.treeViewModel.item(i)
                if not item:
                    continue

                layer_id = item.data(Qt.ItemDataRole.UserRole)
                node = root.findLayer(layer_id) if layer_id else None
                if not node:
                    continue

                desired = (
                    Qt.CheckState.Checked
                    if self._node_checkbox_checked(node)
                    else Qt.CheckState.Unchecked)

                if item.checkState() != desired:
                    item.setCheckState(desired)
        finally:
            self._tree_sync_depth = max(0, getattr(self, "_tree_sync_depth", 1) - 1)

    def layers_added(self, layers):
        """
        Atualiza o treeView quando novas camadas raster são adicionadas ao projeto,
        aguardando um ciclo da UI para o nó da árvore do QGIS estabilizar.
        """
        raster_layers = [
            layer for layer in layers
            if layer.type() == QgsMapLayer.LayerType.RasterLayer]

        if not raster_layers:
            return

        for layer in raster_layers:
            try:
                layer.nameChanged.disconnect(self.on_layer_name_changed)
            except TypeError:
                pass  # nosec B110
            layer.nameChanged.connect(self.on_layer_name_changed)

        def _refresh_after_qgis_tree_settles():
            self.atualizar_treeView_lista_raster()
            self.sync_from_qgis_to_treeview()
            self.atualizar_estado_botoes()

        QTimer.singleShot(0, _refresh_after_qgis_tree_settles)

    def remover_camada_selecionada(self):
        """
        Remove a camada raster selecionada no treeViewListaRaster sem perguntar nada ao usuário.
        """
        # Obtém os índices selecionados no treeView de rasters
        selected_indexes = self.dlg.treeViewListaRaster.selectedIndexes()
        if selected_indexes:
            selected_index = selected_indexes[0]
            # Usa o papel UserRole para pegar o ID real da camada
            layer_id = selected_index.model().itemFromIndex(selected_index).data(Qt.ItemDataRole.UserRole)
            layer_to_remove = QgsProject.instance().mapLayer(layer_id)
            if layer_to_remove:
                # Remove a camada do projeto QGIS sem qualquer confirmação ou salvamento
                QgsProject.instance().removeMapLayer(layer_id)
                self.atualizar_treeView_lista_raster()
                self.iface.mapCanvas().refresh()

    def renomear_camada_selecionada(self):
        """
        Permite ao usuário renomear uma camada de Raster selecionado no treeViewListaRaster,
        garantindo unicidade do nome no projeto.

        Fluxo:
        - Obtém o índice selecionado.
        - Recupera a camada associada ao item (usando Qt.UserRole).
        - Exibe um diálogo para o usuário digitar o novo nome.
        - Garante que o nome será único (ajusta se necessário).
        - Atualiza o nome da camada no QGIS e o texto do item no treeView.
        """
        # Obtém os índices atualmente selecionados no treeView de raster
        selected_indexes = self.dlg.treeViewListaRaster.selectedIndexes()
        if selected_indexes:
            # Pega o primeiro índice selecionado
            selected_index = selected_indexes[0]
            # Recupera o ID da camada usando o papel UserRole (garante que é o ID real da camada QGIS)
            layer_id = selected_index.model().itemFromIndex(selected_index).data(Qt.ItemDataRole.UserRole)
            # Busca a camada correspondente no projeto QGIS
            selected_layer = QgsProject.instance().mapLayer(layer_id)
            if selected_layer:
                # Exibe um diálogo para o usuário digitar o novo nome (pré-preenchido com o nome atual)
                novo_nome, ok = QInputDialog.getText(self.dlg, self.tr("Renomear Camada"), self.tr("Digite o novo nome da camada:"), text=selected_layer.name())

                # Se o usuário confirmou e digitou algo
                if ok and novo_nome:
                    # Gera um nome único para evitar duplicidade no projeto
                    novo_nome = self.gerar_nome_unico(novo_nome, selected_layer.id())
                    # Renomeia a camada no QGIS (isso pode disparar sinais que atualizam a interface automaticamente)
                    selected_layer.setName(novo_nome)
                    # Em vez de tentar alterar diretamente o item do modelo (risco de crash), reconstrói o treeView do zero
                    self.atualizar_treeView_lista_raster()

    def gerar_nome_unico(self, base_nome, current_layer_id):
        """
        Gera um nome único para uma camada raster dentro do projeto QGIS,
        assegurando que não haja conflitos de nomeação entre as camadas raster.

        Parâmetros:
        - base_nome (str): O nome base proposto para a camada.
        - current_layer_id (str): O ID da camada que está sendo renomeada, usado para excluir seu nome atual da verificação de duplicidade.

        Funcionalidades:
        - Cria um dicionário dos nomes de todas as camadas raster existentes no projeto QGIS, excluindo a camada que está sendo renomeada.
        - Verifica se o nome base já existe entre as camadas raster. Se não existir, retorna o nome base como válido.
        - Se o nome base já existir, gera variações do nome acrescentando um sufixo numérico (ex: "Nome_1", "Nome_2") até encontrar um nome não utilizado.
        - Retorna o novo nome único gerado.
        """
        # Restringe apenas para camadas raster
        existing_names = {layer.name(): layer.id()
            for layer in QgsProject.instance().mapLayers().values()
            if (layer.id() != current_layer_id and
                layer.type() == QgsMapLayer.LayerType.RasterLayer)}  # Filtro para rasters

        # Se o nome proposto não existe, retorna ele direto
        if base_nome not in existing_names:
            return base_nome
        else:
            # Gera nomes incrementando um sufixo até ser único
            i = 1
            novo_nome = f"{base_nome}_{i}"
            while novo_nome in existing_names:
                i += 1
                novo_nome = f"{base_nome}_{i}"
            return novo_nome

    def atualizar_estado_botoes(self):
        """
        Atualiza o estado (habilitado/desabilitado) dos botões da interface gráfica conforme a presença de camadas no treeView de Rasters.

        Detalhamento do Processo:
        1. Verifica se o modelo associado ao treeViewListaRaster está vazio, ou seja, sem nenhuma camada listada.
        2. Se o modelo estiver vazio, todos os botões que dependem de camada devem ser desabilitados para evitar operações inválidas.
        3. Caso contrário, os botões são habilitados, permitindo ao usuário interagir normalmente com as funções associadas a uma camada de raster.
        4. Os botões afetados incluem:
            - Deletar camada (`pushButtonDelR`)
            - Renomear camada (`pushButtonRenomeR`)
            - Tornar camada permanente (`pushButtonSalvarRaster`)
            - Salvar em múltiplos formatos (`pushButtonSalvaMultiplosR`)
            - Exportar para DXF (`pushButtonRasterDXF`)
            - Exportar para KML (`pushButtonRasterKML`)
            - Visualizar raster associados (`pushButtonVisualizarR`)
            - Vizzualizar 3D (`pushButton3DRaster`)
            - Reprojetar camada (`pushButtonReprojetarR`)
        5. Garante uma experiência segura e intuitiva, evitando erros por ações em contexto inválido.
        """
        # Verifica se o modelo do treeView está vazio
        modelo_vazio = self.dlg.treeViewListaRaster.model().rowCount() == 0

        # Atualiza o estado dos botões baseado na presença ou ausência de itens no modelo
        self.dlg.pushButtonDelR.setEnabled(not modelo_vazio)
        self.dlg.pushButtonRenomeR.setEnabled(not modelo_vazio)
        self.dlg.pushButtonSalvarRaster.setEnabled(not modelo_vazio)
        self.dlg.pushButtonSalvaMultiplosR.setEnabled(not modelo_vazio)
        self.dlg.pushButtonRasterDXF.setEnabled(not modelo_vazio)
        self.dlg.pushButtonRasterKML.setEnabled(not modelo_vazio)
        self.dlg.pushButtonVisualizarR.setEnabled(not modelo_vazio)
        self.dlg.pushButtonClonarRaster.setEnabled(not modelo_vazio)
        self.dlg.pushButtonReprojetarR.setEnabled(not modelo_vazio)
        self.dlg.pushButton3DRaster.setEnabled(not modelo_vazio)

    def visualizar_raster_selecionado(self):
        """
        Aproxima a visualização do mapa para a camada de raster selecionada no treeView.

        - Obtém a camada de raster atualmente selecionada.
        - Centraliza e ajusta a extensão do mapa para mostrar toda a camada.
        - Se não houver feições ou seleção, não faz nada.
        """
        index = self.dlg.treeViewListaRaster.currentIndex()  # Obtém o índice selecionado
        if not index.isValid():
            return  # Não há seleção

        # Obtém o ID da camada do UserRole (melhor do que usar .data() sem argumentos)
        layer_id = index.model().itemFromIndex(index).data(Qt.ItemDataRole.UserRole)
        layer = QgsProject.instance().mapLayer(layer_id)
        if not layer or layer.extent().isEmpty():
            return  # Camada não encontrada ou sem feições

        # Garante que a camada esteja ativa (opcional, mas recomendado)
        self.iface.setActiveLayer(layer)
        # Ajusta o zoom para a extensão da camada ativa
        self.iface.zoomToActiveLayer()

    def configurar_tooltip(self, index):
        """
        Exibe um tooltip detalhado da camada raster selecionada.

        O que a função faz (passos):
        1. Converte o índice do treeView em item, obtendo o ID da camada.
        2. Recupera a camada no projeto e garante que é RasterLayer.
        3. Coleta atributos principais (SRC, bandas, colunas, linhas).
        4. Calcula a **área** do raster como:
             área = (cols * rows) * (resX * resY)
           • resX/resY = resolução do pixel nas unidades do SRC.
           • cols/rows = largura/altura em número de pixels.
        5. Formata todas as infos em texto amigável.
        6. Mostra o tooltip na posição atual do cursor.

        Nota: Se o SRC for geográfico (graus) o valor é em graus²,
              podendo não representar área real em m².
        """
        item = index.model().itemFromIndex(index)          # item selecionado
        layer_id = item.data(Qt.ItemDataRole.UserRole)                  # ID da camada
        layer = QgsProject.instance().mapLayer(layer_id)   # camada no projeto

        if layer and layer.type() == QgsMapLayer.LayerType.RasterLayer:
            # Informações básicas
            crs_desc = layer.crs().description() if layer.crs().isValid() else self.tr("Sem Georreferenciamento")
            num_bandas = layer.bandCount()
            cols       = layer.width()                     # nº colunas  (= pixels X)
            rows       = layer.height()                    # nº linhas   (= pixels Y)

            # Resolução do pixel (unidades / pixel)
            #   • rasterUnitsPerPixelX/Y já retornam a resolução do provider
            #   • fallback: extent / dimensões
            resX = layer.rasterUnitsPerPixelX() or \
                   (layer.extent().width()  / cols)
            resY = layer.rasterUnitsPerPixelY() or \
                   (layer.extent().height() / rows)

            # Málculo da área
            pixel_area = abs(resX * resY)                  # área de 1 pixel
            area_total = cols * rows * pixel_area          # área total

            # unidade textual ─ metros², graus² etc.
            unidade = layer.crs().mapUnits().name \
                      if layer.crs().isValid() else ""

            # Monta texto do tooltip
            tooltip_text = self.tr("SRC: {crs_desc}\nBandas: {num_bandas}\nDimensões: {cols} x {rows} pixels\nÁrea: {area_total:,.3f} {unidade}²").format(
                crs_desc=crs_desc,
                num_bandas=num_bandas,
                cols=cols,
                rows=rows,
                area_total=area_total,
                unidade=unidade)

            QToolTip.showText(QCursor.pos(), tooltip_text) # exibe tooltip

    def obter_tipo_de_raster(self, layer):
        """
        Retorna uma string que descreve o tipo de geometria da camada fornecida.

        A função obtém o tipo de geometria WKB (Well-Known Binary) da camada e converte esse tipo
        em uma string legível, como 'raster', etc.

        Parâmetros:
        - layer: Objeto QgsVectorLayer representando a camada de onde o tipo de ponto será extraído.

        Retorno:
        - tipo_raster (str): Uma string que descreve o tipo de geometria da camada.
        """
        if layer.type() == QgsMapLayer.LayerType.RasterLayer:
            # Aqui você pode personalizar o tipo conforme a origem do raster, se quiser
            return self.tr("Raster")
        return self.tr("Desconhecido")

    def on_layers_removed(self, removed_ids):
        """
        Remove do treeView apenas os rasters cujos IDs saíram do projeto
        e mantém uma seleção válida quando ainda restarem camadas.
        """
        if self.treeViewModel.rowCount() == 0:
            return

        linha_removida = None

        for layer_id_removido in removed_ids:
            for row in range(self.treeViewModel.rowCount()):
                item = self.treeViewModel.item(row)

                if item and item.data(Qt.ItemDataRole.UserRole) == layer_id_removido:
                    linha_removida = row
                    self.treeViewModel.removeRow(row)
                    break

        model = self.dlg.treeViewListaRaster.model()

        if model.rowCount() > 0 and not self.dlg.treeViewListaRaster.currentIndex().isValid():
            target_row = min(
                linha_removida if linha_removida is not None else 0,
                model.rowCount() - 1)

            idx = model.index(target_row, 0)
            self.dlg.treeViewListaRaster.setCurrentIndex(idx)
            self.dlg.treeViewListaRaster.scrollTo(idx)

        self.atualizar_estado_botoes()

    def close_dialog(self):
        """
        Fecha o diálogo associado a este UiManagerR:
        """
        self.dlg.close()

    def on_treeview_selection_changed(self, selected, deselected):
        """
        Define a camada ativa no QGIS com base na seleção do TreeView.

        Funcionalidades:
        - Acessa os índices selecionados no TreeView.
        - Recupera o ID da camada associado ao item selecionado.
        - Define a camada correspondente como ativa no QGIS (iface.setActiveLayer).
        """
        # Obtém os índices selecionados no TreeView
        indexes = self.dlg.treeViewListaRaster.selectionModel().selectedIndexes()
        if indexes:
            # Recupera o ID da camada a partir do primeiro item selecionado
            layer_id = self.treeViewModel.itemFromIndex(indexes[0]).data(Qt.ItemDataRole.UserRole)
            # Obtém a camada no projeto QGIS através do ID
            layer = QgsProject.instance().mapLayer(layer_id)
            if layer:
                # Define a camada como ativa no QGIS
                self.iface.setActiveLayer(layer)

    def atualizar_treeView_lista_raster(self):
        """
        Atualiza o TreeView que lista as camadas de rasters no QGIS.

        Funcionalidades:
        1) Salva o ID da camada atualmente selecionada no TreeView, se houver.
        2) Limpa e reconstrói o modelo do TreeView:
           - Define o cabeçalho centralizado.
           - Itera sobre todas as camadas do projeto e adiciona ao modelo apenas as camadas rasters.
           - Para cada camada encontrada:
             * Cria um item com o nome da camada.
             * Torna o item checkable para controlar visibilidade.
             * Define flags para impedir edição direta do texto.
             * Armazena o ID único da camada no Qt.UserRole.
             * Ajusta o estado do checkbox de acordo com a visibilidade atual da camada no projeto.
             * Formata a fonte do item (itálico para memória, negrito para outras).
        3) Tenta restaurar a seleção anterior, buscando no modelo o item cujo ID corresponda ao salvo.
        4) Caso não haja seleção anterior ou a camada não exista mais, seleciona o primeiro item do modelo.
        5) Move o scroll para garantir que o item selecionado esteja visível.
        """
        # Guarda a linha selecionada ANTES de recriar o modelo
        current_row   = -1                     # -1 → nada selecionado
        current_index = self.dlg.treeViewListaRaster.currentIndex()
        if current_index.isValid():
            current_row = current_index.row()  # linha que estava selecionada

        # Reconstrói o modelo
        self.treeViewModel.clear()
        header_item = QStandardItem(self.tr("Lista de Camadas de Rasters"))
        header_item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
        self.treeViewModel.setHorizontalHeaderItem(0, header_item)

        root = QgsProject.instance().layerTreeRoot()
        for layer in QgsProject.instance().mapLayers().values():
            if layer.type() == QgsMapLayer.LayerType.RasterLayer:
                item = QStandardItem(layer.name())
                item.setCheckable(True)
                # item.setFlags(item.flags() & ~Qt.ItemIsEditable)
                item.setEditable(False)
                item.setData(layer.id(), Qt.ItemDataRole.UserRole)

                item.setCheckState(Qt.CheckState.Checked
                    if self.camada_esta_visivel(layer)
                    else Qt.CheckState.Unchecked)

                self.adjust_item_font(item, layer)
                self.treeViewModel.appendRow(item)

        # Decide qual linha selecionar DEPOIS da atualização
        model = self.dlg.treeViewListaRaster.model()
        row_count = model.rowCount()

        if row_count == 0:
            return  # não há nada para selecionar

        # Tenta selecionar a mesma linha anterior, ou a primeira
        target_row = current_row if 0 <= current_row < row_count else 0

        target_index = model.index(target_row, 0)
        self.dlg.treeViewListaRaster.setCurrentIndex(target_index)
        self.dlg.treeViewListaRaster.scrollTo(target_index)
        self.sync_from_qgis_to_treeview()

    def on_current_layer_changed(self, layer):
        """
        Sincroniza a seleção do treeView com a camada ativa no QGIS.

        Funcionalidades:
        - Verifica se a nova camada ativa é uma camada de rasters.
        - Percorre o modelo do treeView para encontrar o item correspondente ao ID da nova camada.
        - Se encontrar, seleciona e rola até o item correspondente no treeView.
        - Se a camada ativa for raster → seleciona o item correspondente.
        - Caso contrário → limpa a seleção do treeView.
        • Quando a camada ativa for raster → seleciona o item correspondente.
        • Quando a camada ativa NÃO for raster → mantém a seleção atual.
          (Se por acaso não houver seleção, força a primeira linha.)
        """
        model = self.dlg.treeViewListaRaster.model()
        if model is None or model.rowCount() == 0:
            return  # não há rasters no treeView

        # Caso a camada ativa seja RASTER
        if layer and layer.type() == QgsMapLayer.LayerType.RasterLayer:
            layer_id = layer.id()

            # Percorre as linhas do modelo do treeView
            for row in range(model.rowCount()):
                item = model.item(row, 0)
                if item and item.data(Qt.ItemDataRole.UserRole) == layer_id:
                    index = model.indexFromItem(item)
                    # força a seleção mesmo que já estivesse selecionado
                    self.dlg.treeViewListaRaster.setCurrentIndex(index)
                    self.dlg.treeViewListaRaster.scrollTo(index)
                    break

        # Caso a camada ativa NÃO seja raster
        else:
            # Se por algum motivo não houver item selecionado,
            # garante que a primeira linha fique marcada.
            if not self.dlg.treeViewListaRaster.currentIndex().isValid():
                first_index = model.index(0, 0)
                self.dlg.treeViewListaRaster.setCurrentIndex(first_index)
                self.dlg.treeViewListaRaster.scrollTo(first_index)

    def adjust_item_font(self, item, layer):
        """
        Esta função ajusta a fonte do item no QTreeView com base no tipo de camada.
        Se a camada for temporária (dados em memória), ajusta a fonte para itálico.
        Se a camada for permanente, ajusta a fonte para negrito.

        Detalhes:
        - Cria um objeto QFont para ajustar a fonte do item.
        - Verifica se a camada é temporária usando o método isTemporary().
        - Se a camada for temporária, ajusta a fonte para itálico.
        - Se a camada for permanente, ajusta a fonte para negrito.
        - Aplica a fonte ajustada ao item no QTreeView.
        - Retorna o item com a fonte ajustada para uso posterior, se necessário.
        """
        # Cria um objeto QFont para ajustar a fonte do item
        fonte_item = QFont()

        # Verifica se a camada é temporária (dados em memória) e ajusta a fonte para itálico
        if layer.isTemporary():
            fonte_item.setItalic(True)
        # Se não for temporária, ajusta a fonte para negrito, indicando uma camada permanente
        else:
            fonte_item.setBold(True)

        # Aplica a fonte ajustada ao item no QTreeView
        item.setFont(fonte_item)

        # Retorna o item com a fonte ajustada para uso posterior se necessário
        return item

    def connect_name_changed_signals(self):
        """
        Conecta o sinal nameChanged de todas as camadas reais do projeto.
        Ignora grupos e nós sem camada associada.
        Evita conexões duplicadas.
        """
        root = QgsProject.instance().layerTreeRoot()

        for layerNode in root.findLayers():
            if isinstance(layerNode, QgsLayerTreeLayer):
                layer = layerNode.layer()
                if layer is not None:
                    try:
                        # desconecta primeiro para evitar duplicidade
                        layer.nameChanged.disconnect(self.on_layer_name_changed)
                    except TypeError:
                        # se não estava conectado, ignora o erro
                        pass  # nosec B110

                    # conecta de forma segura
                    layer.nameChanged.connect(self.on_layer_name_changed)

    def on_layer_name_changed(self):
        """
        Responde ao evento de mudança de nome de qualquer camada no projeto QGIS. 
        Este método é chamado automaticamente quando o nome de uma camada é alterado,
        e sua função é garantir que a lista de camadas no QTreeView seja atualizada para refletir
        essa mudança.

        Funções e Ações Desenvolvidas:
        - Atualização da lista de camadas no QTreeView para assegurar que os nomes das camadas estejam corretos.
        """
        # Atualiza a lista de camadas no QTreeView para refletir a mudança de nome
        self.atualizar_treeView_lista_raster()

    def on_layer_was_renamed(self, layerId, newName):
        """
        Responde ao evento de renomeação de uma camada no QGIS, atualizando o nome da camada no QTreeView.
        Este método garante que as mudanças de nome no projeto sejam refletidas na interface do usuário.

        :param layerId: ID da camada que foi renomeada.
        :param newName: Novo nome atribuído à camada.

        Funções e Ações Desenvolvidas:
        - Pesquisa no modelo do QTreeView pelo item que corresponde à camada renomeada.
        - Atualização do texto do item no QTreeView para refletir o novo nome.
        """
        # Itera sobre todos os itens no modelo do QTreeView para encontrar o item correspondente
        for i in range(self.treeViewModel.rowCount()):
            item = self.treeViewModel.item(i)
            layer = QgsProject.instance().mapLayer(layerId)
            # Verifica se o item corresponde à camada que foi renomeada
            if layer and item.text() == layer.name():
                item.setText(newName)  # Atualiza o nome do item no QTreeView
                break  # Sai do loop após atualizar o nome

    def open_context_menu(self, position):
        """
        Esta função abre um menu de contexto ao clicar com o botão direito na árvore de visualização (QTreeView).
        Se um item for selecionado, cria e exibe um menu de contexto com a opção de abrir as propriedades da camada.
        
        Detalhes:
        - Obtém os índices dos itens selecionados no QTreeView.
        - Verifica se há algum item selecionado.
        - Se houver um item selecionado:
            - Cria um novo menu de contexto.
            - Adiciona a opção "Abrir Propriedades da Camada" ao menu de contexto.
            - Exibe o menu de contexto na posição do cursor.
            - Executa a ação correspondente se a opção "Abrir Propriedades da Camada" for selecionada.
        """
        # Obtém os índices dos itens selecionados na árvore de visualização
        indexes = self.dlg.treeViewListaRaster.selectedIndexes()
        
        # Verifica se algum item foi selecionado
        if indexes:
            # Cria um novo menu de contexto
            menu = QMenu()
            
            # Adiciona uma ação ao menu de contexto
            layer_properties_action = menu.addAction(self.tr("Abrir Propriedades da Camada"))
            
            # Exibe o menu de contexto na posição do cursor e obtém a ação selecionada pelo usuário
            action = menu.exec(self.dlg.treeViewListaRaster.viewport().mapToGlobal(position))
            
            # Verifica se a ação selecionada foi "Abrir Propriedades da Camada"
            if action == layer_properties_action:
                # Abre as propriedades da camada para o item selecionado
                self.abrir_layer_properties(indexes[0])

    def abrir_layer_properties(self, index):
        """
        Abre a janela de propriedades da camada selecionada no QTreeView. Este método é chamado quando o usuário deseja
        ver ou editar as propriedades de uma camada específica, como símbolos, campos e outras configurações.

        Funções e Ações Desenvolvidas:
        - Obtenção do ID da camada a partir do item selecionado no QTreeView.
        - Recuperação da camada correspondente no projeto QGIS.
        - Exibição da janela de propriedades da camada se ela for encontrada.

        :param index: O índice do modelo que representa o item selecionado no QTreeView.
        """
        # Obtém o ID da camada do item selecionado no treeView
        layer_id = index.model().itemFromIndex(index).data(Qt.ItemDataRole.UserRole)
        # Busca a camada correspondente no projeto QGIS usando o ID
        layer = QgsProject.instance().mapLayer(layer_id)
        # Se a camada for encontrada, exibe a janela de propriedades da camada
        if layer:
            self.iface.showLayerProperties(layer)

    def escolher_local_para_salvar(self, nome_padrao, tipo_arquivo):
        """
        Permite ao usuário escolher um local e um nome de arquivo para salvar uma camada, usando uma caixa de diálogo.
        O método também gerencia nomes de arquivos para evitar sobreposição e lembra o último diretório utilizado.

        Funções e Ações Desenvolvidas:
        - Recuperação do último diretório utilizado através das configurações do QGIS.
        - Geração de um nome de arquivo único para evitar sobreposição.
        - Exibição de uma caixa de diálogo para escolha do local de salvamento.
        - Atualização do último diretório utilizado nas configurações do QGIS.

        :param nome_padrao: Nome padrão proposto para o arquivo a ser salvo.
        :param tipo_arquivo: Descrição do tipo de arquivo para a caixa de diálogo (ex. "Arquivos DXF (*.dxf)").

        :return: O caminho completo do arquivo escolhido para salvar ou None se nenhum arquivo foi escolhido.
        """
        # Acessa as configurações do QGIS para recuperar o último diretório utilizado
        settings = QSettings()
        lastDir = settings.value("lastDir", "")  # Usa uma string vazia como padrão se não houver último diretório

        # Configura as opções da caixa de diálogo para salvar arquivos
        options = QFileDialog.Options()
        
        # Gera um nome de arquivo com um sufixo numérico caso o arquivo já exista
        base_nome_padrao, extensao = os.path.splitext(nome_padrao)
        numero = 1
        nome_proposto = base_nome_padrao
        
        # Incrementa o número no nome até encontrar um nome que não exista
        while os.path.exists(os.path.join(lastDir, nome_proposto + extensao)):
            nome_proposto = f"{base_nome_padrao}_{numero}"
            numero += 1

        # Propõe o nome completo no último diretório utilizado
        nome_completo_proposto = os.path.join(lastDir, nome_proposto + extensao)

        # Exibe a caixa de diálogo para salvar arquivos com o nome proposto
        fileName, _ = QFileDialog.getSaveFileName(
            self.dlg,
            self.tr("Salvar Camada"),
            nome_completo_proposto,
            tipo_arquivo,
            options=options)

        # Verifica se um nome de arquivo foi escolhido
        if fileName:
            # Atualiza o último diretório usado nas configurações do QGIS
            settings.setValue("lastDir", os.path.dirname(fileName))

            # Assegura que o arquivo tenha a extensão correta
            if not fileName.endswith(extensao):
                fileName += extensao

        return fileName  # Retorna o caminho completo do arquivo escolhido ou None se cancelado

    def mostrar_mensagem(self, texto, tipo, duracao=3, caminho_pasta=None, caminho_arquivo=None):
        """
        Exibe apenas uma mensagem deste módulo por vez.
        """
        bar = self.iface.messageBar()

        mensagem_anterior = getattr(self, "_mensagem_atual", None)

        if mensagem_anterior is not None:
            try:
                bar.popWidget(mensagem_anterior)
            except (RuntimeError, TypeError):
                pass  # A mensagem pode já ter expirado.

            self._mensagem_atual = None

        if tipo == "Erro":
            titulo = self.tr("Erro")
            nivel = Qgis.MessageLevel.Critical

        elif tipo == "Aviso":
            titulo = self.tr("Aviso")
            nivel = Qgis.MessageLevel.Warning

        elif tipo == "Sucesso":
            titulo = self.tr("Sucesso")
            nivel = Qgis.MessageLevel.Info

        else:
            titulo = self.tr("Info")
            nivel = Qgis.MessageLevel.Info

        mensagem = bar.createMessage(titulo, texto)

        posicao_botao = 1

        if caminho_pasta:
            botao_abrir_pasta = QPushButton(
                self.tr("Abrir Pasta"))

            botao_abrir_pasta.clicked.connect(
                lambda _checked=False, caminho=caminho_pasta:
                    QDesktopServices.openUrl(
                        QUrl.fromLocalFile(
                            os.path.abspath(
                                os.fspath(caminho)))))

            mensagem.layout().insertWidget(posicao_botao, botao_abrir_pasta)

            posicao_botao += 1

        if caminho_arquivo:
            botao_executar = QPushButton(
                self.tr("Executar"))

            botao_executar.clicked.connect(
                lambda _checked=False, caminho=caminho_arquivo:
                    QDesktopServices.openUrl(
                        QUrl.fromLocalFile(
                            os.path.abspath(
                                os.fspath(caminho)))))

            mensagem.layout().insertWidget(posicao_botao, botao_executar)

            posicao_botao += 1

        # Exibe o botão do Google Earth somente para arquivos KML/KMZ.
        caminho_google_earth = None

        if caminho_arquivo:
            try:
                caminho_verificado = os.fspath(caminho_arquivo)
                extensao = os.path.splitext(
                    caminho_verificado)[1].lower()

                if extensao in (".kml", ".kmz"):
                    caminho_google_earth = caminho_verificado

            except TypeError:
                caminho_google_earth = None

        if caminho_google_earth:
            botao_google_earth = QPushButton(
                self.tr("Abrir Google Earth Web"))

            botao_google_earth.setToolTip( self.tr(
                    "Abre o Google Earth Web e copia o caminho "
                    "do arquivo para a área de transferência."))

            botao_google_earth.clicked.connect(lambda _checked=False,
                caminho=caminho_google_earth:
                    self.abrir_google_earth_web(caminho))

            mensagem.layout().insertWidget(posicao_botao, botao_google_earth)
                
        bar.pushWidget(mensagem, level=nivel, duration=duracao)

        self._mensagem_atual = mensagem

    def abrir_google_earth_web(self, caminho_arquivo=None):
        """
        Abre o Google Earth Web e copia o caminho do arquivo
        KML/KMZ para a área de transferência.
        """
        if caminho_arquivo:
            try:
                caminho_normalizado = os.path.normpath(
                    os.path.abspath(
                        os.fspath(caminho_arquivo)))

                QGuiApplication.clipboard().setText(
                    caminho_normalizado)

            except (TypeError, OSError):
                pass  # nosec B110

        QDesktopServices.openUrl(
            QUrl("https://earth.google.com/web/"))

        # Substitui a mensagem de sucesso por uma orientação breve.
        QTimer.singleShot(250, lambda: self.mostrar_mensagem(self.tr(
                    "Clique em Novo > Importar arquivo > "
                    "Dispositivo local. O caminho do KMZ foi copiado."), "Info", duracao=5))

    def iniciar_progress_bar(self, total_steps):
        """
        Inicia e exibe uma barra de progresso na interface do usuário para o processo de exportação.

        Parâmetros:
        - total_steps (int): O número total de etapas a serem concluídas no processo de exportação.

        Funcionalidades:
        - Cria uma mensagem personalizada na barra de mensagens para acompanhar o progresso.
        - Configura e estiliza uma barra de progresso.
        - Adiciona a barra de progresso à barra de mensagens e a exibe na interface do usuário.
        - Define o valor máximo da barra de progresso com base no número total de etapas.
        - Retorna os widgets de barra de progresso e de mensagem para que possam ser atualizados durante a exportação.
        """
        progressMessageBar = self.iface.messageBar().createMessage(self.tr("Exportando camada..."))
        progressBar = QProgressBar()  # Cria uma instância da QProgressBar
        progressBar.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)  # Alinha a barra de progresso à esquerda e verticalmente ao centro
        progressBar.setFormat(self.tr("%p% - %v de %m etapas concluídas"))  # Define o formato da barra de progresso
        progressBar.setMinimumWidth(300)  # Define a largura mínima da barra de progresso

        # Estiliza a barra de progresso
        progressBar.setStyleSheet("""
            QProgressBar {
                border: 1px solid grey;
                border-radius: 2px;
                background-color: #cddbde;
                text-align: center;
            }
            QProgressBar::chunk {
                background-color: #55aaff;
                width: 5px;
                margin: 1px;
            }
            QProgressBar {
                min-height: 5px;}""")

        # Adiciona a progressBar ao layout da progressMessageBar e exibe na interface
        progressMessageBar.layout().addWidget(progressBar)
        self.iface.messageBar().pushWidget(progressMessageBar, Qgis.MessageLevel.Info)

        # Define o valor máximo da barra de progresso com base no número total de etapas
        progressBar.setMaximum(total_steps)

        return progressBar, progressMessageBar

    def export_raster_to_kml(self):
        """
        Exporta uma camada raster selecionada para o formato KMZ (KML + Imagens).

        Passos detalhados:
        1. Captura o tempo de início do processo.
        2. Verifica se uma camada raster está selecionada na treeView.
        3. Obtém o nome da camada selecionada e verifica se a camada existe no projeto.
        4. Inicia a barra de progresso para monitorar o processo de exportação.
        5. Reprojeta a camada raster e exporta as imagens necessárias.
        6. Cria o arquivo KML usando as imagens exportadas.
        7. Escolhe o local para salvar o arquivo KMZ.
        8. Cria o arquivo KMZ (ZIP) contendo o KML e as imagens.
        9. Atualiza a barra de progresso e limpa a barra de mensagem.
        10. Exibe uma mensagem informando o sucesso da exportação e o tempo de execução.

        Retorna:
        - None
        """
        start_time = time.time()  # Capturar o tempo de início

        # Verificar se alguma camada está selecionada na treeView
        indexes = self.dlg.treeViewListaRaster.selectedIndexes()
        if not indexes:
            self.mostrar_mensagem(self.tr("Nenhuma camada selecionada"), "Erro")
            return

        # Obter o nome da camada selecionada
        selected_layer_name = self.treeViewModel.itemFromIndex(indexes[0]).text()
        # Obter a camada pelo nome
        layers = QgsProject.instance().mapLayersByName(selected_layer_name)
        if not layers:
            self.mostrar_mensagem(self.tr("Camada não encontrada"), "Erro")
            return

        layer = layers[0]  # Obter a primeira camada encontrada

        # Iniciar a barra de progresso
        total_steps = 5  # Ajuste o número total de etapas conforme necessário
        progressBar, progressMessageBar = self.iniciar_progress_bar(total_steps)
        step = 0  # Inicializar o contador de etapas

        # Reprojetar a camada raster e exportar as imagens necessárias
        reprojected_layer, transformed_extent, output_image_path, legend_image_path = self.reproject_and_export_raster(layer, progressBar, step)
        if not reprojected_layer:
            return

        step += 2  # Atualizar o contador de etapas
        # Criar o arquivo KML usando as imagens exportadas
        kml_output_path = self.create_kml(reprojected_layer, transformed_extent, output_image_path, legend_image_path, progressBar, step)
        if not kml_output_path:
            return

        step += 2  # Atualizar o contador de etapas
        progressBar.setValue(step)  # Atualizar a barra de progresso

        end_time = time.time()  # Capturar o tempo de fim
        execution_time = end_time - start_time  # Calcular o tempo de execução

        # Escolher local para salvar o arquivo KMZ
        kmz_output_path = self.escolher_local_para_salvar(layer.name() + ".kmz", self.tr("Arquivos KMZ (*.kmz)"))
        if not kmz_output_path:
            progressBar.reset()
            self.iface.messageBar().clearWidgets()
            
            return

        # Criar o arquivo KMZ (ZIP)
        with zipfile.ZipFile(kmz_output_path, 'w') as kmz:
            kmz.write(kml_output_path, os.path.basename(kml_output_path))
            kmz.write(output_image_path, os.path.basename(output_image_path))
            kmz.write(legend_image_path, os.path.basename(legend_image_path))

        step += 1  # Atualizar o contador de etapas
        progressBar.setValue(step)  # Atualizar a barra de progresso

        self.iface.messageBar().clearWidgets()  # Limpar a barra de mensagem

        # Exibir mensagem de sucesso com o tempo de execução e caminhos dos arquivos
        self.mostrar_mensagem(self.tr("Camada exportada para KMZ em {execution_time:.2f} segundos").format(execution_time=execution_time), "Sucesso", caminho_pasta=os.path.dirname(kmz_output_path), caminho_arquivo=kmz_output_path)

    def reproject_and_export_raster(self, layer, progressBar, step):
        """
        Reprojeta uma camada raster para WGS84 e exporta uma imagem PNG da camada e sua legenda.

        Passos detalhados:
        1. Verifica se a camada está em WGS84 (EPSG:4326).
        2. Se não estiver em WGS84, reprojeta a camada para WGS84.
        3. Cria um caminho temporário para salvar o raster reprojetado.
        4. Configura a transformação de coordenadas e transforma a extensão da camada.
        5. Usa o GDAL para reprojetar o raster.
        6. Cria uma nova camada raster a partir do arquivo reprojetado.
        7. Se a camada já estiver em WGS84, usa a camada original.
        8. Atualiza a barra de progresso.
        9. Cria um arquivo temporário para a imagem PNG.
        10. Exporta a imagem raster para PNG, aplicando a renderização configurada.
        11. Atualiza a barra de progresso.
        12. Cria a imagem da legenda da camada.
        13. Retorna a camada reprojetada, a extensão transformada, o caminho da imagem PNG e o caminho da imagem da legenda.

        Retorna:
        - reprojected_layer: Camada raster reprojetada para WGS84.
        - transformed_extent: Extensão transformada da camada.
        - output_image_path: Caminho do arquivo PNG exportado.
        - legend_image_path: Caminho do arquivo de imagem da legenda.
        """
        # Verificar se a camada está em WGS84 (EPSG:4326)
        wgs84_crs = QgsCoordinateReferenceSystem('EPSG:4326')
        if layer.crs() != wgs84_crs:
            # Criar um caminho temporário para o raster reprojetado
            with tempfile.NamedTemporaryFile(suffix='.tif', delete=False) as tmp_file:
                reprojected_raster_path = tmp_file.name

            try:
                # Configurar a transformação de coordenadas
                transform = QgsCoordinateTransform(layer.crs(), wgs84_crs, QgsProject.instance())
                extent = layer.extent()
                transformed_extent = transform.transformBoundingBox(extent, QgsCoordinateTransform.TransformDirection.ForwardTransform)
                
                # Usar o GDAL para reprojetar o raster
                gdal.Warp(reprojected_raster_path, layer.source(), dstSRS='EPSG:4326')
                
                # Criar uma nova camada raster a partir do arquivo reprojetado
                reprojected_layer = QgsRasterLayer(reprojected_raster_path, layer.name() + '_wgs84')
                if not reprojected_layer.isValid():
                    self.mostrar_mensagem(self.tr("Erro ao reprojetar a camada para WGS84"), "Erro")
                    return None, None, None, None
            except Exception as e:
                self.mostrar_mensagem(self.tr("Erro ao reprojetar a camada: {error}").format(error=str(e)), "Erro")
                return None, None, None, None
        else:
            reprojected_layer = layer  # Usar a camada original se já estiver em WGS84
            transformed_extent = reprojected_layer.extent()  # Obter a extensão transformada

        # Atualizar a barra de progresso
        step += 1  # Incrementar o contador de etapas
        progressBar.setValue(step)  # Atualizar o valor da barra de progresso

        # Criar um arquivo temporário para a imagem PNG
        with tempfile.NamedTemporaryFile(suffix='.png', delete=False) as tmp_png_file:
            output_image_path = tmp_png_file.name  # Obter o caminho do arquivo PNG temporário

        # Exportar a imagem raster para PNG, aplicando a renderização configurada
        pipe = QgsRasterPipe()  # Criar um pipeline de raster
        pipe.set(layer.dataProvider().clone())  # Clonar o provedor de dados da camada
        pipe.set(layer.renderer().clone())  # Clonar o renderizador da camada

        file_writer = QgsRasterFileWriter(output_image_path)  # Criar um escritor de arquivos raster
        file_writer.writeRaster(
            pipe,  # Usar o pipeline de raster
            layer.width(),  # Largura da imagem
            layer.height(),  # Altura da imagem
            layer.extent(),  # Extensão da camada
            layer.crs())  # Sistema de referência de coordenadas da camada

        # Atualizar a barra de progresso
        step += 1  # Incrementar o contador de etapas
        progressBar.setValue(step)  # Atualizar o valor da barra de progresso

        # Criar a imagem da legenda
        legend_image_path = self.gerar_legenda_como_imagem(layer)  # Gerar a imagem da legenda
        if not legend_image_path:
            self.mostrar_mensagem(self.tr("Erro ao gerar a legenda da camada"), "Erro")
            return None, None, None, None

        return reprojected_layer, transformed_extent, output_image_path, legend_image_path  # Retornar os resultados

    def create_kml(self, reprojected_layer, transformed_extent, output_image_path, legend_image_path, progressBar, step):
        """
        Cria um arquivo KML com a camada raster reprojetada e uma imagem de legenda.

        Passos detalhados:
        1. Obtém a extensão da camada transformada.
        2. Cria um arquivo KML temporário.
        3. Cria um KML com GroundOverlay para a imagem raster.
        4. Adiciona a legenda como ScreenOverlay no KML.
        5. Salva o arquivo KML.
        6. Atualiza a barra de progresso.
        7. Retorna o caminho do arquivo KML criado.

        Retorna:
        - kml_output_path: Caminho do arquivo KML criado.
        """
        # Obter a extensão da camada transformada
        bbox = [transformed_extent.xMinimum(), transformed_extent.yMinimum(), transformed_extent.xMaximum(), transformed_extent.yMaximum()]

        # Criar KML com GroundOverlay
        with tempfile.NamedTemporaryFile(suffix='.kml', delete=False) as tmp_kml_file:
            kml_output_path = tmp_kml_file.name  # Obter o caminho do arquivo KML temporário

        kml = simplekml.Kml()  # Criar um objeto KML
        ground = kml.newgroundoverlay(name=reprojected_layer.name())  # Criar um GroundOverlay no KML
        ground.icon.href = os.path.basename(output_image_path)  # Definir o ícone como a imagem raster exportada (apenas o nome do arquivo)
        ground.latlonbox.north = bbox[3]  # Definir o limite norte da extensão
        ground.latlonbox.south = bbox[1]  # Definir o limite sul da extensão
        ground.latlonbox.east = bbox[2]  # Definir o limite leste da extensão
        ground.latlonbox.west = bbox[0]  # Definir o limite oeste da extensão

        # Adicionar a legenda como ScreenOverlay
        screen = kml.newscreenoverlay(name=self.tr("Legenda"))
        screen.icon.href = os.path.basename(legend_image_path)

        screen.overlayxy = simplekml.OverlayXY(x=0, y=0, xunits=simplekml.Units.fraction, yunits=simplekml.Units.fraction)

        screen.screenxy = simplekml.ScreenXY(x=0.015, y=0.04, xunits=simplekml.Units.fraction, yunits=simplekml.Units.fraction)

        # Define apenas a largura e deixa a altura preservar a proporção da imagem,
        # evitando que a legenda fique achatada.
        screen.size.x = 0.14
        screen.size.y = 0
        screen.size.xunits = simplekml.Units.fraction
        screen.size.yunits = simplekml.Units.fraction

        kml.save(kml_output_path)  # Salvar o arquivo KML

        # Atualizar a barra de progresso
        step += 2  # Incrementar o contador de etapas
        progressBar.setValue(step)  # Atualizar o valor da barra de progresso

        return kml_output_path  # Retornar o caminho do arquivo KML criado

    def _recortar_imagem_transparente(self, image, padding=8):
        """
        Recorta as bordas transparentes da imagem, mantendo uma pequena margem.
        Isso reduz bastante o espaço em branco da legenda.
        """
        if image.isNull():
            return image

        width = image.width()
        height = image.height()

        min_x, min_y = width, height
        max_x, max_y = -1, -1

        for y in range(height):
            for x in range(width):
                if QColor(image.pixel(x, y)).alpha() > 0:
                    if x < min_x:
                        min_x = x
                    if y < min_y:
                        min_y = y
                    if x > max_x:
                        max_x = x
                    if y > max_y:
                        max_y = y

        if max_x == -1 or max_y == -1:
            return image

        min_x = max(0, min_x - padding)
        min_y = max(0, min_y - padding)
        max_x = min(width - 1, max_x + padding)
        max_y = min(height - 1, max_y + padding)

        return image.copy(min_x, min_y, max_x - min_x + 1, max_y - min_y + 1)

    def _obter_modo_legenda_raster(self, layer):
        """
        Identifica o modo visual da legenda raster.

        A quantidade de classes não determina se a legenda é linear:
        uma rampa Linear pode possuir dezenas de classes internas.
        """
        renderer = layer.renderer()

        if not isinstance(renderer, QgsSingleBandPseudoColorRenderer):
            return "outro"

        try:
            shader = renderer.shader()

            if shader is None:
                return "outro"

            shader_fn = shader.rasterShaderFunction()

            if shader_fn is None or not hasattr(shader_fn, "colorRampType"):
                return "outro"

            ramp_type = shader_fn.colorRampType()

            # Comparação direta com o enum do QGIS 4.
            if ramp_type == Qgis.ShaderInterpolationMethod.Linear:
                return "linear"

            # Qualquer outro método de interpolação é tratado
            # como legenda formada por classes.
            return "discreto"

        except Exception:
            return "outro"

    def _estimar_tamanho_legenda_raster(self, layer):
        """
        Estima um tamanho de legenda mais inteligente com base
        no tipo de legenda raster.
        """
        largura_mm = 58
        modo = self._obter_modo_legenda_raster(layer)

        try:
            renderer = layer.renderer()
            legend_items = renderer.legendSymbologyItems() if renderer else []
            n_itens = len(legend_items)
        except Exception:
            n_itens = 0

        if modo == "linear":
            # A legenda linear mostra apenas nome, banda,
            # rampa contínua e valores mínimo/máximo.
            # O total de classes internas não interfere na altura.
            altura_mm = 34

        elif modo == "discreto":
            # Legenda categorizada/discreta:
            # cresce conforme o número de classes.
            altura_mm = 24 + (n_itens * 6.5)

        else:
            # Fallback intermediário
            altura_mm = 50 if n_itens <= 3 else 24 + (n_itens * 6.5)

        altura_mm = max(40, min(altura_mm, 220))

        return largura_mm, altura_mm

    def gerar_legenda_como_imagem(self, layer, page_width=None, page_height=None):
        """
        Gera uma imagem de legenda para a camada raster especificada.
        Ajusta automaticamente a área branca ao conteúdo da legenda.
        """
        project = QgsProject.instance()
        layout = QgsLayout(project)
        layout.initializeDefaults()

        # Remove itens padrão do layout
        for item in list(layout.items()):
            try:
                layout.removeLayoutItem(item)
            except Exception:
                pass  # nosec B110

        # Define tamanho adaptativo
        if page_width is None or page_height is None:
            page_width, page_height = self._estimar_tamanho_legenda_raster(layer)

        legend = QgsLayoutItemLegend(layout)
        legend.setTitle(self.tr("Legenda")) # "Subtitle"/título
        legend.setLinkedMap(None)

        root = QgsLayerTree()
        root.addLayer(layer)
        legend.model().setRootGroup(root)
        legend.updateLegend()

        layout.addLayoutItem(legend)

        try:
            legend.attemptMove(QgsLayoutPoint(2, 2, QgsUnitTypes.LayoutUnit.LayoutMillimeters))
        except Exception:
            pass  # nosec B110

        legend.setMinimumSize(
            QgsLayoutSize(
                page_width,
                page_height,
                QgsUnitTypes.LayoutUnit.LayoutMillimeters))

        legend.attemptResize(
            QgsLayoutSize(
                page_width,
                page_height,
                QgsUnitTypes.LayoutUnit.LayoutMillimeters))

        try:
            legend.adjustBoxSize()
        except Exception:
            pass  # nosec B110

        # Renderiza em uma área proporcional ao tamanho estimado
        escala = 12
        img_width = max(300, int(page_width * escala))
        img_height = max(220, int(page_height * escala))

        image = QImage(img_width, img_height, QImage.Format.Format_ARGB32)
        image.fill(Qt.GlobalColor.transparent)

        painter = QPainter(image)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)

        layout.render(
            painter,
            QRectF(0, 0, img_width, img_height),
            QRectF(0, 0, page_width, page_height))

        painter.end()

        # Recorta apenas o excesso transparente
        image = self._recortar_imagem_transparente(image, padding=10)

        with tempfile.NamedTemporaryFile(suffix='.png', delete=False) as tmp_legend_file:
            legend_image_path = tmp_legend_file.name
            image.save(legend_image_path, 'PNG')

        return legend_image_path
 
    def exportar_raster_dxf(self):
        """
        Exporta uma camada raster para o formato DXF. Dependendo do tipo da camada, 
        realiza uma exportação diferente:
        - Se a camada for um serviço de mapa (WMS/XYZ), exporta a visualização da área de trabalho.
        - Caso contrário, exporta a camada raster comum.

        Passos:
        1. Obtém a camada selecionada pelo usuário.
        2. Verifica se a camada é um serviço de mapa.
        3. Se for um serviço de mapa, exporta a visualização da área de trabalho.
        4. Se for uma camada raster comum, exporta a camada raster comum.
        """
        # Obtém os índices das camadas selecionadas na interface do usuário
        indexes = self.dlg.treeViewListaRaster.selectedIndexes()
        if not indexes:  # Verifica se alguma camada foi selecionada
            self.mostrar_mensagem(self.tr("Nenhuma camada selecionada"), "Erro")  # Mostra mensagem de erro
            return  # Encerra a função se nenhuma camada foi selecionada
        
        # Obtém o nome da camada selecionada
        selected_layer_name = self.treeViewModel.itemFromIndex(indexes[0]).text()
        
        # Obtém a camada pelo nome
        layers = QgsProject.instance().mapLayersByName(selected_layer_name)
        if not layers:  # Verifica se a camada foi encontrada
            self.mostrar_mensagem(self.tr("Camada não encontrada"), "Erro")  # Mostra mensagem de erro
            return  # Encerra a função se a camada não foi encontrada
        
        layer = layers[0]  # Obtém a primeira camada encontrada

        # Verificação para camadas de serviço de mapas
        if layer.providerType() in ['wms', 'xyz']:  # Verifica se a camada é um serviço de mapa (WMS/XYZ)
            self.exportar_visualizacao_para_dxf(layer)  # Exporta a visualização da área de trabalho
        else:  # Caso contrário
            self.exportar_raster_comum_para_dxf(layer)  # Exporta a camada raster comum

    def exportar_visualizacao_para_dxf(self, layer):
        """
        Exporta a visualização da área de trabalho do QGIS para o formato DXF.

        Passos:
        1. Inicia a barra de progresso.
        2. Captura a visualização do canvas do QGIS como uma imagem.
        3. Salva a imagem capturada como PNG.
        4. Solicita ao usuário o local para salvar o arquivo DXF.
        5. Cria um documento DXF e insere a imagem PNG.
        6. Salva o arquivo DXF.
        7. Atualiza a barra de progresso e mostra uma mensagem de sucesso.

        Parâmetros:
        - layer: A camada para a qual a visualização será exportada.
        """
        start_time = time.time()  # Inicia a contagem do tempo de execução
        total_steps = 5  # Define o número total de etapas para a barra de progresso
        progressBar, progressMessageBar = self.iniciar_progress_bar(total_steps)  # Inicia a barra de progresso
        
        canvas = self.iface.mapCanvas()  # Obtém o canvas do QGIS
        rect = canvas.extent()  # Obtém a extensão da visualização
        width = canvas.size().width()  # Obtém a largura do canvas
        height = canvas.size().height()  # Obtém a altura do canvas
        image = QImage(width, height, QImage.Format.Format_ARGB32)  # Cria uma imagem com as dimensões do canvas
        painter = QPainter(image)  # Cria um pintor para a imagem
        canvas.render(painter)  # Renderiza o canvas na imagem
        painter.end()  # Finaliza o pintor

        progressBar.setValue(1)  # Atualiza a barra de progresso

        # Salvar a imagem capturada
        temp_image_path = self.escolher_local_para_salvar(self.tr("visualizacao_qgis.png"), self.tr("Image Files (*.png)"))  # Solicita o caminho para salvar a imagem
        if not temp_image_path:  # Verifica se o caminho foi fornecido
            self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
            return  # Encerra a função se o caminho não foi fornecido
        if not image.save(temp_image_path):  # Salva a imagem como PNG
            self.mostrar_mensagem(self.tr("Erro ao salvar a imagem capturada"), "Erro")  # Mostra mensagem de erro
            self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
            return  # Encerra a função se ocorrer um erro

        progressBar.setValue(2)  # Atualiza a barra de progresso

        # Escolher local para salvar o arquivo DXF
        dxf_file_path = self.escolher_local_para_salvar(self.tr("visualizacao_qgis.dxf"), self.tr("DXF Files (*.dxf)"))  # Solicita o caminho para salvar o DXF
        if not dxf_file_path:  # Verifica se o caminho foi fornecido
            self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
            return  # Encerra a função se o caminho não foi fornecido

        progressBar.setValue(3)  # Atualiza a barra de progresso

        # Converter a imagem para DXF
        doc = ezdxf.new(dxfversion='R2013')  # Cria um novo documento DXF
        msp = doc.modelspace()  # Obtém o espaço do modelo
        image_def = doc.add_image_def(filename=os.path.abspath(temp_image_path), size_in_pixel=(width, height))  # Adiciona a definição da imagem
        insert_point = (rect.xMinimum(), rect.yMinimum())  # Define o ponto de inserção
        msp.add_image(insert=insert_point, size_in_units=(rect.width(), rect.height()), image_def=image_def, rotation=0)  # Define a rotação

        progressBar.setValue(4)  # Atualiza a barra de progresso

        # Salvar o arquivo DXF
        doc.saveas(dxf_file_path)  # Salva o documento DXF

        progressBar.setValue(5)  # Atualiza a barra de progresso

        end_time = time.time()  # Calcula o tempo de execução
        execution_time = end_time - start_time  # Calcula o tempo total de execução
        self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
        self.mostrar_mensagem(self.tr("Visualização da área de trabalho exportada para DXF em {execution_time:.2f} segundos").format(execution_time=execution_time), "Sucesso", caminho_pasta=os.path.dirname(dxf_file_path), caminho_arquivo=dxf_file_path)

    def exportar_raster_comum_para_dxf(self, layer):
        """
        Exporta uma camada raster comum para o formato DXF.
        
        Passos:
        1. Inicia a barra de progresso.
        2. Solicita ao usuário para salvar o arquivo raster como TIFF.
        3. Solicita ao usuário para salvar o arquivo DXF.
        4. Configura os parâmetros do raster, incluindo resolução e extensão.
        5. Cria e salva o arquivo TIFF.
        6. Converte o TIFF para PNG.
        7. Deleta o arquivo TIFF.
        8. Cria um documento DXF e insere a imagem PNG.
        9. Salva o arquivo DXF.
        10. Atualiza a barra de progresso e mostra uma mensagem de sucesso.

        Parâmetros:
        - layer: A camada raster a ser exportada.
        """
        start_time = time.time()  # Inicia a contagem do tempo de execução
        total_steps = 100  # Define o número total de etapas para a barra de progresso
        progressBar, progressMessageBar = self.iniciar_progress_bar(total_steps)  # Inicia a barra de progresso

        progressBar.setValue(10)  # Atualiza a barra de progresso
        raster_file_path_tif = self.escolher_local_para_salvar(f"{layer.name()}.tif", self.tr("Image Files (*.tif)"))  # Solicita o caminho para salvar o TIFF
        if not raster_file_path_tif:  # Verifica se o caminho foi fornecido
            self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
            return  # Encerra a função se o caminho não foi fornecido
        
        progressBar.setValue(20)  # Atualiza a barra de progresso
        dxf_file_path = self.escolher_local_para_salvar(f"{layer.name()}.dxf", self.tr("DXF Files (*.dxf)"))  # Solicita o caminho para salvar o DXF
        if not dxf_file_path:  # Verifica se o caminho foi fornecido
            self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
            return  # Encerra a função se o caminho não foi fornecido
        
        progressBar.setValue(30)  # Atualiza a barra de progresso
        resolution_multiplier = 8  # Define o multiplicador de resolução
        provider = layer.dataProvider()  # Obtém o provedor de dados da camada
        extent = layer.extent()  # Obtém a extensão da camada
        width = layer.width() * resolution_multiplier  # Calcula a largura com base no multiplicador de resolução
        height = layer.height() * resolution_multiplier  # Calcula a altura com base no multiplicador de resolução
        file_writer = QgsRasterFileWriter(raster_file_path_tif)  # Cria o escritor de arquivos raster
        pipe = QgsRasterPipe()  # Cria o pipe raster
        if not pipe.set(provider.clone()):  # Clona o provedor de dados do raster
            self.mostrar_mensagem(self.tr("Erro ao clonar o provedor de dados do raster"), "Erro")  # Mostra mensagem de erro
            self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
            return  # Encerra a função se ocorrer um erro
        if not pipe.set(layer.renderer().clone()):  # Clona o renderizador do raster
            self.mostrar_mensagem(self.tr("Erro ao clonar o renderizador do raster"), "Erro")  # Mostra mensagem de erro
            self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
            return  # Encerra a função se ocorrer um erro
        if file_writer.writeRaster(pipe, width, height, extent, layer.crs()) != QgsRasterFileWriter.WriterError.NoError:  # Escreve o raster no arquivo TIFF
            self.mostrar_mensagem(self.tr("Erro ao salvar o arquivo raster"), "Erro")  # Mostra mensagem de erro
            self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
            return  # Encerra a função se ocorrer um erro
        
        progressBar.setValue(50)  # Atualiza a barra de progresso
        if not os.path.exists(raster_file_path_tif):  # Verifica se o arquivo TIFF foi salvo
            self.mostrar_mensagem(self.tr("Erro ao salvar o arquivo raster"), "Erro")  # Mostra mensagem de erro
            self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
            return  # Encerra a função se o arquivo não foi salvo
        
        # Converter TIFF para PNG
        raster_file_path_png = raster_file_path_tif.replace(".tif", ".png")  # Define o caminho do arquivo PNG
        image = QImage()  # Cria uma instância de QImage
        if not image.load(raster_file_path_tif):  # Carrega o arquivo TIFF
            self.mostrar_mensagem(self.tr("Erro ao carregar o arquivo TIFF para conversão"), "Erro")  # Mostra mensagem de erro
            self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
            return  # Encerra a função se ocorrer um erro
        progressBar.setValue(60)  # Atualiza a barra de progresso durante o carregamento da imagem
        
        if not image.save(raster_file_path_png, "PNG"):  # Salva a imagem como PNG
            self.mostrar_mensagem(self.tr("Erro ao salvar o arquivo como PNG"), "Erro")  # Mostra mensagem de erro
            self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
            return  # Encerra a função se ocorrer um erro
        progressBar.setValue(70)  # Atualiza a barra de progresso durante a conversão para PNG
        
        # Deletar o arquivo TIFF
        os.remove(raster_file_path_tif)  # Deleta o arquivo TIFF
        
        progressBar.setValue(80)  # Atualiza a barra de progresso após a exclusão do TIFF
        doc = ezdxf.new(dxfversion='R2010')  # Cria um novo documento DXF
        msp = doc.modelspace()  # Obtém o espaço do modelo
        image_def = doc.add_image_def(filename=os.path.abspath(raster_file_path_png), size_in_pixel=(width, height))  # Adiciona a definição da imagem
        insert_point = (extent.xMinimum(), extent.yMinimum())  # Define o ponto de inserção
        msp.add_image(insert=insert_point,  # Adiciona a imagem ao espaço do modelo
                      size_in_units=(extent.width(), extent.height()),  # Define o tamanho da imagem em unidades
                      image_def=image_def,  # Define a imagem
                      rotation=0)  # Define a rotação
        
        progressBar.setValue(90)  # Atualiza a barra de progresso durante a criação do DXF
        doc.saveas(dxf_file_path)  # Salva o documento DXF
        progressBar.setValue(100)  # Atualiza a barra de progresso após salvar o DXF
        
        end_time = time.time()  # Calcula o tempo de execução
        execution_time = end_time - start_time  # Calcula o tempo total de execução
        self.iface.messageBar().clearWidgets()  # Limpa a barra de mensagens
        self.mostrar_mensagem(self.tr("Camada exportada para DXF em {execution_time:.2f} segundos").format(execution_time=execution_time), "Sucesso", caminho_pasta=os.path.dirname(dxf_file_path), caminho_arquivo=dxf_file_path)

    def abrir_visualizador_raster_3d(self):
        """
        Abre o visualizador 3D próprio para o raster selecionado.

        A camada é recuperada pelo ID armazenado no Qt.UserRole, evitando
        ambiguidades quando existirem camadas com nomes repetidos.
        """
        indexes = self.dlg.treeViewListaRaster.selectedIndexes()
        if not indexes:
            self.mostrar_mensagem(self.tr("Nenhuma camada raster selecionada."), "Aviso")
            return

        item = self.treeViewModel.itemFromIndex(indexes[0])
        layer_id = item.data(Qt.ItemDataRole.UserRole) if item else None
        layer = QgsProject.instance().mapLayer(layer_id) if layer_id else None

        if not isinstance(layer, QgsRasterLayer) or not layer.isValid():
            self.mostrar_mensagem(self.tr("Selecione uma camada raster válida."), "Erro")
            return

        if layer.bandCount() < 1:
            self.mostrar_mensagem(self.tr("O raster selecionado não possui bandas disponíveis."), "Erro")
            return

        if layer.providerType().lower() in ("wms", "xyz", "arcgismapserver", "arcgisfeatureserver"):
            self.mostrar_mensagem(self.tr("A visualização 3D inicial aceita apenas rasters locais de elevação."), "Aviso")
            return

        visualizador_existente = self._visualizadores_raster_3d.get(layer.id())
        if visualizador_existente is not None:
            try:
                visualizador_existente.show()
                visualizador_existente.raise_()
                visualizador_existente.activateWindow()
                return
            except RuntimeError:
                self._visualizadores_raster_3d.pop(layer.id(), None)

        try:
            visualizador = VisualizadorRaster3DManager(
                raster_layer=layer,
                parent=self.dlg,
                ui_manager=self)

            visualizador.fechado.connect(self._remover_referencia_visualizador_raster_3d)
            self._visualizadores_raster_3d[layer.id()] = visualizador

            visualizador.show()
            visualizador.raise_()
            visualizador.activateWindow()

        except Exception as e:
            self.mostrar_mensagem(self.tr("Erro ao abrir o visualizador 3D: {error}").format(error=str(e)), "Erro", duracao=5)

    def _remover_referencia_visualizador_raster_3d(self, layer_id):
        """Remove a referência da janela 3D quando ela é fechada."""
        self._visualizadores_raster_3d.pop(layer_id, None)

class FerramentaCoordenadaRaster3D(QObject):
    """
    Captura uma coordenada da superfície 3D através de Ctrl + clique.

    Regras:
    - mantém apenas uma coordenada por vez;
    - um novo clique substitui a coordenada anterior;
    - a coordenada permanece visível até novo clique;
    - ao desativar a ferramenta, a coordenada é removida.
    """
    coordenadaCapturada = pyqtSignal(float, float, float)

    def __init__(self, visualizador):
        super().__init__(visualizador)

        self.visualizador = visualizador
        self.ativa = False

        self._ponto_cena = None
        self._label = None
        self._marcador = None

        self.visualizador.view.ctrlCliqueCoordenada.connect(self._ao_ctrl_clique)
        self.visualizador.view.cameraAlterada.connect(self._reposicionar_elementos)
        self.visualizador.view.cenaRenderizada.connect(self._reposicionar_elementos)

    def ativar(self):
        self.ativa = True

        self.visualizador.view._captura_coordenada_ativa = (True)
        self.visualizador.view.setFocus()

    def desativar(self):
        self.ativa = False

        self.visualizador.view._captura_coordenada_ativa = (False)

        try:
            self.visualizador.view.setCursor(self.visualizador.view._cursor_reposo)
        except Exception:
            pass  # nosec B110

        self.limpar()

    def limpar(self):
        """
        Remove a coordenada atualmente exibida.
        """
        self._ponto_cena = None

        if self._label is not None:
            self._label.hide()
            self._label.deleteLater()
            self._label = None

        if self._marcador is not None:
            self._marcador.hide()
            self._marcador.deleteLater()
            self._marcador = None

    def _ao_ctrl_clique(self, posicao):
        """
        Substitui a coordenada anterior pela nova.
        """
        if not self.ativa:
            return

        ponto = self._obter_ponto_cena(posicao)

        if ponto is None:
            return

        exagero = max(1.0e-12, float(self.visualizador.spin_exagero.value()))

        x_real = (float(ponto[0]) + self.visualizador._x_centro)
        y_real = (float(ponto[1]) + self.visualizador._y_centro)
        z_real = (float(ponto[2]) / exagero+ self.visualizador._z_centro)

        # O novo clique remove imediatamente
        # a coordenada anterior.
        self.limpar()

        self._ponto_cena = np.asarray(ponto, dtype=np.float64)

        self._criar_elementos(x_real, y_real, z_real)
        self.coordenadaCapturada.emit(x_real, y_real, z_real)

    def _obter_ponto_cena(self, posicao):
        """
        Lança um raio a partir do clique e encontra
        a primeira interseção com o MDT visível.

        A busca é limitada somente à extensão XY
        do terreno, evitando percorrer todo o volume
        entre os planos near/far da câmera.
        """
        view = self.visualizador.view

        try:
            largura = max(2.0, float(view.width()))

            altura = max(2.0, float(view.height()))

            # Mouse -> coordenadas normalizadas OpenGL.
            ndc_x = (2.0 * float(posicao.x()) / (largura - 1.0) - 1.0)
            ndc_y = (1.0 - 2.0 * float(posicao.y()) / (altura - 1.0))

            modelview = (view.viewMatrix())

            try:
                projection = (view.projectionMatrix())

            except TypeError:
                viewport_view = (view.getViewport())

                projection = (view.projectionMatrix(viewport_view, viewport_view))

            matriz = (projection * modelview)

            resultado = (matriz.inverted())

            if isinstance(resultado, tuple):

                matriz_inversa = (resultado[0])
                invertivel = bool(resultado[1])

            else:
                matriz_inversa = (resultado)
                invertivel = True

            if not invertivel:
                return None

            perto_clip = QVector4D(ndc_x, ndc_y, -1.0, 1.0)
            longe_clip = QVector4D(ndc_x, ndc_y, 1.0, 1.0)

            perto = (matriz_inversa * perto_clip)

            longe = (matriz_inversa * longe_clip)

            if (abs(float(perto.w())) <= 1e-12
                or abs(float(longe.w())) <= 1e-12):

                return None

            ponto_perto = np.array(
                (float(perto.x()) / float(perto.w()),
                    float(perto.y()) / float(perto.w()),
                    float(perto.z()) / float(perto.w())),
                dtype=np.float64)

            ponto_longe = np.array(
                (float(longe.x()) / float(longe.w()),
                    float(longe.y()) / float(longe.w()),
                    float(longe.z()) / float(longe.w())),
                dtype=np.float64)

            direcao = (ponto_longe - ponto_perto)

            # Prepara UMA única vez a geometria visual.
            vertices_visuais = (self.visualizador ._vertices_com_exagero())

            if (vertices_visuais is None
                or len(vertices_visuais) == 0):

                return None

            z_grade = (vertices_visuais[:, 2].reshape(self.visualizador._grade_y, self.visualizador._grade_x))

            # Extensão do MDT em coordenadas da cena.
            x_min = float(np.min(vertices_visuais[:, 0]))
            x_max = float(np.max(vertices_visuais[:, 0]))
            y_min = float(np.min(vertices_visuais[:, 1]))
            y_max = float(np.max(vertices_visuais[:, 1]))

            # Limita o raio à caixa XY ocupada pelo MDT.
            t_entrada = 0.0
            t_saida = 1.0

            for origem, delta, minimo, maximo in (
                (ponto_perto[0],
                    direcao[0],
                    x_min,
                    x_max),
                (ponto_perto[1],
                    direcao[1],
                    y_min,
                    y_max)):

                if abs(float(delta)) <= 1e-15:
                    if (origem < minimo
                        or origem > maximo):

                        return None

                    continue

                t1 = ((minimo - origem) / delta)
                t2 = ((maximo - origem) / delta)

                if t1 > t2:
                    t1, t2 = t2, t1

                t_entrada = max(t_entrada, float(t1))
                t_saida = min(t_saida, float(t2))

                if t_entrada > t_saida:
                    return None

            t_entrada = max(0.0, t_entrada)
            t_saida = min(1.0, t_saida)

            if t_entrada > t_saida:
                return None

            # Agora os passos são distribuídos SOMENTE
            # sobre a região atravessada pelo terreno.
            quantidade_passos = max(256, min(3000, int(
                        max(self.visualizador._grade_x,
                            self.visualizador._grade_y) * 2)))

            t_anterior = None
            diferenca_anterior = None

            for indice in range(quantidade_passos + 1):

                fator = (indice / quantidade_passos)

                t = (t_entrada + (t_saida - t_entrada) * fator)

                ponto = (ponto_perto + direcao * t)

                x_real = (float(ponto[0]) + self.visualizador._x_centro)

                y_real = (float(ponto[1]) + self.visualizador._y_centro)

                z_superficie = (self.visualizador ._amostrar_z_visual_malha_3d(x_real, y_real, z_grade))

                # NoData quebra a sequência.
                if z_superficie is None:
                    t_anterior = None
                    diferenca_anterior = None
                    continue

                diferenca = (float(ponto[2]) - float(z_superficie))

                # Se caiu praticamente sobre a superfície.
                if abs(diferenca) <= 1e-7:
                    ponto[2] = float(z_superficie)

                    return ponto

                if (diferenca_anterior is not None
                    and t_anterior is not None
                    and diferenca_anterior
                        * diferenca <= 0.0):

                    t_min = (t_anterior)
                    t_max = t

                    diferenca_min = (diferenca_anterior)

                    # Refina a interseção.
                    for _ in range(28):
                        t_meio = (0.5 * (t_min + t_max))

                        ponto_meio = (ponto_perto + direcao * t_meio)

                        x_meio = (float(ponto_meio[0])
                            + self.visualizador._x_centro)

                        y_meio = (float(ponto_meio[1])
                            + self.visualizador._y_centro)

                        z_meio = (self.visualizador
                            ._amostrar_z_visual_malha_3d(
                                x_meio, y_meio, z_grade))

                        if z_meio is None:
                            break

                        diferenca_meio = ( float(ponto_meio[2])
                            - float(z_meio))

                        if (diferenca_min * diferenca_meio <= 0.0):

                            t_max = (t_meio)

                        else:
                            t_min = (t_meio)

                            diferenca_min = (diferenca_meio)

                    t_final = (0.5 * (t_min + t_max))

                    ponto_final = (ponto_perto + direcao * t_final)

                    x_final = (float(ponto_final[0])
                        + self.visualizador._x_centro)

                    y_final = (float(ponto_final[1])
                        + self.visualizador._y_centro)

                    z_final = (self.visualizador
                        ._amostrar_z_visual_malha_3d(
                            x_final,
                            y_final,
                            z_grade))

                    if z_final is None:
                        return None

                    # O marcador é colocado exatamente
                    # na superfície visual encontrada.
                    ponto_final[2] = float(
                        z_final)

                    return ponto_final

                t_anterior = t
                diferenca_anterior = (diferenca)

            return None

        except Exception as e:
            QgsMessageLog.logMessage(f"Erro ao capturar coordenada 3D: {repr(e)}", "Tempo Salvo 3D", Qgis.MessageLevel.Warning)

            return None

    def _criar_elementos(self, x, y, z):
        """
        Cria o marcador e a caixa de coordenadas.
        """
        view = self.visualizador.view
        self._marcador = QLabel(view)
        self._marcador.setFixedSize(10, 10)

        self._marcador.setStyleSheet(
            "background-color: rgb(255, 48, 48);"
            "border: 1px solid rgb(120, 0, 0);"
            "border-radius: 5px;")

        self._marcador.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)

        self._label = QLabel(view)
        self._label.setText(
            f"X: {x:.3f}\n"
            f"Y: {y:.3f}\n"
            f"Z: {z:.3f}")

        self._label.setStyleSheet(
            "QLabel {"
            "background-color: rgba(255, 255, 255, 235);"
            "border: 1px solid rgba(0, 0, 0, 100);"
            "border-radius: 4px;"
            "padding: 5px 7px;"
            "color: rgb(32, 33, 36);"
            "}")

        self._label.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)

        self._label.adjustSize()

        self._marcador.show()
        self._label.show()

        self._reposicionar_elementos()

    def _reposicionar_elementos(self):
        """
        Mantém a caixa e o marcador ligados ao ponto 3D
        mesmo após girar, deslocar ou aproximar a câmera.
        """
        if (self._ponto_cena is None
            or self._label is None
            or self._marcador is None):

            return

        view = self.visualizador.view

        try:
            modelview = view.viewMatrix()

            try:
                projection = (view.projectionMatrix())

            except TypeError:
                viewport_view = view.getViewport()

                projection = (view.projectionMatrix( viewport_view, viewport_view))

            vetor = QVector4D(
                float(self._ponto_cena[0]),
                float(self._ponto_cena[1]),
                float(self._ponto_cena[2]),
                1.0)

            clip = (projection * modelview * vetor)

            w = float(clip.w())

            if w <= 1.0e-12:
                self._label.hide()
                self._marcador.hide()
                return

            ndc_x = (float(clip.x()) / w)
            ndc_y = (float(clip.y()) / w)
            ndc_z = (float(clip.z()) / w)

            if (ndc_x < -1.0
                or ndc_x > 1.0
                or ndc_y < -1.0
                or ndc_y > 1.0
                or ndc_z < -1.0
                or ndc_z > 1.0):

                self._label.hide()
                self._marcador.hide()
                return

            x_tela = ((ndc_x + 1.0) * 0.5 * float(view.width()))

            y_tela = ((1.0 - (ndc_y + 1.0) * 0.5) * float(view.height()))

            self._marcador.move(
                int(round(x_tela - 5)),
                int(round(y_tela - 5)))

            x_label = int(round(x_tela + 12))

            y_label = int(round( y_tela - self._label.height() - 12))

            x_label = max(0, min(x_label, max(0, view.width() - self._label.width())))

            y_label = max(0, min(y_label, max(0, view.height() - self._label.height())))

            self._label.move(x_label, y_label)

            self._marcador.show()
            self._label.show()

            self._marcador.raise_()
            self._label.raise_()

        except Exception:
            pass  # nosec B110

class GradientGLViewWidget(gl.GLViewWidget):
    """
    GLViewWidget com suporte opcional a fundo em gradiente.
    O gradiente é desenhado atrás da renderização 3D.
    """
    cameraAlterada = pyqtSignal()
    cenaRenderizada = pyqtSignal()
    ctrlCliqueCoordenada = pyqtSignal(object)
    cliqueMedicao = pyqtSignal(object)
    finalizarMedicao = pyqtSignal()
    atalhoMedirDistancia = pyqtSignal()
    atalhoMedirArea = pyqtSignal()

    iniciarArrasteVerticeMedicao = pyqtSignal(object)
    moverArrasteVerticeMedicao = pyqtSignal(object)
    finalizarArrasteVerticeMedicao = pyqtSignal(object)

    inserirVerticeSegmentoMedicao = pyqtSignal(object)

    def __init__(self, parent=None):
        super().__init__(parent)

        formato = QSurfaceFormat(self.format())
        formato.setDepthBufferSize(24)
        formato.setStencilBufferSize(8)
        formato.setSamples(4)
        self.setFormat(formato)

        # FBO auxiliar sem MSAA usado somente para leitura do depth buffer.
        self._fbo_depth_oclusao = 0
        self._rbo_depth_oclusao = 0
        self._fbo_depth_tamanho = None
        self._viewport_depth_leitura = None

        self._usar_gradiente_ceu = False

        self._cor_topo = QColor(90, 165, 235)
        self._cor_base = QColor(242, 247, 252)

        # Eixo XYZ de orientação fixo no canto inferior esquerdo.
        self._corner_axis_visible = False
        self._corner_axis_size = 55.0
        self._corner_axis_margin = 28.0
        self._corner_axis_line_width = 3.0

        self.setAutoFillBackground(False)

        try:
            self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        except Exception:
            pass  # nosec B110

        # Permite controlar diretamente a navegação da câmera.
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setMouseTracking(True)
        self.setContextMenuPolicy(Qt.ContextMenuPolicy.NoContextMenu)

        # Captura de coordenadas por Ctrl + clique.
        self._captura_coordenada_ativa = False
        self._captura_medicao_ativa = False
        self._medicao_finaliza_direita = False

        self._previa_medicao_ativa = False
        self._previa_medicao_inicio = None
        self._previa_medicao_mouse = None
        self._previa_area_pontos = []

        # Edição interativa dos vértices das medições.
        self._vertices_editaveis_medicao = []

        self._vertice_medicao_hover = None
        self._arraste_vertice_medicao = None

        self._tolerancia_vertice_medicao_px = 12.0

        # Arestas nas quais um novo vértice pode
        # ser inserido.
        self._segmentos_editaveis_medicao = []

        self._segmento_medicao_hover = None

        self._tolerancia_segmento_medicao_px = 10.0

        self._hachura_area_final_ativa = False
        self._hachura_area_pontos = []

        # PAN com o botão direito.
        self._panning = False
        self._lastPosPan = None

        # Sensibilidade do deslocamento.
        self._sens = 0.25

        # Compensação quando a câmera estiver muito próxima.
        self._pan_zoom_boost = 2.5
        self._pan_zoom_boost_max = 5.0

        # Rotação com o botão esquerdo.
        self._rotating = False
        self._lastPosRot = None
        self._rot_sx = 0.0
        self._rot_sy = 0.0

        # Suavização e sensibilidade iguais às da malha.
        self._rot_alpha = 0.25
        self._rot_sens = 0.35

        # Distância correspondente ao enquadramento inicial.
        self._zoom_center_distance = 200.0

        # Cursor em repouso.
        self._cursor_reposo = Qt.CursorShape.OpenHandCursor

        try:
            self.setCursor(self._cursor_reposo)
        except Exception:
            pass  # nosec B110

    def iniciar_previa_medicao(self, ponto_cena):
        """
        Inicia ou continua a linha temporária da medição.

        Mantém a última posição conhecida do mouse para que
        a hachura não desapareça entre cliques consecutivos.
        """
        self._previa_medicao_ativa = True
        self._previa_medicao_inicio = np.asarray(ponto_cena, dtype=np.float64)
        self.update()

    def limpar_previa_medicao(self):
        """
        Remove a linha e a hachura temporárias da medição
        e descarta a última posição conhecida do mouse.
        """
        self._previa_medicao_ativa = False
        self._previa_medicao_inicio = None
        self._previa_medicao_mouse = None
        self._previa_area_pontos = []

        self.update()

    def atualizar_previa_area(self, pontos_cena):
        """
        Atualiza os vértices já confirmados da área.
        A hachura passa a aparecer a partir de 2 pontos.
        """
        self._previa_area_pontos = [
            np.asarray(ponto, dtype=np.float64)
            for ponto in pontos_cena]

        self.update()

    def _desenhar_hachura_area_final(self, painter):
        """
        Desenha a hachura somente para uma área já fechada.
        """
        if not self._hachura_area_final_ativa:
            return

        if len(self._hachura_area_pontos) < 3:
            return

        pontos_tela = []

        for ponto in self._hachura_area_pontos:
            posicao = self._projetar_ponto_cena_para_tela(ponto)

            if posicao is None:
                return

            pontos_tela.append(posicao)

        caminho = QPainterPath()
        caminho.moveTo(pontos_tela[0])

        for ponto in pontos_tela[1:]:
            caminho.lineTo(ponto)

        caminho.closeSubpath()

        painter.save()

        brush = QBrush(QColor(255, 170, 0, 90), Qt.BrushStyle.BDiagPattern)

        painter.fillPath(caminho, brush)

        pen = QPen(QColor(255, 170, 0, 220))
        pen.setWidth(1)

        painter.setPen(pen)
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.drawPath(caminho)

        painter.restore()

    def definir_hachura_area_final(self, pontos_cena):
        """
        Mantém a hachura somente depois que a área for concluída.
        """
        self._hachura_area_pontos = [
            np.asarray(ponto, dtype=np.float64)
            for ponto in pontos_cena]

        self._hachura_area_final_ativa = len(self._hachura_area_pontos) >= 3
        self.update()

    def definir_vertices_editaveis_medicao(self, vertices):
        """
        Registra os vértices das medições concluídas que
        poderão ser movimentados com o mouse.

        Cada item deve possuir:
        - tipo: "distancia" ou "area";
        - indice;
        - cena.
        """
        saida = []

        for item in vertices or []:
            try:
                saida.append({
                    "tipo":
                        str(item["tipo"]),

                    "indice":
                        int(item["indice"]),

                    "cena":
                        np.asarray(
                            item["cena"],
                            dtype=np.float64)})

            except (KeyError, TypeError, ValueError) as erro:
                QgsMessageLog.logMessage(f"Vértice editável de medição ignorado: {erro}", "Tempo Salvo Tools", Qgis.MessageLevel.Warning)

        self._vertices_editaveis_medicao = saida

        self.update()

    def definir_segmentos_editaveis_medicao(self, segmentos):
        """
        Registra os segmentos das medições nos quais
        poderá ser inserido um novo vértice.

        Cada segmento pode possuir também a polilinha
        real acompanhando a superfície do MDT.
        """
        saida = []

        for item in segmentos or []:
            try:
                cena_inicio = np.asarray(
                    item["cena_inicio"],
                    dtype=np.float64)

                cena_fim = np.asarray(
                    item["cena_fim"],
                    dtype=np.float64)

                pontos_segmento = item.get(
                    "cena_segmento")

                if pontos_segmento is None:
                    pontos_segmento = np.asarray(
                        [cena_inicio, cena_fim],
                        dtype=np.float64)

                else:
                    pontos_segmento = np.asarray(
                        pontos_segmento,
                        dtype=np.float64)

                    if (pontos_segmento.ndim != 2
                        or pontos_segmento.shape[0] < 2
                        or pontos_segmento.shape[1] < 3):

                        pontos_segmento = np.asarray(
                            [cena_inicio, cena_fim],
                            dtype=np.float64)

                saida.append({
                    "tipo":
                        str(item["tipo"]),

                    "indice_inicio":
                        int(item["indice_inicio"]),

                    "indice_fim":
                        int(item["indice_fim"]),

                    "indice_insercao":
                        int(item["indice_insercao"]),

                    "cena_inicio":
                        cena_inicio,

                    "cena_fim":
                        cena_fim,

                    "cena_segmento":
                        pontos_segmento})

            except (KeyError, TypeError, ValueError) as erro:
                QgsMessageLog.logMessage(f"Segmento editável de medição ignorado: {erro}", "Tempo Salvo Tools", Qgis.MessageLevel.Warning)

        self._segmentos_editaveis_medicao = (saida)

        self.update()

    def limpar_segmentos_editaveis_medicao(self):
        """
        Remove os segmentos disponíveis para
        inserção de novos vértices.
        """
        self._segmentos_editaveis_medicao = []
        self._segmento_medicao_hover = None

        self.update()

    def _obter_segmento_editavel_medicao(self, posicao):
        """
        Localiza a aresta editável mais próxima do mouse
        utilizando a polilinha real sobre o MDT.
        """
        if not self._segmentos_editaveis_medicao:
            return None

        px = float(posicao.x())
        py = float(posicao.y())

        tolerancia = float(self._tolerancia_segmento_medicao_px)

        melhor = None
        melhor_distancia = (tolerancia * tolerancia)

        for item in self._segmentos_editaveis_medicao:

            pontos_cena = item.get("cena_segmento")

            if pontos_cena is None:
                continue

            pontos_tela = []

            for ponto_cena in pontos_cena:
                ponto_tela = (self._projetar_ponto_cena_para_tela(ponto_cena))

                if ponto_tela is not None:
                    pontos_tela.append(ponto_tela)

            if len(pontos_tela) < 2:
                continue

            # Próximo aos extremos, quem manda é a edição do próprio vértice.
            inicio = pontos_tela[0]
            fim = pontos_tela[-1]

            distancia_inicio = math.hypot(
                px - float(inicio.x()),
                py - float(inicio.y()))

            distancia_fim = math.hypot(
                px - float(fim.x()),
                py - float(fim.y()))

            limite_vertice = (float(self._tolerancia_vertice_medicao_px) + 3.0)

            if (distancia_inicio <= limite_vertice
                or distancia_fim <= limite_vertice):

                continue

            # Procura o ponto mais próximo ao longo de toda a polilinha projetada.
            for indice in range(
                len(pontos_tela) - 1):

                a = pontos_tela[indice]
                b = pontos_tela[indice + 1]

                ax = float(a.x())
                ay = float(a.y())

                bx = float(b.x())
                by = float(b.y())

                dx = (bx - ax)
                dy = (by - ay)

                comprimento_quadrado = (dx * dx + dy * dy)

                if comprimento_quadrado <= 1e-12:
                    continue

                fator = (((px - ax) * dx + (py - ay) * dy) / comprimento_quadrado)
                fator = max(0.0, min(1.0, fator))

                qx = (ax + fator * dx)
                qy = (ay + fator * dy)

                distancia_quadrado = ((px - qx) ** 2 + (py - qy) ** 2)

                if distancia_quadrado > melhor_distancia:
                    continue

                melhor_distancia = (distancia_quadrado)

                melhor = {
                    "tipo":
                        item["tipo"],

                    "indice_inicio":
                        item["indice_inicio"],

                    "indice_fim":
                        item["indice_fim"],

                    "indice_insercao":
                        item["indice_insercao"],

                    "cena_inicio":
                        np.asarray(item["cena_inicio"], dtype=np.float64).copy(),

                    "cena_fim":
                        np.asarray(item["cena_fim"], dtype=np.float64).copy(),

                    "cena_segmento":
                        np.asarray(pontos_cena, dtype=np.float64).copy(),

                    "pontos_tela":
                        list(pontos_tela),

                    "indice_trecho":
                        indice,

                    "fator":
                        float(fator),

                    "ponto_tela":
                        QPointF(qx, qy)}

        return melhor

    def limpar_vertices_editaveis_medicao(self):
        """
        Remove todo o estado interativo das
        medições editáveis.
        """
        self._vertices_editaveis_medicao = []
        self._segmentos_editaveis_medicao = []

        self._vertice_medicao_hover = None
        self._segmento_medicao_hover = None

        self._arraste_vertice_medicao = None

        self.update()

    def atualizar_vertice_editavel_medicao(self, tipo, indice, ponto_cena):
        """
        Atualiza a posição visual de um vértice registrado
        enquanto ele está sendo arrastado.
        """
        ponto = np.asarray(ponto_cena, dtype=np.float64)

        for item in self._vertices_editaveis_medicao:
            if (item["tipo"] == tipo
                and item["indice"] == indice):

                item["cena"] = ponto.copy()
                break

        if (self._vertice_medicao_hover is not None
            and self._vertice_medicao_hover["tipo"] == tipo
            and self._vertice_medicao_hover["indice"] == indice):

            self._vertice_medicao_hover["cena"] = (ponto.copy())

        if (self._arraste_vertice_medicao is not None
            and self._arraste_vertice_medicao["tipo"] == tipo
            and self._arraste_vertice_medicao["indice"] == indice):

            self._arraste_vertice_medicao["cena"] = (ponto.copy())

        self.update()

    def _obter_vertice_editavel_medicao(self, posicao):
        """
        Localiza o vértice editável mais próximo do mouse
        em coordenadas de tela.
        """
        if not self._vertices_editaveis_medicao:
            return None

        px = float(posicao.x())
        py = float(posicao.y())

        tolerancia = float(self._tolerancia_vertice_medicao_px)

        limite_quadrado = (tolerancia * tolerancia)

        melhor = None
        melhor_distancia = limite_quadrado

        for item in self._vertices_editaveis_medicao:
            ponto_tela = (self._projetar_ponto_cena_para_tela(item["cena"]))

            if ponto_tela is None:
                continue

            dx = float(ponto_tela.x()) - px
            dy = float(ponto_tela.y()) - py

            distancia = (dx * dx + dy * dy)

            if distancia <= melhor_distancia:
                melhor_distancia = distancia

                melhor = {
                    "tipo":
                        item["tipo"],

                    "indice":
                        item["indice"],

                    "cena":
                        np.asarray(item["cena"],
                            dtype=np.float64).copy()}

        return melhor

    def _desenhar_hover_vertice_medicao(self, painter):
        """
        Destaca o vértice que pode ser arrastado.
        """
        item = self._vertice_medicao_hover

        if item is None:
            return

        ponto_tela = (self._projetar_ponto_cena_para_tela(item["cena"]))

        if ponto_tela is None:
            return

        painter.save()

        pen = QPen(QColor(255, 215, 0, 255))
        pen.setWidth(2)

        painter.setPen(pen)
        painter.setBrush(QColor(255, 255, 255, 210))
        painter.drawEllipse(ponto_tela, 7.0, 7.0)

        painter.restore()

    def _desenhar_hover_segmento_medicao(self, painter):
        """
        Destaca a aresta real sobre o MDT e mostra
        o ponto de inserção do novo vértice.
        """
        item = (self._segmento_medicao_hover)

        if item is None:
            return

        pontos_tela = item.get("pontos_tela", [])
        ponto = item.get("ponto_tela")

        if (len(pontos_tela) < 2
            or ponto is None):

            return

        painter.save()

        # HALO / BRILHO
        pen_brilho = QPen(QColor(255, 170, 0, 75))

        pen_brilho.setWidth(7)

        pen_brilho.setCapStyle(Qt.PenCapStyle.RoundCap)
        pen_brilho.setJoinStyle(Qt.PenJoinStyle.RoundJoin)

        painter.setPen(pen_brilho)

        for indice in range(len(pontos_tela) - 1):

            painter.drawLine(pontos_tela[indice], pontos_tela[indice + 1])

        # LINHA PRINCIPAL
        pen_linha = QPen(QColor(255, 205, 0, 245))
        pen_linha.setWidth(3)
        pen_linha.setCapStyle(Qt.PenCapStyle.RoundCap)
        pen_linha.setJoinStyle(Qt.PenJoinStyle.RoundJoin)

        painter.setPen(pen_linha)

        for indice in range(len(pontos_tela) - 1):

            painter.drawLine(pontos_tela[indice], pontos_tela[indice + 1])

        # PONTO DE INSERÇÃO
        pen_ponto = QPen(QColor(255, 140, 0, 255))
        pen_ponto.setWidth(2)

        painter.setPen(pen_ponto)
        painter.setBrush(QColor(255, 255, 255, 240))
        painter.drawEllipse(ponto, 6.0, 6.0)

        # +
        painter.drawLine(
            QPointF(ponto.x() - 3.0, ponto.y()),
            QPointF(ponto.x() + 3.0, ponto.y()))

        painter.drawLine(
            QPointF(ponto.x(), ponto.y() - 3.0),
            QPointF(ponto.x(), ponto.y() + 3.0))

        painter.restore()

    def limpar_hachura_area_final(self):
        self._hachura_area_final_ativa = False
        self._hachura_area_pontos = []
        self.update()

    def _projetar_ponto_cena_para_tela(self, ponto):
        """
        Converte uma coordenada da cena 3D para posição
        em pixels dentro do GLViewWidget.
        """
        if ponto is None:
            return None

        try:
            modelview = self.viewMatrix()

            try:
                projection = self.projectionMatrix()
            except TypeError:
                viewport = self.getViewport()
                projection = self.projectionMatrix(viewport, viewport)

            vetor = QVector4D(float(ponto[0]), float(ponto[1]), float(ponto[2]), 1.0)
            clip = projection * modelview * vetor

            w = float(clip.w())

            if w <= 1e-12:
                return None

            ndc_x = float(clip.x()) / w
            ndc_y = float(clip.y()) / w
            ndc_z = float(clip.z()) / w

            if ndc_z < -1.0 or ndc_z > 1.0:
                return None

            x = (ndc_x + 1.0) * 0.5 * float(self.width())
            y = (1.0 - (ndc_y + 1.0) * 0.5) * float(self.height())

            return QPointF(x, y)

        except Exception:
            return None

    def _desenhar_previa_medicao(self, painter):
        """
        Desenha uma linha-guia temporária entre P1
        e a posição atual do mouse.
        """
        if not self._previa_medicao_ativa:
            return

        if self._previa_medicao_inicio is None or self._previa_medicao_mouse is None:
            return

        inicio = self._projetar_ponto_cena_para_tela(self._previa_medicao_inicio)

        if inicio is None:
            return

        pen = QPen(QColor(255, 180, 0, 230))
        pen.setWidth(2)
        pen.setStyle(Qt.PenStyle.DashLine)

        painter.save()
        painter.setPen(pen)
        painter.drawLine(inicio, self._previa_medicao_mouse)
        painter.restore()

    def _desenhar_hachura_previa_area(self, painter):
        """
        Desenha a hachura enquanto a área está sendo construída.

        A partir do segundo ponto confirmado, o cursor funciona
        como o próximo vértice provisório.
        """
        if len(self._previa_area_pontos) < 2:
            return

        if self._previa_medicao_mouse is None:
            return

        pontos_tela = []

        for ponto in self._previa_area_pontos:
            posicao = self._projetar_ponto_cena_para_tela(ponto)

            if posicao is None:
                return

            pontos_tela.append(posicao)

        # Cursor = próximo vértice provisório.
        pontos_tela.append(self._previa_medicao_mouse)

        if len(pontos_tela) < 3:
            return

        caminho = QPainterPath()
        caminho.moveTo(pontos_tela[0])

        for ponto in pontos_tela[1:]:
            caminho.lineTo(ponto)

        caminho.closeSubpath()

        painter.save()

        brush = QBrush(QColor(255, 170, 0, 90), Qt.BrushStyle.BDiagPattern)
        painter.fillPath(caminho, brush)

        pen = QPen(QColor(255, 170, 0, 210))
        pen.setWidth(1)
        pen.setStyle(Qt.PenStyle.DashLine)

        painter.setPen(pen)
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.drawPath(caminho)

        painter.restore()

    def _effective_dpr(self):
        """
        Retorna a escala de pixels da tela, incluindo HiDPI.
        """
        try:
            return float(self.devicePixelRatioF())
        except Exception:
            return 1.0

    def _px_to_world_scale(self):
        """
        Converte o deslocamento do mouse em unidades da cena 3D.

        A escala acompanha a distância da câmera e recebe uma compensação
        quando o zoom está muito próximo.
        """
        try:
            distancia = max(0.000001, float(self.opts.get("distance", 200.0)))

            distancia_central = max( 0.000001, float(getattr(self, "_zoom_center_distance", distancia)))

            fov_graus = float(self.opts.get("fov", 60.0))
            fov_radianos = np.deg2rad(fov_graus)
            altura = max(1, self.height())
            dpr = self._effective_dpr()
            altura_efetiva = max(1.0, altura * dpr)
            altura_mundo_visivel = (2.0 * distancia * np.tan(fov_radianos * 0.5))
            escala_base = (altura_mundo_visivel / altura_efetiva * self._sens)
            relacao_zoom = (distancia_central / distancia)

            if relacao_zoom > 1.0:
                compensacao = (1.0 + (math.sqrt(relacao_zoom) - 1.0) * self._pan_zoom_boost)

                compensacao = min(compensacao, self._pan_zoom_boost_max)

            else:
                compensacao = 1.0

            return escala_base * compensacao

        except Exception:
            return self._sens

    def _liberar_fbo_depth_oclusao(self):
        """
        Libera os objetos OpenGL usados pelo framebuffer auxiliar de profundidade.
        """
        try:
            self.makeCurrent()

            if self._rbo_depth_oclusao:
                GL.glDeleteRenderbuffers(1, [int(self._rbo_depth_oclusao)])

            if self._fbo_depth_oclusao:
                GL.glDeleteFramebuffers(1, [int(self._fbo_depth_oclusao)])

        except Exception:
            pass  # nosec B110

        self._fbo_depth_oclusao = 0
        self._rbo_depth_oclusao = 0
        self._fbo_depth_tamanho = None
        self._viewport_depth_leitura = None

    def preparar_depth_para_leitura(self):
        """
        Resolve o depth buffer atual para um FBO auxiliar sem MSAA,
        permitindo posteriormente o uso de glReadPixels.
        """
        try:
            self.makeCurrent()

            fbo_principal = int(
                self.defaultFramebufferObject())

            if fbo_principal <= 0:
                return False

            viewport_gl = GL.glGetIntegerv(
                GL.GL_VIEWPORT)

            viewport = np.asarray(
                viewport_gl,
                dtype=np.int32).reshape(-1)

            if viewport.size < 4:
                return False

            x_view = int(viewport[0])
            y_view = int(viewport[1])
            largura = int(viewport[2])
            altura = int(viewport[3])

            if (largura <= 0
                or altura <= 0):
                return False

            tamanho = (largura, altura)

            # Recria somente quando o tamanho do framebuffer mudar.
            if (not self._fbo_depth_oclusao
                or not self._rbo_depth_oclusao
                or self._fbo_depth_tamanho != tamanho):

                self._liberar_fbo_depth_oclusao()

                self._fbo_depth_oclusao = int(GL.glGenFramebuffers(1))
                self._rbo_depth_oclusao = int(GL.glGenRenderbuffers(1))

                GL.glBindFramebuffer(GL.GL_FRAMEBUFFER, self._fbo_depth_oclusao)
                GL.glBindRenderbuffer(GL.GL_RENDERBUFFER, self._rbo_depth_oclusao)

                GL.glRenderbufferStorage(
                    GL.GL_RENDERBUFFER,
                    GL.GL_DEPTH24_STENCIL8,
                    largura,
                    altura)

                GL.glFramebufferRenderbuffer(
                    GL.GL_FRAMEBUFFER,
                    GL.GL_DEPTH_STENCIL_ATTACHMENT,
                    GL.GL_RENDERBUFFER,
                    self._rbo_depth_oclusao)

                GL.glDrawBuffer(GL.GL_NONE)
                GL.glReadBuffer(GL.GL_NONE)

                status = GL.glCheckFramebufferStatus(GL.GL_FRAMEBUFFER)

                if status != GL.GL_FRAMEBUFFER_COMPLETE:
                    self._liberar_fbo_depth_oclusao()
                    self.restaurar_framebuffer_padrao()
                    return False

                self._fbo_depth_tamanho = tamanho

            # Origem do FBO auxiliar é sempre 0, 0.
            self._viewport_depth_leitura = (0, 0, largura, altura)

            # Origem: framebuffer MSAA utilizado pelo QOpenGLWidget.
            GL.glBindFramebuffer(GL.GL_READ_FRAMEBUFFER, fbo_principal)

            # Destino: nosso framebuffer auxiliar sem MSAA.
            GL.glBindFramebuffer(GL.GL_DRAW_FRAMEBUFFER, self._fbo_depth_oclusao)

            GL.glBlitFramebuffer(
                x_view,
                y_view,
                x_view + largura,
                y_view + altura,
                0,
                0,
                largura,
                altura,
                GL.GL_DEPTH_BUFFER_BIT,
                GL.GL_NEAREST)

            # O glReadPixels deve ler do FBO auxiliar.
            GL.glBindFramebuffer(GL.GL_READ_FRAMEBUFFER, self._fbo_depth_oclusao)

            # A renderização normal continua associada ao principal.
            GL.glBindFramebuffer(GL.GL_DRAW_FRAMEBUFFER, fbo_principal)

            GL.glBindBuffer(GL.GL_PIXEL_PACK_BUFFER, 0)

            return True

        except Exception:
            self.restaurar_framebuffer_padrao()
            return False

    def obter_viewport_depth_leitura(self):
        """
        Retorna o viewport correspondente ao FBO auxiliar.
        """
        return self._viewport_depth_leitura

    def restaurar_framebuffer_padrao(self):
        """
        Restaura o framebuffer interno do QOpenGLWidget.
        """
        try:
            fbo_principal = int(
                self.defaultFramebufferObject())

            if fbo_principal > 0:
                GL.glBindFramebuffer(GL.GL_READ_FRAMEBUFFER, fbo_principal)
                GL.glBindFramebuffer(GL.GL_DRAW_FRAMEBUFFER, fbo_principal)

            GL.glBindBuffer(GL.GL_PIXEL_PACK_BUFFER, 0)

        except Exception:
            pass  # nosec B110

    def keyPressEvent(self, event):
        """
        Trata atalhos do visualizador 3D.
        L:
            inicia medição de distância.
        P:
            inicia medição de área e perímetro.
        Ctrl:
            altera o cursor durante a captura
            de coordenadas.
        """
        if not event.isAutoRepeat():
            modificadores = event.modifiers()

            if modificadores == Qt.KeyboardModifier.NoModifier:
                if event.key() == Qt.Key.Key_L:
                    self.atalhoMedirDistancia.emit()
                    event.accept()
                    return

                if event.key() == Qt.Key.Key_P:
                    self.atalhoMedirArea.emit()
                    event.accept()
                    return

        if (getattr(self, "_captura_coordenada_ativa",  False)
            and event.key() == Qt.Key.Key_Control):

            try:
                self.setCursor(Qt.CursorShape.PointingHandCursor)

            except Exception:
                pass  # nosec B110

            event.accept()
            return

        super().keyPressEvent(event)

    def keyReleaseEvent(self, event):
        """
        Ao soltar Ctrl, restaura o cursor normal
        do visualizador.
        """
        if (getattr(self, "_captura_coordenada_ativa", False)
            and event.key() == Qt.Key.Key_Control):

            try:
                self.setCursor(self._cursor_reposo)
            except Exception:
                pass  # nosec B110

            event.accept()
            return

        super().keyReleaseEvent(event)

    def mousePressEvent(self, event):
        """
        Ctrl + botão esquerdo:
            captura coordenada quando a ferramenta estiver ativa.

        Botão esquerdo:
            rotação.

        Botão direito:
            deslocamento.
        """
        if (getattr(self, "_captura_coordenada_ativa", False)
            and event.button()
                == Qt.MouseButton.LeftButton
            and bool(event.modifiers()
                & Qt.KeyboardModifier.ControlModifier)):

            self._rotating = False
            self._lastPosRot = None

            try:
                posicao = event.position()
            except Exception:
                posicao = QPointF(event.pos())

            self.ctrlCliqueCoordenada.emit(posicao)

            event.accept()
            return

        if (getattr(self, "_captura_medicao_ativa", False)
            and event.button() == Qt.MouseButton.LeftButton):

            self._rotating = False
            self._lastPosRot = None

            try:
                posicao = event.position()
            except Exception:
                posicao = QPointF(event.pos())

            self.cliqueMedicao.emit(posicao)
            event.accept()
            return

        # ARRASTE DE VÉRTICE DE MEDIÇÃO CONCLUÍDA
        if (event.button()
            == Qt.MouseButton.LeftButton
            and not getattr(self, "_captura_medicao_ativa", False)):

            try:
                posicao = event.position()
            except Exception:
                posicao = QPointF(event.pos())

            vertice = (self._obter_vertice_editavel_medicao(posicao))

            if vertice is not None:
                self._rotating = False
                self._lastPosRot = None

                self._arraste_vertice_medicao = (vertice)

                dados = dict(vertice)
                dados["posicao"] = (posicao)

                self.iniciarArrasteVerticeMedicao.emit(dados)

                try:
                    self.setCursor(Qt.CursorShape.ClosedHandCursor)

                except Exception:
                    pass  # nosec B110

                event.accept()
                return

            # Não encontrou vértice.
            # Tenta inserir um novo sobre uma aresta.
            segmento = (self._obter_segmento_editavel_medicao(posicao))

            if segmento is not None:

                dados_segmento = dict(
                    segmento)

                dados_segmento["posicao"] = (posicao)

                # O sinal é entregue diretamente ao
                # VisualizadorRaster3DManager.
                self.inserirVerticeSegmentoMedicao.emit(dados_segmento)

                # O Manager já atualizou a lista de
                # vértices editáveis neste ponto.
                tipo = dados_segmento["tipo"]

                indice_novo = (dados_segmento["indice_insercao"])

                novo_vertice = None

                for item in self._vertices_editaveis_medicao:
                    if (item["tipo"] == tipo
                        and item["indice"]
                            == indice_novo):

                        novo_vertice = {
                            "tipo":
                                item["tipo"],

                            "indice":
                                item["indice"],

                            "cena":
                                np.asarray(
                                    item["cena"],
                                    dtype=np.float64).copy()}

                        break

                if novo_vertice is not None:
                    self._rotating = False
                    self._lastPosRot = None

                    self._arraste_vertice_medicao = (novo_vertice)
                    self._vertice_medicao_hover = (novo_vertice)

                    self._segmento_medicao_hover = (None)
                    dados_arraste = dict(novo_vertice)
                    dados_arraste["posicao"] = (posicao)

                    self.iniciarArrasteVerticeMedicao.emit(dados_arraste)

                    try:
                        self.setCursor(Qt.CursorShape.ClosedHandCursor)

                    except Exception:
                        pass  # nosec B110

                    event.accept()
                    return

        if (getattr(self, "_captura_medicao_ativa", False)
            and getattr(self, "_medicao_finaliza_direita", False)
            and event.button() == Qt.MouseButton.RightButton):

            self.finalizarMedicao.emit()
            event.accept()
            return

        if event.button() == Qt.MouseButton.RightButton:
            self._panning = True
            self._lastPosPan = event.pos()

            try:
                self.setCursor(Qt.CursorShape.ClosedHandCursor)
            except Exception:
                pass  # nosec B110

            event.accept()
            return

        if event.button() == Qt.MouseButton.LeftButton:
            self._rotating = True
            self._lastPosRot = event.pos()

            self._rot_sx = 0.0
            self._rot_sy = 0.0

            event.accept()
            return

        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        """
        Aplica rotação suave ou deslocamento conforme o botão pressionado.
        """
        try:
            posicao_mouse = event.position()
        except Exception:
            posicao_mouse = QPointF(event.pos())

        # VÉRTICE SENDO ARRASTADO
        if self._arraste_vertice_medicao is not None:
            dados = dict(self._arraste_vertice_medicao)

            dados["posicao"] = (posicao_mouse)
            self.moverArrasteVerticeMedicao.emit(dados)

            try:
                self.setCursor(Qt.CursorShape.ClosedHandCursor)

            except Exception:
                pass  # nosec B110

            event.accept()
            return

        # HOVER DE EDIÇÃO DAS MEDIÇÕES
        if (not self._rotating
            and not self._panning
            and not getattr(self, "_captura_medicao_ativa", False)):

            # Vértices têm prioridade absoluta.
            vertice = (
                self._obter_vertice_editavel_medicao(posicao_mouse))

            segmento = None

            if vertice is None:
                segmento = (self._obter_segmento_editavel_medicao(posicao_mouse))

            anterior_vertice = (self._vertice_medicao_hover)
            anterior_segmento = (self._segmento_medicao_hover)

            self._vertice_medicao_hover = (vertice)
            self._segmento_medicao_hover = (segmento)

            try:
                if vertice is not None:
                    self.setCursor(Qt.CursorShape.SizeAllCursor)

                elif segmento is not None:
                    self.setCursor(Qt.CursorShape.CrossCursor)

                else:
                    self.setCursor(self._cursor_reposo)

            except Exception:
                pass  # nosec B110

            alterou = (
                (anterior_vertice is None)
                != (vertice is None)
                or
                (anterior_segmento is None)
                != (segmento is None))

            if (anterior_vertice is not None
                and vertice is not None):

                alterou = (alterou
                    or anterior_vertice["tipo"]
                        != vertice["tipo"]
                    or anterior_vertice["indice"]
                        != vertice["indice"])

            if (anterior_segmento is not None
                and segmento is not None):

                alterou = (alterou
                    or anterior_segmento["indice_inicio"]
                        != segmento["indice_inicio"]
                    or abs(
                        anterior_segmento.get("fator", 0.0) - segmento.get("fator", 0.0)) > 0.01)

            if alterou:
                self.update()

        if getattr(self, "_previa_medicao_ativa", False):
            try:
                self._previa_medicao_mouse = QPointF(event.position())
            except Exception:
                self._previa_medicao_mouse = QPointF(event.pos())

            try:
                self.setCursor(Qt.CursorShape.PointingHandCursor)
            except Exception:
                pass  # nosec B110

            self.update()

        # Rotação com o botão esquerdo.
        if (self._rotating
            and self._lastPosRot is not None):
            deslocamento = (event.pos() - self._lastPosRot)

            self._lastPosRot = event.pos()

            dpr = self._effective_dpr()

            dx = float(deslocamento.x()) * dpr
            dy = float(deslocamento.y()) * dpr

            alpha = self._rot_alpha

            self._rot_sx = ((1.0 - alpha) * self._rot_sx + alpha * dx)
            self._rot_sy = ((1.0 - alpha) * self._rot_sy + alpha * dy)

            # Evita trancos em movimentos muito rápidos.
            maximo_passo = 60.0

            sx = float(np.clip(self._rot_sx, -maximo_passo, maximo_passo))
            sy = float(np.clip(self._rot_sy, -maximo_passo, maximo_passo))

            self.orbit(-sx * self._rot_sens, sy * self._rot_sens)
            self.cameraAlterada.emit()

            event.accept()
            return

        # Deslocamento com o botão direito.
        if (self._panning
            and self._lastPosPan is not None):
            deslocamento = ( event.pos() - self._lastPosPan)

            self._lastPosPan = event.pos()
            dpr = self._effective_dpr()
            dx_pixels = float(deslocamento.x()) * dpr
            dy_pixels = float(deslocamento.y()) * dpr
            escala = self._px_to_world_scale()

            dx_mundo = dx_pixels * escala
            dy_mundo = dy_pixels * escala

            try:
                self.pan(dx_mundo, dy_mundo, 0.0, relative="view")

            except TypeError:
                self.pan(dx_mundo, dy_mundo, 0.0)

            self.cameraAlterada.emit()

            event.accept()
            return

        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        """
        Finaliza a rotação ou o deslocamento.

        Se a captura de coordenadas estiver ativa e Ctrl
        continuar pressionado, mantém o cursor de apontar.
        """
        if (event.button()
            == Qt.MouseButton.LeftButton
            and self._arraste_vertice_medicao
                is not None):

            try:
                posicao = event.position()
            except Exception:
                posicao = QPointF(event.pos())

            dados = dict(self._arraste_vertice_medicao)

            dados["posicao"] = (posicao)

            self._arraste_vertice_medicao = (None)
            self.finalizarArrasteVerticeMedicao.emit(dados)

            self._vertice_medicao_hover = (self._obter_vertice_editavel_medicao(posicao))

            try:
                if self._vertice_medicao_hover is not None:
                    self.setCursor(Qt.CursorShape.SizeAllCursor)

                else:
                    self.setCursor(self._cursor_reposo)

            except Exception:
                pass  # nosec B110

            self.update()

            event.accept()
            return

        if event.button() == Qt.MouseButton.RightButton:
            self._panning = False
            self._lastPosPan = None

            try:
                ctrl_ativo = bool(
                    QGuiApplication.keyboardModifiers()
                    & Qt.KeyboardModifier.ControlModifier)

                if (getattr(self, "_captura_coordenada_ativa", False)
                    and ctrl_ativo):
                    self.setCursor(Qt.CursorShape.PointingHandCursor)

                else:
                    self.setCursor(self._cursor_reposo)

            except Exception:
                pass  # nosec B110

            event.accept()
            return

        if event.button() == Qt.MouseButton.LeftButton:
            self._rotating = False
            self._lastPosRot = None

            try:
                ctrl_ativo = bool(QGuiApplication.keyboardModifiers() & Qt.KeyboardModifier.ControlModifier)

                if getattr(self, "_captura_medicao_ativa", False):
                    self.setCursor(Qt.CursorShape.PointingHandCursor)

                elif (getattr(self, "_captura_coordenada_ativa", False) and ctrl_ativo):
                    self.setCursor(Qt.CursorShape.PointingHandCursor)

                else:
                    self.setCursor(self._cursor_reposo)

            except Exception:
                pass  # nosec B110

            event.accept()
            return

        super().mouseReleaseEvent(event)

    def _ponto_cursor_plano_zoom(self, posicao, z_plano=None):
        """
        Obtém o ponto da cena localizado sob o cursor
        no plano horizontal usado como referência do zoom.
        """
        try:
            largura = max(2.0, float(self.width()))
            altura = max(2.0, float(self.height()))

            ndc_x = (2.0 * float(posicao.x()) / (largura - 1.0) - 1.0)
            ndc_y = (1.0 - 2.0 * float(posicao.y()) / (altura - 1.0))

            modelview = self.viewMatrix()

            try:
                projection = (self.projectionMatrix())

            except TypeError:
                viewport = (self.getViewport())

                projection = (self.projectionMatrix(viewport, viewport))

            resultado = (projection * modelview).inverted()

            if isinstance(resultado, tuple):
                matriz_inversa, invertivel = (resultado)

                if not invertivel:
                    return None

            else:
                matriz_inversa = (resultado)

            perto = (matriz_inversa * QVector4D(ndc_x, ndc_y, -1.0, 1.0))
            longe = (matriz_inversa * QVector4D(ndc_x, ndc_y, 1.0, 1.0))

            if (abs(float(perto.w())) <= 1e-12
                or abs(float(longe.w())) <= 1e-12):

                return None

            p0 = QVector3D(
                float(perto.x())
                / float(perto.w()),
                float(perto.y())
                / float(perto.w()),
                float(perto.z())
                / float(perto.w()))

            p1 = QVector3D(
                float(longe.x())
                / float(longe.w()),
                float(longe.y())
                / float(longe.w()),
                float(longe.z())
                / float(longe.w()))

            if z_plano is None:
                z_plano = float(self.opts["center"].z())

            direcao = p1 - p0
            dz = float(direcao.z())

            if abs(dz) <= 1e-12:
                return None

            t = (float(z_plano) - float(p0.z())) / dz

            if t < 0.0 or t > 1.0:
                return None

            return (p0 + direcao * t)

        except Exception:
            return None

    def wheelEvent(self, event):
        """
        Aplica zoom mantendo sob o cursor a região
        para a qual o usuário está apontando.
        """
        posicao = event.position()

        ancora_antes = self._ponto_cursor_plano_zoom(posicao)

        super().wheelEvent(event)

        if ancora_antes is not None:
            ancora_depois = (self._ponto_cursor_plano_zoom(posicao, float(ancora_antes.z())))

            if ancora_depois is not None:
                deslocamento = (ancora_antes - ancora_depois)
                self.opts["center"] = (self.opts["center"] + deslocamento)
                self.update()

        self.cameraAlterada.emit()

    def set_corner_axis_visible(self, visible: bool):
        """
        Exibe ou oculta o eixo XYZ de orientação no canto do visualizador.
        """
        self._corner_axis_visible = bool(visible)
        self.update()

    def _project_axis_to_screen(self, axis: QVector3D):
        """
        Transforma um vetor do mundo usando apenas a rotação atual da câmera
        e retorna sua direção projetada na tela.
        """
        try:
            matriz = self.viewMatrix()

            # mapVector ignora a translação e considera somente orientação/escala.
            vetor_camera = matriz.mapVector(axis)

            x = float(vetor_camera.x())
            y = float(vetor_camera.y())

            comprimento = math.hypot(x, y)

            if comprimento < 1e-9:
                return QPointF(0.0, 0.0)

            return QPointF(x / comprimento, -y / comprimento)

        except Exception:
            return QPointF(0.0, 0.0)

    def _draw_corner_axis(self, painter: QPainter):
        """
        Desenha um eixo XYZ fixo no canto inferior esquerdo.

        O eixo não acompanha o pan ou o zoom.
        Ele acompanha somente a rotação da câmera.
        """
        if not self._corner_axis_visible:
            return

        tamanho = float(self._corner_axis_size)
        margem = float(self._corner_axis_margin)

        origem = QPointF(margem + tamanho, self.height() - margem - tamanho)

        eixos = (
            ("X", QVector3D(1.0, 0.0, 0.0), QColor(220, 45, 45)),
            ("Y", QVector3D(0.0, 1.0, 0.0), QColor(35, 170, 70)),
            ("Z", QVector3D(0.0, 0.0, 1.0), QColor(40, 100, 230)))

        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)

        # Fundo discreto para o eixo permanecer legível.
        raio_fundo = tamanho + 17.0

        painter.setPen(QPen(QColor(80, 80, 80, 100), 1.0))
        painter.setBrush(QColor(255, 255, 255, 185))
        painter.drawEllipse(origem, raio_fundo, raio_fundo)

        fonte = painter.font()
        fonte.setBold(True)
        fonte.setPointSize(9)
        painter.setFont(fonte)

        for texto, vetor, cor in eixos:
            direcao = self._project_axis_to_screen(vetor)

            fim = QPointF(
                origem.x() + direcao.x() * tamanho,
                origem.y() + direcao.y() * tamanho)

            pen = QPen(cor, self._corner_axis_line_width)

            pen.setCapStyle(Qt.PenCapStyle.RoundCap)

            painter.setPen(pen)
            painter.drawLine(origem, fim)

            # Ponta da seta.
            dx = fim.x() - origem.x()
            dy = fim.y() - origem.y()
            angulo = math.atan2(dy, dx)

            tamanho_seta = 8.0
            abertura = math.radians(28.0)

            p1 = QPointF(
                fim.x() - tamanho_seta * math.cos(angulo - abertura),
                fim.y() - tamanho_seta * math.sin(angulo - abertura))

            p2 = QPointF(
                fim.x() - tamanho_seta * math.cos(angulo + abertura),
                fim.y() - tamanho_seta * math.sin(angulo + abertura))

            painter.drawLine(fim, p1)
            painter.drawLine(fim, p2)

            # Identificação X, Y ou Z.
            painter.setPen(QPen(cor, 1.0))

            deslocamento_texto = 12.0

            pos_texto = QPointF(
                fim.x() + direcao.x() * deslocamento_texto - 4.0,
                fim.y() + direcao.y() * deslocamento_texto + 5.0)

            painter.drawText(pos_texto, texto)

        # Pequeno círculo na origem.
        painter.setPen(QPen(QColor(40, 40, 40), 1.0))
        painter.setBrush(QColor(40, 40, 40))
        painter.drawEllipse(origem, 3.0, 3.0)

        painter.restore()

    def paintGL(self):
        """
        Renderiza a cena OpenGL e os elementos 2D
        sobrepostos ao visualizador.
        """
        super().paintGL()

        self.cenaRenderizada.emit()

        mostrar_previa = bool(
            getattr(self, "_previa_medicao_ativa", False)
            and self._previa_medicao_inicio is not None
            and self._previa_medicao_mouse is not None)

        mostrar_hachura = bool(getattr(self, "_hachura_area_final_ativa", False))

        mostrar_hover_vertice = (self._vertice_medicao_hover
            is not None)

        mostrar_hover_segmento = (self._segmento_medicao_hover
            is not None)

        if (not self._corner_axis_visible
            and not mostrar_previa
            and not mostrar_hachura
            and not mostrar_hover_vertice
            and not mostrar_hover_segmento):

            return

        painter = QPainter(self)

        try:
            if mostrar_previa:
                self._desenhar_hachura_previa_area(painter)
                self._desenhar_previa_medicao(painter)

            if self._hachura_area_final_ativa:
                self._desenhar_hachura_area_final(painter)

            if self._corner_axis_visible:
                self._draw_corner_axis(painter)

            if mostrar_hover_segmento:
                self._desenhar_hover_segmento_medicao(painter)

            if mostrar_hover_vertice:
                self._desenhar_hover_vertice_medicao(painter)

        finally:
            painter.end()

    def definir_fundo_solido(self, cor):
        """
        Ativa fundo sólido padrão do GLViewWidget.
        """
        self._usar_gradiente_ceu = False
        self.setBackgroundColor(QColor(cor))
        self.update()

    def definir_gradiente_ceu(self, cor_topo=None, cor_base=None):
        """
        Ativa fundo em gradiente azul -> branco.
        """
        self._usar_gradiente_ceu = True

        if cor_topo is not None:
            self._cor_topo = QColor(cor_topo)

        if cor_base is not None:
            self._cor_base = QColor(cor_base)

        try:
            # deixa a limpeza do fundo transparente para o gradiente aparecer
            self.setBackgroundColor(QColor(0, 0, 0, 0))
        except Exception:
            pass  # nosec B110

        self.update()

    def paintEvent(self, event):
        """
        Desenha a cena 3D normalmente e, quando ativado,
        aplica o gradiente atrás da cena.
        """
        super().paintEvent(event)

        if not self._usar_gradiente_ceu:
            return

        painter = QPainter(self)

        try:
            painter.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationOver)
        except Exception:
            painter.end()
            return

        gradiente = QLinearGradient(0, 0, 0, self.height())

        gradiente.setColorAt(0.00, self._cor_topo)
        gradiente.setColorAt(1.00, self._cor_base)

        painter.fillRect(self.rect(), gradiente)

        painter.end()

class GLMalhaTexturizadaItem(gl.GLGraphicsItem.GLGraphicsItem):
    """
    Malha OpenGL com textura 2D real.

    A geometria e a resolução da textura são independentes.
    Isso permite usar uma ortofoto de alta resolução sobre
    uma malha 3D relativamente leve.
    """

    _programas_shader = {}

    def __init__(self, vertices, faces, uv, imagem, parentItem=None, fatores_luz=None):
        super().__init__()

        self.setGLOptions("translucent")
        self.setParentItem(parentItem)

        quantidade = len(vertices)

        if fatores_luz is None:
            fatores = np.ones(quantidade, dtype=np.float32)
        else:
            fatores = np.asarray(fatores_luz, dtype=np.float32).reshape(-1)

            if (len(fatores) != quantidade
                or not np.all(np.isfinite(fatores))):
                raise ValueError(self.tr("Os fatores de iluminação não correspondem à malha."))

            fatores = np.maximum(fatores, 0.0)

        # XYZ + UV + fator de iluminação.
        self.vertex_data = np.ascontiguousarray(
            np.column_stack((vertices, uv, fatores)),
            dtype=np.float32)

        self.faces_data = np.ascontiguousarray(faces, dtype=np.uint32)

        self.imagem = (imagem
            .convertToFormat(QImage.Format.Format_RGBA8888)
            .mirrored(False, True))

        self._precisa_upload = True

        self.m_vao = QOpenGLVertexArrayObject(self)
        self.m_vbo = QOpenGLBuffer(QOpenGLBuffer.Type.VertexBuffer)
        self.m_ebo = QOpenGLBuffer(QOpenGLBuffer.Type.IndexBuffer)

        self.m_texture = None

    def cleanup(self):
        """
        Libera os recursos OpenGL com o contexto ativo.
        """
        if self.m_texture is not None:
            try:
                textura = np.array([int(self.m_texture)], dtype=np.uint32)

                GL.glDeleteTextures(1, textura)

            except Exception:
                pass  # nosec B110

            self.m_texture = None

        try:
            if self.m_vbo.isCreated():
                self.m_vbo.destroy()

            if self.m_ebo.isCreated():
                self.m_ebo.destroy()

            if self.m_vao.isCreated():
                self.m_vao.destroy()

        except Exception:
            pass  # nosec B110

    def _programa_shader(self):
        contexto = self.view().context()

        # Diferencia este programa do shader anterior da textura.
        chave = (id(contexto), "textura_solar_v1")

        programa = self._programas_shader.get(chave)

        if programa is not None:
            return programa

        vertex_shader = """
        #version 140

        in vec3 a_posicao;
        in vec2 a_uv;
        in float a_luz;

        uniform mat4 u_mvp;

        out vec2 v_uv;
        out float v_luz;

        void main()
        {
            gl_Position = u_mvp * vec4(a_posicao, 1.0);
            v_uv = a_uv;
            v_luz = a_luz;
        }
        """

        fragment_shader = """
        #version 140

        in vec2 v_uv;
        in float v_luz;

        uniform sampler2D u_textura;

        out vec4 fragColor;

        void main()
        {
            vec4 cor = texture(u_textura, v_uv);

            vec3 iluminada = clamp(
                cor.rgb * max(v_luz, 0.0),
                0.0,
                1.0
            );

            fragColor = vec4(iluminada, cor.a);
        }
        """

        vert = gl_shaders.compileShader(vertex_shader, GL.GL_VERTEX_SHADER)
        frag = gl_shaders.compileShader(fragment_shader, GL.GL_FRAGMENT_SHADER)

        programa = gl_shaders.compileProgram(vert, frag)

        self._programas_shader[chave] = programa

        return programa

    def _criar_objetos(self):
        programa = self._programa_shader()

        if not self.m_vbo.isCreated():
            self.m_vbo.create()

        if not self.m_ebo.isCreated():
            self.m_ebo.create()

        if not self.m_vao.isCreated():
            self.m_vao.create()

        self.m_vao.bind()
        self.m_vbo.bind()

        if self._precisa_upload:
            self.m_vbo.allocate(self.vertex_data, self.vertex_data.nbytes)

        # Seis floats por vértice: XYZ, UV e iluminação.
        stride = 6 * np.dtype(np.float32).itemsize

        atributos = (
            ("a_posicao", 3, 0),
            ("a_uv", 2, 3 * 4),
            ("a_luz", 1, 5 * 4))

        for nome, componentes, deslocamento in atributos:
            local = GL.glGetAttribLocation(programa, nome)

            if local >= 0:
                GL.glEnableVertexAttribArray(local)

                GL.glVertexAttribPointer(
                    local,
                    componentes,
                    GL.GL_FLOAT,
                    False,
                    stride,
                    ctypes.c_void_p(deslocamento))

        self.m_ebo.bind()

        if self._precisa_upload:
            self.m_ebo.allocate(self.faces_data, self.faces_data.nbytes)

        self.m_vao.release()
        self.m_vbo.release()
        self.m_ebo.release()

    def _enviar_textura(self):
        if not self._precisa_upload:
            return

        largura = int(self.imagem.width())
        altura = int(self.imagem.height())

        if largura <= 0 or altura <= 0:
            return

        ponteiro = self.imagem.bits()
        ponteiro.setsize(self.imagem.sizeInBytes())

        bytes_linha = int(self.imagem.bytesPerLine())

        rgba = np.array(ponteiro, dtype=np.uint8).reshape( altura, bytes_linha)

        rgba = np.ascontiguousarray(rgba[:, :largura * 4].reshape(altura, largura, 4))

        if self.m_texture is None:
            textura = GL.glGenTextures(1)

            if isinstance(textura, (list, tuple, np.ndarray)):

                textura = textura[0]

            self.m_texture = int(textura)

        GL.glActiveTexture(GL.GL_TEXTURE0)
        GL.glBindTexture(GL.GL_TEXTURE_2D, self.m_texture)

        GL.glTexParameteri(
            GL.GL_TEXTURE_2D,
            GL.GL_TEXTURE_MIN_FILTER,
            GL.GL_LINEAR_MIPMAP_LINEAR)

        GL.glTexParameteri(
            GL.GL_TEXTURE_2D,
            GL.GL_TEXTURE_MAG_FILTER,
            GL.GL_LINEAR)

        GL.glTexParameteri(
            GL.GL_TEXTURE_2D,
            GL.GL_TEXTURE_WRAP_S,
            GL.GL_CLAMP_TO_EDGE)

        GL.glTexParameteri(
            GL.GL_TEXTURE_2D,
            GL.GL_TEXTURE_WRAP_T,
            GL.GL_CLAMP_TO_EDGE)

        GL.glTexImage2D(
            GL.GL_TEXTURE_2D,
            0,
            GL.GL_RGBA8,
            largura,
            altura,
            0,
            GL.GL_RGBA,
            GL.GL_UNSIGNED_BYTE,
            rgba)

        GL.glGenerateMipmap(GL.GL_TEXTURE_2D)

        try:
            max_anisotropia = float(
                GL.glGetFloatv(GL.GL_MAX_TEXTURE_MAX_ANISOTROPY_EXT))

            GL.glTexParameterf(
                GL.GL_TEXTURE_2D,
                GL.GL_TEXTURE_MAX_ANISOTROPY_EXT,
                min(8.0, max_anisotropia))

        except Exception:
            pass  # nosec B110

        GL.glBindTexture(GL.GL_TEXTURE_2D, 0)

        self._precisa_upload = False

    def paint(self):
        if self.vertex_data.size == 0 or self.faces_data.size == 0:
            return

        self.setupGLState()

        self._criar_objetos()
        self._enviar_textura()

        if self.m_texture is None:
            return

        programa = self._programa_shader()

        # Matriz MVP compatível com a versão do PyQtGraph usada pelo QGIS.
        view = self.view()

        if view is None:
            return

        modelview = view.viewMatrix()

        try:
            projection = view.projectionMatrix()

        except TypeError:
            viewport = view.getViewport()
            projection = view.projectionMatrix(viewport, viewport)

        matriz_qt = projection * modelview

        matriz = np.asarray(matriz_qt.data(), dtype=np.float32)

        GL.glUseProgram(programa)

        loc_mvp = GL.glGetUniformLocation(programa, "u_mvp")

        GL.glUniformMatrix4fv(loc_mvp, 1, False, matriz)

        loc_textura = GL.glGetUniformLocation(programa, "u_textura")

        GL.glUniform1i(loc_textura, 0)

        GL.glActiveTexture(GL.GL_TEXTURE0)

        GL.glBindTexture(GL.GL_TEXTURE_2D, int(self.m_texture))

        # Evita conflito de profundidade com a malha-base.
        GL.glEnable(GL.GL_POLYGON_OFFSET_FILL)

        GL.glPolygonOffset(-1.0, -1.0)

        self.m_vao.bind()
        self.m_ebo.bind()

        GL.glDrawElements(
            GL.GL_TRIANGLES,
            int(self.faces_data.size),
            GL.GL_UNSIGNED_INT,
            None)

        self.m_ebo.release()
        self.m_vao.release()

        GL.glPolygonOffset(0.0, 0.0)

        GL.glDisable(GL.GL_POLYGON_OFFSET_FILL)

        GL.glBindTexture(GL.GL_TEXTURE_2D, 0)

        GL.glUseProgram(0)

class ExportadorWebRaster3D:
    """
    Responsável pela exportação da visualização 3D para Web.

    Etapa 1:
    - seleção da pasta de destino;
    - criação da estrutura da exportação;
    - geração de um index.html inicial;
    - abertura automática no navegador.

    As geometrias 3D serão adicionadas nas próximas etapas.
    """

    def __init__(self, visualizador):
        self.visualizador = visualizador
        self.raster_layer = visualizador.raster_layer
        self.ui_manager = visualizador.ui_manager

    def tr(self, message):
        return QCoreApplication.translate("ExportadorWebRaster3D", message)

    def _atualizar_progresso(self, valor, texto):
        """
        Encaminha o progresso da exportação para
        o indicador do visualizador 3D.
        """
        try:
            self.visualizador._atualizar_progresso_exportacao_web(valor, texto)

        except Exception:
            pass  # nosec B110

    def exportar(self):
        """
        Executa a exportação da visualização atual
        para Web exibindo o progresso das etapas.
        """
        pasta_base = (QFileDialog.getExistingDirectory(self.visualizador, self.tr("Selecione a pasta para exportar a visualização Web")))

        if not pasta_base:
            return None

        progresso_iniciado = False
        sucesso = False

        try:
            progresso_iniciado = True

            self._atualizar_progresso(2, self.tr("Preparando exportação Web..."))

            pasta_saida = (self._criar_pasta_saida(pasta_base))

            self._atualizar_progresso(5, self.tr("Criando estrutura de arquivos..."))

            os.makedirs(os.path.join(pasta_saida, "assets"), exist_ok=True)

            os.makedirs(os.path.join(pasta_saida, "js"), exist_ok=True)

            # TERRENO + TEXTURAS
            self._atualizar_progresso(10, self.tr("Exportando terreno e texturas..."))

            self._exportar_terreno(pasta_saida)

            self._atualizar_progresso(48, self.tr("Terreno exportado."))

            # SUPERFÍCIES 3D
            self._atualizar_progresso(52, self.tr("Exportando superfícies 3D..."))
            self._exportar_superficies_3d(pasta_saida)

            # LINHAS
            self._atualizar_progresso(60, self.tr("Exportando linhas..."))
            self._exportar_linhas(pasta_saida)

            # POLÍGONOS
            self._atualizar_progresso(68, self.tr("Exportando polígonos..."))
            self._exportar_poligonos(pasta_saida)

            # PONTOS
            self._atualizar_progresso(76, self.tr("Exportando pontos..."))
            self._exportar_pontos(pasta_saida)

            # RÓTULOS
            self._atualizar_progresso(84, self.tr("Exportando rótulos..."))

            self._exportar_rotulos(pasta_saida)

            # HTML
            self._atualizar_progresso(92, self.tr("Gerando visualizador Web..."))

            caminho_html = os.path.join(pasta_saida, "index.html")

            with open(caminho_html, "w",
                encoding="utf-8") as arquivo:

                arquivo.write(self._gerar_html_inicial())

            self._atualizar_progresso(98, self.tr("Finalizando exportação Web..."))

            sucesso = True

            self._mostrar_sucesso(pasta_saida, caminho_html)

            QDesktopServices.openUrl(QUrl.fromLocalFile(caminho_html))

            return caminho_html

        except Exception as e:
            self._mostrar_erro(str(e))

            return None

        finally:
            if progresso_iniciado:
                try:
                    self.visualizador._finalizar_progresso_exportacao_web(sucesso)

                except Exception:
                    pass  # nosec B110

    def _criar_pasta_saida(self, pasta_base):
        """
        Cria uma pasta exclusiva para cada exportação.
        """
        nome_raster = self._sanitizar_nome(
            self.raster_layer.name())

        nome_base = f"Visualizacao_3D_{nome_raster}"

        pasta_saida = os.path.join(
            pasta_base,
            nome_base)

        contador = 1

        while os.path.exists(pasta_saida):
            pasta_saida = os.path.join(
                pasta_base,
                f"{nome_base}_{contador}")

            contador += 1

        os.makedirs(
            pasta_saida,
            exist_ok=False)

        return pasta_saida

    def _sanitizar_nome(self, nome):
        """
        Gera nome seguro para pasta e arquivo.
        """
        nome = str(
            nome or "Raster")

        nome = re.sub(r'[<>:"/\\|?*]+', "_", nome)

        nome = re.sub(r"\s+", "_", nome)

        nome = nome.strip("._ ")

        return nome or "Raster"

    def _array_para_base64(self, array, dtype):
        """
        Converte um array NumPy em Base64 para transporte direto
        ao JavaScript sem arquivos binários externos.
        """
        dados = np.ascontiguousarray(array, dtype=dtype)

        return base64.b64encode(dados.tobytes()).decode("ascii")

    def _obter_camera_web(self, vertices):
        """
        Obtém a posição atual da câmera do GLViewWidget para
        reproduzir aproximadamente a mesma vista no navegador.
        """
        try:
            posicao = self.visualizador.view.cameraPosition()
            centro = self.visualizador.view.opts["center"]
            fov = float(
                self.visualizador.view.opts.get("fov", 60.0))

            return {
                "position": [
                    float(posicao.x()),
                    float(posicao.y()),
                    float(posicao.z())],
                "target": [
                    float(centro.x()),
                    float(centro.y()),
                    float(centro.z())],
                "fov": fov}

        except Exception:
            largura = float(np.ptp(vertices[:, 0]))
            altura = float(np.ptp(vertices[:, 1]))
            relevo = float(np.ptp(vertices[:, 2]))

            distancia = max(largura, altura, relevo, 1.0) * 1.45

            return {
                "position": [
                    distancia * 0.65,
                    -distancia * 0.65,
                    distancia * 0.45],
                "target": [
                    0.0,
                    0.0,
                    0.0],
                "fov": 60.0}

    def _obter_fundo_web(self):
        """
        Retorna o fundo atual do visualizador para reprodução no Web.
        """
        try:
            if self.visualizador.radio_fundo_preto.isChecked():
                return {
                    "modo": "preto",
                    "css": "#000000",
                    "linha": "#ffffff"}

            if self.visualizador.radio_fundo_ceu.isChecked():
                return {
                    "modo": "ceu",
                    "css": "linear-gradient(to bottom, #4191eb 0%, #73bef9 35%, #cde6f8 72%, #f2f8fc 100%)",
                    "linha": "#222222"}

        except Exception:
            pass  # nosec B110

        return {
            "modo": "branco",
            "css": "#f5f5f5",
            "linha": "#202020"}

    def _coletar_dados_terreno(self):
        """
        Coleta o MDT na qualidade atualmente carregada e,
        quando existir, a composição raster exibida sobre ele.
        """
        visualizador = self.visualizador

        if (visualizador._vertices_base is None
            or visualizador._faces is None):

            raise RuntimeError(self.tr("A superfície 3D ainda não está disponível."))

        vertices = visualizador._vertices_com_exagero().astype(np.float32, copy=False)

        faces = np.asarray(visualizador._faces, dtype=np.uint32)
        cores_base_rgba = visualizador._gerar_cores_vertices_suaves()

        if (cores_base_rgba is None
            or len(cores_base_rgba) != len(vertices)):

            raise RuntimeError(self.tr("Não foi possível preparar as cores do terreno."))

        cores_base = np.ascontiguousarray(cores_base_rgba[:, :3], dtype=np.float32)
        cores_diferenca = None
        cores_diferenca_rgba = (visualizador._gerar_cores_corte_aterro_vertices())

        if (cores_diferenca_rgba is not None
            and len(cores_diferenca_rgba) == len(vertices)):

            cores_diferenca = np.ascontiguousarray(
                cores_diferenca_rgba[:, :3],
                dtype=np.float32)

        raster_sobreposto = False
        cores_raster = None
        nomes_rasters = []

        # A textura de alta resolução é independente
        # das cores reduzidas por vértice.
        imagem_textura = getattr(visualizador, "_imagem_textura_sobreposicao", None)

        tem_textura_raster = (imagem_textura is not None
            and not imagem_textura.isNull())

        cores_raster_origem = getattr(visualizador, "_cores_imagem_sobreposicao", None)

        raster_ativo = (
            getattr(visualizador, "check_sobreposicao", None) is not None
            and visualizador.check_sobreposicao.isChecked()
            and getattr(visualizador, "_sobrepor_rasters", False)
            and (tem_textura_raster
                or cores_raster_origem is not None))

        if raster_ativo:
            # A existência da textura real já é suficiente
            # para caracterizar a sobreposição raster.
            raster_sobreposto = True

            nomes_rasters = [layer.name()
                for layer in getattr(visualizador, "_camadas_raster_sobreposicao", [])
                if layer is not None]

            # Mantém as cores por vértice somente como fallback.
            if cores_raster_origem is not None:
                cores_raster_rgba = np.asarray(
                    cores_raster_origem,
                    dtype=np.float32)

                if (cores_raster_rgba.ndim == 2
                    and cores_raster_rgba.shape[0] == len(vertices)
                    and cores_raster_rgba.shape[1] >= 3):

                    cores_raster = np.ascontiguousarray(
                        cores_raster_rgba[:, :3],
                        dtype=np.float32)

        # Coordenadas UV da textura raster em alta resolução.
        uv_textura = None

        try:
            uv = visualizador._coordenadas_uv_textura_3d()

            if (uv is not None
                and len(uv) == len(vertices)):

                uv_textura = np.ascontiguousarray(uv, dtype=np.float32)

        except Exception:
            uv_textura = None

        camera = self._obter_camera_web(vertices)
        fundo = self._obter_fundo_web()

        largura = float(np.ptp(vertices[:, 0]))
        altura = float(np.ptp(vertices[:, 1]))
        relevo = float(np.ptp(vertices[:, 2]))
        escala = max(largura, altura, relevo, 1.0)

        try:
            mostrar_linhas = bool(visualizador.check_linhas.isChecked())
        except Exception:
            mostrar_linhas = False

        try:
            mostrar_eixos_xyz = bool(visualizador.check_eixos_xyz.isChecked())
        except Exception:
            mostrar_eixos_xyz = False

        crs = visualizador.raster_layer.crs()

        # Localização geográfica do centro do MDT para
        # cálculo solar no visualizador Web.
        latitude_solar = None
        longitude_solar = None

        try:
            if not crs.isValid():
                raise ValueError("SRC inválido.")

            centro = visualizador.raster_layer.extent().center()

            transformacao_solar = QgsCoordinateTransform(crs,
                QgsCoordinateReferenceSystem("EPSG:4326"),
                QgsProject.instance())

            ponto_geografico = transformacao_solar.transform(centro)

            longitude_solar = float(ponto_geografico.x())
            latitude_solar = float(ponto_geografico.y())

            if not (
                math.isfinite(latitude_solar)
                and math.isfinite(longitude_solar)
                and -90.0 <= latitude_solar <= 90.0
                and -180.0 <= longitude_solar <= 180.0):
                raise ValueError("Coordenadas geográficas inválidas.")

        except Exception:
            latitude_solar = None
            longitude_solar = None

        crs_geografico = bool(crs.isValid() and crs.isGeographic())
        fator_unidade_metros = 1.0

        if crs.isValid() and not crs_geografico:
            try:
                fator_unidade_metros = float(
                    QgsUnitTypes.fromUnitToUnitFactor(
                        crs.mapUnits(),
                        Qgis.DistanceUnit.Meters))
            except Exception:
                fator_unidade_metros = 1.0

        try:
            elipsoide = crs.ellipsoidAcronym()
        except Exception:
            elipsoide = ""

        return {
            "vertices": vertices,
            "faces": faces,
            "cores": cores_base,
            "cores_raster": cores_raster,
            "cores_diferenca": cores_diferenca,
            "uv_textura": uv_textura,
            "raster_sobreposto": raster_sobreposto,
            "camadas_raster": nomes_rasters,
            "camera": camera,
            "fundo": fundo,
            "escala": escala,
            "mostrar_linhas": mostrar_linhas,
            "mostrar_eixos_xyz": mostrar_eixos_xyz,
            "mostrar_base_mdt": bool(
                getattr(visualizador, "check_base_mdt", None) is not None
                and visualizador.check_base_mdt.isChecked()),
            "nome": visualizador.raster_layer.name(),
            "crs": crs.authid() if crs.isValid() else "",
            "latitude_solar": latitude_solar,
            "longitude_solar": longitude_solar,
            "crs_geografico": crs_geografico,
            "fator_unidade_metros": fator_unidade_metros,
            "elipsoide": elipsoide,
            "grade_x": int(visualizador._grade_x),
            "grade_y": int(visualizador._grade_y),
            "raster_largura": int(visualizador._raster_largura),
            "raster_altura": int(visualizador._raster_altura),
            "geo_transform": [float(valor) for valor in visualizador._geo_transform],
            "validos": np.asarray(visualizador._validos, dtype=np.uint8),
            "qualidade": visualizador.combo_qualidade_terreno.currentText(),
            "exagero": float(visualizador.spin_exagero.value()),
            "origem": {
                "x": float(getattr(visualizador, "_x_centro", 0.0)),
                "y": float(getattr( visualizador, "_y_centro", 0.0)),
                "z": float(getattr(visualizador, "_z_centro", 0.0))}}

    def _exportar_expansoes_raster_web(
        self,
        pasta_saida):
        """
        Exporta as expansões laterais raster atualmente
        exibidas no visualizador 3D.

        A geometria, UV e imagem são obtidas diretamente
        dos GLMalhaTexturizadaItem já renderizados no desktop,
        garantindo paridade entre Desktop e Web.
        """
        visualizador = self.visualizador

        try:
            sobreposicao_ativa = (visualizador.check_sobreposicao.isChecked()
                and getattr(visualizador, "_sobrepor_rasters", False))

        except Exception:
            sobreposicao_ativa = False

        if not sobreposicao_ativa:
            return []

        itens = list(
            getattr(visualizador, "_itens_raster_expansao", []))

        if not itens:
            return []

        expansoes = []

        for ordem, item in enumerate(itens):
            try:
                vertex_data = np.asarray(
                    item.vertex_data,
                    dtype=np.float32)

                faces = np.asarray(
                    item.faces_data,
                    dtype=np.uint32)

                if (vertex_data.ndim != 2
                    or vertex_data.shape[0] < 4
                    or vertex_data.shape[1] < 5
                    or faces.size == 0):

                    continue

                vertices = np.ascontiguousarray(
                    vertex_data[:, :3],
                    dtype=np.float32)

                uv = np.ascontiguousarray(
                    vertex_data[:, 3:5],
                    dtype=np.float32)

                imagem_gl = getattr(item, "imagem", None)

                if (imagem_gl is None
                    or imagem_gl.isNull()):

                    continue

                # GLMalhaTexturizadaItem armazena internamente
                # a imagem invertida verticalmente para OpenGL.
                # Revertemos para salvar a imagem normal no PNG.
                imagem_exportar = (imagem_gl.mirrored(False, True))

                indice_saida = (len(expansoes) + 1)

                nome_arquivo = (f"expansao_raster_" f"{indice_saida}.png")

                caminho_textura = os.path.join(pasta_saida, "assets", nome_arquivo)

                if not imagem_exportar.save(caminho_textura, "PNG"):

                    continue

                textura_data = None

                try:
                    with open(caminho_textura,
                        "rb") as arquivo:

                        textura_b64 = (
                            base64.b64encode(
                                arquivo.read())
                            .decode("ascii"))

                    textura_data = (
                        "data:image/png;base64,"
                        + textura_b64)

                except Exception:
                    textura_data = None

                layer_id = getattr(item, "_tempo_salvo_layer_id", None)

                layer = (QgsProject.instance().mapLayer(layer_id)
                    if layer_id
                    else None)

                nome_layer = (
                    layer.name()
                    if layer is not None
                    else self.tr("Expansão raster"))

                expansoes.append({"nome":
                        nome_layer,

                    "layer_id":
                        layer_id or "",

                    "ordem":
                        int(ordem),

                    "expansao":
                        float(
                            getattr(item, "_tempo_salvo_expansao",0.0)),

                    "vertices_b64":
                        self._array_para_base64(
                            vertices,
                            "<f4"),

                    "faces_b64":
                        self._array_para_base64(
                            faces,
                            "<u4"),

                    "uv_b64":
                        self._array_para_base64(
                            uv,
                            "<f4"),

                    "textura":
                        ("assets/"
                            + nome_arquivo),

                    "textura_data":
                        textura_data})

            except Exception as erro:
                QgsMessageLog.logMessage(f"Expansão raster ignorada durante exportação Web: {erro}", "Tempo Salvo Tools", Qgis.MessageLevel.Warning)

        return expansoes

    def _exportar_terreno(self, pasta_saida):
        """
        Exporta a geometria do MDT e, quando disponível,
        a textura raster em alta resolução utilizada pelo visualizador 3D.
        """
        dados = self._coletar_dados_terreno()

        vertices = dados.pop("vertices")
        faces = dados.pop("faces")
        cores = dados.pop("cores")
        validos = dados.pop("validos")
        cores_raster = dados.pop("cores_raster")
        cores_diferenca = dados.pop("cores_diferenca")
        uv_textura = dados.pop("uv_textura")

        dados["quantidade_vertices"] = int(len(vertices))
        dados["quantidade_faces"] = int(len(faces))
        dados["vertices_b64"] = self._array_para_base64(vertices, "<f4")
        dados["faces_b64"] = self._array_para_base64(faces, "<u4")
        dados["cores_b64"] = self._array_para_base64(cores, "<f4")
        dados["validos_b64"] = self._array_para_base64(validos, "u1")

        if cores_raster is not None:
            dados["cores_raster_b64"] = self._array_para_base64(cores_raster, "<f4")
        else:
            dados["cores_raster_b64"] = None

        if cores_diferenca is not None:
            dados["cores_diferenca_b64"] = self._array_para_base64(cores_diferenca, "<f4")
        else:
            dados["cores_diferenca_b64"] = None

        if uv_textura is not None:
            dados["uv_textura_b64"] = self._array_para_base64(uv_textura, "<f4")
        else:
            dados["uv_textura_b64"] = None

        # Exporta a mesma textura em alta resolução usada
        # pelo visualizador 3D desktop.
        dados["textura_raster"] = None
        dados["textura_raster_data"] = None
        dados["textura_raster_largura"] = 0
        dados["textura_raster_altura"] = 0

        imagem_textura = getattr(
            self.visualizador,
            "_imagem_textura_sobreposicao",
            None)

        if (dados.get("raster_sobreposto", False)
            and imagem_textura is not None
            and not imagem_textura.isNull()
            and uv_textura is not None):

            caminho_textura = os.path.join(pasta_saida, "assets", "textura_terreno.png")

            self._atualizar_progresso(22, self.tr("Salvando textura do terreno..."))

            salvou_textura = imagem_textura.save(caminho_textura, "PNG")

            if salvou_textura:
                self._atualizar_progresso(30, self.tr("Incorporando textura no Web..."))

                dados["textura_raster"] = (
                    "assets/textura_terreno.png")

                dados["textura_raster_largura"] = int(
                    imagem_textura.width())

                dados["textura_raster_altura"] = int(
                    imagem_textura.height())

                # Incorpora também a imagem no terreno.js.
                # Isso evita problemas ao abrir o HTML diretamente
                # pelo protocolo file://.
                try:
                    with open(caminho_textura,
                        "rb") as arquivo_textura:

                        textura_b64 = base64.b64encode(
                            arquivo_textura.read()).decode("ascii")

                    dados["textura_raster_data"] = (
                        "data:image/png;base64,"
                        + textura_b64)

                except Exception:
                    dados["textura_raster_data"] = None

        caminho = os.path.join(pasta_saida, "assets", "terreno.js")

        self._atualizar_progresso(38, self.tr("Exportando expansão lateral..."))

        # Expansões laterais raster exibidas no desktop.
        dados["expansoes_raster"] = (
            self._exportar_expansoes_raster_web(pasta_saida))

        self._atualizar_progresso(45, self.tr("Finalizando dados do terreno..."))

        caminho = os.path.join(pasta_saida, "assets", "terreno.js")

        with open(caminho, "w", encoding="utf-8") as arquivo:

            arquivo.write("window.TEMPO_SALVO_TERRENO = ")

            json.dump(
                dados,
                arquivo,
                ensure_ascii=False,
                separators=(",", ":"))

            arquivo.write(";\n")

    def _coletar_dados_superficies_3d(self):
        """
        Coleta os MDTs secundários atualmente exibidos
        como superfícies 3D independentes.

        Camadas com diferença ativa não são exportadas
        como superfície separada, pois já deformam o MDT principal.
        """
        visualizador = self.visualizador

        sobreposicao_ativa = (
            getattr(visualizador, "check_sobreposicao", None) is not None
            and visualizador.check_sobreposicao.isChecked()
            and getattr(visualizador, "_sobrepor_rasters", False))

        if not sobreposicao_ativa:
            return {"ativo": False, "camadas": [], "superficies": []}

        camadas = list(getattr(visualizador, "_camadas_mdt_secundario_3d", []))

        if not camadas:
            return {"ativo": False, "camadas": [], "superficies": []}

        exagero = float(visualizador.spin_exagero.value())
        superficies = []
        nomes = []

        for ordem, layer in enumerate(camadas):
            if layer is None:
                continue

            config = visualizador._obter_config_3d_camada("raster", layer)

            if bool(config.get("habilitar_diferenca", False)):
                continue

            if str(config.get("modo", "")) != "superficie_3d":
                continue

            geometria = visualizador._preparar_geometria_mdt_secundario_3d(layer)

            vertices = geometria["vertices"].copy().astype(np.float32, copy=False)
            faces = np.asarray(geometria["faces"], dtype=np.uint32)

            vertices[:, 2] *= exagero

            opacidade = max(0.0, min(100.0, float(config.get("opacidade", 100.0)))) / 100.0

            if opacidade <= 0.0:
                continue

            cores_rgba = visualizador._gerar_cores_qgis_mdt_secundario_3d(layer, geometria, opacidade)

            if cores_rgba is None or len(cores_rgba) != len(vertices):
                continue

            cores = np.ascontiguousarray(cores_rgba[:, :3], dtype=np.float32)

            superficies.append({
                "nome": layer.name(),
                "ordem": int(ordem),
                "opacidade": float(opacidade),
                "vertices": vertices,
                "faces": faces,
                "cores": cores})

            nomes.append(layer.name())

        return {
            "ativo": bool(superficies),
            "camadas": nomes,
            "superficies": superficies}

    def _exportar_superficies_3d(self, pasta_saida):
        """
        Exporta os MDTs secundários em modo Superfície 3D.
        """
        dados = self._coletar_dados_superficies_3d()
        superficies_saida = []

        for superficie in dados["superficies"]:
            item = dict(superficie)

            vertices = item.pop("vertices")
            faces = item.pop("faces")
            cores = item.pop("cores")

            item["quantidade_vertices"] = int(len(vertices))
            item["quantidade_faces"] = int(len(faces))
            item["vertices_b64"] = self._array_para_base64(vertices, "<f4")
            item["faces_b64"] = self._array_para_base64(faces, "<u4")
            item["cores_b64"] = self._array_para_base64(cores, "<f4")

            superficies_saida.append(item)

        dados["superficies"] = superficies_saida

        caminho = os.path.join(pasta_saida, "assets", "superficies3d.js")

        with open(caminho, "w", encoding="utf-8") as arquivo:
            arquivo.write("window.TEMPO_SALVO_SUPERFICIES_3D = ")
            json.dump(dados, arquivo, ensure_ascii=False, separators=(",", ":"))
            arquivo.write(";\n")

    def _coletar_dados_linhas(self):
        """
        Coleta as linhas atualmente exibidas sobre o MDT.
        """
        visualizador = self.visualizador

        sobreposicao_ativa = (getattr(visualizador, "check_sobreposicao", None) is not None
            and visualizador.check_sobreposicao.isChecked()
            and getattr(visualizador, "_sobrepor_linhas", False))

        if not sobreposicao_ativa:
            return {"ativo": False, "grupos": []}

        camadas = list(getattr(visualizador, "_camadas_linhas_sobreposicao", []))

        if not camadas:
            camadas = visualizador._obter_linhas_sobre_mdt()

        if not camadas:
            return {"ativo": False, "grupos": []}

        if visualizador.ui_manager is not None:
            map_settings = visualizador.ui_manager.iface.mapCanvas().mapSettings()
            contexto = QgsRenderContext.fromMapSettings(map_settings)
        else:
            contexto = QgsRenderContext()

        grupos_saida = []

        for ordem, layer in enumerate(reversed(camadas)):
            config = visualizador._obter_config_3d_camada("linhas", layer)

            altura = max(0.0, float(config.get("altura", 0.05)))
            espessura = max(0.10, float(config.get("espessura", 2.0)))
            opacidade_config = max(0.0, min(100.0, float(config.get("opacidade", 100.0)))) / 100.0
            mostrar_parede = bool(config.get("parede", False))
            opacidade_parede = max(0.0, min(100.0, float(config.get("opacidade_parede", 60.0)))) / 100.0

            transformacao = None

            if (layer.crs().isValid()
                and visualizador.raster_layer.crs().isValid()
                and layer.crs() != visualizador.raster_layer.crs()):

                transformacao = QgsCoordinateTransform(layer.crs(), visualizador.raster_layer.crs(), QgsProject.instance())

            renderer = layer.renderer()
            grupos_estilo = {}

            try:
                contexto.expressionContext().setFields(layer.fields())
            except Exception:
                pass  # nosec B110

            if renderer is not None:
                try:
                    renderer.startRender(contexto, layer.fields())
                except Exception:
                    renderer = None

            try:
                for feature in layer.getFeatures():
                    try:
                        contexto.expressionContext().setFeature(feature)
                    except Exception:
                        pass  # nosec B110

                    geometria = feature.geometry()

                    if (geometria is None
                        or geometria.isEmpty()):

                        continue

                    if transformacao is not None:
                        try:
                            geometria.transform(transformacao)
                        except Exception as e:
                            QgsMessageLog.logMessage(self.tr("Falha ao transformar a geometria: {erro}").format(erro=str(e)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)
                            continue

                    try:
                        objeto_geometria = geometria.constGet()

                        if (objeto_geometria is not None
                            and objeto_geometria.hasCurvedSegments()):

                            geometria = geometria.segmentize()

                    except Exception:
                        pass  # nosec B110

                    if geometria.isMultipart():
                        partes = geometria.asMultiPolyline()
                    else:
                        parte = geometria.asPolyline()
                        partes = [parte] if parte else []

                    simbolo = None

                    if renderer is not None:
                        try:
                            simbolo = renderer.symbolForFeature(feature, contexto)
                        except Exception:
                            simbolo = None

                        if simbolo is None:
                            try:
                                simbolo = renderer.symbol()
                            except Exception:
                                simbolo = None

                        if simbolo is None:
                            continue

                    cor_qgis, _ = visualizador._estilo_linha_3d(simbolo)

                    cor_linha = (
                        float(cor_qgis[0]),
                        float(cor_qgis[1]),
                        float(cor_qgis[2]),
                        max(0.0, min(1.0, float(cor_qgis[3]) * opacidade_config)))

                    cor_parede = (
                        cor_linha[0],
                        cor_linha[1],
                        cor_linha[2],
                        max(0.0, min(1.0, cor_linha[3] * opacidade_parede)))

                    chave = (
                        tuple(round(valor, 5) for valor in cor_linha),
                        tuple(round(valor, 5) for valor in cor_parede),
                        round(espessura, 2))

                    grupo = grupos_estilo.setdefault(chave, {
                        "linhas": [],
                        "vertices_parede": [],
                        "faces_parede": []})

                    for parte in partes:
                        for segmento in visualizador._segmentos_linha_3d(parte, altura):
                            if len(segmento) < 2:
                                continue

                            pares = np.empty(((len(segmento) - 1) * 2, 3), dtype=np.float32)
                            pares[0::2] = segmento[:-1]
                            pares[1::2] = segmento[1:]
                            grupo["linhas"].append(pares)

                            if (mostrar_parede
                                and altura > 0.0):

                                vertices_parede, faces_parede = visualizador._criar_parede_segmento_linha(segmento, altura)

                                if (vertices_parede is not None
                                    and faces_parede is not None):

                                    deslocamento = sum(len(vertices) for vertices in grupo["vertices_parede"])
                                    grupo["vertices_parede"].append(vertices_parede)
                                    grupo["faces_parede"].append(faces_parede + deslocamento)

            finally:
                if renderer is not None:
                    try:
                        renderer.stopRender(contexto)
                    except Exception:
                        pass  # nosec B110

            for chave, grupo in grupos_estilo.items():
                cor_linha, cor_parede, espessura_grupo = chave

                if not grupo["linhas"]:
                    continue

                posicoes = np.ascontiguousarray(np.vstack(grupo["linhas"]), dtype=np.float32)

                dados_grupo = {
                    "camada": layer.name(),
                    "ordem": int(ordem),
                    "cor": [float(cor_linha[0]), float(cor_linha[1]), float(cor_linha[2])],
                    "opacidade": float(cor_linha[3]),
                    "espessura": float(espessura_grupo),
                    "quantidade_segmentos": int(len(posicoes) // 2),
                    "posicoes_b64": self._array_para_base64(posicoes, "<f4"),
                    "parede": None}

                if (grupo["vertices_parede"]
                    and grupo["faces_parede"]):

                    vertices_parede = np.ascontiguousarray(np.vstack(grupo["vertices_parede"]), dtype=np.float32)
                    faces_parede = np.ascontiguousarray(np.vstack(grupo["faces_parede"]), dtype=np.uint32)

                    dados_grupo["parede"] = {
                        "cor": [float(cor_parede[0]), float(cor_parede[1]), float(cor_parede[2])],
                        "opacidade": float(cor_parede[3]),
                        "vertices_b64": self._array_para_base64(vertices_parede, "<f4"),
                        "faces_b64": self._array_para_base64(faces_parede, "<u4")}

                grupos_saida.append(dados_grupo)

        return {"ativo": bool(grupos_saida), "grupos": grupos_saida}

    def _exportar_linhas(self, pasta_saida):
        """
        Exporta as linhas e paredes para assets/linhas.js.
        """
        dados = self._coletar_dados_linhas()
        caminho = os.path.join(pasta_saida, "assets", "linhas.js")

        with open(caminho, "w", encoding="utf-8") as arquivo:
            arquivo.write("window.TEMPO_SALVO_LINHAS = ")
            json.dump(dados, arquivo, ensure_ascii=False, separators=(",", ":"))
            arquivo.write(";\n")

    def _coletar_pintura_poligono_web(self, layer, ordem, config, contexto):
        """
        Converte o modo Pintura rápida em grupos de faces para a Web.
        """
        visualizador = self.visualizador
        largura = int(visualizador._grade_x)
        altura_grade = int(visualizador._grade_y)

        if (largura <= 0
            or altura_grade <= 0):

            return []

        opacidade_config = max(0.0, min(100.0, float(config.get("opacidade", 100.0)))) / 100.0

        if opacidade_config <= 0.0:
            return []

        altura = float(config.get("altura", 0.0))
        exagero = float(visualizador.spin_exagero.value())
        altura_3d = altura * exagero
        folga_z = max(0.002, abs(visualizador._z_max - visualizador._z_min) * exagero * 0.00002)

        imagem = QImage(largura, altura_grade, QImage.Format.Format_RGBA8888)
        imagem.fill(QColor(0, 0, 0, 0))

        painter = QPainter(imagem)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, False)

        transformacao = None

        if (layer.crs().isValid()
            and visualizador.raster_layer.crs().isValid()
            and layer.crs() != visualizador.raster_layer.crs()):

            transformacao = QgsCoordinateTransform(layer.crs(), visualizador.raster_layer.crs(), QgsProject.instance())

        renderer = layer.renderer()

        try:
            contexto.expressionContext().setFields(layer.fields())
        except Exception:
            pass  # nosec B110

        if renderer is not None:
            try:
                renderer.startRender(contexto, layer.fields())
            except Exception:
                renderer = None

        try:
            for feature in layer.getFeatures():
                try:
                    contexto.expressionContext().setFeature(feature)
                except Exception:
                    pass  # nosec B110

                geometria = feature.geometry()

                if (geometria is None
                    or geometria.isEmpty()):

                    continue

                if transformacao is not None:
                    try:
                        geometria.transform(transformacao)
                    except Exception as e:
                        QgsMessageLog.logMessage(self.tr("Falha ao transformar a geometria: {erro}").format(erro=str(e)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)
                        continue

                try:
                    objeto_geometria = geometria.constGet()

                    if (objeto_geometria is not None
                        and objeto_geometria.hasCurvedSegments()):

                        geometria = geometria.segmentize()
                except Exception:
                    pass  # nosec B110

                caminho = visualizador._caminho_poligono_grade_pintura(geometria)

                if caminho is None:
                    continue

                simbolo = None

                if renderer is not None:
                    try:
                        simbolo = renderer.symbolForFeature(feature, contexto)
                    except Exception:
                        simbolo = None

                    if simbolo is None:
                        try:
                            simbolo = renderer.symbol()
                        except Exception:
                            simbolo = None

                cor = visualizador._estilo_poligono_preenchimento_3d(simbolo)
                alpha = max(0.0, min(1.0, float(cor[3]) * opacidade_config))

                if alpha <= 0.0:
                    continue

                painter.fillPath(caminho, QColor.fromRgbF(float(cor[0]), float(cor[1]), float(cor[2]), alpha))

        finally:
            painter.end()

            if renderer is not None:
                try:
                    renderer.stopRender(contexto)
                except Exception:
                    pass  # nosec B110

        ponteiro = imagem.bits()
        ponteiro.setsize(imagem.sizeInBytes())

        rgba = np.array(ponteiro, dtype=np.uint8).reshape(altura_grade, largura, 4)
        pixels_faces = visualizador._pixels_centros_faces_pintura()

        if pixels_faces is None:
            return []

        pixel_x, pixel_y = pixels_faces
        cores_faces = rgba[pixel_y, pixel_x]
        mascara = cores_faces[:, 3] > 0

        if not np.any(mascara):
            return []

        faces_selecionadas = visualizador._faces[mascara]
        cores_selecionadas = cores_faces[mascara]

        cores_unicas, indices_cores = np.unique(cores_selecionadas, axis=0, return_inverse=True)
        grupos = []

        for indice_cor, rgba_cor in enumerate(cores_unicas):
            mascara_cor = indices_cores == indice_cor
            faces_cor = faces_selecionadas[mascara_cor]

            if not len(faces_cor):
                continue

            vertices_usados, faces_locais = np.unique(faces_cor.reshape(-1), return_inverse=True)
            vertices = visualizador._vertices_base[vertices_usados].astype(np.float32, copy=True)
            vertices[:, 2] = vertices[:, 2] * exagero + altura_3d + folga_z
            faces_locais = faces_locais.reshape(-1, 3).astype(np.uint32, copy=False)

            grupos.append({
                "camada": layer.name(),
                "ordem": int(ordem),
                "modo": "pintura",
                "cor": [float(rgba_cor[0]) / 255.0, float(rgba_cor[1]) / 255.0, float(rgba_cor[2]) / 255.0],
                "opacidade": float(rgba_cor[3]) / 255.0,
                "vertices_b64": self._array_para_base64(vertices, "<f4"),
                "faces_b64": self._array_para_base64(faces_locais, "<u4")})

        return grupos

    def _coletar_superficie_poligono_web(self, layer, ordem, config, contexto):
        """
        Coleta preenchimento em Superfície 3D ou Recorte preciso.
        """
        visualizador = self.visualizador
        modo = str(config.get("modo_preenchimento", "superficie"))
        opacidade_config = max(0.0, min(100.0, float(config.get("opacidade", 100.0)))) / 100.0
        altura = float(config.get("altura", 0.05))
        exagero = float(visualizador.spin_exagero.value())
        altura_3d = altura * exagero
        folga_z = max(0.002, abs(visualizador._z_max - visualizador._z_min) * exagero * 0.00002)
        faces_base = visualizador._faces

        transformacao = None

        if (layer.crs().isValid()
            and visualizador.raster_layer.crs().isValid()
            and layer.crs() != visualizador.raster_layer.crs()):

            transformacao = QgsCoordinateTransform(layer.crs(), visualizador.raster_layer.crs(), QgsProject.instance())

        renderer = layer.renderer()
        grupos_estilo = {}

        try:
            contexto.expressionContext().setFields(layer.fields())
        except Exception:
            pass  # nosec B110

        if renderer is not None:
            try:
                renderer.startRender(contexto, layer.fields())
            except Exception:
                renderer = None

        try:
            for feature in layer.getFeatures():
                try:
                    contexto.expressionContext().setFeature(feature)
                except Exception:
                    pass  # nosec B110

                geometria = feature.geometry()

                if (geometria is None
                    or geometria.isEmpty()):

                    continue

                if transformacao is not None:
                    try:
                        geometria.transform(transformacao)
                    except Exception as e:
                        QgsMessageLog.logMessage(self.tr("Falha ao transformar a geometria: {erro}").format(erro=str(e)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)

                try:
                    objeto_geometria = geometria.constGet()

                    if (objeto_geometria is not None
                        and objeto_geometria.hasCurvedSegments()):

                        geometria = geometria.segmentize()
                except Exception:
                    pass  # nosec B110

                simbolo = None

                if renderer is not None:
                    try:
                        simbolo = renderer.symbolForFeature(feature, contexto)
                    except Exception:
                        simbolo = None

                    if simbolo is None:
                        try:
                            simbolo = renderer.symbol()
                        except Exception:
                            simbolo = None

                cor_qgis = visualizador._estilo_poligono_preenchimento_3d(simbolo)

                cor = (
                    float(cor_qgis[0]),
                    float(cor_qgis[1]),
                    float(cor_qgis[2]),
                    max(0.0, min(1.0, float(cor_qgis[3]) * opacidade_config)))

                chave = tuple(round(valor, 6) for valor in cor)
                grupo = grupos_estilo.setdefault(chave, {"vertices": [], "faces": [], "quantidade_vertices": 0})

                if modo == "preciso":
                    faces_internas, faces_borda = visualizador._classificar_faces_poligono_grade(geometria)
                else:
                    faces_internas = visualizador._indices_faces_preenchimento_rapido(geometria)
                    faces_borda = np.empty(0, dtype=np.int32)

                if faces_internas.size:
                    indices_vertices = faces_base[faces_internas]
                    vertices = visualizador._vertices_base[indices_vertices].astype(np.float32, copy=True)
                    vertices[:, :, 2] = vertices[:, :, 2] * exagero + altura_3d + folga_z
                    vertices = vertices.reshape(-1, 3)
                    faces = np.arange(len(vertices), dtype=np.uint32).reshape(-1, 3)

                    deslocamento = grupo["quantidade_vertices"]
                    grupo["vertices"].append(vertices)
                    grupo["faces"].append(faces + deslocamento)
                    grupo["quantidade_vertices"] += len(vertices)

                vertices_borda = []
                faces_borda_local = []

                for indice_face in faces_borda:
                    idx0, idx1, idx2 = faces_base[indice_face]

                    p0 = QgsPointXY(float(visualizador._x_real[idx0]), float(visualizador._y_real[idx0]))
                    p1 = QgsPointXY(float(visualizador._x_real[idx1]), float(visualizador._y_real[idx1]))
                    p2 = QgsPointXY(float(visualizador._x_real[idx2]), float(visualizador._y_real[idx2]))
                    triangulo_geom = QgsGeometry.fromPolygonXY([[p0, p1, p2, p0]])

                    try:
                        if geometria.contains(triangulo_geom):
                            triangulos = [[p0, p1, p2]]

                        elif not geometria.intersects(triangulo_geom):
                            continue

                        else:
                            intersecao = geometria.intersection(triangulo_geom)

                            if (intersecao is None
                                or intersecao.isEmpty()):

                                continue

                            triangulos = visualizador._triangulos_da_geometria(intersecao)

                    except Exception as e:
                        QgsMessageLog.logMessage(self.tr("Falha ao processar a feição {id}: {erro}").format(id=feature.id(), erro=str(e)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)
                        continue

                    for tri in triangulos:
                        if len(tri) != 3:
                            continue

                        coords = []
                        valido = True

                        for ponto in tri:
                            x = float(ponto.x())
                            y = float(ponto.y())
                            z = visualizador._amostrar_cota_mdt(x, y)

                            if z is None:
                                valido = False
                                break

                            coords.append((
                                x - visualizador._x_centro,
                                y - visualizador._y_centro,
                                (z - visualizador._z_centro) * exagero + altura_3d + folga_z))

                        if not valido:
                            continue

                        inicio = len(vertices_borda)
                        vertices_borda.extend(coords)
                        faces_borda_local.append((inicio, inicio + 1, inicio + 2))

                if faces_borda_local:
                    vertices = np.asarray(vertices_borda, dtype=np.float32)
                    faces = np.asarray(faces_borda_local, dtype=np.uint32)

                    deslocamento = grupo["quantidade_vertices"]
                    grupo["vertices"].append(vertices)
                    grupo["faces"].append(faces + deslocamento)
                    grupo["quantidade_vertices"] += len(vertices)

        finally:
            if renderer is not None:
                try:
                    renderer.stopRender(contexto)
                except Exception:
                    pass  # nosec B110

        saida = []

        for cor, grupo in grupos_estilo.items():
            if (not grupo["vertices"]
                or not grupo["faces"]):

                continue

            vertices = np.ascontiguousarray(np.vstack(grupo["vertices"]), dtype=np.float32)
            faces = np.ascontiguousarray(np.vstack(grupo["faces"]), dtype=np.uint32)

            saida.append({
                "camada": layer.name(),
                "ordem": int(ordem),
                "modo": modo,
                "cor": [float(cor[0]), float(cor[1]), float(cor[2])],
                "opacidade": float(cor[3]),
                "vertices_b64": self._array_para_base64(vertices, "<f4"),
                "faces_b64": self._array_para_base64(faces, "<u4")})

        return saida

    def _coletar_preenchimentos_poligonos(self, camadas):
        """
        Coleta somente as tampas/preenchimentos dos polígonos.
        """
        if not camadas:
            return []

        visualizador = self.visualizador

        if visualizador.ui_manager is not None:
            contexto = QgsRenderContext.fromMapSettings(visualizador.ui_manager.iface.mapCanvas().mapSettings())
        else:
            contexto = QgsRenderContext()

        preenchimentos = []

        for ordem, layer in enumerate(reversed(camadas)):
            config = visualizador._obter_config_3d_camada("poligonos", layer)

            if not bool(config.get("preenchimento", True)):
                continue

            if float(config.get("opacidade", 100.0)) <= 0.0:
                continue

            modo = str(config.get("modo_preenchimento", "pintura"))

            if modo == "pintura":
                preenchimentos.extend(self._coletar_pintura_poligono_web(layer, ordem, config, contexto))
            else:
                preenchimentos.extend(self._coletar_superficie_poligono_web(layer, ordem, config, contexto))

        return preenchimentos

    def _coletar_dados_poligonos(self):
        """
        Coleta contornos e caixas dos polígonos atualmente exibidos sobre o MDT.
        O preenchimento superior será incorporado separadamente na Etapa 5B.
        """
        visualizador = self.visualizador

        sobreposicao_ativa = (getattr(visualizador, "check_sobreposicao", None) is not None
            and visualizador.check_sobreposicao.isChecked()
            and getattr(visualizador, "_sobrepor_poligonos", False))

        if not sobreposicao_ativa:
            return {"ativo": False, "grupos": [], "preenchimentos": []}

        camadas = list(getattr(visualizador, "_camadas_poligonos_sobreposicao", []))

        if not camadas:
            camadas = visualizador._obter_poligonos_sobre_mdt()

        if not camadas:
            return {"ativo": False, "grupos": [], "preenchimentos": []}

        preenchimentos_saida = self._coletar_preenchimentos_poligonos(camadas)

        if visualizador.ui_manager is not None:
            contexto = QgsRenderContext.fromMapSettings(visualizador.ui_manager.iface.mapCanvas().mapSettings())
        else:
            contexto = QgsRenderContext()

        grupos_saida = []

        for ordem, layer in enumerate(reversed(camadas)):
            config = visualizador._obter_config_3d_camada("poligonos", layer)

            altura = float(config.get("altura", 0.05))
            mostrar_caixa = bool(config.get("caixa", False))
            mostrar_contorno = bool(config.get("contorno", True))
            espessura_contorno = max(0.10, float(config.get("espessura_contorno", 2.0)))
            opacidade_config = max(0.0, min(100.0, float(config.get("opacidade", 100.0)))) / 100.0

            transformacao = None

            if (layer.crs().isValid()
                and visualizador.raster_layer.crs().isValid()
                and layer.crs() != visualizador.raster_layer.crs()):

                transformacao = QgsCoordinateTransform(layer.crs(), visualizador.raster_layer.crs(), QgsProject.instance())

            renderer = layer.renderer()

            try:
                contexto.expressionContext().setFields(layer.fields())
            except Exception:
                pass  # nosec B110

            if renderer is not None:
                try:
                    renderer.startRender(contexto, layer.fields())
                except Exception:
                    renderer = None

            try:
                for feature in layer.getFeatures():
                    try:
                        contexto.expressionContext().setFeature(feature)
                    except Exception:
                        pass  # nosec B110

                    geometria = feature.geometry()

                    if (geometria is None
                        or geometria.isEmpty()):

                        continue

                    if transformacao is not None:
                        try:
                            geometria.transform(transformacao)
                        except Exception as e:
                            QgsMessageLog.logMessage(self.tr("Falha ao transformar a geometria: {erro}").format(erro=str(e)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)
                            continue

                    try:
                        objeto_geometria = geometria.constGet()

                        if (objeto_geometria is not None
                            and objeto_geometria.hasCurvedSegments()):

                            geometria = geometria.segmentize()

                    except Exception:
                        pass  # nosec B110

                    if geometria.isMultipart():
                        poligonos = geometria.asMultiPolygon()
                    else:
                        poligono = geometria.asPolygon()
                        poligonos = [poligono] if poligono else []

                    if not poligonos:
                        continue

                    simbolo = None

                    if renderer is not None:
                        try:
                            simbolo = renderer.symbolForFeature(feature, contexto)
                        except Exception:
                            simbolo = None

                        if simbolo is None:
                            try:
                                simbolo = renderer.symbol()
                            except Exception:
                                simbolo = None

                    cor_contorno, _ = visualizador._estilo_poligono_contorno_3d(simbolo)
                    cor_preenchimento = visualizador._estilo_poligono_preenchimento_3d(simbolo)

                    cor_parede = (
                        float(cor_preenchimento[0]),
                        float(cor_preenchimento[1]),
                        float(cor_preenchimento[2]),
                        max(0.0, min(1.0, float(cor_preenchimento[3]) * opacidade_config)))

                    blocos_contorno = []
                    vertices_parede = []
                    faces_parede = []
                    quantidade_vertices_parede = 0

                    for poligono in poligonos:
                        for anel in poligono:
                            if not anel or len(anel) < 2:
                                continue

                            pontos_anel = list(anel)

                            if (pontos_anel[0].x() != pontos_anel[-1].x()
                                or pontos_anel[0].y() != pontos_anel[-1].y()):

                                pontos_anel.append(pontos_anel[0])

                            segmentos_topo = visualizador._segmentos_linha_3d(pontos_anel, altura)

                            if mostrar_contorno:
                                for segmento in segmentos_topo:
                                    if len(segmento) < 2:
                                        continue

                                    pares = np.empty(((len(segmento) - 1) * 2, 3), dtype=np.float32)
                                    pares[0::2] = segmento[:-1]
                                    pares[1::2] = segmento[1:]
                                    blocos_contorno.append(pares)

                            if (mostrar_caixa
                                and abs(altura) > 1e-9):

                                if mostrar_contorno:
                                    for segmento_base in visualizador._segmentos_linha_3d(pontos_anel, 0.0):
                                        if len(segmento_base) < 2:
                                            continue

                                        pares_base = np.empty(((len(segmento_base) - 1) * 2, 3), dtype=np.float32)
                                        pares_base[0::2] = segmento_base[:-1]
                                        pares_base[1::2] = segmento_base[1:]
                                        blocos_contorno.append(pares_base)

                                    pares_verticais = visualizador._pares_arestas_verticais_poligono_3d(pontos_anel, altura)

                                    if (pares_verticais is not None
                                        and len(pares_verticais) >= 2):

                                        blocos_contorno.append(pares_verticais)

                                if opacidade_config > 0.0:
                                    for segmento in segmentos_topo:
                                        vertices, faces = visualizador._criar_parede_poligono_3d(segmento, altura)

                                        if (vertices is None
                                            or faces is None):

                                            continue

                                        vertices_parede.append(vertices)
                                        faces_parede.append(faces + quantidade_vertices_parede)
                                        quantidade_vertices_parede += len(vertices)

                    if (not blocos_contorno
                        and not vertices_parede):

                        continue

                    dados_grupo = {
                        "camada": layer.name(),
                        "feature_id": int(feature.id()),
                        "ordem": int(ordem),
                        "altura": float(altura),
                        "caixa": mostrar_caixa,
                        "contorno": mostrar_contorno,
                        "cor_contorno": [
                            float(cor_contorno[0]),
                            float(cor_contorno[1]),
                            float(cor_contorno[2])],
                        "opacidade_contorno": float(cor_contorno[3]),
                        "espessura_contorno": float(espessura_contorno),
                        "posicoes_contorno_b64": None,
                        "parede": None}

                    if blocos_contorno:
                        posicoes = np.ascontiguousarray(np.vstack(blocos_contorno), dtype=np.float32)
                        dados_grupo["posicoes_contorno_b64"] = self._array_para_base64(posicoes, "<f4")

                    if (vertices_parede
                        and faces_parede):

                        vertices = np.ascontiguousarray(np.vstack(vertices_parede), dtype=np.float32)
                        faces = np.ascontiguousarray(np.vstack(faces_parede), dtype=np.uint32)

                        dados_grupo["parede"] = {
                            "cor": [
                                float(cor_parede[0]),
                                float(cor_parede[1]),
                                float(cor_parede[2])],
                            "opacidade": float(cor_parede[3]),
                            "vertices_b64": self._array_para_base64(vertices, "<f4"),
                            "faces_b64": self._array_para_base64(faces, "<u4")}

                    grupos_saida.append(dados_grupo)

            finally:
                if renderer is not None:
                    try:
                        renderer.stopRender(contexto)
                    except Exception:
                        pass  # nosec B110

        return {
            "ativo": bool(grupos_saida or preenchimentos_saida),
            "grupos": grupos_saida,
            "preenchimentos": preenchimentos_saida}

    def _exportar_poligonos(self, pasta_saida):
        """
        Exporta contornos e caixas dos polígonos para assets/poligonos.js.
        """
        dados = self._coletar_dados_poligonos()
        caminho = os.path.join(pasta_saida, "assets", "poligonos.js")

        with open(caminho, "w", encoding="utf-8") as arquivo:
            arquivo.write("window.TEMPO_SALVO_POLIGONOS = ")
            json.dump(dados, arquivo, ensure_ascii=False, separators=(",", ":"))
            arquivo.write(";\n")

    def _coletar_dados_pontos(self):
        """
        Coleta pontos e hastes atualmente exibidos sobre o MDT.
        """
        visualizador = self.visualizador

        sobreposicao_ativa = (getattr(visualizador, "check_sobreposicao", None) is not None
            and visualizador.check_sobreposicao.isChecked()
            and getattr(visualizador, "_sobrepor_pontos", False))

        if not sobreposicao_ativa:
            return {"ativo": False, "pontos": [], "hastes": []}

        camadas = list(getattr(visualizador, "_camadas_pontos_sobreposicao", []))

        if not camadas:
            camadas = visualizador._obter_pontos_sobre_mdt()

        if not camadas:
            return {"ativo": False, "pontos": [], "hastes": []}

        exagero = float(visualizador.spin_exagero.value())
        folga_z = max(0.002, abs(visualizador._z_max - visualizador._z_min) * exagero * 0.00002)

        if visualizador.ui_manager is not None:
            contexto = QgsRenderContext.fromMapSettings(visualizador.ui_manager.iface.mapCanvas().mapSettings())
        else:
            contexto = QgsRenderContext()

        pontos_saida = []
        hastes_saida = []

        for ordem, layer in enumerate(reversed(camadas)):
            config = visualizador._obter_config_3d_camada("pontos", layer)

            altura = float(config.get("altura", 0.05))
            tamanho = max(1.0, float(config.get("tamanho", 7.0)))
            mostrar_haste = bool(config.get("haste", False))
            altura_haste = max(0.0, float(config.get("altura_haste", 5.0)))
            espessura_haste = max(0.10, float(config.get("espessura_haste", 1.0)))

            altura_3d = altura * exagero
            altura_haste_3d = altura_haste * exagero

            transformacao = None

            if (layer.crs().isValid()
                and visualizador.raster_layer.crs().isValid()
                and layer.crs() != visualizador.raster_layer.crs()):

                transformacao = QgsCoordinateTransform(layer.crs(), visualizador.raster_layer.crs(), QgsProject.instance())

            renderer = layer.renderer()
            grupos_pontos = {}
            grupos_hastes = {}

            try:
                contexto.expressionContext().setFields(layer.fields())
            except Exception:
                pass  # nosec B110

            if renderer is not None:
                try:
                    renderer.startRender(contexto, layer.fields())
                except Exception:
                    renderer = None

            try:
                for feature in layer.getFeatures():
                    try:
                        contexto.expressionContext().setFeature(feature)
                    except Exception:
                        pass  # nosec B110

                    geometria = feature.geometry()

                    if (geometria is None
                        or geometria.isEmpty()):

                        continue

                    if transformacao is not None:
                        try:
                            geometria.transform(transformacao)
                        except Exception as e:
                            QgsMessageLog.logMessage(self.tr("Falha ao transformar a geometria: {erro}").format(erro=str(e)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)
                            continue

                    if geometria.isMultipart():
                        pontos = geometria.asMultiPoint()
                    else:
                        ponto = geometria.asPoint()
                        pontos = [ponto] if ponto else []

                    if not pontos:
                        continue

                    simbolo = None

                    if renderer is not None:
                        try:
                            simbolo = renderer.symbolForFeature(feature, contexto)
                        except Exception:
                            simbolo = None

                        if simbolo is None:
                            try:
                                simbolo = renderer.symbol()
                            except Exception:
                                simbolo = None

                    cor, _ = visualizador._estilo_ponto_3d(simbolo)

                    chave_ponto = (tuple(round(float(valor), 5) for valor in cor), round(tamanho, 2))
                    posicoes = grupos_pontos.setdefault(chave_ponto, [])

                    chave_haste = (tuple(round(float(valor), 5) for valor in cor), round(espessura_haste, 2))
                    hastes = grupos_hastes.setdefault(chave_haste, [])

                    for ponto in pontos:
                        x = float(ponto.x())
                        y = float(ponto.y())
                        z = visualizador._amostrar_cota_mdt(x, y)

                        if z is None:
                            continue

                        x_3d = x - visualizador._x_centro
                        y_3d = y - visualizador._y_centro
                        z_ponto = (z - visualizador._z_centro) * exagero + altura_3d + folga_z

                        posicoes.append((x_3d, y_3d, z_ponto))

                        if (mostrar_haste
                            and altura_haste_3d > 1e-9):

                            hastes.extend(((x_3d, y_3d, z_ponto), (x_3d, y_3d, z_ponto + altura_haste_3d)))

            finally:
                if renderer is not None:
                    try:
                        renderer.stopRender(contexto)
                    except Exception:
                        pass  # nosec B110

            for chave, posicoes in grupos_pontos.items():
                if not posicoes:
                    continue

                cor, tamanho_grupo = chave
                posicoes_np = np.ascontiguousarray(np.asarray(posicoes, dtype=np.float32))

                pontos_saida.append({
                    "camada": layer.name(),
                    "ordem": int(ordem),
                    "cor": [float(cor[0]), float(cor[1]), float(cor[2])],
                    "opacidade": float(cor[3]),
                    "tamanho": float(tamanho_grupo),
                    "quantidade": int(len(posicoes_np)),
                    "posicoes_b64": self._array_para_base64(posicoes_np, "<f4")})

            if mostrar_haste:
                for chave, posicoes in grupos_hastes.items():
                    if not posicoes:
                        continue

                    cor, espessura = chave
                    posicoes_np = np.ascontiguousarray(np.asarray(posicoes, dtype=np.float32))

                    hastes_saida.append({
                        "camada": layer.name(),
                        "ordem": int(ordem),
                        "cor": [float(cor[0]), float(cor[1]), float(cor[2])],
                        "opacidade": float(cor[3]),
                        "espessura": float(espessura),
                        "quantidade_segmentos": int(len(posicoes_np) // 2),
                        "posicoes_b64": self._array_para_base64(posicoes_np, "<f4")})

        return {
            "ativo": bool(pontos_saida),
            "pontos": pontos_saida,
            "hastes": hastes_saida}

    def _exportar_pontos(self, pasta_saida):
        """
        Exporta pontos e hastes para assets/pontos.js.
        """
        dados = self._coletar_dados_pontos()
        caminho = os.path.join(pasta_saida, "assets", "pontos.js")

        with open(caminho, "w", encoding="utf-8") as arquivo:
            arquivo.write("window.TEMPO_SALVO_PONTOS = ")
            json.dump(dados, arquivo, ensure_ascii=False, separators=(",", ":"))
            arquivo.write(";\n")

    def _cor_qt_para_web(self, cor):
        """
        Converte QColor para componentes RGB/A utilizados na Web.
        """
        try:
            cor = QColor(cor)

            if cor.isValid():
                return [
                    int(cor.red()),
                    int(cor.green()),
                    int(cor.blue()),
                    float(cor.alphaF())]

        except Exception:
            pass  # nosec B110

        return [255, 255, 255, 1.0]

    def _coletar_rotulos_linhas_web(self, camadas, contexto):
        visualizador = self.visualizador
        saida = []

        for ordem, layer in enumerate(reversed(camadas)):
            config = visualizador._obter_config_3d_camada("linhas", layer)

            if not bool(config.get("rotulo", False)):
                continue

            campo = config.get("campo_rotulo")

            if not campo:
                continue

            altura = max(0.0, float(config.get("altura", 0.05)))
            altura_rotulo = max(0.0, float(config.get("altura_rotulo", 2.0)))
            tamanho = max(6, int(config.get("tamanho_rotulo", 10)))
            ocultar_encoberto = bool(config.get("ocultar_rotulo_encoberto", False))

            transformacao = None

            if (layer.crs().isValid()
                and visualizador.raster_layer.crs().isValid()
                and layer.crs() != visualizador.raster_layer.crs()):

                transformacao = QgsCoordinateTransform(layer.crs(), visualizador.raster_layer.crs(), QgsProject.instance())

            try:
                contexto.expressionContext().setFields(layer.fields())
            except Exception:
                pass  # nosec B110

            for feature in layer.getFeatures():
                try:
                    contexto.expressionContext().setFeature(feature)
                except Exception:
                    pass  # nosec B110

                geometria = feature.geometry()

                if (geometria is None
                    or geometria.isEmpty()):

                    continue

                if transformacao is not None:
                    try:
                        geometria.transform(transformacao)
                    except Exception as e:
                        QgsMessageLog.logMessage(self.tr("Falha ao transformar a geometria: {erro}").format(erro=str(e)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)
                        continue

                try:
                    objeto = geometria.constGet()

                    if (objeto is not None
                        and objeto.hasCurvedSegments()):

                        geometria = geometria.segmentize()
                except Exception:
                    pass  # nosec B110

                texto = visualizador._texto_rotulo_feature(feature, campo)

                if not texto:
                    continue

                posicao = visualizador._posicao_rotulo_linha_3d(geometria, altura, altura_rotulo)

                if posicao is None:
                    continue

                cor = visualizador._cor_rotulo_linha_qgis(layer, feature, contexto)

                saida.append({
                    "tipo": "linhas",
                    "camada": layer.name(),
                    "ordem": int(ordem),
                    "texto": str(texto),
                    "posicao": [float(posicao[0]), float(posicao[1]), float(posicao[2])],
                    "cor": self._cor_qt_para_web(cor),
                    "tamanho": int(tamanho),
                    "ocultar_encoberto": ocultar_encoberto})

        return saida

    def _coletar_rotulos_poligonos_web(self, camadas):
        visualizador = self.visualizador
        saida = []

        for ordem, layer in enumerate(reversed(camadas)):
            config = visualizador._obter_config_3d_camada("poligonos", layer)

            if not bool(config.get("rotulo", False)):
                continue

            campo = config.get("campo_rotulo")

            if not campo:
                continue

            altura = float(config.get("altura", 0.05))
            altura_rotulo = max(0.0, float(config.get("altura_rotulo", 2.0)))
            tamanho = max(6, int(config.get("tamanho_rotulo", 10)))
            ocultar_encoberto = bool(config.get("ocultar_rotulo_encoberto", False))
            cor = visualizador._cor_rotulo_poligono_qgis(layer)

            transformacao = None

            if (layer.crs().isValid()
                and visualizador.raster_layer.crs().isValid()
                and layer.crs() != visualizador.raster_layer.crs()):

                transformacao = QgsCoordinateTransform(layer.crs(), visualizador.raster_layer.crs(), QgsProject.instance())

            for feature in layer.getFeatures():
                geometria = feature.geometry()

                if (geometria is None
                    or geometria.isEmpty()):

                    continue

                if transformacao is not None:
                    try:
                        geometria.transform(transformacao)
                    except Exception as e:
                        QgsMessageLog.logMessage(self.tr("Falha ao transformar a geometria: {erro}").format(erro=str(e)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)
                        continue

                texto = visualizador._texto_rotulo_feature(feature, campo)

                if not texto:
                    continue

                posicao = visualizador._posicao_rotulo_poligono_3d(geometria, altura, altura_rotulo)

                if posicao is None:
                    continue

                saida.append({
                    "tipo": "poligonos",
                    "camada": layer.name(),
                    "ordem": int(ordem),
                    "texto": str(texto),
                    "posicao": [float(posicao[0]), float(posicao[1]), float(posicao[2])],
                    "cor": self._cor_qt_para_web(cor),
                    "tamanho": int(tamanho),
                    "ocultar_encoberto": ocultar_encoberto})

        return saida

    def _coletar_rotulos_pontos_web(self, camadas):
        visualizador = self.visualizador
        saida = []

        exagero = float(visualizador.spin_exagero.value())
        folga_z = max(0.002, abs(visualizador._z_max - visualizador._z_min) * exagero * 0.00002)

        for ordem, layer in enumerate(reversed(camadas)):
            config = visualizador._obter_config_3d_camada("pontos", layer)

            if not bool(config.get("rotulo", False)):
                continue

            campo = config.get("campo_rotulo")

            if not campo:
                continue

            altura = float(config.get("altura", 0.05))
            mostrar_haste = bool(config.get("haste", False))
            altura_haste = max(0.0, float(config.get("altura_haste", 5.0)))
            altura_rotulo = max(0.0, float(config.get("altura_rotulo", 0.5)))
            tamanho = max(6, int(config.get("tamanho_rotulo", 10)))
            ocultar_encoberto = bool(config.get("ocultar_rotulo_encoberto", False))

            altura_3d = altura * exagero
            altura_haste_3d = altura_haste * exagero
            altura_rotulo_3d = altura_rotulo * exagero

            cor = visualizador._cor_rotulo_ponto_qgis(layer)
            transformacao = None

            if (layer.crs().isValid()
                and visualizador.raster_layer.crs().isValid()
                and layer.crs() != visualizador.raster_layer.crs()):

                transformacao = QgsCoordinateTransform(layer.crs(), visualizador.raster_layer.crs(), QgsProject.instance())

            for feature in layer.getFeatures():
                geometria = feature.geometry()

                if (geometria is None
                    or geometria.isEmpty()):

                    continue

                if transformacao is not None:
                    try:
                        geometria.transform(transformacao)
                    except Exception as e:
                        QgsMessageLog.logMessage(self.tr("Falha ao transformar a geometria: {erro}").format(erro=str(e)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)
                        continue

                if geometria.isMultipart():
                    pontos = geometria.asMultiPoint()
                else:
                    ponto = geometria.asPoint()
                    pontos = [ponto] if ponto else []

                texto = visualizador._texto_rotulo_feature(feature, campo)

                if not texto:
                    continue

                for ponto in pontos:
                    x = float(ponto.x())
                    y = float(ponto.y())
                    z = visualizador._amostrar_cota_mdt(x, y)

                    if z is None:
                        continue

                    x_3d = x - visualizador._x_centro
                    y_3d = y - visualizador._y_centro
                    z_rotulo = (z - visualizador._z_centro) * exagero + altura_3d + folga_z

                    if (mostrar_haste
                        and altura_haste_3d > 1e-9):

                        z_rotulo += altura_haste_3d

                    z_rotulo += altura_rotulo_3d

                    saida.append({
                        "tipo": "pontos",
                        "camada": layer.name(),
                        "ordem": int(ordem),
                        "texto": str(texto),
                        "posicao": [float(x_3d), float(y_3d), float(z_rotulo)],
                        "cor": self._cor_qt_para_web(cor),
                        "tamanho": int(tamanho),
                        "ocultar_encoberto": ocultar_encoberto})

        return saida

    def _coletar_dados_rotulos(self):
        visualizador = self.visualizador

        if (getattr(visualizador, "check_sobreposicao", None) is None
            or not visualizador.check_sobreposicao.isChecked()):

            return {"ativo": False, "rotulos": []}

        if visualizador.ui_manager is not None:
            contexto = QgsRenderContext.fromMapSettings(visualizador.ui_manager.iface.mapCanvas().mapSettings())
        else:
            contexto = QgsRenderContext()

        rotulos = []

        if getattr(visualizador, "_sobrepor_linhas", False):
            camadas = list(getattr(visualizador, "_camadas_linhas_sobreposicao", []))

            if not camadas:
                camadas = visualizador._obter_linhas_sobre_mdt()

            rotulos.extend(self._coletar_rotulos_linhas_web(camadas, contexto))

        if getattr(visualizador, "_sobrepor_poligonos", False):
            camadas = list(getattr(visualizador, "_camadas_poligonos_sobreposicao", []))

            if not camadas:
                camadas = visualizador._obter_poligonos_sobre_mdt()

            rotulos.extend(self._coletar_rotulos_poligonos_web(camadas))

        if getattr(visualizador, "_sobrepor_pontos", False):
            camadas = list(getattr(visualizador, "_camadas_pontos_sobreposicao", []))

            if not camadas:
                camadas = visualizador._obter_pontos_sobre_mdt()

            rotulos.extend(self._coletar_rotulos_pontos_web(camadas))

        return {
            "ativo": bool(rotulos),
            "rotulos": rotulos}

    def _exportar_rotulos(self, pasta_saida):
        """
        Exporta os rótulos das sobreposições para assets/rotulos.js.
        """
        dados = self._coletar_dados_rotulos()
        caminho = os.path.join(pasta_saida, "assets", "rotulos.js")

        with open(caminho, "w", encoding="utf-8") as arquivo:
            arquivo.write("window.TEMPO_SALVO_ROTULOS = ")
            json.dump(dados, arquivo, ensure_ascii=False, separators=(",", ":"))
            arquivo.write(";\n")

