        # Camadas e objetos OpenGL usados na sobreposição de polígonos.
        self._camadas_poligonos_sobreposicao = []
        self._itens_poligonos_sobreposicao = []
        self._itens_rotulos_poligonos_sobreposicao = []

        # Pixels correspondentes aos centroides das faces do MDT, evita recalcular esse mapeamento em cada pintura de polígonos.
        self._cache_pixels_faces_pintura = {}

        # Cache dos objetos 3D de polígonos por qualidade do terreno.
        self._cache_poligonos_3d = {}
        self._chave_cache_poligonos_ativa = None

        # Índice direto célula → faces do MDT, separado por qualidade.
        self._cache_indice_faces_poligono = {}

        # Camadas e objetos OpenGL usados na sobreposição de pontos.
        self._camadas_pontos_sobreposicao = []
        self._itens_pontos_sobreposicao = []
        self._itens_hastes_pontos_sobreposicao = []
        self._itens_rotulos_pontos_sobreposicao = []

