    def tr(self, message):
        return QCoreApplication.translate("VisualizadorRaster3DManager", message)

    def _criar_hline(self, parent):
        linha = QFrame(parent)
        linha.setFrameShape(QFrame.Shape.HLine)
        linha.setFrameShadow(QFrame.Shadow.Sunken)
        return linha

    def _criar_interface(self):
        # ÁREA CENTRAL DO VISUALIZADOR
        self.view = GradientGLViewWidget(self)

        self.view.definir_fundo_solido(QColor(245, 245, 245))

        self.view.opts["antialias"] = True

        self.setCentralWidget(self.view)

        # Faz o painel direito ocupar também
        # o canto inferior direito.
        self.setCorner(Qt.Corner.BottomRightCorner, Qt.DockWidgetArea.RightDockWidgetArea)
        self.setCorner(Qt.Corner.TopRightCorner, Qt.DockWidgetArea.RightDockWidgetArea)

        # Aviso de SRC exibido sobre a área 3D.
        self.label_aviso_crs_3d = QLabel(self.view)

        self.label_aviso_crs_3d.setText(self.tr("Atenção: raster em coordenadas geográficas. Converta para um SRC UTM antes da visualização 3D."))

        self.label_aviso_crs_3d.setAlignment(
            Qt.AlignmentFlag.AlignCenter)

        self.label_aviso_crs_3d.setWordWrap(True)
        self.label_aviso_crs_3d.setFixedHeight(44)

        self.label_aviso_crs_3d.setStyleSheet(
            "QLabel {"
            "background-color: rgba(255, 245, 210, 225);"
            "color: #9a3d00;"
            "border: 1px solid #d89b55;"
            "border-radius: 4px;"
            "font-weight: bold;"
            "padding: 4px 10px;"
            "}")

        self.label_aviso_crs_3d.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)

        crs_raster = self.raster_layer.crs()

        self.label_aviso_crs_3d.setVisible(
            bool(crs_raster.isValid()
                and crs_raster.isGeographic()))

        self.view.cameraAlterada.connect(self._solicitar_atualizacao_oclusao_rotulos)
        self.view.cenaRenderizada.connect(self._atualizar_oclusao_rotulos)

        self.view.cameraAlterada.connect(self._reposicionar_texto_cursor_perfil_mapa_3d)
        self.view.cenaRenderizada.connect(self._reposicionar_texto_cursor_perfil_mapa_3d)

        # Indicador discreto de processamento sobre a área 3D.
        self.frame_progresso_3d = QFrame(self.view)
        self.frame_progresso_3d.setFrameShape(QFrame.Shape.StyledPanel)
        self.frame_progresso_3d.setFixedSize(320, 56)
        self.frame_progresso_3d.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)

        layout_progresso_3d = QVBoxLayout(self.frame_progresso_3d)
        layout_progresso_3d.setContentsMargins(8, 5, 8, 5)
        layout_progresso_3d.setSpacing(3)

        self.label_progresso_3d = QLabel(self.tr("Processando terreno..."), self.frame_progresso_3d)

        self.progress_progresso_3d = QProgressBar(self.frame_progresso_3d)

        self.progress_progresso_3d.setRange(0, 0)
        self.progress_progresso_3d.setTextVisible(False)
        self.progress_progresso_3d.setFixedHeight(16)

        layout_progresso_3d.addWidget(self.label_progresso_3d)
        layout_progresso_3d.addWidget(self.progress_progresso_3d)

        self.frame_progresso_3d.hide()

        # Frame lateral para as configurações.
        painel = QFrame()
        painel.setFrameShape(QFrame.Shape.Box)
        painel.setFrameShadow(QFrame.Shadow.Raised)
        painel.setMinimumWidth(215)
        painel.setMaximumWidth(265)

        # Layout interno do painel.
        painel_layout = QVBoxLayout()
        painel_layout.setContentsMargins(10, 10, 10, 10)
        painel_layout.setSpacing(8)
        painel.setLayout(painel_layout)

        # Texto "Configurações:" fixado no topo.
        label = QLabel(self.tr("Configurações:"))
        label.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop)

        painel_layout.addWidget(label, alignment=Qt.AlignmentFlag.AlignTop)

        # Mantém os controles agrupados na parte inferior do painel.
        vertical_spacer = QSpacerItem(20, 40, QSizePolicy.Policy.Minimum, QSizePolicy.Policy.Expanding)

        painel_layout.addItem(vertical_spacer)

        # Quadro com informações do raster.
        frame_info = QFrame(painel)
        frame_info.setFrameShape(QFrame.Shape.Box)
        frame_info.setFrameShadow(QFrame.Shadow.Sunken)
        frame_info.setLineWidth(1)

        info_layout = QGridLayout(frame_info)
        info_layout.setContentsMargins(8, 8, 8, 8)
        info_layout.setHorizontalSpacing(6)
        info_layout.setVerticalSpacing(4)

        self.label_nome = QLabel(self.raster_layer.name(), frame_info)

        self.label_nome.setWordWrap(True)

        self.label_crs = QLabel(self.raster_layer.crs().authid()
            or self.tr("Sem SRC"), frame_info)

        self.label_dimensoes = QLabel(
            f"{self.raster_layer.width()} × "
            f"{self.raster_layer.height()}",
            frame_info)

        self.label_intervalo = QLabel("-", frame_info)
        self.label_amostragem = QLabel("-", frame_info)

        info_layout.addWidget(QLabel(self.tr("Raster:"), frame_info), 0, 0)
        info_layout.addWidget(self.label_nome, 0, 1)
        info_layout.addWidget(QLabel(self.tr("SRC:"), frame_info), 1, 0)
        info_layout.addWidget(self.label_crs, 1, 1)
        info_layout.addWidget(QLabel(self.tr("Dimensões:"), frame_info), 2, 0)
        info_layout.addWidget(self.label_dimensoes, 2, 1)
        info_layout.addWidget(QLabel(self.tr("Elevação:"), frame_info), 3, 0)
        info_layout.addWidget(self.label_intervalo, 3, 1)
        info_layout.addWidget(QLabel(self.tr("Grade 3D:"), frame_info), 4, 0)
        info_layout.addWidget(self.label_amostragem, 4, 1)

        painel_layout.addWidget(frame_info)

        # Quadro com a escala de cores.
        self.frame_cores = QFrame(painel)
        self.frame_cores.setFrameShape(QFrame.Shape.Box)
        self.frame_cores.setFrameShadow(QFrame.Shadow.Sunken)
        self.frame_cores.setLineWidth(1)

        cores_layout = QVBoxLayout(self.frame_cores)
        cores_layout.setContentsMargins(8, 8, 8, 8)
        cores_layout.setSpacing(6)

        cores_layout.addWidget(QLabel(self.tr("Escala de Cores:"), self.frame_cores))

        self.legenda_layout = QGridLayout()
        self.legenda_layout.setContentsMargins(0, 0, 0, 0)
        self.legenda_layout.setHorizontalSpacing(12)
        self.legenda_layout.setVerticalSpacing(2)

        cores_layout.addLayout(self.legenda_layout)

        painel_layout.addWidget(self.frame_cores)

        # Linha horizontal abaixo da legenda.
        painel_layout.addWidget(self._criar_hline(painel))

        self.label_rampa_cores = QLabel(self.tr("Selecione a Rampa de Cores:"), painel)

        painel_layout.addWidget(self.label_rampa_cores)

        self.combo_rampa = QComboBox(painel)

        self._configurar_combobox_rampas()

        self.combo_rampa.currentIndexChanged.connect(self._agendar_atualizacao_cores)

        painel_layout.addWidget(self.combo_rampa)

        self.check_inverter = QCheckBox(self.tr("Inverter cores do gradiente"), painel)
        self.check_inverter.toggled.connect(self._agendar_atualizacao_cores)

        painel_layout.addWidget(self.check_inverter)

        # Número de Faixas de Cores.
        layout_faixas = QHBoxLayout()
        layout_faixas.setContentsMargins(0, 0, 0, 0)
        layout_faixas.setSpacing(6)

        self.label_faixas = QLabel(self.tr("Número de Faixas de Cores:"), painel)

        self.spin_faixas = QSpinBox(painel)
        self.spin_faixas.setRange(3, 20)
        self.spin_faixas.setValue(10)
        self.spin_faixas.setMinimumWidth(90)
        self.spin_faixas.valueChanged.connect(self._agendar_atualizacao_cores)

        layout_faixas.addWidget(self.label_faixas, 1)
        layout_faixas.addWidget(self.spin_faixas)

        painel_layout.addLayout(layout_faixas)

        # Qualidade do Terreno.
        layout_qualidade = QHBoxLayout()
        layout_qualidade.setContentsMargins(0, 0, 0, 0)
        layout_qualidade.setSpacing(6)

        label_qualidade = QLabel(self.tr("Qualidade do Terreno:"), painel)
        self.combo_qualidade_terreno = QComboBox(painel)
        self.combo_qualidade_terreno.setMinimumWidth(90)
        self.combo_qualidade_terreno.addItem(self.tr("Rápido"), 180)
        self.combo_qualidade_terreno.addItem(self.tr("Equilibrado"), 350)
        self.combo_qualidade_terreno.addItem(self.tr("Detalhado"), 550)
        self.combo_qualidade_terreno.addItem(self.tr("Pesado"), 750)
        self.combo_qualidade_terreno.addItem(self.tr("Ultra"), 1000)

        indice_equilibrado = (self.combo_qualidade_terreno.findData( self.LIMITE_GRADE))

        if indice_equilibrado >= 0:
            self.combo_qualidade_terreno.setCurrentIndex(indice_equilibrado)

        self.combo_qualidade_terreno.setToolTip(self.tr("Controla a quantidade de amostras utilizadas para construir a superfície 3D. Qualidades maiores produzem mais detalhes, mas aumentam o processamento."))

        # Conectar somente depois de definir o valor inicial.
        self.combo_qualidade_terreno.currentIndexChanged.connect(self._agendar_qualidade_terreno)

        layout_qualidade.addWidget(label_qualidade, 1)

        layout_qualidade.addWidget(self.combo_qualidade_terreno)

