    def _alternar_eixos_xyz(self, state):
        """
        Exibe ou oculta somente o eixo de orientação
        fixo no canto inferior esquerdo.
        """
        visivel = (state == Qt.CheckState.Checked)
        self.view.set_corner_axis_visible(visivel)

    def _alternar_coordenadas(self, ativar):
        """
        Ativa ou desativa a consulta de coordenadas
        por Ctrl + clique.
        """
        if not hasattr(self, "ferramenta_coordenada"):

            return

        if ativar:
            self.ferramenta_coordenada.ativar()

        else:
            self.ferramenta_coordenada.desativar()

    @staticmethod
    def _posicao_solar_3d(instante, latitude, longitude):
        """Azimute do norte verdadeiro e elevação geométrica, em graus."""
        from datetime import timezone

        if instante.tzinfo is None or instante.utcoffset() is None:
            raise ValueError("O instante solar precisa de fuso horário.")

        utc = instante.astimezone(timezone.utc)

        t = (utc.timestamp() / 86400.0 + 2440587.5 - 2451545.0) / 36525.0

        rad = math.radians

        longitude_media = (280.46646 + t * (36000.76983 + 0.0003032 * t)) % 360

        m = rad(357.52911 + t * (35999.05029 - 0.0001537 * t))
        e = 0.016708634 - t * (0.000042037 + 0.0000001267 * t)

        c = (
            (1.914602 - t * (0.004817 + 0.000014 * t))
            * math.sin(m)
            + (0.019993 - 0.000101 * t) * math.sin(2 * m)
            + 0.000289 * math.sin(3 * m))

        omega = rad(125.04 - 1934.136 * t)

        longitude_sol = rad(longitude_media + c - 0.00569 - 0.00478 * math.sin(omega))

        eps = rad(23 + (26 + (21.448 - t * (46.815 + t * (0.00059 - 0.001813 * t))) / 60) / 60 + 0.00256 * math.cos(omega))

        decl = math.asin(math.sin(eps) * math.sin(longitude_sol))

        y = math.tan(eps / 2) ** 2
        lr = rad(longitude_media)

        eq = 4 * math.degrees(
            y * math.sin(2 * lr)
            - 2 * e * math.sin(m)
            + 4 * e * y * math.sin(m) * math.cos(2 * lr)
            - 0.5 * y * y * math.sin(4 * lr)
            - 1.25 * e * e * math.sin(2 * m))

        minutos = (utc.hour * 60 + utc.minute + utc.second / 60)

        h = rad(((minutos + eq + 4 * longitude) % 1440) / 4 - 180)

        lat = rad(latitude)
        leste = -math.cos(decl) * math.sin(h)
        norte = (math.cos(lat) * math.sin(decl) - math.sin(lat) * math.cos(decl) * math.cos(h))

        cima = (math.sin(lat) * math.sin(decl) + math.cos(lat) * math.cos(decl) * math.cos(h))

        azimute = math.degrees(math.atan2(leste, norte)) % 360
        elevacao = math.degrees(math.asin(max(-1.0, min(1.0, cima))))

        return azimute, elevacao

    def _normais_solares_3d(self, config):
        """Normais em base métrica local; cotas reais em metros."""
        base = self._vertices_base
        faces = self._faces

        if base is None or faces is None or not len(faces):
            raise ValueError(self.tr("O terreno ainda não está disponível."))

        lat = config["latitude"]
        lon = config["longitude"]
        wkt = self.raster_layer.crs().toWkt()

        cache = getattr(self, "_cache_normais_solares_3d", None)

        if (cache is not None
            and cache[0] is base
            and cache[1] is faces
            and cache[2:5] == (lat, lon, wkt)):
            return cache[5], cache[6]

        # Base local em metros, orientada ao norte verdadeiro no centro.
        origem = osr.SpatialReference()
        destino = osr.SpatialReference()

        if origem.ImportFromWkt(wkt) != 0:
            raise ValueError(self.tr("Não foi possível interpretar o SRC do MDT."))

        proj_local = (
            f"+proj=aeqd +lat_0={lat:.12f} +lon_0={lon:.12f} "
            "+datum=WGS84 +units=m +no_defs")

        if destino.ImportFromProj4(proj_local) != 0:
            raise ValueError(self.tr("Não foi possível criar a referência solar local."))

        origem.SetAxisMappingStrategy(osr.OAMS_TRADITIONAL_GIS_ORDER)
        destino.SetAxisMappingStrategy(osr.OAMS_TRADITIONAL_GIS_ORDER)

        transformar = osr.CoordinateTransformation(origem, destino)

        xy = np.column_stack((self._x_real, self._y_real))

        pontos = np.asarray(
            transformar.TransformPoints(xy),
            dtype=np.float64
        )[:, :3].copy()

        # Usa o relevo original, sem exagero vertical.
        pontos[:, 2] = base[:, 2]

        if not np.all(np.isfinite(pontos)):
            raise ValueError(self.tr("Falha na transformação das coordenadas do terreno."))

        triangulos = pontos[faces]

        nf = np.cross(
            triangulos[:, 1] - triangulos[:, 0],
            triangulos[:, 2] - triangulos[:, 0])

        # Garante normais voltadas para cima.
        nf[nf[:, 2] < 0] *= -1

        nv = np.zeros_like(pontos)

        # Média ponderada pela área dos triângulos.
        for coluna in range(3):
            np.add.at(nv, faces[:, coluna], nf)

        nf /= np.maximum(np.linalg.norm(nf, axis=1, keepdims=True), 1e-15)
        nv /= np.maximum(np.linalg.norm(nv, axis=1, keepdims=True), 1e-15)

        self._cache_normais_solares_3d = (base, faces, lat, lon, wkt, nf, nv, pontos)

        return nf, nv

    def _ler_profundidade_solar_3d(self, vertices_ndc, faces, tamanho):
        """Calcula a profundidade solar em um contexto OpenGL separado."""
        anterior = QOpenGLContext.currentContext()
        superficie = anterior.surface() if anterior is not None else None

        contexto_cena = self.view.context()

        if contexto_cena is None or not contexto_cena.isValid():
            raise RuntimeError(self.tr("O contexto OpenGL da cena não está disponível."))

        # Contexto exclusivo, sem compartilhar os recursos da cena.
        contexto_sombra = QOpenGLContext()
        contexto_sombra.setScreen(contexto_cena.screen())
        contexto_sombra.setFormat(contexto_cena.format())

        superficie_sombra = QOffscreenSurface(contexto_cena.screen())

        fbo = rbo = vao = vbo = ebo = programa = 0
        shaders = []
        estado = None

        try:
            if not contexto_sombra.create():
                raise RuntimeError(self.tr("Não foi possível criar o contexto das sombras."))

            superficie_sombra.setFormat(contexto_sombra.format())
            superficie_sombra.create()

            if not superficie_sombra.isValid():
                raise RuntimeError(self.tr("Não foi possível criar a superfície das sombras."))

            if not contexto_sombra.makeCurrent(superficie_sombra):
                raise RuntimeError(self.tr("Não foi possível ativar o contexto das sombras."))

            def inteiro(nome):
                return int(np.asarray(GL.glGetIntegerv(nome)).ravel()[0])

            if tamanho > inteiro(GL.GL_MAX_RENDERBUFFER_SIZE):
                raise RuntimeError(self.tr("Resolução de sombra não suportada. Escolha uma qualidade menor."))

            capacidades = (
                GL.GL_DEPTH_TEST, GL.GL_BLEND, GL.GL_CULL_FACE,
                GL.GL_SCISSOR_TEST, GL.GL_STENCIL_TEST,
                GL.GL_POLYGON_OFFSET_FILL, GL.GL_RASTERIZER_DISCARD)

            parametros_pack = (
                GL.GL_PACK_ALIGNMENT, GL.GL_PACK_ROW_LENGTH,
                GL.GL_PACK_SKIP_ROWS, GL.GL_PACK_SKIP_PIXELS,
                GL.GL_PACK_SWAP_BYTES)

            estado = {
                "draw": inteiro(GL.GL_DRAW_FRAMEBUFFER_BINDING),
                "read": inteiro(GL.GL_READ_FRAMEBUFFER_BINDING),
                "rbo": inteiro(GL.GL_RENDERBUFFER_BINDING),
                "vao": inteiro(GL.GL_VERTEX_ARRAY_BINDING),
                "vbo": inteiro(GL.GL_ARRAY_BUFFER_BINDING),
                "pack_buffer": inteiro(GL.GL_PIXEL_PACK_BUFFER_BINDING),
                "programa": inteiro(GL.GL_CURRENT_PROGRAM),
                "viewport": GL.glGetIntegerv(GL.GL_VIEWPORT),
                "funcao": inteiro(GL.GL_DEPTH_FUNC),
                "mascara": bool(GL.glGetBooleanv(GL.GL_DEPTH_WRITEMASK)),
                "limpeza": float(GL.glGetDoublev(GL.GL_DEPTH_CLEAR_VALUE)),
                "faixa": GL.glGetDoublev(GL.GL_DEPTH_RANGE),
                "poligono": GL.glGetIntegerv(GL.GL_POLYGON_MODE),
                "offset": (
                    float(GL.glGetFloatv(GL.GL_POLYGON_OFFSET_FACTOR)),
                    float(GL.glGetFloatv(GL.GL_POLYGON_OFFSET_UNITS))),
                "capacidades": {
                    c: bool(GL.glIsEnabled(c)) for c in capacidades},
                "pack": {p: inteiro(p) for p in parametros_pack}}

            fbo = int(GL.glGenFramebuffers(1))
            rbo = int(GL.glGenRenderbuffers(1))
            GL.glBindFramebuffer(GL.GL_FRAMEBUFFER, fbo)
            GL.glBindRenderbuffer(GL.GL_RENDERBUFFER, rbo)
            GL.glRenderbufferStorage(
                GL.GL_RENDERBUFFER, GL.GL_DEPTH_COMPONENT24,
                tamanho, tamanho)
            GL.glFramebufferRenderbuffer(
                GL.GL_FRAMEBUFFER, GL.GL_DEPTH_ATTACHMENT,
                GL.GL_RENDERBUFFER, rbo)
            GL.glDrawBuffer(GL.GL_NONE)
            GL.glReadBuffer(GL.GL_NONE)

            if (GL.glCheckFramebufferStatus(GL.GL_FRAMEBUFFER)
                != GL.GL_FRAMEBUFFER_COMPLETE):
                raise RuntimeError(self.tr("Não foi possível criar o mapa de sombras."))

            shaders.append(gl_shaders.compileShader("""
                #version 140
                in vec3 a_posicao;
                void main()
                {
                    gl_Position = vec4(a_posicao, 1.0);
                }
            """, GL.GL_VERTEX_SHADER))

            shaders.append(gl_shaders.compileShader("""
                #version 140
                void main()
                {
                }
            """, GL.GL_FRAGMENT_SHADER))

            programa = int(GL.glCreateProgram())
            for shader in shaders:
                GL.glAttachShader(programa, shader)
            GL.glBindAttribLocation(programa, 0, "a_posicao")
            GL.glLinkProgram(programa)

            if not GL.glGetProgramiv(programa, GL.GL_LINK_STATUS):
                raise RuntimeError(str(GL.glGetProgramInfoLog(programa)))

            vao = int(GL.glGenVertexArrays(1))
            vbo, ebo = [int(v) for v in GL.glGenBuffers(2)]
            GL.glBindVertexArray(vao)
            vertices = np.ascontiguousarray(vertices_ndc, dtype=np.float32)
            indices = np.ascontiguousarray(faces, dtype=np.uint32)

            GL.glBindBuffer(GL.GL_ARRAY_BUFFER, vbo)
            GL.glBufferData(
                GL.GL_ARRAY_BUFFER, vertices.nbytes,
                vertices, GL.GL_STATIC_DRAW)
            GL.glEnableVertexAttribArray(0)
            GL.glVertexAttribPointer(
                0, 3, GL.GL_FLOAT, False, 0, ctypes.c_void_p(0))
            GL.glBindBuffer(GL.GL_ELEMENT_ARRAY_BUFFER, ebo)
            GL.glBufferData(GL.GL_ELEMENT_ARRAY_BUFFER, indices.nbytes,
                indices, GL.GL_STATIC_DRAW)

            for capacidade in capacidades:
                GL.glDisable(capacidade)
            GL.glEnable(GL.GL_DEPTH_TEST)
            GL.glEnable(GL.GL_POLYGON_OFFSET_FILL)
            GL.glPolygonOffset(1.1, 4.0)
            GL.glDepthFunc(GL.GL_LESS)
            GL.glDepthMask(True)
            GL.glDepthRange(0.0, 1.0)
            GL.glClearDepth(1.0)
            GL.glPolygonMode(GL.GL_FRONT_AND_BACK, GL.GL_FILL)
            GL.glViewport(0, 0, tamanho, tamanho)
            GL.glClear(GL.GL_DEPTH_BUFFER_BIT)
            GL.glUseProgram(programa)
            GL.glDrawElements(
                GL.GL_TRIANGLES, int(indices.size),
                GL.GL_UNSIGNED_INT, None)

            GL.glBindBuffer(GL.GL_PIXEL_PACK_BUFFER, 0)
            for parametro in parametros_pack:
                GL.glPixelStorei(parametro,
                    1 if parametro == GL.GL_PACK_ALIGNMENT else 0)

            dados = GL.glReadPixels(
                0, 0, tamanho, tamanho,
                GL.GL_DEPTH_COMPONENT, GL.GL_FLOAT)
            return np.frombuffer(
                dados, dtype=np.float32).reshape(tamanho, tamanho).copy()

        finally:
            try:
                if estado is not None:
                    GL.glBindFramebuffer(
                        GL.GL_DRAW_FRAMEBUFFER, estado["draw"])
                    GL.glBindFramebuffer(
                        GL.GL_READ_FRAMEBUFFER, estado["read"])
                    GL.glBindRenderbuffer(
                        GL.GL_RENDERBUFFER, estado["rbo"])
                    GL.glBindVertexArray(estado["vao"])
                    GL.glBindBuffer(GL.GL_ARRAY_BUFFER, estado["vbo"])
                    GL.glBindBuffer(
                        GL.GL_PIXEL_PACK_BUFFER, estado["pack_buffer"])
                    GL.glUseProgram(estado["programa"])
                    GL.glViewport(*[int(v) for v in estado["viewport"]])
                    GL.glDepthFunc(estado["funcao"])
                    GL.glDepthMask(estado["mascara"])
                    GL.glDepthRange(*estado["faixa"])
                    GL.glClearDepth(estado["limpeza"])
                    GL.glPolygonOffset(*estado["offset"])

                    modos = estado["poligono"]
                    if modos[0] == modos[1]:
                        GL.glPolygonMode(
                            GL.GL_FRONT_AND_BACK, int(modos[0]))
                    else:
                        GL.glPolygonMode(GL.GL_FRONT, int(modos[0]))
                        GL.glPolygonMode(GL.GL_BACK, int(modos[1]))

                    for capacidade, habilitada in estado["capacidades"].items():
                        (GL.glEnable if habilitada else GL.glDisable)(
                            capacidade)
                    for parametro, valor in estado["pack"].items():
                        GL.glPixelStorei(parametro, valor)
            finally:
                try:
                    if programa:
                        GL.glDeleteProgram(programa)
                    for shader in shaders:
                        GL.glDeleteShader(shader)
                    if vbo:
                        GL.glDeleteBuffers(1, [vbo])
                    if ebo:
                        GL.glDeleteBuffers(1, [ebo])
                    if vao:
                        GL.glDeleteVertexArrays(1, [vao])
                    if rbo:
                        GL.glDeleteRenderbuffers(1, [rbo])
                    if fbo:
                        GL.glDeleteFramebuffers(1, [fbo])
                finally:
                    try:
                        if QOpenGLContext.currentContext() == contexto_sombra:
                            contexto_sombra.doneCurrent()
                    finally:
                        try:
                            if anterior is not None and superficie is not None:
                                if not anterior.makeCurrent(superficie):
                                    raise RuntimeError(self.tr("Não foi possível restaurar o contexto OpenGL anterior."))
                        finally:
                            superficie_sombra.destroy()

    def _visibilidade_solar_3d(self, sol, por_face, config):
        """Fração iluminada por amostra da malha, com cache por posição solar."""
        self._normais_solares_3d(config)
        geometria = self._cache_normais_solares_3d
        tamanho = int(config.get("resolucao_sombra", 2048))
        if tamanho not in (1024, 2048, 4096):
            tamanho = 2048

        chave = (tuple(float(v) for v in sol), tamanho, bool(por_face))
        cache = getattr(self, "_cache_sombras_solares_3d", None)
        if cache is not None and cache[0] is geometria and cache[1] == chave:
            return cache[2]

        pontos, faces = geometria[7], geometria[1]
        lateral = np.cross(sol, np.array([0.0, 0.0, 1.0]))
        if np.linalg.norm(lateral) < 1e-8:
            lateral = np.array([1.0, 0.0, 0.0])
        lateral /= np.linalg.norm(lateral)
        acima = np.cross(lateral, sol)
        base_luz = np.column_stack((lateral, acima, -sol))
        projetados = pontos @ base_luz
        minimo = projetados.min(axis=0)
        maximo = projetados.max(axis=0)
        margem = np.maximum((maximo - minimo) * 0.01, 0.01)
        minimo -= margem
        extensao = maximo + margem - minimo
        normalizados = (projetados - minimo) / extensao
        profundidade = self._ler_profundidade_solar_3d(
            normalizados * 2.0 - 1.0, faces, tamanho)

        if por_face:
            amostras = normalizados[faces].mean(axis=1)
            normais = geometria[5]
        else:
            amostras = normalizados
            normais = geometria[6]

        coseno = np.clip(normais @ sol, 0.0, 1.0)
        inclinacao = (
            np.sqrt(np.maximum(0.0, 1.0 - coseno ** 2))
            / np.maximum(coseno, 0.10))
        pixel_m = max(extensao[0], extensao[1]) / tamanho
        tolerancia = (2e-6 + (1.5 * pixel_m / extensao[2]) * (1.0 + inclinacao))
        coluna = np.floor(amostras[:, 0] * tamanho).astype(np.int32)
        linha = np.floor(amostras[:, 1] * tamanho).astype(np.int32)
        visibilidade = np.zeros(len(amostras), dtype=np.float32)

        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                x = np.clip(coluna + dx, 0, tamanho - 1)
                y = np.clip(linha + dy, 0, tamanho - 1)
                visibilidade += (
                    amostras[:, 2] <= profundidade[y, x] + tolerancia)

        visibilidade /= 9.0
        self._cache_sombras_solares_3d = (geometria, chave, visibilidade)
        return visibilidade

    def _iluminar_malha_solar_3d(self, mesh_data):
        config = self._config_sombreamento_3d

        azimute, elevacao = self._posicao_solar_3d(
            datetime.fromisoformat(config["instante_utc"]),
            config["latitude"],
            config["longitude"])

        az = math.radians(azimute)
        el = math.radians(elevacao)

        sol = np.array([
            math.cos(el) * math.sin(az),
            math.cos(el) * math.cos(az),
            math.sin(el)])

        nf, nv = self._normais_solares_3d(config)

        por_face = mesh_data.hasFaceColor()
        normais = nf if por_face else nv

        # Copia as cores para preservar a rampa original.
        cores = np.array(
            mesh_data.faceColors()
            if por_face
            else mesh_data.vertexColors(),
            dtype=np.float32,
            copy=True)

        if elevacao > 0:
            incidencia = np.maximum(normais @ sol, 0.0)
        else:
            incidencia = np.zeros(len(normais))

        if elevacao > 0 and config.get("sombras_relevo", False):
            incidencia *= self._visibilidade_solar_3d(sol, por_face, config)

        ambiente = float(config["luz_ambiente"])

        fator = (ambiente
            + (1.0 - ambiente)
            * float(config["intensidade_solar"])
            * incidencia)

        # Preserva os fatores de iluminação da malha atual.
        # Eles não dependem da rampa de cores.
        self.mesh_item._tempo_salvo_fatores_luz_solar = (np.ascontiguousarray(fator, dtype=np.float32))

        self.mesh_item._tempo_salvo_config_solar = (tuple(sorted(config.items())))

        self.mesh_item._tempo_salvo_luz_por_face = bool(por_face)

        cores[:, :3] = np.clip(cores[:, :3] * fator[:, None], 0.0, 1.0)

        if por_face:
            mesh_data.setFaceColors(cores)
        else:
            mesh_data.setVertexColors(cores)

        self.mesh_item.setMeshData(meshdata=mesh_data)

        # Evita somar a iluminação padrão à iluminação solar calculada.
        self.mesh_item.setShader(None)
        # A textura utiliza os mesmos fatores calculados para o terreno.
        if not por_face:
            self._fatores_luz_vertices_3d = np.asarray(fator, dtype=np.float32).copy()
        else:
            self._fatores_luz_vertices_3d = None

    def _alternar_sombreamento(self, ativar):
        dlg = getattr(self, "_dialogo_sombreamento_3d", None)

        if not ativar:
            if dlg is not None:
                dlg.reject()
            return

        if dlg is not None:
            dlg.show()
            dlg.raise_()
            dlg.activateWindow()
            return

        self._abrir_dialogo_sombreamento()

    def _abrir_dialogo_sombreamento(self):
        config = dict(getattr(self, "_config_sombreamento_3d", {}))

        dlg = QDialog(self)
        dlg.setWindowTitle(self.tr("Sombreamento do MDT"))
        dlg.setModal(False)
        dlg.setMinimumWidth(350)

        layout = QVBoxLayout(dlg)

        aviso = QLabel(self.tr("Iluminação e sombras sobre as cores ou a ortofoto do MDT principal. O cálculo usa o relevo real, com cotas em metros."), dlg)

        aviso.setWordWrap(True)
        layout.addWidget(aviso)

        form = QFormLayout()
        layout.addLayout(form)

        ativar_sol = QCheckBox(self.tr("Ativar iluminação solar"), dlg)
        ativar_sol.setChecked(config.get("iluminacao_ativa", False))

        form.addRow(ativar_sol)

        # Localização automática pelo centro da extensão do MDT.
        localizacao = None
        label_local = QLabel(dlg)
        label_local.setWordWrap(True)

        try:
            crs = self.raster_layer.crs()

            if not crs.isValid():
                raise ValueError(self.tr("O MDT não possui SRC válido."))

            centro = self.raster_layer.extent().center()

            transformacao = QgsCoordinateTransform(crs,
                QgsCoordinateReferenceSystem("EPSG:4326"),
                QgsProject.instance())

            ponto = transformacao.transform(centro)
            lon, lat = float(ponto.x()), float(ponto.y())

            if not (math.isfinite(lat)
                and math.isfinite(lon)
                and -90 <= lat <= 90
                and -180 <= lon <= 180):
                raise ValueError(self.tr("Coordenadas geográficas inválidas."))

            localizacao = {
                "latitude": lat,
                "longitude": lon,
                "crs_mdt": crs.authid(),
                "referencia": "centro_extensao_mdt"}

            label_local.setText(self.tr("Latitude: {lat}\nLongitude: {lon}\nReferência: centro da extensão do MDT.").format(lat=f"{lat:.7f}°", lon=f"{lon:.7f}°"))

        except Exception as erro:
            label_local.setText(self.tr("Localização indisponível: {erro}").format(erro=str(erro)))

        form.addRow(self.tr("Localização:"), label_local)

        # Data com avanço contínuo entre dias, meses e anos.
        class DateEditCiclico(QDateEdit):
            def stepBy(self, passos):
                secao = self.currentSection()
                atual = self.date()

                if secao == QDateEdit.Section.DaySection:
                    nova = atual.addDays(passos)

                elif secao == QDateEdit.Section.MonthSection:
                    nova = atual.addMonths(passos)

                elif secao == QDateEdit.Section.YearSection:
                    nova = atual.addYears(passos)

                else:
                    super().stepBy(passos)
                    return

                if nova < self.minimumDate():
                    nova = self.minimumDate()

                elif nova > self.maximumDate():
                    nova = self.maximumDate()

                self.setDate(nova)

        data = DateEditCiclico(dlg)
        data.setCalendarPopup(True)

        # O formato também entra no sistema de tradução.
        data.setDisplayFormat(self.tr("dd/MM/yyyy"))

        data.setDateRange(QDate(1900, 1, 1), QDate(2100, 12, 31))

        valor_data = QDate.fromString(config.get("data", ""), "yyyy-MM-dd")

        data.setDate(valor_data if valor_data.isValid()
            else QDate.currentDate())

        form.addRow(self.tr("Data:"), data)

        # Horário com avanço contínuo:
        # 16:59 -> 17:00
        # 23:59 -> 00:00 + próximo dia
        # 00:00 -> 23:59 + dia anterior
        class TimeEditCiclico(QTimeEdit):
            def __init__(self, date_edit, parent=None):
                super().__init__(parent)
                self._date_edit = date_edit

            def stepBy(self, passos):
                secao = self.currentSection()
                atual = self.time()

                minutos_atuais = (atual.hour() * 60 + atual.minute())

                if secao == QTimeEdit.Section.MinuteSection:
                    deslocamento = passos

                elif secao == QTimeEdit.Section.HourSection:
                    deslocamento = passos * 60

                else:
                    super().stepBy(passos)
                    return

                total = minutos_atuais + deslocamento

                # divmod também resolve corretamente valores negativos.
                dias, minutos_dia = divmod(total, 24 * 60)

                hora = minutos_dia // 60
                minuto = minutos_dia % 60

                self.setTime(QTime(hora, minuto))

                if dias:
                    nova_data = self._date_edit.date().addDays(dias)

                    if nova_data < self._date_edit.minimumDate():
                        nova_data = self._date_edit.minimumDate()

                    elif nova_data > self._date_edit.maximumDate():
                        nova_data = self._date_edit.maximumDate()

                    self._date_edit.setDate(nova_data)

        horario = TimeEditCiclico(data, dlg)
        horario.setDisplayFormat("HH:mm")

        valor_hora = QTime.fromString(config.get("horario", "12:00"), "HH:mm")

        horario.setTime(valor_hora if valor_hora.isValid()
            else QTime(12, 0))

        form.addRow(self.tr("Horário local:"), horario)

        # Deslocamento UTC explícito: não depende do fuso do computador.
        fuso = QComboBox(dlg)

        for minutos in range(-12 * 60, 14 * 60 + 1, 15):
            sinal = "+" if minutos >= 0 else "−"
            horas, resto = divmod(abs(minutos), 60)

            fuso.addItem(f"UTC{sinal}{horas:02d}:{resto:02d}", minutos)

        fuso.setCurrentIndex(fuso.findData(config.get("utc_offset_minutos", -180)))

        fuso.setToolTip(self.tr("Selecione o deslocamento UTC válido no local e na data escolhida, incluindo horário de verão quando aplicável. Não é detectado pelo SRC."))

        form.addRow(self.tr("Fuso horário:"), fuso)

        label_fuso = QLabel(self.tr("UTC−03:00 é apenas o valor inicial; confirme o fuso do local para a data escolhida."), dlg)
        label_fuso.setWordWrap(True)
        layout.addWidget(label_fuso)

        frame_info_solar = QFrame(dlg)
        frame_info_solar.setFrameShape(QFrame.Shape.StyledPanel)
        frame_info_solar.setFrameShadow(QFrame.Shadow.Plain)

        layout_info_solar = QGridLayout(frame_info_solar)
        layout_info_solar.setContentsMargins(6, 6, 6, 6)
        layout_info_solar.setHorizontalSpacing(8)
        layout_info_solar.setVerticalSpacing(4)

        label_utc_titulo = QLabel(self.tr("Instante UTC:"), frame_info_solar)

        label_sol_titulo = QLabel(self.tr("Posição do Sol:"), frame_info_solar)

        label_utc = QLabel(frame_info_solar)
        label_sol = QLabel(frame_info_solar)
        label_sol.setWordWrap(True)
        label_sol.setMinimumHeight(34)

        layout_info_solar.addWidget(label_utc_titulo, 0, 0)
        layout_info_solar.addWidget(label_utc, 0, 1)

        layout_info_solar.addWidget(label_sol_titulo, 1, 0, Qt.AlignmentFlag.AlignTop)

        layout_info_solar.addWidget(label_sol, 1, 1)

        form.addRow(frame_info_solar)

        def instante_utc():
            dia = data.date()
            hora = horario.time()

            tz = timezone(timedelta(minutes=int(fuso.currentData())))

            return datetime(
                dia.year(),
                dia.month(),
                dia.day(),
                hora.hour(),
                hora.minute(),
                tzinfo=tz).astimezone(timezone.utc)

        def atualizar_utc(*_):
            instante = instante_utc()

            label_utc.setText(instante.strftime("%d/%m/%Y %H:%M UTC"))

            if localizacao is None:
                label_sol.setText(self.tr("Localização indisponível."))
                return

            az, el = self._posicao_solar_3d(instante, localizacao["latitude"], localizacao["longitude"])

            texto = self.tr("Azimute: {az}° | Elevação: {el}°").format(az=f"{az:.2f}", el=f"{el:.2f}")

            if el <= 0:
                texto += self.tr(" — sem luz solar direta")

            label_sol.setText(texto)

        data.dateChanged.connect(atualizar_utc)
        horario.timeChanged.connect(atualizar_utc)
        fuso.currentIndexChanged.connect(atualizar_utc)

        atualizar_utc()

        # Parâmetros preparados para a etapa de renderização.
        luz = QDoubleSpinBox(dlg)
        luz.setRange(0.0, 3.0)
        luz.setDecimals(2)
        luz.setSingleStep(0.10)
        luz.setValue(config.get("intensidade_solar", 1.0))
        luz.setToolTip(self.tr("Intensidade visual relativa, sem unidade de irradiância."))

        form.addRow(self.tr("Intensidade solar:"), luz)

        ambiente = QDoubleSpinBox(dlg)
        ambiente.setRange(0.0, 1.0)
        ambiente.setDecimals(2)
        ambiente.setSingleStep(0.05)
        ambiente.setValue(config.get("luz_ambiente", 0.25))

        form.addRow(self.tr("Luz ambiente:"), ambiente)

        sombras = QCheckBox(self.tr("Projetar sombras do relevo"), dlg)
        sombras.setChecked(config.get("sombras_relevo", True))

        form.addRow(sombras)

        qualidade = QComboBox(dlg)

        for texto, valor in (
            (self.tr("Rápida"), 1024),
            (self.tr("Equilibrada"), 2048),
            (self.tr("Detalhada"), 4096)):
            qualidade.addItem(texto, valor)

        qualidade.setCurrentIndex(qualidade.findData(config.get("resolucao_sombra", 2048)))
        qualidade.setEnabled(sombras.isChecked())
        sombras.toggled.connect(qualidade.setEnabled)

        form.addRow(self.tr("Qualidade das sombras:"), qualidade)

        sombras.setEnabled(True)
        qualidade.setEnabled(sombras.isChecked())

        sombras.setToolTip(self.tr("Permite que uma parte do relevo projete sombra sobre outra."))

        estado = QLabel(dlg)
        estado.setWordWrap(True)
        layout.addWidget(estado)

        linha_botoes = QHBoxLayout()
        linha_botoes.setSpacing(8)

        resetar = QPushButton(self.tr("Resetar"), dlg)
        ok = QPushButton(self.tr("OK"), dlg)

        resetar.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)

        ok.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)

        resetar.setAutoDefault(False)
        ok.setDefault(True)

        resetar.setEnabled(localizacao is not None)
        ok.setEnabled(localizacao is not None)

        linha_botoes.addWidget(resetar, 1)
        linha_botoes.addWidget(ok, 1)

        layout.addLayout(linha_botoes)

        def guardar():
            if localizacao is None:
                return False

            anterior = dict(getattr(self, "_config_sombreamento_3d", {}))

            nova = {
                **localizacao,
                "iluminacao_ativa": ativar_sol.isChecked(),
                "data": data.date().toString("yyyy-MM-dd"),
                "horario": horario.time().toString("HH:mm"),
                "utc_offset_minutos": int(fuso.currentData()),
                "instante_utc": instante_utc().isoformat(),
                "intensidade_solar": luz.value(),
                "luz_ambiente": ambiente.value(),
                "sombras_relevo": sombras.isChecked(),
                "resolucao_sombra": int(qualidade.currentData())}

            try:
                if nova["iluminacao_ativa"]:
                    if self._obter_camadas_diferenca_mdt_ativas():
                        raise ValueError(self.tr("Desative a comparação com MDTs secundários para aplicar o sombreamento ao MDT principal."))

                    # Valida e prepara as normais antes de reconstruir a cena.
                    self._normais_solares_3d(nova)

                self._config_sombreamento_3d = nova
                self._atualizar_geometria()

                if getattr(self, "_erro_iluminacao_solar_3d", None):
                    raise ValueError(self._erro_iluminacao_solar_3d)

            except Exception as erro:
                self._config_sombreamento_3d = anterior
                self._atualizar_geometria()

                estado.setText(self.tr("Erro: {erro}").format(erro=str(erro)))

                return False

            if nova["iluminacao_ativa"]:
                if nova["sombras_relevo"]:
                    estado.setText(self.tr("Iluminação e sombras do relevo aplicadas ao MDT."))
                else:
                    estado.setText(self.tr("Iluminação solar aplicada ao MDT, sem sombras projetadas."))
            else:
                estado.setText(self.tr("Iluminação solar desativada; aparência original restaurada."))

            return True

        # Configuração confirmada: Cancelar desfaz apenas as prévias seguintes.
        confirmado = dict(config)
        encerrado = False

        timer_previa = QTimer(dlg)
        timer_previa.setSingleShot(True)
        timer_previa.setInterval(50)

        def agendar_previa(*_):
            if encerrado or localizacao is None:
                return

            # Reiniciar agrupa alterações rápidas dos controles.
            timer_previa.start()

        def executar_previa():
            if not encerrado:
                guardar()

        def confirmar(*_):
            nonlocal confirmado

            timer_previa.stop()

            if not guardar():
                return False

            confirmado = dict(self._config_sombreamento_3d)
            return True

        def aceitar():
            if confirmar():
                dlg.accept()

        def finalizar(resultado):
            nonlocal encerrado

            encerrado = True
            timer_previa.stop()

            try:
                if resultado != QDialog.DialogCode.Accepted:
                    atual = dict(getattr(self, "_config_sombreamento_3d", {}))

                    if atual != confirmado:
                        self._config_sombreamento_3d = dict(confirmado)
                        self._atualizar_geometria()

            except Exception as erro:
                QgsMessageLog.logMessage(self.tr("Erro ao restaurar o sombreamento: {erro}").format(erro=str(erro)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)

            finally:
                self._dialogo_sombreamento_3d = None

                bloqueado = self.check_sombreamento.blockSignals(True)
                self.check_sombreamento.setChecked(False)
                self.check_sombreamento.blockSignals(bloqueado)

                dlg.deleteLater()

        def restaurar_padrao():
            timer_previa.stop()

            controles = (ativar_sol, data, horario, fuso, luz, ambiente, sombras, qualidade)

            bloqueios = [controle.blockSignals(True)
                for controle in controles]

            try:
                ativar_sol.setChecked(False)
                data.setDate(QDate.currentDate())
                horario.setTime(QTime(12, 0))
                fuso.setCurrentIndex(fuso.findData(-180))
                luz.setValue(1.0)
                ambiente.setValue(0.25)
                sombras.setChecked(True)
                qualidade.setCurrentIndex(qualidade.findData(2048))

            finally:
                for controle, bloqueado in zip(controles, bloqueios):
                    controle.blockSignals(bloqueado)

            qualidade.setEnabled(sombras.isChecked())
            atualizar_utc()

            # Aplica todos os padrões em uma única atualização.
            executar_previa()

        timer_previa.timeout.connect(executar_previa)

        # Prévia automática de todos os parâmetros editáveis.
        ativar_sol.toggled.connect(agendar_previa)
        data.dateChanged.connect(agendar_previa)
        horario.timeChanged.connect(agendar_previa)
        fuso.currentIndexChanged.connect(agendar_previa)
        luz.valueChanged.connect(agendar_previa)
        ambiente.valueChanged.connect(agendar_previa)
        sombras.toggled.connect(agendar_previa)
        qualidade.currentIndexChanged.connect(agendar_previa)

        resetar.clicked.connect(restaurar_padrao)
        ok.clicked.connect(aceitar)
        dlg.finished.connect(finalizar)

        def posicionar_dialogo():
            if encerrado or not dlg.isVisible():
                return

            margem = 12
            area = self.view.rect()
            origem = self.view.mapToGlobal(area.topLeft())
            tamanho = dlg.frameGeometry().size()

            x = origem.x() + area.width() - tamanho.width() - margem
            y = origem.y() + margem

            # Mantém o diálogo dentro da área útil do monitor.
            tela = self.view.screen()

            if tela is not None:
                disponivel = tela.availableGeometry()

                limite_x = (disponivel.x() + disponivel.width() - tamanho.width())
                limite_y = (disponivel.y() + disponivel.height() - tamanho.height())

                x = max(disponivel.x(), min(x, limite_x))
                y = max(disponivel.y(), min(y, limite_y))

            dlg.move(x, y)

        self._dialogo_sombreamento_3d = dlg

        dlg.adjustSize()
        dlg.show()

        # Aguarda a criação da janela para considerar suas bordas.
        QTimer.singleShot(0, posicionar_dialogo)

    def _alternar_medicoes(self, ativar):
        """
        Abre ou fecha o diálogo não modal de medições 3D.
        """
        if ativar:
            self._abrir_dialogo_medicoes()

        else:
            if self._dialogo_medicoes_3d is not None:
                try:
                    self._dialogo_medicoes_3d.close()
                except Exception:
                    pass  # nosec B110

    def _abrir_dialogo_medicoes(self):
        """
        Abre o diálogo não modal destinado às medições
        de distância, inclinação e área do MDT.
        """
        if self._dialogo_medicoes_3d is not None:
            try:
                self._dialogo_medicoes_3d.show()
                self._dialogo_medicoes_3d.raise_()
                self._dialogo_medicoes_3d.activateWindow()
                return

            except Exception:
                self._dialogo_medicoes_3d = None

        dlg = QDialog(self)
        dlg.setWindowTitle(self.tr("Medições no MDT"))
        dlg.setWindowModality(Qt.WindowModality.NonModal)
        dlg.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)

        dlg.resize(310, 500)

        layout_principal = QVBoxLayout(dlg)
        layout_principal.setContentsMargins(10, 10, 10, 10)
        layout_principal.setSpacing(10)

        # ORIENTAÇÃO
        label_orientacao = QLabel(self.tr("Selecione abaixo o tipo de medição que deseja executar sobre a superfície do MDT."), dlg)

        label_orientacao.setWordWrap(True)

        layout_principal.addWidget(label_orientacao)

        # DISTÂNCIA
        frame_distancia = QFrame(dlg)
        frame_distancia.setFrameShape(QFrame.Shape.Box)
        frame_distancia.setFrameShadow(QFrame.Shadow.Sunken)

        layout_distancia = QVBoxLayout(frame_distancia)
        layout_distancia.setContentsMargins(10, 10, 10, 10)

        layout_distancia.setSpacing(7)

        titulo_distancia = QLabel(self.tr("Medição de Distância"), frame_distancia)

        fonte = titulo_distancia.font()
        fonte.setBold(True)

        titulo_distancia.setFont(fonte)
        layout_distancia.addWidget(titulo_distancia)

        layout_acoes_distancia = QHBoxLayout()
        layout_acoes_distancia.setContentsMargins(0, 0, 0, 0)
        layout_acoes_distancia.setSpacing(10)

        self.pushButton_medir_distancia_3d = QPushButton(self.tr("Medir Distância (L)"), frame_distancia)
        self.pushButton_medir_distancia_3d.setShortcut("L")

        self.check_perfil_topografico_3d = QCheckBox(self.tr("Perfil Topográfico"), frame_distancia)

        self.check_perfil_topografico_3d.setChecked(False)
        self.check_perfil_topografico_3d.setEnabled(False)
        self.check_perfil_topografico_3d.toggled.connect(self._alternar_perfil_topografico_3d)


        layout_acoes_distancia.addWidget(self.pushButton_medir_distancia_3d, 1)
