    def _criar_medidor_metrico(self):
        """
        Cria o QgsDistanceArea utilizado pelas medições.

        O cálculo horizontal é convertido para metros inclusive
        quando o MDT utiliza coordenadas geográficas.
        """
        medidor = QgsDistanceArea()
        crs = self.raster_layer.crs()

        if crs.isValid():
            medidor.setSourceCrs(crs, QgsProject.instance().transformContext())

        ellipsoid = ""

        try:
            ellipsoid = crs.ellipsoidAcronym()
        except Exception:
            pass  # nosec B110

        if not ellipsoid or str(ellipsoid).upper() == "NONE":
            try:
                ellipsoid = QgsProject.instance().ellipsoid()
            except Exception:
                ellipsoid = ""

        if not ellipsoid or str(ellipsoid).upper() == "NONE":
            ellipsoid = "WGS84"

        try:
            medidor.setEllipsoid(ellipsoid)
        except Exception:
            pass  # nosec B110

        return medidor

    def _distancia_horizontal_metros(self, medidor, p1, p2):
        """
        Distância horizontal entre dois pontos em metros.
        """
        ponto1 = QgsPointXY(float(p1[0]), float(p1[1]))
        ponto2 = QgsPointXY(float(p2[0]), float(p2[1]))

        distancia = float(medidor.measureLine(ponto1, ponto2))

        try:
            distancia = float(medidor.convertLengthMeasurement(distancia, Qgis.DistanceUnit.Meters))
        except Exception:
            pass  # nosec B110

        return distancia

    def _amostrar_linha_medicao_mdt(self, p1, p2):
        """
        Gera pontos entre P1 e P2 acompanhando a superfície
        realmente exibida no visualizador.

        Retorna:
            pontos_reais -> X, Y, Z real
            pontos_cena  -> X, Y, Z usados pelo OpenGL
        """
        x1, y1 = float(p1[0]), float(p1[1])
        x2, y2 = float(p2[0]), float(p2[1])

        extensao = self.raster_layer.extent()

        passo_x = abs(extensao.width() / max(self._grade_x - 1, 1))
        passo_y = abs(extensao.height() / max(self._grade_y - 1, 1))

        passos = [valor for valor in (passo_x, passo_y) if valor > 0.0]
        passo = min(passos) * 0.50 if passos else 1.0

        distancia_xy = math.hypot(x2 - x1, y2 - y1)
        quantidade = max(1, min(5000, int(math.ceil(distancia_xy / max(passo, 1e-12)))))

        vertices_visuais = self._vertices_com_exagero()
        z_grade = vertices_visuais[:, 2].reshape(self._grade_y, self._grade_x)

        exagero = max(1e-12, float(self.spin_exagero.value()))

        pontos_reais = []
        pontos_cena = []

        for indice in range(quantidade + 1):
            fator = indice / quantidade

            x = x1 + (x2 - x1) * fator
            y = y1 + (y2 - y1) * fator

            z_cena = self._amostrar_z_visual_malha_3d(x, y, z_grade)

            if z_cena is None:
                return None, None

            z_real = float(z_cena) / exagero + self._z_centro

            pontos_reais.append((x, y, z_real))
            pontos_cena.append((x - self._x_centro, y - self._y_centro, float(z_cena)))

        return pontos_reais, pontos_cena

    def _atalho_medir_distancia_3d(self):
        """
        Inicia a medição de distância pelo atalho L,
        quando o diálogo de medições estiver aberto.
        """
        botao = getattr(self, "pushButton_medir_distancia_3d", None)

        if botao is None:
            return

        try:
            if botao.isEnabled():
                self._iniciar_medicao_distancia_3d()

        except RuntimeError:
            self.pushButton_medir_distancia_3d = None

    def _atalho_medir_area_3d(self):
        """
        Inicia a medição de área/perímetro pelo atalho P,
        quando o diálogo de medições estiver aberto.
        """
        botao = getattr(self, "pushButton_medir_area_3d", None)

        if botao is None:
            return

        try:
            if botao.isEnabled():
                self._iniciar_medicao_area_3d()

        except RuntimeError:
            self.pushButton_medir_area_3d = None

    def _iniciar_medicao_distancia_3d(self):
        """
        Inicia uma nova medição de distância com dois cliques,
        preservando a opção de perfil topográfico.
        """
        check_perfil = getattr(self, "check_perfil_topografico_3d", None)

        # Guarda a preferência atual antes de limpar
        # a medição anterior.
        perfil_marcado = bool(check_perfil is not None
            and check_perfil.isChecked())

        self._limpar_medicao_distancia_3d()

        # Ao iniciar uma nova medição, mantém a preferência
        # visualmente marcada, mas bloqueada até P1 + P2.
        if check_perfil is not None:
            check_perfil.blockSignals(True)
            check_perfil.setChecked(perfil_marcado)
            check_perfil.setEnabled(False)
            check_perfil.blockSignals(False)

        self._modo_medicao_3d = "distancia"
        self._pontos_medicao_distancia = []

        self.view._captura_medicao_ativa = True

        try:
            self.view.setCursor(Qt.CursorShape.PointingHandCursor)
            self.view.setFocus()

        except Exception:
            pass  # nosec B110

        self.pushButton_medir_distancia_3d.setText(self.tr("Clique em dois pontos no MDT..."))

    def _finalizar_medicao_distancia_3d(self, recalculo_edicao=False):
        """
        Calcula os resultados entre os dois pontos selecionados
        e prepara os dados do perfil topográfico.
        """
        if len(self._pontos_medicao_distancia) < 2:
            return

        self.view.limpar_previa_medicao()

        p1 = self._pontos_medicao_distancia[0]["real"]
        p2 = self._pontos_medicao_distancia[1]["real"]

        medidor = self._criar_medidor_metrico()

        distancia_horizontal = self._distancia_horizontal_metros(medidor, p1, p2)
        desnivel = float( p2[2] - p1[2])
        distancia_reta = math.sqrt(distancia_horizontal ** 2 + desnivel ** 2)

        # Primeiro cria os pontos que acompanham a superfície do MDT.
        pontos_reais, pontos_cena = (self._amostrar_linha_medicao_mdt(p1, p2))

        # Limpa qualquer perfil anterior.
        self._dados_perfil_topografico_3d = None

        if pontos_reais is None:
            distancia_terreno = None

        else:
            distancia_terreno = 0.0
            distancias_perfil = [0.0]
            cotas_perfil = [float(pontos_reais[0][2])]

            distancia_acumulada = 0.0

            for indice in range(len(pontos_reais) - 1):

                a = pontos_reais[indice]
                b = pontos_reais[indice + 1]

                horizontal_segmento = (self._distancia_horizontal_metros(medidor, a, b))

                dz_segmento = float(b[2] - a[2])

                # Distância acompanhando o relevo.
                distancia_terreno += math.sqrt(horizontal_segmento ** 2 + dz_segmento ** 2)

                # Distância horizontal acumulada utilizada
                # no eixo X do perfil topográfico.
                distancia_acumulada += (horizontal_segmento)
                distancias_perfil.append(distancia_acumulada)

                cotas_perfil.append(float(b[2]))

            if len(pontos_reais) >= 2:
                distancias_array = np.asarray(distancias_perfil, dtype=np.float64)

                cotas_array = np.asarray(cotas_perfil, dtype=np.float64)

                if distancia_horizontal > 1e-12:
                    fatores_reta = (distancias_array / float(distancia_horizontal))
                else:
                    fatores_reta = np.zeros_like(distancias_array, dtype=np.float64)

                fatores_reta = np.clip(fatores_reta, 0.0, 1.0)

                cotas_reta_array = (float(p1[2]) + fatores_reta * float(p2[2] - p1[2]))

                self._dados_perfil_topografico_3d = {
                    "distancias": distancias_array,
                    "cotas": cotas_array,
                    "cotas_reta": cotas_reta_array,

                    "pontos": np.asarray(
                        pontos_reais,
                        dtype=np.float64),

                    "pontos_cena": np.asarray(
                        pontos_cena,
                        dtype=np.float64)}

        if distancia_horizontal > 1e-12:
            inclinacao = (desnivel / distancia_horizontal * 100.0)
            angulo = math.degrees(math.atan2(desnivel, distancia_horizontal))

        else:
            inclinacao = None

            angulo = (90.0
                if desnivel >= 0.0
                else -90.0)

        self.label_medicao_distancia_horizontal.setText(f"{distancia_horizontal:.3f} m")
        self.label_medicao_distancia_reta.setText(f"{distancia_reta:.3f} m")
        self.label_medicao_desnivel.setText(f"{desnivel:+.3f} m")
        self.label_medicao_angulo.setText(f"{angulo:+.3f} °")

        if distancia_terreno is not None:
            self.label_medicao_distancia_terreno.setText(f"{distancia_terreno:.3f} m")

        else:
            self.label_medicao_distancia_terreno.setText(self.tr("Indisponível"))

        if inclinacao is not None:
            self.label_medicao_inclinacao.setText(f"{inclinacao:+.3f} %")

        else:
            self.label_medicao_inclinacao.setText(self.tr("Vertical"))

        if pontos_cena is not None:
            self._desenhar_medicao_distancia_3d(pontos_cena)

        check_perfil = getattr(self, "check_perfil_topografico_3d", None)

        if check_perfil is not None:
            tem_perfil = (self._dados_perfil_topografico_3d
                is not None)

            # O estado marcado foi preservado durante
            # a construção da nova medição.
            perfil_marcado = (check_perfil.isChecked())

            check_perfil.setEnabled(tem_perfil)

            # Se o usuário já havia escolhido exibir o perfil,
            # atualiza e reabre automaticamente o DockWidget.
            if (tem_perfil
                and perfil_marcado):

                self._abrir_dock_perfil_topografico_3d()

        if not recalculo_edicao:
            self._modo_medicao_3d = None
            self.view._captura_medicao_ativa = False

            self.pushButton_medir_distancia_3d.setText(
                self.tr("Medir Distância (L)"))

            try:
                self.view.setCursor(self.view._cursor_reposo)

            except Exception:
                pass  # nosec B110

            self._sincronizar_vertices_editaveis_medicao_3d()

    def _reposicionar_texto_cursor_perfil_mapa_3d(self):
        """
        Reposiciona na tela o rótulo da cota associado
        ao cursor do perfil sobre o mapa 3D.
        """
        label = getattr(self, "_texto_cursor_perfil_mapa_3d", None)
        ponto = getattr(self, "_posicao_texto_cursor_perfil_mapa_3d", None)

        if label is None or ponto is None:
            return

        view = self.view

        try:
            modelview = view.viewMatrix()

            try:
                projection = view.projectionMatrix()

            except TypeError:
                viewport_view = view.getViewport()

                projection = view.projectionMatrix(viewport_view, viewport_view)

            vetor = QVector4D(
                float(ponto[0]),
                float(ponto[1]),
                float(ponto[2]),
                1.0)

            clip = projection * modelview * vetor

            w = float(clip.w())

            if w <= 1.0e-12:
                label.hide()
                return

            ndc_x = float(clip.x()) / w
            ndc_y = float(clip.y()) / w
            ndc_z = float(clip.z()) / w

            if (ndc_x < -1.0 or ndc_x > 1.0
                or ndc_y < -1.0 or ndc_y > 1.0
                or ndc_z < -1.0 or ndc_z > 1.0):

                label.hide()
                return

            x_tela = ((ndc_x + 1.0) * 0.5 * float(view.width()))
            y_tela = ((1.0 - (ndc_y + 1.0) * 0.5) * float(view.height()))

            label.adjustSize()

            x_label = int(round(x_tela + 10))
            y_label = int(round(y_tela - label.height() - 10))

            x_label = max(0, min(x_label, max(0, view.width() - label.width())))
            y_label = max(0, min(y_label, max(0, view.height() - label.height())))

            label.move(x_label, y_label)
            label.show()
            label.raise_()

        except Exception:
            pass  # nosec B110

    def _atualizar_cursor_perfil_mapa_3d(self, indice, cota):
        """
        Posiciona no visualizador 3D um ponto correspondente
        à posição atual do cursor no perfil topográfico.
        """
        dados = getattr(self, "_dados_perfil_topografico_3d", None)

        if dados is None:
            return

        pontos_cena = dados.get("pontos_cena")

        if (pontos_cena is None
            or indice < 0
            or indice >= len(pontos_cena)):

            return

        ponto = np.asarray([pontos_cena[indice]], dtype=np.float32).copy()

        # Mesma folga visual utilizada pela linha azul
        # da medição sobre o MDT.
        amplitude = abs(float(self._z_max) - float(self._z_min))

        folga = max(0.02, amplitude * 0.001)

        ponto[0, 2] += folga

        # BOLINHA SOBRE O MDT
        if self._item_cursor_perfil_mapa_3d is None:
            self._item_cursor_perfil_mapa_3d = (
                gl.GLScatterPlotItem(
                    pos=ponto,
                    color=(1.0, 0.85, 0.0, 1.0),
                    size=11.0,
                    pxMode=True))

            self._item_cursor_perfil_mapa_3d.setGLOptions("translucent")
            self._item_cursor_perfil_mapa_3d.setDepthValue(1100.0)
            self.view.addItem(self._item_cursor_perfil_mapa_3d)

        else:
            self._item_cursor_perfil_mapa_3d.setData(
                pos=ponto,
                color=(1.0, 0.85, 0.0, 1.0),
                size=11.0,
                pxMode=True)

        # TEXTO DA COTA
        posicao_texto = ponto[0].copy()

        deslocamento_texto = max(0.50, amplitude * 0.008)
        posicao_texto[2] += deslocamento_texto

        texto = self.tr("{cota:.3f} m").format(cota=cota)

        self._posicao_texto_cursor_perfil_mapa_3d = np.asarray(posicao_texto, dtype=np.float64)

        if self._texto_cursor_perfil_mapa_3d is None:
            self._texto_cursor_perfil_mapa_3d = QLabel(self.view)

            fonte = QFont()
            fonte.setPointSize(10)
            fonte.setBold(True)

            self._texto_cursor_perfil_mapa_3d.setFont(fonte)

            self._texto_cursor_perfil_mapa_3d.setStyleSheet(
                "QLabel {"
                "background-color: rgba(35, 35, 35, 215);"
                "color: rgb(255, 215, 0);"
                "border: 1px solid rgba(255, 215, 0, 160);"
                "border-radius: 4px;"
                "padding: 3px 6px;"
                "}")

            self._texto_cursor_perfil_mapa_3d.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)

        self._texto_cursor_perfil_mapa_3d.setText(texto)
        self._texto_cursor_perfil_mapa_3d.adjustSize()

        self._reposicionar_texto_cursor_perfil_mapa_3d()

        self._item_cursor_perfil_mapa_3d.show()
        self._texto_cursor_perfil_mapa_3d.show()
        self._texto_cursor_perfil_mapa_3d.raise_()

        self.view.update()

    def _desenhar_medicao_distancia_3d(self, pontos_cena):
        """
        Desenha:
        - linha reta entre P1 e P2;
        - linha acompanhando o MDT;
        - os dois pontos extremos.
        """
        if not pontos_cena:
            return

        self._remover_itens_medicao_distancia_3d()

        pontos_terreno = np.asarray(pontos_cena, dtype=np.float32)

        amplitude = abs(float(self._z_max) - float(self._z_min))
        folga = max(0.02, amplitude * 0.001)

        pontos_terreno[:, 2] += folga

        pontos_reta = np.asarray([
            pontos_terreno[0],
            pontos_terreno[-1]], dtype=np.float32)

        self._item_medicao_distancia_reta = gl.GLLinePlotItem(
            pos=pontos_reta,
            color=(1.0, 0.80, 0.0, 1.0),
            width=2.0,
            antialias=True)

        self._item_medicao_distancia_terreno = gl.GLLinePlotItem(
            pos=pontos_terreno,
            color=(0.0, 0.75, 1.0, 1.0),
            width=3.0,
            antialias=True)

        self._item_medicao_distancia_pontos = gl.GLScatterPlotItem(pos=pontos_reta, color=(1.0, 0.15, 0.15, 1.0), size=8.0)

        # As medições precisam ser renderizadas depois
        # do MDT, da textura raster e das sobreposições.
        self._item_medicao_distancia_reta.setGLOptions("translucent")
        self._item_medicao_distancia_reta.setDepthValue(1000.0)
        self._item_medicao_distancia_terreno.setGLOptions("translucent")
        self._item_medicao_distancia_terreno.setDepthValue(1001.0)
        self._item_medicao_distancia_pontos.setGLOptions("translucent")
        self._item_medicao_distancia_pontos.setDepthValue(1002.0)

        self.view.addItem(self._item_medicao_distancia_reta)
        self.view.addItem(self._item_medicao_distancia_terreno)
        self.view.addItem(self._item_medicao_distancia_pontos)

        self.view.update()

    def _alternar_perfil_topografico_3d(self, marcado):
        """
        Exibe ou oculta o DockWidget do perfil topográfico.
        """
        if marcado:
            if self._dados_perfil_topografico_3d is None:
                return

            self._abrir_dock_perfil_topografico_3d()

        else:
            dock = getattr(self, "_dock_perfil_topografico_3d", None)

            if dock is not None:
                dock.hide()

    def _abrir_dock_perfil_topografico_3d(self):
        """
        Cria, atualiza e exibe o perfil topográfico
        engatado na parte inferior do visualizador 3D.
        """
        if self._dados_perfil_topografico_3d is None:
            return

        if self._dock_perfil_topografico_3d is None:
            self._criar_dock_perfil_topografico_3d()

        self._atualizar_dock_perfil_topografico_3d()

        self._dock_perfil_topografico_3d.show()
        self._dock_perfil_topografico_3d.raise_()

    def _criar_dock_perfil_topografico_3d(self):
        """
        Cria o DockWidget do perfil topográfico.
        """
        dock = QDockWidget(self.tr("Perfil Topográfico"), self)

        dock.setObjectName("dockPerfilTopografico3D")
        dock.setAllowedAreas(Qt.DockWidgetArea.BottomDockWidgetArea)

        dock.setFeatures(QDockWidget.DockWidgetFeature.DockWidgetClosable
            | QDockWidget.DockWidgetFeature.DockWidgetMovable
            | QDockWidget.DockWidgetFeature.DockWidgetFloatable)

        dock.setMinimumHeight(260)

        conteudo = QWidget(dock)

        layout_principal = QHBoxLayout(conteudo)
        layout_principal.setContentsMargins(8, 8, 8, 8)

        layout_principal.setSpacing(12)

        # GRÁFICO
        grafico = pg.PlotWidget(conteudo)
        grafico.setBackground("w")
        grafico.setLabel("bottom", self.tr("Distância"), units="m")
        grafico.setLabel("left", self.tr("Cota"),  units="m")

        grafico.showGrid(x=True, y=True, alpha=0.25)
        grafico.setMouseEnabled(x=True, y=True)

        layout_principal.addWidget(grafico, 1)

        # INFORMAÇÕES DO PERFIL - LADO DIREITO
        frame_info = QFrame(conteudo)
        frame_info.setFrameShape(QFrame.Shape.Box)
        frame_info.setFrameShadow(QFrame.Shadow.Sunken)

        frame_info.setMinimumWidth(220)
        frame_info.setMaximumWidth(260)

        layout_info = QVBoxLayout(frame_info)
        layout_info.setContentsMargins(12, 10, 12, 10)
        layout_info.setSpacing(8)

        titulo = QLabel(self.tr("Informações do Perfil"), frame_info)

        fonte = titulo.font()
        fonte.setBold(True)
        titulo.setFont(fonte)

        layout_info.addWidget(titulo)

        grid = QGridLayout()

        grid.setHorizontalSpacing(12)
        grid.setVerticalSpacing(8)

        self._labels_perfil_topografico_3d = {}

        def adicionar_informacao(linha, texto, chave):

            label = QLabel(texto, frame_info)

            valor = QLabel("---", frame_info)
            valor.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
            valor.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)

            grid.addWidget(label, linha, 0)
            grid.addWidget(valor, linha, 1)

            self._labels_perfil_topografico_3d[chave] = valor

        adicionar_informacao(0, self.tr("Distância total:"), "distancia")
        adicionar_informacao(1, self.tr("Cota inicial:"), "cota_inicial")
        adicionar_informacao(2, self.tr("Cota final:"), "cota_final")
        adicionar_informacao(3, self.tr("Cota mínima:"), "cota_minima")
        adicionar_informacao(4, self.tr("Cota máxima:"), "cota_maxima")

        layout_info.addLayout(grid)
        layout_info.addStretch(1)

        layout_principal.addWidget(frame_info)

        dock.setWidget(conteudo)

        self.addDockWidget(Qt.DockWidgetArea.BottomDockWidgetArea, dock)

        dock.visibilityChanged.connect(self._ao_visibilidade_dock_perfil_topografico_3d)

        self._dock_perfil_topografico_3d = dock
        self._grafico_perfil_topografico_3d = grafico

        self._proxy_mouse_perfil_3d = (
            pg.SignalProxy(
                grafico.scene().sigMouseMoved,
                rateLimit=60,
                slot=self._mover_cursor_perfil_topografico_3d))

    def _preparar_cursor_perfil_topografico_3d(self):
        """
        Cria ou recoloca no gráfico as linhas vertical e
        horizontal e o ponto associado ao perfil.
        """
        grafico = getattr(self, "_grafico_perfil_topografico_3d", None)

        if grafico is None:
            return

        if self._linha_vertical_perfil_3d is None:
            self._linha_vertical_perfil_3d = (
                pg.InfiniteLine(
                    angle=90,
                    movable=False,
                    pen=pg.mkPen(
                        "#555555",
                        width=1,
                        style=Qt.PenStyle.DashLine)))

        if self._linha_horizontal_perfil_3d is None:
            self._linha_horizontal_perfil_3d = (
                pg.InfiniteLine(
                    angle=0,
                    movable=False,
                    pen=pg.mkPen(
                        "#555555",
                        width=1,
                        style=Qt.PenStyle.DashLine)))

        if self._ponto_cursor_perfil_3d is None:
            self._ponto_cursor_perfil_3d = (
                pg.ScatterPlotItem(
                    size=9,
                    brush=pg.mkBrush(
                        255, 255, 255),
                    pen=pg.mkPen(
                        "#1769aa",
                        width=2)))

        if self._texto_cursor_perfil_3d is None:
            self._texto_cursor_perfil_3d = pg.TextItem(
                text="",
                color=(35, 35, 35),
                anchor=(0, 1),
                border=pg.mkPen(
                    120, 120, 120, 180),
                fill=pg.mkBrush(
                    255, 255, 255, 230))

            self._texto_cursor_perfil_3d.setZValue(
                1000)

        grafico.addItem(self._linha_vertical_perfil_3d, ignoreBounds=True)
        grafico.addItem(self._linha_horizontal_perfil_3d, ignoreBounds=True)
        grafico.addItem(self._ponto_cursor_perfil_3d)
        grafico.addItem(self._texto_cursor_perfil_3d, ignoreBounds=True)


        self._linha_vertical_perfil_3d.hide()
        self._linha_horizontal_perfil_3d.hide()
        self._ponto_cursor_perfil_3d.hide()
        self._texto_cursor_perfil_3d.hide()

    def _mover_cursor_perfil_topografico_3d(self, evento):
        """
        Move a cruz do gráfico para a amostra do perfil
        mais próxima da posição atual do mouse.
        """
        grafico = getattr(self, "_grafico_perfil_topografico_3d", None)

        dados = getattr(self, "_dados_perfil_topografico_3d", None)

        if (grafico is None
            or dados is None):

            return

        distancias = dados.get("distancias")
        cotas = dados.get("cotas")

        if (distancias is None
            or cotas is None
            or len(distancias) == 0
            or len(cotas) == 0):

            return

        try:
            posicao_cena = evento[0]

        except Exception:
            posicao_cena = evento

        if not grafico.sceneBoundingRect().contains(posicao_cena):

            self._ocultar_cursor_perfil_topografico_3d()
            return

        ponto_grafico = (grafico.getPlotItem()
            .vb.mapSceneToView(posicao_cena))

        x_mouse = float(ponto_grafico.x())
        indice = int(np.searchsorted(distancias, x_mouse))

        if indice <= 0:
            indice = 0

        elif indice >= len(distancias):
            indice = len(distancias) - 1

        else:
            anterior = indice - 1

            if abs(x_mouse - float(distancias[anterior])) <= abs(float(distancias[indice]) - x_mouse):
                indice = anterior

        distancia = float(distancias[indice])
        cota = float(cotas[indice])
        
        self._atualizar_cursor_perfil_mapa_3d(indice, cota)

        self._linha_vertical_perfil_3d.setPos(distancia)
        self._linha_horizontal_perfil_3d.setPos(cota)

        self._ponto_cursor_perfil_3d.setData([distancia], [cota])

        self._texto_cursor_perfil_3d.setText(self.tr("Distância: {distancia:.3f} m\n"
                "Cota: {cota:.3f} m").format(distancia=distancia, cota=cota))

        # Pequeno deslocamento proporcional ao tamanho
        # atualmente visível do gráfico.
        view_box = (grafico.getPlotItem().vb)
        faixa_x, faixa_y = (view_box.viewRange())

        largura_visivel = max(1e-12, float(faixa_x[1] - faixa_x[0]))
        altura_visivel = max(1e-12, float(faixa_y[1] - faixa_y[0]))

        deslocamento_x = (largura_visivel * 0.012)
        deslocamento_y = (altura_visivel * 0.025)

        # Quando estiver próximo da borda direita,
        # coloca a etiqueta do outro lado do ponto.
        limite_direita = (float(faixa_x[0]) + largura_visivel * 0.78)

        if distancia >= limite_direita:
            self._texto_cursor_perfil_3d.setAnchor((1, 1))

            x_texto = (distancia - deslocamento_x)

        else:
            self._texto_cursor_perfil_3d.setAnchor((0, 1))

            x_texto = (distancia + deslocamento_x)

        y_texto = (cota + deslocamento_y)

        self._texto_cursor_perfil_3d.setPos(x_texto, y_texto)

        self._linha_vertical_perfil_3d.show()
        self._linha_horizontal_perfil_3d.show()
        self._ponto_cursor_perfil_3d.show()
        self._texto_cursor_perfil_3d.show()

    def _ocultar_cursor_perfil_mapa_3d(self):
        """
        Oculta o marcador correspondente no visualizador 3D.
        """
        self._posicao_texto_cursor_perfil_mapa_3d = None

        for item in (self._item_cursor_perfil_mapa_3d, self._texto_cursor_perfil_mapa_3d):

            if item is not None:
                try:
                    item.hide()

                except Exception:
                    pass  # nosec B110

        try:
            self.view.update()

        except Exception:
            pass  # nosec B110

    def _ocultar_cursor_perfil_topografico_3d(self):
        """
        Oculta os elementos temporários do cursor do perfil.
        """
        for item in (
            self._linha_vertical_perfil_3d,
            self._linha_horizontal_perfil_3d,
            self._ponto_cursor_perfil_3d,
            self._texto_cursor_perfil_3d):

            if item is not None:
                try:
                    item.hide()

                except Exception:
                    pass  # nosec B110

        self._ocultar_cursor_perfil_mapa_3d()

    def _atualizar_dock_perfil_topografico_3d(self):
        """
        Atualiza o gráfico e as informações do perfil atual.
        """
        dados = self._dados_perfil_topografico_3d

        if dados is None:
            return

        grafico = self._grafico_perfil_topografico_3d

        if grafico is None:
            return

        distancias = dados.get("distancias")
        cotas = dados.get("cotas")
        cotas_reta = dados.get("cotas_reta")

        if (distancias is None
            or cotas is None
            or len(distancias) < 2
            or len(cotas) < 2):

            return

        grafico.clear()

        # Linha reta entre o ponto inicial e final.
        if (cotas_reta is not None
            and len(cotas_reta) == len(distancias)):

            grafico.plot(distancias, cotas_reta, pen=pg.mkPen( QColor(230, 185, 0), width=2, style=Qt.PenStyle.DashLine))

        # Perfil do terreno sobre o MDT.
        grafico.plot(distancias, cotas, pen=pg.mkPen("#1769aa", width=2))

        self._preparar_cursor_perfil_topografico_3d()

        grafico.enableAutoRange()

        valores = {
            "distancia":
                f"{float(distancias[-1]):.3f} m",

            "cota_inicial":
                f"{float(cotas[0]):.3f} m",

            "cota_final":
                f"{float(cotas[-1]):.3f} m",

            "cota_minima":
                f"{float(np.min(cotas)):.3f} m",

            "cota_maxima":
                f"{float(np.max(cotas)):.3f} m"}

        for chave, texto in valores.items():
            label = (self._labels_perfil_topografico_3d.get(chave))

            if label is not None:
                label.setText(texto)

    def _ao_visibilidade_dock_perfil_topografico_3d(self, visivel):
        """
        Mantém o checkbox sincronizado com o DockWidget,
        ignorando widgets que já tenham sido destruídos.
        """
        check = getattr(self, "check_perfil_topografico_3d", None)

        if check is None:
            return

        try:
            check.blockSignals(True)
            check.setChecked(bool(visivel))
            check.blockSignals(False)

        except RuntimeError:
            # O diálogo de medições foi fechado e o
            # QCheckBox C++ já foi destruído.
            self.check_perfil_topografico_3d = None

    def _dialogo_perfil_topografico_finalizado(self, resultado=None):
        """
        Limpa as referências do diálogo do perfil e
        sincroniza seu estado com o checkbox.
        """
        self._dialogo_perfil_topografico_3d = None
        self._grafico_perfil_topografico_3d = None

        check = getattr(self, "check_perfil_topografico_3d",  None)

        if check is not None:
            try:
                check.blockSignals(True)
                check.setChecked(False)
                check.blockSignals(False)

            except Exception:
                pass  # nosec B110

    def _remover_itens_medicao_distancia_3d(self):
        itens = (
            "_item_medicao_distancia_reta",
            "_item_medicao_distancia_terreno",
            "_item_medicao_distancia_pontos")

        for atributo in itens:
            item = getattr(self, atributo, None)

            if item is not None:
                try:
                    if item in self.view.items:
                        self.view.removeItem(item)
                except Exception:
                    pass  # nosec B110

            setattr(self, atributo, None)

    def _limpar_medicao_distancia_3d(self):
        self.view.limpar_previa_medicao()
        self._remover_itens_medicao_distancia_3d()
        self._ocultar_cursor_perfil_mapa_3d()

        self._modo_medicao_3d = None
        self._pontos_medicao_distancia = []
        self.view._captura_medicao_ativa = False

        if getattr(self, "label_medicao_distancia_horizontal", None) is not None:
            self.label_medicao_distancia_horizontal.setText("--- m")
            self.label_medicao_distancia_reta.setText("--- m")
            self.label_medicao_distancia_terreno.setText("--- m")
            self.label_medicao_desnivel.setText("--- m")
            self.label_medicao_inclinacao.setText("--- %")
            self.label_medicao_angulo.setText("--- °")

        if getattr(self, "check_perfil_topografico_3d", None) is not None:

            self.check_perfil_topografico_3d.blockSignals(True)
            self.check_perfil_topografico_3d.setChecked(False)
            self.check_perfil_topografico_3d.setEnabled(False)
            self.check_perfil_topografico_3d.blockSignals(False)

        self._dados_perfil_topografico_3d = None

        dock = getattr(self, "_dock_perfil_topografico_3d", None)

        if dock is not None:
            dock.hide()

        if getattr(self, "pushButton_medir_distancia_3d", None) is not None:
            self.pushButton_medir_distancia_3d.setText(self.tr("Medir Distância (L)"))

        try:
            self.view.setCursor(self.view._cursor_reposo)
        except Exception:
            pass  # nosec B110

        self._sincronizar_vertices_editaveis_medicao_3d()

    def _limpar_medicoes_3d(self):
        self._limpar_medicao_distancia_3d()
        self._limpar_medicao_area_3d()

    def _encerrar_captura_medicao_3d(self):
        """
        Encerra uma medição que ainda esteja em construção,
        sem apagar medições já concluídas.
        """
        modo = self._modo_medicao_3d

        self.view.limpar_previa_medicao()
        self.view._captura_medicao_ativa = False
        self.view._medicao_finaliza_direita = False

        if modo == "distancia":
            self._remover_itens_medicao_distancia_3d()
            self._pontos_medicao_distancia = []

        elif modo == "area":
            self._remover_itens_medicao_area_3d()
            self._pontos_medicao_area = []

        self._modo_medicao_3d = None

        try:
            self.view.setCursor(self.view._cursor_reposo)
        except Exception:
            pass  # nosec B110

    def _dialogo_medicoes_finalizado(self, resultado=None):
        """
        Finaliza corretamente o estado das ferramentas quando
        o diálogo de medições é fechado.
        """
        # Impede recálculos pendentes depois que os widgets
        # do diálogo forem destruídos.
        timer = getattr(self, "_timer_recalculo_edicao_medicao_3d", None)

        if timer is not None:
            timer.stop()

        # Encerra qualquer edição de vértice em andamento.
        self._edicao_vertice_medicao_3d = None

        view = getattr(self, "view", None)

        if view is not None:
            view.limpar_vertices_editaveis_medicao()

        self._encerrar_captura_medicao_3d()

        self._dialogo_medicoes_3d = None

        # Remove referências Python aos widgets que pertenciam
        # ao diálogo e serão destruídos pelo WA_DeleteOnClose.
        self.pushButton_medir_distancia_3d = None
        self.pushButton_medir_area_3d = None
        self.pushButton_limpar_medicoes_3d = None
        self.check_perfil_topografico_3d = None

        self.label_medicao_distancia_horizontal = None
        self.label_medicao_distancia_reta = None
        self.label_medicao_distancia_terreno = None
        self.label_medicao_desnivel = None
        self.label_medicao_inclinacao = None
        self.label_medicao_angulo = None

        self.label_medicao_area_plana = None
        self.label_medicao_area_mdt = None
        self.label_medicao_perimetro_plano = None
        self.label_medicao_perimetro_mdt = None
        self.label_medicao_crs = None

        if hasattr(self, "check_medicoes"):
            self.check_medicoes.blockSignals(True)
            self.check_medicoes.setChecked(False)
            self.check_medicoes.blockSignals(False)

    def _mostrar_primeiro_ponto_medicao_distancia_3d(self, ponto_cena):
        """
        Exibe imediatamente o primeiro ponto da medição.
        """
        if self._item_medicao_distancia_pontos is not None:
            try:
                if self._item_medicao_distancia_pontos in self.view.items:
                    self.view.removeItem(self._item_medicao_distancia_pontos)
            except Exception:
                pass  # nosec B110

        ponto = np.asarray([ponto_cena], dtype=np.float32)

        def _folga_visual_medicao_3d(self):
            amplitude = abs(float(self._z_max) - float(self._z_min))

            folga = max(0.02, amplitude * 0.001)

            sobreposicao_ativa = (getattr(self, "check_sobreposicao", None) is not None
                and self.check_sobreposicao.isChecked())

            if sobreposicao_ativa:
                folga *= 3.0
            return folga

        self._item_medicao_distancia_pontos = gl.GLScatterPlotItem(
            pos=ponto,
            color=(1.0, 0.15, 0.15, 1.0),
            size=9.0)

        self._item_medicao_distancia_pontos.setGLOptions("translucent")

        self._item_medicao_distancia_pontos.setDepthValue(1002.0)

        self.view.addItem(self._item_medicao_distancia_pontos)
        self.view.update()

        return ponto[0]

    def _iniciar_medicao_area_3d(self):
        """
        Inicia a captura de um polígono sobre o MDT.

        Clique esquerdo:
            adiciona vértice.

        Botão direito:
            conclui a área.
        """
        self._limpar_medicao_area_3d()

        self._modo_medicao_3d = "area"
        self._pontos_medicao_area = []

        self.view._captura_medicao_ativa = True
        self.view._medicao_finaliza_direita = True

        try:
            self.view.setCursor(Qt.CursorShape.PointingHandCursor)
            self.view.setFocus()
        except Exception:
            pass  # nosec B110

        self.pushButton_medir_area_3d.setText(self.tr("Clique nos vértices • botão direito conclui"))

    def _ao_clique_medicao_3d(self, posicao):
        """
        Recebe cliques das ferramentas de medição.
        """
        if self._modo_medicao_3d not in ("distancia", "area"):
            return

        ponto_cena = self.ferramenta_coordenada._obter_ponto_cena(posicao)

        if ponto_cena is None:
            return

        exagero = max(1e-12, float(self.spin_exagero.value()))

        x = float(ponto_cena[0]) + self._x_centro
        y = float(ponto_cena[1]) + self._y_centro
        z = float(ponto_cena[2]) / exagero + self._z_centro

        registro = {"real": (x, y, z),
            "cena": np.asarray(ponto_cena, dtype=np.float64)}

        # DISTÂNCIA
        if self._modo_medicao_3d == "distancia":
            self._pontos_medicao_distancia.append(registro)

            if len(self._pontos_medicao_distancia) == 1:
                ponto_visual = self._mostrar_primeiro_ponto_medicao_distancia_3d(ponto_cena)
                self.view.iniciar_previa_medicao(ponto_visual)

                if hasattr(self, "pushButton_medir_distancia_3d"):
                    self.pushButton_medir_distancia_3d.setText(self.tr("Clique no segundo ponto..."))

                return

            if len(self._pontos_medicao_distancia) >= 2:
                self._finalizar_medicao_distancia_3d()

            return

        # ÁREA
        self._pontos_medicao_area.append(registro)

        self._atualizar_desenho_medicao_area_3d(fechado=False)

        self.view.atualizar_previa_area(
            [item["cena"] for item in self._pontos_medicao_area])

        ponto_visual = np.asarray(ponto_cena, dtype=np.float64).copy()

        amplitude = abs(float(self._z_max) - float(self._z_min))
        ponto_visual[2] += max(0.02, amplitude * 0.001)

        self.view.iniciar_previa_medicao(ponto_visual)

        quantidade = len(self._pontos_medicao_area)

        self.pushButton_medir_area_3d.setText(self.tr("{quantidade} vértices • botão direito conclui").format(quantidade=quantidade))

    def _atualizar_desenho_medicao_area_3d(self, fechado=False):
        """
        Desenha os vértices e o contorno da área acompanhando
        a superfície do MDT.
        """
        self._remover_itens_medicao_area_3d()

        if not self._pontos_medicao_area:
            return

        amplitude = abs(float(self._z_max) - float(self._z_min))
        folga = max(0.02, amplitude * 0.001)

        pontos_vertices = np.asarray(
            [item["cena"] for item in self._pontos_medicao_area],
            dtype=np.float32)

        pontos_vertices[:, 2] += folga

        self._item_medicao_area_pontos = gl.GLScatterPlotItem(pos=pontos_vertices, color=(1.0, 0.15, 0.15, 1.0), size=8.0)

        self.view.addItem(self._item_medicao_area_pontos)

        if len(self._pontos_medicao_area) < 2:
            self.view.update()
            return

        contorno = []

        quantidade = len(self._pontos_medicao_area)
        total_segmentos = quantidade if fechado else quantidade - 1

        for indice in range(total_segmentos):
            proximo = (indice + 1) % quantidade

            p1 = self._pontos_medicao_area[indice]["real"]
            p2 = self._pontos_medicao_area[proximo]["real"]

            _, pontos_cena = self._amostrar_linha_medicao_mdt(p1, p2)

            if not pontos_cena:
                continue

            trecho = np.asarray(pontos_cena, dtype=np.float32)
            trecho[:, 2] += folga

            if contorno:
                trecho = trecho[1:]

            contorno.extend(trecho.tolist())

        if len(contorno) >= 2:
            self._item_medicao_area_contorno = gl.GLLinePlotItem(
                pos=np.asarray(contorno, dtype=np.float32),
                color=(1.0, 0.65, 0.0, 1.0),
                width=3.0,
                antialias=True)

            self.view.addItem(self._item_medicao_area_contorno)

        self.view.update()

    def _calcular_area_plana_m2(self, geometria):
        """
        Calcula a área horizontal do polígono em m².

        CRS projetado:
            área cartesiana convertida para metros.

        CRS geográfico:
            área elipsoidal/geodésica.
        """
        if geometria is None or geometria.isEmpty():
            return 0.0

        crs = self.raster_layer.crs()

        if crs.isGeographic():
            medidor = self._criar_medidor_metrico()
            area = abs(float(medidor.measureArea(geometria)))

            try:
                area = float(medidor.convertAreaMeasurement(area, Qgis.AreaUnit.SquareMeters))
            except Exception:
                pass  # nosec B110

            return area

        area = abs(float(geometria.area()))

        try:
            fator = float(QgsUnitTypes.fromUnitToUnitFactor(crs.mapUnits(), Qgis.DistanceUnit.Meters))
        except Exception:
            fator = 1.0

        return area * fator * fator

    def _area_triangulo_3d_m2(self, p0, p1, p2, medidor, geografico, fator_xy):
        """
        Calcula a área de um triângulo 3D em m².
        Cada ponto deve estar no formato X, Y, Z.
        """
        if geografico:
            h01 = self._distancia_horizontal_metros(medidor, p0, p1)
            h12 = self._distancia_horizontal_metros(medidor, p1, p2)
            h20 = self._distancia_horizontal_metros(medidor, p2, p0)

            a = math.hypot(h01, float(p1[2]) - float(p0[2]))
            b = math.hypot(h12, float(p2[2]) - float(p1[2]))
            c = math.hypot(h20, float(p0[2]) - float(p2[2]))

            s = (a + b + c) * 0.5
            termo = s * (s - a) * (s - b) * (s - c)

            return math.sqrt(max(0.0, termo))

        v1 = np.array((
            (float(p1[0]) - float(p0[0])) * fator_xy,
            (float(p1[1]) - float(p0[1])) * fator_xy,
            float(p1[2]) - float(p0[2])))

        v2 = np.array((
            (float(p2[0]) - float(p0[0])) * fator_xy,
            (float(p2[1]) - float(p0[1])) * fator_xy,
            float(p2[2]) - float(p0[2])))

        return float(np.linalg.norm(np.cross(v1, v2)) * 0.5)

    def _calcular_area_superficie_mdt_m2(self, geometria):
        """
        Calcula a área real da superfície 3D existente dentro
        do polígono selecionado.

        A geometria utilizada é a superfície atualmente exibida,
        incluindo eventual deformação entre MDTs.
        """
        if geometria is None or geometria.isEmpty():
            return 0.0

        faces_internas, faces_borda = self._classificar_faces_poligono_grade(geometria)

        if self._faces is None:
            return 0.0

        medidor = self._criar_medidor_metrico()
        crs = self.raster_layer.crs()
        geografico = bool(crs.isGeographic())

        try:
            fator_xy = float(QgsUnitTypes.fromUnitToUnitFactor(crs.mapUnits(), Qgis.DistanceUnit.Meters))
        except Exception:
            fator_xy = 1.0

        vertices_visuais = self._vertices_com_exagero()
        exagero = max(1e-12, float(self.spin_exagero.value()))

        z_real = vertices_visuais[:, 2].astype(np.float64) / exagero + self._z_centro
        z_grade = vertices_visuais[:, 2].reshape(self._grade_y, self._grade_x)

        faces_base = self._faces.astype(np.int64)
        area_total = 0.0

        # FACES COMPLETAMENTE INTERNAS
        if faces_internas.size:
            indices = faces_base[faces_internas]

            if not geografico:
                x = self._x_real[indices].astype(np.float64)
                y = self._y_real[indices].astype(np.float64)
                z = z_real[indices]

                v1 = np.stack((
                    (x[:, 1] - x[:, 0]) * fator_xy,
                    (y[:, 1] - y[:, 0]) * fator_xy,
                    z[:, 1] - z[:, 0]), axis=1)

                v2 = np.stack((
                    (x[:, 2] - x[:, 0]) * fator_xy,
                    (y[:, 2] - y[:, 0]) * fator_xy,
                    z[:, 2] - z[:, 0]), axis=1)

                area_total += float(np.sum(np.linalg.norm(np.cross(v1, v2), axis=1) * 0.5))

            else:
                for indice_face in faces_internas:
                    idx0, idx1, idx2 = faces_base[indice_face]

                    p0 = (float(self._x_real[idx0]), float(self._y_real[idx0]), float(z_real[idx0]))
                    p1 = (float(self._x_real[idx1]), float(self._y_real[idx1]), float(z_real[idx1]))
                    p2 = (float(self._x_real[idx2]), float(self._y_real[idx2]), float(z_real[idx2]))

                    area_total += self._area_triangulo_3d_m2(
                        p0, p1, p2, medidor, geografico, fator_xy)

        # FACES DE BORDA
        for indice_face in faces_borda:
            idx0, idx1, idx2 = faces_base[indice_face]

            p0 = QgsPointXY(float(self._x_real[idx0]), float(self._y_real[idx0]))
            p1 = QgsPointXY(float(self._x_real[idx1]), float(self._y_real[idx1]))
            p2 = QgsPointXY(float(self._x_real[idx2]), float(self._y_real[idx2]))

            triangulo_geom = QgsGeometry.fromPolygonXY([[p0, p1, p2, p0]])

            triangulos = []

            try:
                if geometria.contains(triangulo_geom):
                    triangulos = [[p0, p1, p2]]

                elif geometria.intersects(triangulo_geom):
                    intersecao = geometria.intersection(triangulo_geom)

                    if (intersecao is not None
                        and not intersecao.isEmpty()):

                        triangulos = self._triangulos_da_geometria(intersecao)

            except Exception as e:
                self._registrar_erro_sobreposicao_3d(self.tr("Falha ao processar face de borda na medição de área 3D"), e)

            if not triangulos:
                continue

            for triangulo in triangulos:
                if len(triangulo) != 3:
                    continue

                pontos_3d = []

                for ponto in triangulo:
                    x = float(ponto.x())
                    y = float(ponto.y())

                    z_cena = self._amostrar_z_visual_malha_3d(x, y, z_grade)

                    if z_cena is None:
                        pontos_3d = []
                        break

                    z = float(z_cena) / exagero + self._z_centro
                    pontos_3d.append((x, y, z))

                if len(pontos_3d) != 3:
                    continue

                area_total += self._area_triangulo_3d_m2(
                    pontos_3d[0],
                    pontos_3d[1],
                    pontos_3d[2],
                    medidor,
                    geografico,
                    fator_xy)

        return area_total

    def _calcular_perimetros_area_3d(self):
        """
        Calcula:
        - perímetro plano/horizontal;
        - perímetro acompanhando a superfície do MDT.

        O fechamento entre o último e o primeiro vértice
        é incluído automaticamente.
        """
        if len(self._pontos_medicao_area) < 3:
            return 0.0, None

        medidor = self._criar_medidor_metrico()

        pontos = [item["real"]
            for item in self._pontos_medicao_area]

        perimetro_plano = 0.0
        perimetro_mdt = 0.0

        quantidade = len(pontos)

        for indice in range(quantidade):
            p1 = pontos[indice]
            p2 = pontos[(indice + 1) % quantidade]

            # PERÍMETRO PLANO
            distancia_horizontal = (self._distancia_horizontal_metros(medidor, p1, p2))

            perimetro_plano += (distancia_horizontal)

            # PERÍMETRO SOBRE O MDT
            pontos_reais, _ = (self._amostrar_linha_medicao_mdt(p1, p2))

            if (pontos_reais is None
                or len(pontos_reais) < 2):

                perimetro_mdt = None
                continue

            distancia_segmento_mdt = 0.0

            for indice_segmento in range(
                len(pontos_reais) - 1):

                a = pontos_reais[indice_segmento]
                b = pontos_reais[indice_segmento + 1]

                horizontal_segmento = (self._distancia_horizontal_metros(medidor, a, b))
                dz_segmento = float(b[2] - a[2])

                distancia_segmento_mdt += math.sqrt(horizontal_segmento ** 2 + dz_segmento ** 2)

            if perimetro_mdt is not None:
                perimetro_mdt += (distancia_segmento_mdt)

        return (perimetro_plano, perimetro_mdt)

    def _finalizar_medicao_area_3d(self, recalculo_edicao=False):
        """
        Finaliza o polígono com botão direito.
        """
        if (not recalculo_edicao
            and self._modo_medicao_3d
                != "area"):

            return

        if len(self._pontos_medicao_area) < 3:
            if getattr(self, "pushButton_medir_area_3d",
                    None) is not None:

                self.pushButton_medir_area_3d.setText(self.tr("Selecione pelo menos 3 vértices..."))

            return

        self.view.limpar_previa_medicao()

        pontos = [QgsPointXY(float(item["real"][0]), float(item["real"][1]))
            for item in self._pontos_medicao_area]

        pontos.append(QgsPointXY(pontos[0]))

        geometria = QgsGeometry.fromPolygonXY([pontos])

        if geometria.isEmpty():
            return

        try:
            if not geometria.isGeosValid():
                geometria_valida = geometria.makeValid()

                if geometria_valida is not None and not geometria_valida.isEmpty():
                    geometria = geometria_valida
        except Exception:
            pass  # nosec B110

        area_plana = self._calcular_area_plana_m2(geometria)
        area_mdt = (self._calcular_area_superficie_mdt_m2(geometria))

        (perimetro_plano, perimetro_mdt) = self._calcular_perimetros_area_3d()

        self.label_medicao_area_plana.setText(f"{area_plana:.3f} m²")
        self.label_medicao_area_mdt.setText(f"{area_mdt:.3f} m²")
        self.label_medicao_perimetro_plano.setText(f"{perimetro_plano:.3f} m")

        if perimetro_mdt is not None:
            self.label_medicao_perimetro_mdt.setText(f"{perimetro_mdt:.3f} m")

        else:
            self.label_medicao_perimetro_mdt.setText(self.tr("Indisponível"))

        self._atualizar_desenho_medicao_area_3d(fechado=True)

        self.view.definir_hachura_area_final([item["cena"] for item in self._pontos_medicao_area])

        if not recalculo_edicao:
            self._modo_medicao_3d = None

            self.view._captura_medicao_ativa = False
            self.view._medicao_finaliza_direita = False

            self.pushButton_medir_area_3d.setText(
                self.tr(
                    "Medir Área e Perímetro (P)"))

            try:
                self.view.setCursor(
                    self.view._cursor_reposo)

            except Exception:
                pass  # nosec B110

            self._sincronizar_vertices_editaveis_medicao_3d()

    def _sincronizar_vertices_editaveis_medicao_3d(
        self):
        """
        Atualiza:
        - vértices que podem ser movimentados;
        - arestas que aceitam inserção de novos vértices.
        """
        vertices = []
        segmentos = []

        # DISTÂNCIA
        if (len(self._pontos_medicao_distancia) == 2
            and self._modo_medicao_3d
                != "distancia"):

            for indice, item in enumerate(self._pontos_medicao_distancia):

                vertices.append({
                    "tipo":
                        "distancia",
                    "indice":
                        indice,
                    "cena":
                        item["cena"]})

        # ÁREA
        if (len(self._pontos_medicao_area) >= 3
            and self._modo_medicao_3d
                != "area"):

            quantidade = len(self._pontos_medicao_area)

            # Vértices existentes.
            for indice, item in enumerate(self._pontos_medicao_area):

                vertices.append({
                    "tipo":
                        "area",
                    "indice":
                        indice,
                    "cena":
                        item["cena"]})

            # Segmentos editáveis acompanhando o MDT.
            amplitude = abs(float(self._z_max) - float(self._z_min))
            folga = max(0.02, amplitude * 0.001)

            maximo_pontos_hover = (160)

            for indice in range(quantidade):

                proximo = ((indice + 1)
                    % quantidade)

                if proximo == 0:
                    indice_insercao = (quantidade)

                else:
                    indice_insercao = (proximo)

                p1_real = (self._pontos_medicao_area[indice]["real"])
                p2_real = (self._pontos_medicao_area[proximo]["real"])

                _, pontos_cena = (self._amostrar_linha_medicao_mdt(p1_real, p2_real))

                if (pontos_cena is None
                    or len(pontos_cena) < 2):

                    pontos_segmento = np.asarray(
                        [self._pontos_medicao_area[indice]["cena"],
                            self._pontos_medicao_area[proximo]["cena"]],
                        dtype=np.float64)

                else:
                    pontos_segmento = np.asarray(
                        pontos_cena,
                        dtype=np.float64).copy()

                    # Mesma pequena folga utilizada no
                    # desenho real do contorno.
                    pontos_segmento[:, 2] += (folga)

                # Para hover não precisamos projetar milhares de pontos a cada movimento.
                if len(pontos_segmento) > maximo_pontos_hover:

                    indices = np.linspace(0, len(pontos_segmento) - 1, maximo_pontos_hover, dtype=int)
                    pontos_segmento = (pontos_segmento[indices])

                segmentos.append({
                    "tipo":
                        "area",
                    "indice_inicio":
                        indice,
                    "indice_fim":
                        proximo,
                    "indice_insercao":
                        indice_insercao,

                    "cena_inicio":
                        self._pontos_medicao_area[indice]["cena"],

                    "cena_fim":
                        self._pontos_medicao_area[proximo]["cena"],

                    "cena_segmento":
                        pontos_segmento})

        self.view.definir_vertices_editaveis_medicao(vertices)
        self.view.definir_segmentos_editaveis_medicao(segmentos)

    def _atualizar_vertice_medicao_por_mouse_3d(self, tipo, indice, posicao):
        """
        Move um vértice para a posição do MDT localizada
        sob o mouse.
        """
        ponto_cena = (self.ferramenta_coordenada
            ._obter_ponto_cena(posicao))

        if ponto_cena is None:
            return False

        exagero = max(1e-12, float(self.spin_exagero.value()))

        x = (float(ponto_cena[0]) + self._x_centro)
        y = (float(ponto_cena[1]) + self._y_centro)
        z = (float(ponto_cena[2]) / exagero + self._z_centro)

        registro = {"real": (x, y,z),
            "cena":
                np.asarray(ponto_cena, dtype=np.float64)}

        if tipo == "distancia":
            if (indice < 0
                or indice
                    >= len(
                        self._pontos_medicao_distancia)):

                return False

            self._pontos_medicao_distancia[indice] = registro

        elif tipo == "area":
            if (indice < 0
                or indice
                    >= len(self._pontos_medicao_area)):

                return False

            self._pontos_medicao_area[indice] = registro

        else:
            return False

        self.view.atualizar_vertice_editavel_medicao(tipo, indice, ponto_cena)

        return True

    def _iniciar_arraste_vertice_medicao_3d(self, dados):
        """
        Inicia a edição de um vértice existente.
        """
        if not isinstance(dados, dict):

            return

        tipo = dados.get("tipo")
        indice = dados.get("indice")

        if tipo not in ("distancia", "area"):

            return

        try:
            indice = int(indice)

        except Exception:
            return

        self._edicao_vertice_medicao_3d = {
            "tipo":
                tipo,
            "indice":
                indice}

        self._timer_recalculo_edicao_medicao_3d.stop()

        # Cursor temporário do perfil não deve ficar
        # pairando sobre a posição antiga.
        self._ocultar_cursor_perfil_mapa_3d()

    def _atualizar_valores_rapidos_medicao_3d(self, tipo):
        """
        Atualiza os resultados geométricos leves durante o arraste.
        Os cálculos sobre a superfície do MDT permanecem na
        rotina de recálculo completo.
        """
        if self._dialogo_medicoes_3d is None:
            return

        medidor = self._criar_medidor_metrico()

        if tipo == "distancia":
            if len(self._pontos_medicao_distancia) != 2:
                return

            p1 = self._pontos_medicao_distancia[0]["real"]
            p2 = self._pontos_medicao_distancia[1]["real"]

            horizontal = self._distancia_horizontal_metros(medidor, p1, p2)

            desnivel = float(p2[2] - p1[2])
            reta = math.hypot(horizontal, desnivel)

            angulo = math.degrees(math.atan2(desnivel, horizontal))

            self.label_medicao_distancia_horizontal.setText(f"{horizontal:.3f} m")
            self.label_medicao_distancia_reta.setText(f"{reta:.3f} m")
            self.label_medicao_desnivel.setText(f"{desnivel:+.3f} m")
            self.label_medicao_angulo.setText(f"{angulo:+.3f} °")

            if horizontal > 1e-12:
                inclinacao = desnivel / horizontal * 100.0

                self.label_medicao_inclinacao.setText(f"{inclinacao:+.3f} %")
            else:
                self.label_medicao_inclinacao.setText(self.tr("Vertical"))

        elif tipo == "area":
            pontos = self._pontos_medicao_area

            if len(pontos) < 3:
                return

            coordenadas = [QgsPointXY(
                    float(item["real"][0]),
                    float(item["real"][1]))
                for item in pontos]

            geometria = QgsGeometry.fromPolygonXY([coordenadas + [QgsPointXY(coordenadas[0])]])

            if geometria.isEmpty():
                return

            area_plana = self._calcular_area_plana_m2(geometria)

            perimetro_plano = 0.0

            for i in range(len(pontos)):
                p1 = pontos[i]["real"]
                p2 = pontos[(i + 1) % len(pontos)]["real"]

                perimetro_plano += (self._distancia_horizontal_metros(medidor, p1, p2 ))

            self.label_medicao_area_plana.setText(f"{area_plana:.3f} m²")
            self.label_medicao_perimetro_plano.setText(f"{perimetro_plano:.3f} m")

    def _mover_arraste_vertice_medicao_3d(self, dados):
        """
        Atualiza visualmente a medição enquanto o
        vértice acompanha o mouse.
        """
        edicao = (self._edicao_vertice_medicao_3d)

        if edicao is None:
            return

        posicao = dados.get("posicao")

        if posicao is None:
            return

        tipo = edicao["tipo"]
        indice = edicao["indice"]

        if not self._atualizar_vertice_medicao_por_mouse_3d(tipo, indice, posicao):

            return

        # Atualiza imediatamente os valores geométricos.
        self._atualizar_valores_rapidos_medicao_3d(tipo)

        # DISTÂNCIA
        if tipo == "distancia":
            if len(self._pontos_medicao_distancia) == 2:

                p1 = self._pontos_medicao_distancia[0]["real"]
                p2 = self._pontos_medicao_distancia[1]["real"]

                _, pontos_cena = self._amostrar_linha_medicao_mdt(p1, p2)

                if pontos_cena is not None and len(pontos_cena) > 0:
                    self._desenhar_medicao_distancia_3d(pontos_cena)

            # Recalcula distância sobre MDT e perfil.
            if not self._timer_recalculo_edicao_medicao_3d.isActive():
                self._timer_recalculo_edicao_medicao_3d.start(16)

        # ÁREA
        else:
            self._atualizar_desenho_medicao_area_3d(fechado=True)

            self.view.definir_hachura_area_final([item["cena"]
                    for item in self._pontos_medicao_area])

            # Recalcula área e perímetro sobre o MDT.
            # Intervalo maior para evitar travamentos em malhas com muitos triângulos.
            if not self._timer_recalculo_edicao_medicao_3d.isActive():
                self._timer_recalculo_edicao_medicao_3d.start(100)

    def _finalizar_arraste_vertice_medicao_3d(self, dados):
        """
        Conclui o arraste e força o cálculo definitivo
        de todos os resultados.
        """
        edicao = (self._edicao_vertice_medicao_3d)

        if edicao is None:
            return

        posicao = dados.get("posicao")

        if posicao is not None:
            self._atualizar_vertice_medicao_por_mouse_3d(
                edicao["tipo"],
                edicao["indice"],
                posicao)

        self._timer_recalculo_edicao_medicao_3d.stop()

        tipo = edicao["tipo"]

        self._recalcular_medicao_editada_3d()
        self._edicao_vertice_medicao_3d = None
        self._sincronizar_vertices_editaveis_medicao_3d()

        self.view.update()

    def _recalcular_medicao_editada_3d(self):
        """
        Recalcula os resultados da medição durante
        ou após o reposicionamento de um vértice.
        """
        edicao = self._edicao_vertice_medicao_3d

        if edicao is None:
            return

        # O diálogo pode ter sido fechado enquanto havia
        # um recálculo pendente no QTimer.
        if self._dialogo_medicoes_3d is None:
            self._edicao_vertice_medicao_3d = None
            return

        tipo = edicao["tipo"]

        if tipo == "distancia":
            self._finalizar_medicao_distancia_3d(recalculo_edicao=True)

        elif tipo == "area":
            self._finalizar_medicao_area_3d(recalculo_edicao=True)

    def _inserir_vertice_segmento_medicao_3d(self, dados):
        """
        Insere um novo vértice em uma aresta existente
        da medição de área.

        O novo ponto é obtido diretamente sobre a
        superfície visual atual do MDT.
        """
        if not isinstance(dados, dict):

            return

        tipo = dados.get("tipo")

        # Distância permanece uma medição P1 -> P2.
        if tipo != "area":
            return

        if len(self._pontos_medicao_area) < 3:

            return

        # Só edita uma área já concluída.
        if self._modo_medicao_3d == "area":
            return

        posicao = dados.get("posicao")

        if posicao is None:
            return

        try:
            indice_insercao = int(dados.get("indice_insercao"))
        except Exception:
            return

        ponto_cena = (self.ferramenta_coordenada
            ._obter_ponto_cena(posicao))

        if ponto_cena is None:
            return

        exagero = max(1e-12, float(self.spin_exagero.value()))

        x = (float(ponto_cena[0]) + self._x_centro)
        y = (float(ponto_cena[1]) + self._y_centro)
        z = (float(ponto_cena[2]) / exagero + self._z_centro)

        registro = {"real": (x, y, z),
            "cena":
                np.asarray(ponto_cena, dtype=np.float64)}

        indice_insercao = max(0,
            min(indice_insercao,
                len(self._pontos_medicao_area)))

        self._pontos_medicao_area.insert(indice_insercao, registro)

        # Atualização visual imediata.
        self._atualizar_desenho_medicao_area_3d(fechado=True)

        self.view.definir_hachura_area_final(
            [item["cena"]
                for item
                in self._pontos_medicao_area])

        # Refaz índices de vértices e segmentos,
        # pois todos os posteriores podem ter mudado.
        self._sincronizar_vertices_editaveis_medicao_3d()

        self.view.update()

    def _remover_itens_medicao_area_3d(self):
        for atributo in ("_item_medicao_area_contorno", "_item_medicao_area_pontos"):
            item = getattr(self, atributo, None)

            if item is not None:
                try:
                    if item in self.view.items:
                        self.view.removeItem(item)
                except Exception:
                    pass  # nosec B110

            setattr(self, atributo, None)

    def _limpar_medicao_area_3d(self):
        self.view.limpar_hachura_area_final()
        self.view.limpar_previa_medicao()
        self._remover_itens_medicao_area_3d()

        self._pontos_medicao_area = []

        if self._modo_medicao_3d == "area":
            self._modo_medicao_3d = None
            self.view._captura_medicao_ativa = False
            self.view._medicao_finaliza_direita = False

        if getattr(self, "label_medicao_area_plana",
            None) is not None:

            self.label_medicao_area_plana.setText("--- m²")
            self.label_medicao_area_mdt.setText("--- m²")

            self.label_medicao_perimetro_plano.setText("--- m")
            self.label_medicao_perimetro_mdt.setText("--- m")

        if getattr(self, "pushButton_medir_area_3d", None) is not None:
            self.pushButton_medir_area_3d.setText(self.tr("Medir Área e Perímetro (P)"))

        try:
            self.view.setCursor(self.view._cursor_reposo)
        except Exception:
            pass  # nosec B110

        self._sincronizar_vertices_editaveis_medicao_3d()

    def exportar_para_web(self):
        """
        Inicia a exportação da visualização atual para Web.
        """
        try:
            exportador = ExportadorWebRaster3D(self)
            exportador.exportar()

        except Exception as e:
            if self.ui_manager is not None:
                self.ui_manager.mostrar_mensagem(self.tr("Erro ao iniciar a exportação Web: {erro}").format(erro=str(e)), "Erro")

    def _camadas_para_configuracao_3d(self, tipo):
        """
        Retorna as camadas atualmente disponíveis para configuração
        individual de cada tipo de sobreposição.
        """
        if tipo == "raster":
            return self._obter_rasters_sobre_mdt()

        if tipo == "linhas":
            return self._obter_linhas_sobre_mdt()

        if tipo == "poligonos":
            return self._obter_poligonos_sobre_mdt()

        if tipo == "pontos":
            return self._obter_pontos_sobre_mdt()

        return []

    def _mostrar_dialogo_auxiliar_3d(self, dlg, deslocamento_y=12):
        """
        Exibe um diálogo não modal inicialmente no canto superior
        direito da área 3D, permitindo continuar interagindo com
        o visualizador e com o painel lateral.
        """
        dlg.setWindowModality(Qt.WindowModality.NonModal)
        dlg.setWindowFlag(Qt.WindowType.Tool, True)
        dlg.adjustSize()

        canto = self.view.mapToGlobal(self.view.rect().topRight())
        margem = 12

        x = (canto.x() - dlg.width() - margem)
        y = (canto.y() + deslocamento_y)

        tela = QGuiApplication.screenAt(canto)

        if tela is not None:
            area = tela.availableGeometry()

            x = max(area.left() + margem, min(x, area.right() - dlg.width() - margem))
            y = max(area.top() + margem, min(y, area.bottom() - dlg.height() - margem))

        dlg.move(x, y)

        dlg.show()
        dlg.raise_()
        dlg.activateWindow()

    def _abrir_configuracao_sobreposicao_tipo(self, tipo):
        """
        Abre as configurações 3D padrão e individuais das camadas
        de um determinado tipo de sobreposição.

        Nesta etapa os valores são apenas armazenados.
        A aplicação visual será implementada posteriormente.
        """
        dlg_existente = self._dialogos_config_sobreposicao_3d.get(tipo)

        if dlg_existente is not None:
            try:
                if dlg_existente.isVisible():
                    dlg_existente.show()
                    dlg_existente.raise_()
                    dlg_existente.activateWindow()
                    return

            except RuntimeError:
                self._dialogos_config_sobreposicao_3d.pop(tipo, None)

        titulos = {
            "raster": self.tr("Configurar Rasters"),
            "linhas": self.tr("Configurar Linhas"),
            "poligonos": self.tr("Configurar Polígonos"),
            "pontos": self.tr("Configurar Pontos")}

        dlg = QDialog(self)
        dlg.setWindowTitle(titulos.get(tipo, self.tr("Configurar Sobreposição")))
        dlg.setMinimumWidth(300)

        layout = QVBoxLayout(dlg)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)

        # Trabalha inicialmente sobre cópias.
        padrao_rascunho = copy.deepcopy(self._config_3d_padrao[tipo])
        camadas_rascunho = copy.deepcopy(self._config_3d_camadas[tipo])

        padrao_original = copy.deepcopy(self._config_3d_padrao[tipo])
        camadas_original = copy.deepcopy(self._config_3d_camadas[tipo])

        # Seleção da camada
        frame_camada = QFrame(dlg)
        frame_camada.setFrameShape(QFrame.Shape.Box)
        frame_camada.setFrameShadow(QFrame.Shadow.Sunken)

        layout_camada = QGridLayout(frame_camada)
        layout_camada.setContentsMargins(8, 8, 8, 8)

        label_camada = QLabel(self.tr("Configurar:"), frame_camada)
        combo_camada = QComboBox(frame_camada)

        combo_camada.addItem(self.tr("Configuração padrão"), None)
        camadas = self._camadas_para_configuracao_3d(tipo)

        for layer in camadas:
            combo_camada.addItem(layer.name(), layer.id())

        layout_camada.addWidget(label_camada, 0, 0)
        layout_camada.addWidget(combo_camada, 0, 1)
        layout.addWidget(frame_camada)

        # Parâmetros
        frame_parametros = QFrame(dlg)
        frame_parametros.setFrameShape(QFrame.Shape.Box)
        frame_parametros.setFrameShadow(QFrame.Shadow.Sunken)

        grid = QGridLayout(frame_parametros)
        grid.setContentsMargins(10, 10, 10, 10)
        grid.setHorizontalSpacing(10)
        grid.setVerticalSpacing(7)

        controles = {}
        linha = 0

        def adicionar_double(chave, texto, minimo, maximo, casas=2, passo=0.10, sufixo=""):
            nonlocal linha

            label = QLabel(self.tr(texto), frame_parametros)
            spin = QDoubleSpinBox(frame_parametros)
            spin.setRange(minimo, maximo)
            spin.setDecimals(casas)
            spin.setSingleStep(passo)

            if sufixo:
                spin.setSuffix(sufixo)

            grid.addWidget(label, linha, 0)
            grid.addWidget(spin, linha, 1)

            controles[chave] = spin
            linha += 1

        def adicionar_int(chave, texto, minimo, maximo):
            nonlocal linha

            label = QLabel(self.tr(texto), frame_parametros)
            spin = QSpinBox(frame_parametros)
            spin.setRange(minimo, maximo)

            grid.addWidget(label, linha, 0)
            grid.addWidget(spin, linha, 1)

            controles[chave] = spin
            linha += 1

        def adicionar_check(chave, texto):
            nonlocal linha

            check = QCheckBox(self.tr(texto), frame_parametros)
            grid.addWidget(check, linha, 0, 1, 2)

            controles[chave] = check
            linha += 1

        def adicionar_combo(chave, texto, itens):
            nonlocal linha

            label = QLabel(self.tr(texto), frame_parametros)
            combo = QComboBox(frame_parametros)

            for texto_item, valor in itens:
                combo.addItem(self.tr(texto_item), valor)

            grid.addWidget(label, linha, 0)
            grid.addWidget(combo, linha, 1)

            controles[chave] = combo
            linha += 1

        # Raster
        if tipo == "raster":
            adicionar_combo("modo", self.tr("Modo:"),
                [(self.tr("Sobreposição"), "sobreposicao"),
                    (self.tr("Superfície 3D"), "superficie_3d")])

            adicionar_check("habilitar_diferenca",
                self.tr("Habilitar diferença entre MDTs"))

            adicionar_check("mostrar_cores_diferenca",
                self.tr("Exibir cores de corte e aterro"))

            adicionar_double("expansao_lateral",
                self.tr("Expansão lateral:"), 0.0, 10000.0, 2, 10)

            adicionar_double("opacidade",
                self.tr("Opacidade:"), 0.0, 100.0, 1, 5.0, " %")

            adicionar_combo("qualidade_textura",
                self.tr("Qualidade da textura:"),
                [(self.tr("Automática"), "auto"),
                    (self.tr("Média - 2048 px"), 2048),
                    (self.tr("Alta - 4096 px"), 4096),
                    (self.tr("Máxima - 8192 px"), 8192)])

        # Linhas
        elif tipo == "linhas":
            adicionar_double("altura", self.tr("Altura sobre o terreno:"), 0.0, 10000.0, 2, 1.0, " m")
            adicionar_double("espessura", self.tr("Espessura:"), 0.10, 50.0, 2, 0.10)
            adicionar_double("opacidade", self.tr("Opacidade:"), 0.0, 100.0, 1, 5.0, " %")

            adicionar_check("parede", self.tr("Mostrar parede vertical até o terreno"))
            adicionar_double("opacidade_parede", self.tr("Opacidade da parede:"), 0.0, 100.0, 1, 5.0, " %")

            adicionar_check("rotulo", self.tr("Mostrar rótulo"))
            adicionar_check("ocultar_rotulo_encoberto", self.tr("Ocultar rótulos encobertos"))
            adicionar_double("altura_rotulo", self.tr("Altura do rótulo sobre a linha:"), 0.0, 10000.0, 2, 0.25, " m")
            adicionar_int("tamanho_rotulo", self.tr("Tamanho do texto:"), 6, 72)

        # Polígonos
        elif tipo == "poligonos":
            adicionar_double("altura", self.tr("Altura sobre o terreno:"), -10000.0, 10000.0, 2, 1.0, " m")

            adicionar_check("caixa", self.tr("Elevar em forma de caixa"))

            adicionar_check("preenchimento", self.tr("Mostrar preenchimento"))

            adicionar_combo(
                "modo_preenchimento",
                self.tr("Modo do preenchimento:"),
                [(self.tr("Pintura rápida"), "pintura"),
                    (self.tr("Superfície 3D"), "superficie"),
                    (self.tr("Recorte preciso"), "preciso")])

            controles["modo_preenchimento"].setToolTip(
                self.tr(
                    "Pintura rápida: maior desempenho.\n"
                    "Superfície 3D: usa as faces completas do terreno.\n"
                    "Recorte preciso: recorta exatamente as bordas e pode ser mais lento."))

            adicionar_double("opacidade", self.tr("Opacidade do preenchimento:"), 0.0, 100.0, 1, 5.0, " %")
            adicionar_check("contorno", self.tr("Mostrar contorno"))
            adicionar_double("espessura_contorno", self.tr("Espessura do contorno:"), 0.10, 50.0, 2, 0.10)

            adicionar_check("rotulo", self.tr("Mostrar rótulo"))
            adicionar_check("ocultar_rotulo_encoberto", self.tr("Ocultar rótulos encobertos"))
            adicionar_double("altura_rotulo", self.tr("Altura do rótulo sobre o polígono:"), 0.0, 10000.0, 2, 0.25, " m")
            adicionar_int("tamanho_rotulo", self.tr("Tamanho do texto:"), 6, 72)

        # Pontos
        elif tipo == "pontos":
            adicionar_double("altura", self.tr("Altura sobre o terreno:"), -10000.0, 10000.0, 2, 1.0, " m")
            adicionar_double("tamanho", self.tr("Tamanho do ponto:"), 1.0, 100.0, 1, 1.0)
            adicionar_check("haste", self.tr("Mostrar haste"))
            adicionar_double("altura_haste", self.tr("Altura da haste:"), 0.0, 10000.0, 2, 0.25, " m")
            adicionar_double("espessura_haste", self.tr("Espessura da haste:"), 0.10, 20.0, 2, 0.10)
            adicionar_check("rotulo", self.tr("Mostrar rótulo"))
            adicionar_check("ocultar_rotulo_encoberto", self.tr("Ocultar rótulos encobertos"))
            adicionar_double("altura_rotulo", self.tr("Altura do rótulo sobre o topo:"), 0.0, 1000.0, 2, 0.10, " m")
            adicionar_int("tamanho_rotulo", self.tr("Tamanho do texto:"), 6, 72)

        # Campo utilizado pelo rótulo
        combo_campo_rotulo = None
        label_campo_rotulo = None

        if tipo in ("linhas", "poligonos", "pontos"):
            label_campo_rotulo = QLabel(self.tr("Campo do rótulo:"), frame_parametros)
            combo_campo_rotulo = QComboBox(frame_parametros)

            grid.addWidget(label_campo_rotulo, linha, 0)
            grid.addWidget(combo_campo_rotulo, linha, 1)

            linha += 1

        layout.addWidget(frame_parametros)

        # Botões de configuração
        push_restaurar_padrao = QPushButton(self.tr("Restaurar configuração padrão"), dlg)

        layout.addWidget(push_restaurar_padrao)

        textos_aplicar_todas = {
            "raster": self.tr("Aplicar esta configuração a todos os rasters"),
            "linhas": self.tr("Aplicar esta configuração a todas as linhas"),
            "poligonos": self.tr("Aplicar esta configuração a todos os polígonos"),
            "pontos": self.tr("Aplicar esta configuração a todos os pontos")}

        push_aplicar_todas = QPushButton(textos_aplicar_todas[tipo], dlg)

        layout.addWidget(push_aplicar_todas)

        aviso = QLabel(self.tr("As alterações são visualizadas imediatamente no 3D. Cada camada pode possuir sua própria configuração."), dlg)

        aviso.setWordWrap(True)
        layout.addWidget(aviso)

        # Funções internas
        carregando = {"ativo": False}

        def obter_valores_controles():
            valores = {}

            for chave, widget in controles.items():
                if isinstance(widget, QCheckBox):
                    valores[chave] = widget.isChecked()

                elif isinstance(widget, QDoubleSpinBox):
                    valores[chave] = float(widget.value())

                elif isinstance(widget, QSpinBox):
                    valores[chave] = int(widget.value())

                elif isinstance(widget, QComboBox):
                    valores[chave] = widget.currentData()

            if combo_campo_rotulo is not None:
                valores["campo_rotulo"] = combo_campo_rotulo.currentData()

            return valores

        def definir_valores_controles(config):
            carregando["ativo"] = True

            try:
                for chave, widget in controles.items():
                    valor = config.get(chave)

                    if valor is None:
                        continue

                    if isinstance(widget, QCheckBox):
                        widget.setChecked(bool(valor))

                    elif isinstance(widget, QDoubleSpinBox):
                        widget.setValue(float(valor))

                    elif isinstance(widget, QSpinBox):
                        widget.setValue(int(valor))

                    elif isinstance(widget, QComboBox):
                        indice = widget.findData(valor)

                        if indice >= 0:
                            widget.setCurrentIndex(indice)

            finally:
                carregando["ativo"] = False

        def obter_layer_por_id(layer_id):
            if not layer_id:
                return None

            return QgsProject.instance().mapLayer(layer_id)

        def atualizar_marcas_camadas():
            """
            Exibe ✓ ao lado das camadas que possuem
            configuração 3D individual.
            """
            for indice in range(1, combo_camada.count()):
                layer_id = combo_camada.itemData(indice)
                layer = obter_layer_por_id(layer_id)

                if layer is None:
                    continue

                nome = layer.name()

                if layer_id in camadas_rascunho:
                    nome = f"{nome} ✓"

                combo_camada.setItemText(indice, nome)

        def preencher_campos_rotulo(layer_id, campo_atual=None):
            if combo_campo_rotulo is None:
                return

            combo_campo_rotulo.blockSignals(True)
            combo_campo_rotulo.clear()

            if layer_id is None:
                combo_campo_rotulo.addItem(self.tr("Definir individualmente por camada"), None)
                combo_campo_rotulo.setEnabled(False)

            else:
                layer = obter_layer_por_id(layer_id)

                if isinstance(layer, QgsVectorLayer):
                    for field in layer.fields():
                        combo_campo_rotulo.addItem(field.name(), field.name())

                combo_campo_rotulo.setEnabled(True)

                if campo_atual:
                    indice = combo_campo_rotulo.findData(campo_atual)

                    if indice >= 0:
                        combo_campo_rotulo.setCurrentIndex(indice)

            combo_campo_rotulo.blockSignals(False)

        def habilitar_controles(habilitar):
            for widget in controles.values():
                widget.setEnabled(habilitar)

            if combo_campo_rotulo is not None:
                layer_id = combo_camada.currentData()
                combo_campo_rotulo.setEnabled(habilitar and layer_id is not None)

        indice_anterior = {"valor": None}

        def atualizar_controles_raster():
            """
            Atualiza os controles específicos do Raster.

            - serviço online -> Sobreposição;
            - raster RGB/RGBA local -> Sobreposição;
            - raster local com menos de 3 bandas -> permite
              Sobreposição ou Superfície 3D;
            - expansão lateral -> somente serviços online;
            - diferença entre MDTs -> somente raster local de elevação.
            """
            if tipo != "raster":
                return

            combo_modo = controles.get("modo")
            check_diferenca = controles.get("habilitar_diferenca")
            check_cores_diferenca = controles.get("mostrar_cores_diferenca")
            spin_expansao = controles.get("expansao_lateral")
            spin_opacidade = controles.get("opacidade")
            combo_qualidade_textura = controles.get("qualidade_textura")

            if combo_modo is None:
                return

            layer_id = combo_camada.currentData()
            layer = obter_layer_por_id(layer_id)

            if layer is None:
                combo_modo.setEnabled(True)

                if check_diferenca is not None:
                    check_diferenca.blockSignals(True)
                    check_diferenca.setChecked(False)
                    check_diferenca.blockSignals(False)
                    check_diferenca.setEnabled(False)

                if check_cores_diferenca is not None:
                    check_cores_diferenca.blockSignals(True)
                    check_cores_diferenca.setChecked(False)
                    check_cores_diferenca.blockSignals(False)
                    check_cores_diferenca.setEnabled(False)

                if spin_expansao is not None:
                    spin_expansao.setEnabled(False)

                if spin_opacidade is not None:
                    spin_opacidade.setEnabled(False)

                if combo_qualidade_textura is not None:
                    combo_qualidade_textura.setEnabled(False)

                return

            servico_online = self._raster_e_servico_online(layer)
            pode_diferenca = self._raster_pode_ter_diferenca_3d(layer)

            if servico_online:
                indice = combo_modo.findData("sobreposicao")

                if indice >= 0:
                    combo_modo.blockSignals(True)
                    combo_modo.setCurrentIndex(indice)
                    combo_modo.blockSignals(False)

                combo_modo.setEnabled(False)

                if check_diferenca is not None:
                    check_diferenca.blockSignals(True)
                    check_diferenca.setChecked(False)
                    check_diferenca.blockSignals(False)
                    check_diferenca.setEnabled(False)

                if check_cores_diferenca is not None:
                    check_cores_diferenca.blockSignals(True)
                    check_cores_diferenca.setChecked(False)
                    check_cores_diferenca.blockSignals(False)
                    check_cores_diferenca.setEnabled(False)

                # Expansão lateral disponível somente para serviços online.
                if spin_expansao is not None:
                    spin_expansao.setEnabled(True)

                if spin_opacidade is not None:
                    spin_opacidade.setEnabled(True)

                if combo_qualidade_textura is not None:
                    combo_qualidade_textura.setEnabled(True)

            elif pode_diferenca:
                combo_modo.setEnabled(True)

                modo_atual = combo_modo.currentData()
                em_sobreposicao = (modo_atual == "sobreposicao")

                if combo_qualidade_textura is not None:
                    combo_qualidade_textura.setEnabled(em_sobreposicao)

                if check_diferenca is not None:
                    if em_sobreposicao:
                        check_diferenca.blockSignals(True)
                        check_diferenca.setChecked(False)
                        check_diferenca.blockSignals(False)
                        check_diferenca.setEnabled(False)
                    else:
                        check_diferenca.setEnabled(True)

                diferenca_ativa = (
                    check_diferenca is not None
                    and check_diferenca.isChecked())

                if check_cores_diferenca is not None:
                    if not diferenca_ativa:
                        check_cores_diferenca.blockSignals(True)
                        check_cores_diferenca.setChecked(False)
                        check_cores_diferenca.blockSignals(False)

                    check_cores_diferenca.setEnabled(diferenca_ativa)

                if spin_opacidade is not None:
                    spin_opacidade.setEnabled(not diferenca_ativa)

                if spin_expansao is not None:
                    spin_expansao.setEnabled(False)

            else:
                indice = combo_modo.findData("sobreposicao")

                if indice >= 0:
                    combo_modo.blockSignals(True)
                    combo_modo.setCurrentIndex(indice)
                    combo_modo.blockSignals(False)

                combo_modo.setEnabled(False)

                if check_diferenca is not None:
                    check_diferenca.blockSignals(True)
                    check_diferenca.setChecked(False)
                    check_diferenca.blockSignals(False)
                    check_diferenca.setEnabled(False)

                if check_cores_diferenca is not None:
                    check_cores_diferenca.blockSignals(True)
                    check_cores_diferenca.setChecked(False)
                    check_cores_diferenca.blockSignals(False)
                    check_cores_diferenca.setEnabled(False)

                if spin_expansao is not None:
                    spin_expansao.setEnabled(False)

                if spin_opacidade is not None:
                    spin_opacidade.setEnabled(True)

                if combo_qualidade_textura is not None:
                    combo_qualidade_textura.setEnabled(True)

        def atualizar_estado_botao_restaurar():
            if push_restaurar_padrao is None:
                return

            layer_id = combo_camada.currentData()

            push_restaurar_padrao.setEnabled(
                layer_id is not None
                and layer_id in camadas_rascunho)

        def salvar_item_atual(indice=None):
            if carregando["ativo"]:
                return

            if indice is None:
                layer_id = combo_camada.currentData()
            else:
                layer_id = combo_camada.itemData(indice)

            valores = obter_valores_controles()

            if layer_id is None:
                valores.pop("campo_rotulo", None)
                padrao_rascunho.update(valores)

            else:
                camadas_rascunho[layer_id] = valores

            atualizar_estado_botao_restaurar()
            atualizar_marcas_camadas()

        def aplicar_previa_raster():
            """
            Publica temporariamente o rascunho do Raster e atualiza
            o visualizador sem fechar o diálogo.
            """
            if tipo != "raster":
                return

            if carregando["ativo"]:
                return

            salvar_item_atual()

            self._config_3d_padrao[tipo] = copy.deepcopy(padrao_rascunho)
            self._config_3d_camadas[tipo] = copy.deepcopy(camadas_rascunho)

            self._invalidar_cache_raster_sobreposto_3d()

            if (self.check_sobreposicao.isChecked()
                and self._sobrepor_rasters):
                self._atualizar_sobreposicoes()

            QCoreApplication.processEvents()

        timer_previa_linhas = QTimer(dlg)
        timer_previa_linhas.setSingleShot(True)
        timer_previa_linhas.setInterval(350)

        timer_previa_expansao_raster = QTimer(dlg)
        timer_previa_expansao_raster.setSingleShot(True)
        timer_previa_expansao_raster.setInterval(500)

        timer_previa_opacidade_raster = QTimer(dlg)
        timer_previa_opacidade_raster.setSingleShot(True)
        timer_previa_opacidade_raster.setInterval(500)

        def aplicar_previa_expansao_raster():
            """
            Atualiza somente a expansão lateral do raster.
            Não invalida nem recria a textura aplicada sobre o MDT.
            """
            if tipo != "raster":
                return

            if carregando["ativo"]:
                return

            # Salva o novo valor da expansão no rascunho.
            salvar_item_atual()

            # Publica temporariamente a configuração para que
            # _renderizar_expansao_rasters() leia o novo valor.
            self._config_3d_padrao[tipo] = copy.deepcopy(padrao_rascunho)
            self._config_3d_camadas[tipo] = copy.deepcopy(camadas_rascunho)

            # Atualiza exclusivamente o objeto OpenGL da expansão.
            self._atualizar_expansao_raster()

            QCoreApplication.processEvents()

        def agendar_previa_expansao_raster():
            """
            Aguarda um pequeno intervalo após a última
            alteração antes de reconstruir a expansão.
            """
            if tipo != "raster":
                return

            if carregando["ativo"]:
                return

            timer_previa_expansao_raster.stop()
            timer_previa_expansao_raster.start(500)

        def finalizar_previa_expansao_raster_pendente():
            """
            Executa imediatamente uma atualização de
            expansão ainda pendente.
            """
            if tipo != "raster":
                return

            if timer_previa_expansao_raster.isActive():
                timer_previa_expansao_raster.stop()

            aplicar_previa_expansao_raster()

        timer_previa_expansao_raster.timeout.connect(aplicar_previa_expansao_raster)

        def agendar_previa_opacidade_raster():
            """
            Aguarda o término provável da digitação
            antes de reconstruir a textura raster.
            """
            if tipo != "raster":
                return

            if carregando["ativo"]:
                return

            timer_previa_opacidade_raster.stop()
            timer_previa_opacidade_raster.start(500)

        def finalizar_previa_opacidade_raster_pendente():
            """
            Executa imediatamente uma alteração de
            opacidade ainda pendente.
            """
            if tipo != "raster":
                return

            if not timer_previa_opacidade_raster.isActive():
                return

            timer_previa_opacidade_raster.stop()
            aplicar_previa_raster()

        timer_previa_opacidade_raster.timeout.connect(aplicar_previa_raster)

        def executar_previa_linhas():
            """
            Publica temporariamente as configurações das linhas e
            atualiza imediatamente os objetos OpenGL correspondentes.
            """
            if tipo != "linhas":
                return

            if carregando["ativo"]:
                return

            salvar_item_atual()

            self._config_3d_padrao[tipo] = copy.deepcopy(padrao_rascunho)
            self._config_3d_camadas[tipo] = copy.deepcopy(camadas_rascunho)

            if (self.check_sobreposicao.isChecked()
                and self._sobrepor_linhas):

                # Reutiliza a relação de camadas já identificada.
                # As configurações visuais são aplicadas pela rotina de renderização abaixo.
                if not self._camadas_linhas_sobreposicao:
                    self._camadas_linhas_sobreposicao = (self._obter_linhas_sobre_mdt())

                self._atualizar_linhas_sobreposicao()

            QCoreApplication.processEvents()

        def agendar_previa_linhas(atraso_ms=350):
            """
            Aguarda alguns milissegundos antes de reconstruir as linhas,
            evitando atualizações durante a digitação contínua.
            """
            if tipo != "linhas":
                return

            if carregando["ativo"]:
                return

            timer_previa_linhas.stop()
            timer_previa_linhas.setInterval(int(atraso_ms))
            timer_previa_linhas.start()

        def aplicar_previa_linhas():
            """
            Prévia normal dos controles de linhas.
            """
            agendar_previa_linhas(100)

        timer_previa_linhas.timeout.connect(executar_previa_linhas)

        def finalizar_previa_linhas_pendente():
            """
            Executa imediatamente a última alteração pendente das linhas.
            """
            if tipo != "linhas":
                return

            if timer_previa_linhas.isActive():
                timer_previa_linhas.stop()

            executar_previa_linhas()

        timer_previa_poligonos = QTimer(dlg)
        timer_previa_poligonos.setSingleShot(True)
        timer_previa_poligonos.setInterval(100)

        def executar_previa_poligonos():
            """
            Executa efetivamente a atualização 3D dos polígonos.
            """
            if tipo != "poligonos":
                return

            if carregando["ativo"]:
                return

            self._config_3d_padrao[tipo] = copy.deepcopy(padrao_rascunho)
            self._config_3d_camadas[tipo] = copy.deepcopy(camadas_rascunho)

            if (self.check_sobreposicao.isChecked()
                and self._sobrepor_poligonos):

                if not self._camadas_poligonos_sobreposicao:
                    self._camadas_poligonos_sobreposicao = self._obter_poligonos_sobre_mdt()

                self._atualizar_poligonos_sobreposicao()

        def aplicar_previa_oclusao_rotulo():
            """
            Salva a opção de oclusão dos rótulos sem reconstruir
            as geometrias 3D da sobreposição.
            """
            if carregando["ativo"]:
                return

            salvar_item_atual()

            self._config_3d_padrao[tipo] = copy.deepcopy(padrao_rascunho)
            self._config_3d_camadas[tipo] = copy.deepcopy(camadas_rascunho)

            self._solicitar_atualizacao_oclusao_rotulos()

        def agendar_previa_poligonos(atraso_ms):
            """
            Publica a configuração atual e agenda a reconstrução
            dos polígonos após o intervalo solicitado.
            """
            if tipo != "poligonos":
                return

            if carregando["ativo"]:
                return

            salvar_item_atual()

            self._config_3d_padrao[tipo] = copy.deepcopy(padrao_rascunho)
            self._config_3d_camadas[tipo] = copy.deepcopy(camadas_rascunho)

            timer_previa_poligonos.start(atraso_ms)

        def aplicar_previa_poligonos():
            """
            Prévia normal dos controles de polígonos.
            """
            agendar_previa_poligonos(100)

        def aplicar_previa_altura_poligonos():
            """
            Aguarda o término provável da digitação da altura antes
            de reconstruir os polígonos.
            """
            agendar_previa_poligonos(450)

        def aplicar_previa_numerica_poligonos():
            """
            Aguarda pequenas alterações consecutivas em controles numéricos
            antes de reconstruir os polígonos.
            """
            agendar_previa_poligonos(350)

        timer_previa_poligonos.timeout.connect(executar_previa_poligonos)

        timer_previa_pontos = QTimer(dlg)
        timer_previa_pontos.setSingleShot(True)
        timer_previa_pontos.setInterval(350)

        def executar_previa_pontos():
            """
            Executa efetivamente a atualização 3D dos pontos
            após o período de espera.
            """
            if tipo != "pontos":
                return

            if carregando["ativo"]:
                return

            self._config_3d_padrao[tipo] = copy.deepcopy(
                padrao_rascunho)

            self._config_3d_camadas[tipo] = copy.deepcopy(
                camadas_rascunho)

            if (self.check_sobreposicao.isChecked()
                and self._sobrepor_pontos):

                if not self._camadas_pontos_sobreposicao:
                    self._camadas_pontos_sobreposicao = self._obter_pontos_sobre_mdt()

                self._atualizar_pontos_sobreposicao()

            QCoreApplication.processEvents()

        def agendar_previa_pontos(atraso_ms=350):
            """
            Salva imediatamente o valor do controle, mas aguarda antes
            de reconstruir os objetos 3D dos pontos.
            """
            if tipo != "pontos":
                return

            if carregando["ativo"]:
                return

            salvar_item_atual()

            self._config_3d_padrao[tipo] = copy.deepcopy(
                padrao_rascunho)

            self._config_3d_camadas[tipo] = copy.deepcopy(
                camadas_rascunho)

            timer_previa_pontos.stop()
            timer_previa_pontos.setInterval(
                int(atraso_ms))
            timer_previa_pontos.start()

        def aplicar_previa_pontos():
            agendar_previa_pontos(100)

        def finalizar_previa_pontos_pendente():
            """
            Executa imediatamente uma atualização ainda pendente.
            """
            if tipo != "pontos":
                return

            if timer_previa_pontos.isActive():
                timer_previa_pontos.stop()

            salvar_item_atual()

            self._config_3d_padrao[tipo] = copy.deepcopy(
                padrao_rascunho)

            self._config_3d_camadas[tipo] = copy.deepcopy(
                camadas_rascunho)

            executar_previa_pontos()

        timer_previa_pontos.timeout.connect(executar_previa_pontos)

        def carregar_item(indice):
            carregando["ativo"] = True

            try:
                layer_id = combo_camada.itemData(indice)
                self._ultima_camada_config_3d[tipo] = layer_id

                if layer_id is None:
                    preencher_campos_rotulo(None)
                    definir_valores_controles(padrao_rascunho)
                    habilitar_controles(True)
                #
                else:
                    if layer_id in camadas_rascunho:
                        config = copy.deepcopy(camadas_rascunho[layer_id])

                    else:
                        config = copy.deepcopy(padrao_rascunho)

                        # Raster ainda sem configuração individual:
                        # usa automaticamente o modo mais adequado.
                        if tipo == "raster":
                            layer = obter_layer_por_id(layer_id)

                            config["modo"] = (self._modo_inicial_raster_3d(layer))

                    preencher_campos_rotulo(layer_id, config.get("campo_rotulo"))

                    definir_valores_controles(config)

                    habilitar_controles(True)

                indice_anterior["valor"] = indice

            finally:
                carregando["ativo"] = False

            if tipo == "raster":
                atualizar_controles_raster()

            if tipo == "linhas":
                atualizar_controles_rotulo_linha()

            if tipo == "poligonos":
                atualizar_controles_preenchimento_poligono()
                atualizar_controles_rotulo_poligono()

            if tipo == "pontos":
                atualizar_controles_haste_ponto()
                atualizar_controles_rotulo_ponto()

            atualizar_estado_botao_restaurar()

        def restaurar_configuracao_padrao():
            layer_id = combo_camada.currentData()

            if layer_id is None:
                return

            # Remove a configuração individual da camada.
            # A camada volta a herdar a configuração padrão.
            camadas_rascunho.pop(layer_id, None)

            # Recarrega os controles usando a configuração padrão.
            carregar_item(combo_camada.currentIndex())

            self._config_3d_padrao[tipo] = copy.deepcopy(padrao_rascunho)

            self._config_3d_camadas[tipo] = copy.deepcopy(camadas_rascunho)

            if tipo == "raster":
                self._invalidar_cache_raster_sobreposto_3d()

                if (self.check_sobreposicao.isChecked()
                    and self._sobrepor_rasters):

                    self._atualizar_sobreposicoes()

            if (tipo == "linhas"
                and self.check_sobreposicao.isChecked()
                and self._sobrepor_linhas):

                self._camadas_linhas_sobreposicao = (self._obter_linhas_sobre_mdt())

                self._atualizar_linhas_sobreposicao()

            if (tipo == "poligonos"
                and self.check_sobreposicao.isChecked()
                and self._sobrepor_poligonos):

                self._camadas_poligonos_sobreposicao = (self._obter_poligonos_sobre_mdt())

                self._atualizar_poligonos_sobreposicao()

            if (tipo == "pontos"
                and self.check_sobreposicao.isChecked()
                and self._sobrepor_pontos):

                self._camadas_pontos_sobreposicao = (self._obter_pontos_sobre_mdt())

                self._atualizar_pontos_sobreposicao()

            atualizar_estado_botao_restaurar()
            atualizar_marcas_camadas()

            QCoreApplication.processEvents()

        def aplicar_todas():
            salvar_item_atual()

            layer_id_origem = combo_camada.currentData()

            # Configuração padrão selecionada:
            # todas as camadas voltam a herdar diretamente o padrão.
            if layer_id_origem is None:
                camadas_rascunho.clear()

            else:
                config_origem = obter_valores_controles()
                campo_origem = config_origem.get("campo_rotulo")

                for layer in camadas:
                    config = copy.deepcopy(config_origem)

                    if tipo == "raster":
                        if self._raster_e_servico_online(layer):
                            config["modo"] = "sobreposicao"
                            config["habilitar_diferenca"] = False

                        elif not self._raster_pode_ter_diferenca_3d(layer):
                            config["modo"] = "sobreposicao"
                            config["habilitar_diferenca"] = False

                        elif bool(config.get("habilitar_diferenca", False)):
                            config["modo"] = "superficie_3d"

                    if tipo in ("linhas", "poligonos", "pontos"):
                        nomes_campos = {field.name()
                            for field in layer.fields()}

                        if (campo_origem
                            and campo_origem in nomes_campos):

                            config["campo_rotulo"] = campo_origem

                        else:
                            config_anterior = (camadas_rascunho.get(layer.id(), {}))

                            campo_anterior = (config_anterior.get("campo_rotulo"))

                            if (campo_anterior
                                and campo_anterior in nomes_campos):

                                config["campo_rotulo"] = (campo_anterior)

                            else:
                                config["campo_rotulo"] = None

                    camadas_rascunho[layer.id()] = config

            self._config_3d_padrao[tipo] = copy.deepcopy(padrao_rascunho)

            self._config_3d_camadas[tipo] = copy.deepcopy(camadas_rascunho)

            carregar_item(combo_camada.currentIndex())

            if tipo == "raster":
                aplicar_previa_raster()

            if tipo == "linhas":
                aplicar_previa_linhas()

            if tipo == "poligonos":
                aplicar_previa_poligonos()

            if tipo == "pontos":
                aplicar_previa_pontos()

            atualizar_estado_botao_restaurar()

        def aplicar_previa_cores_diferenca():
            if tipo != "raster":
                return

            if carregando["ativo"]:
                return

            salvar_item_atual()

            self._config_3d_padrao[tipo] = copy.deepcopy(padrao_rascunho)

            self._config_3d_camadas[tipo] = copy.deepcopy(camadas_rascunho)

            self._invalidar_cache_raster_sobreposto_3d()
            self._invalidar_cache_malhas_qualidade()

            if self.mesh_item is not None:
                self._atualizar_geometria()

        def salvar_estado_diferenca():
            """
            Salva a opção de diferença e reaplica a prévia.

            Quando a diferença é ativada:
            - força Superfície 3D.

            Quando é desativada:
            - desliga também as cores de corte/aterro.
            """
            if tipo != "raster":
                return

            if carregando["ativo"]:
                return

            check_diferenca = controles.get("habilitar_diferenca")

            check_cores_diferenca = controles.get("mostrar_cores_diferenca")

            combo_modo = controles.get("modo")

            if check_diferenca is None:
                return

            if check_diferenca.isChecked():
                if combo_modo is not None:
                    indice = combo_modo.findData("superficie_3d")

                    if indice >= 0:
                        combo_modo.blockSignals(True)
                        combo_modo.setCurrentIndex(indice)
                        combo_modo.blockSignals(False)

            else:
                if check_cores_diferenca is not None:
                    check_cores_diferenca.blockSignals(True)
                    check_cores_diferenca.setChecked(False)
                    check_cores_diferenca.blockSignals(False)

            aplicar_previa_raster()
            atualizar_controles_raster()

        if tipo == "raster":
            controles["modo"].currentIndexChanged.connect(atualizar_controles_raster)
            controles["modo"].currentIndexChanged.connect(aplicar_previa_raster)

            controles["habilitar_diferenca"].toggled.connect(salvar_estado_diferenca)
            controles["mostrar_cores_diferenca"].toggled.connect(aplicar_previa_cores_diferenca)

            controles["expansao_lateral"].valueChanged.connect(lambda _valor:
                    agendar_previa_expansao_raster())

            controles["opacidade"].valueChanged.connect(lambda _valor:
                    agendar_previa_opacidade_raster())
            controles["qualidade_textura"].currentIndexChanged.connect(aplicar_previa_raster)

        if tipo == "linhas":
            controles["altura"].valueChanged.connect(lambda: agendar_previa_linhas(450))
            controles["espessura"].valueChanged.connect(lambda: agendar_previa_linhas(350))
            controles["opacidade"].valueChanged.connect(lambda: agendar_previa_linhas(350))
            controles["parede"].toggled.connect(lambda: agendar_previa_linhas(100))
            controles["opacidade_parede"].valueChanged.connect(lambda: agendar_previa_linhas(350))
            controles["rotulo"].toggled.connect(lambda: agendar_previa_linhas(100))
            controles["ocultar_rotulo_encoberto"].toggled.connect(aplicar_previa_oclusao_rotulo)
            controles["altura_rotulo"].valueChanged.connect(lambda: agendar_previa_linhas(450))
            controles["tamanho_rotulo"].valueChanged.connect(lambda: agendar_previa_linhas(350))

            if combo_campo_rotulo is not None:
                combo_campo_rotulo.currentIndexChanged.connect(
                    lambda: agendar_previa_linhas(100))

            def atualizar_controles_rotulo_linha():
                habilitar = (controles["rotulo"].isEnabled()
                    and controles["rotulo"].isChecked())

                controles["ocultar_rotulo_encoberto"].setEnabled(habilitar)
                controles["altura_rotulo"].setEnabled(habilitar)
                controles["tamanho_rotulo"].setEnabled(habilitar)

                if combo_campo_rotulo is not None:
                    combo_campo_rotulo.setEnabled(habilitar)

            controles["rotulo"].toggled.connect(
                atualizar_controles_rotulo_linha)

        if tipo == "poligonos":
            controles["altura"].valueChanged.connect(aplicar_previa_altura_poligonos)
            controles["caixa"].toggled.connect(aplicar_previa_poligonos)

            controles["preenchimento"].toggled.connect(aplicar_previa_poligonos)
            controles["modo_preenchimento"].currentIndexChanged.connect(aplicar_previa_poligonos)
            controles["opacidade"].valueChanged.connect(aplicar_previa_numerica_poligonos)

            controles["contorno"].toggled.connect(aplicar_previa_poligonos)
            controles["espessura_contorno"].valueChanged.connect(aplicar_previa_numerica_poligonos)

            controles["rotulo"].toggled.connect(aplicar_previa_poligonos)
            controles["ocultar_rotulo_encoberto"].toggled.connect(aplicar_previa_oclusao_rotulo)
            controles["altura_rotulo"].valueChanged.connect(aplicar_previa_poligonos)
            controles["tamanho_rotulo"].valueChanged.connect(aplicar_previa_poligonos)

            if combo_campo_rotulo is not None:
                combo_campo_rotulo.currentIndexChanged.connect(aplicar_previa_poligonos)

            def atualizar_controles_rotulo_poligono():
                habilitar = (controles["rotulo"].isEnabled()
                    and controles["rotulo"].isChecked())

                controles["ocultar_rotulo_encoberto"].setEnabled(habilitar)
                controles["altura_rotulo"].setEnabled(habilitar)
                controles["tamanho_rotulo"].setEnabled(habilitar)

                if combo_campo_rotulo is not None:
                    combo_campo_rotulo.setEnabled(habilitar)

            def atualizar_controles_preenchimento_poligono():
                habilitar = (
                    controles["preenchimento"].isEnabled()
                    and controles["preenchimento"].isChecked())

                controles["modo_preenchimento"].setEnabled(
                    habilitar)

            controles["preenchimento"].toggled.connect(
                atualizar_controles_preenchimento_poligono)

            controles["rotulo"].toggled.connect(atualizar_controles_rotulo_poligono)

        if tipo == "pontos":
            controles["altura"].valueChanged.connect(lambda: agendar_previa_pontos(450))

            controles["tamanho"].valueChanged.connect(lambda: agendar_previa_pontos(350))

            controles["haste"].toggled.connect(lambda: agendar_previa_pontos(100))

            controles["altura_haste"].valueChanged.connect(lambda: agendar_previa_pontos(450))

            controles["espessura_haste"].valueChanged.connect(lambda: agendar_previa_pontos(350))

            controles["rotulo"].toggled.connect(lambda: agendar_previa_pontos(100))

            controles["ocultar_rotulo_encoberto"].toggled.connect(aplicar_previa_oclusao_rotulo)

            controles["altura_rotulo"].valueChanged.connect(lambda: agendar_previa_pontos(450))

            controles["tamanho_rotulo"].valueChanged.connect(lambda: agendar_previa_pontos(350))

            if combo_campo_rotulo is not None:
                combo_campo_rotulo.currentIndexChanged.connect(
                    lambda: agendar_previa_pontos(100))

            def atualizar_controles_haste_ponto():
                habilitar = (controles["haste"].isEnabled()
                    and controles["haste"].isChecked())

                controles["altura_haste"].setEnabled(habilitar)
                controles["espessura_haste"].setEnabled(habilitar)

            def atualizar_controles_rotulo_ponto():
                habilitar = (controles["rotulo"].isEnabled()
                    and controles["rotulo"].isChecked())

                controles["ocultar_rotulo_encoberto"].setEnabled(habilitar)
                controles["altura_rotulo"].setEnabled(habilitar)
                controles["tamanho_rotulo"].setEnabled(habilitar)

                if combo_campo_rotulo is not None:
                    combo_campo_rotulo.setEnabled(habilitar)

            controles["rotulo"].toggled.connect(
                atualizar_controles_rotulo_ponto)

            controles["haste"].toggled.connect(atualizar_controles_haste_ponto)

        combo_camada.currentIndexChanged.connect(carregar_item)
        push_aplicar_todas.clicked.connect(aplicar_todas)

        if push_restaurar_padrao is not None:
            push_restaurar_padrao.clicked.connect(restaurar_configuracao_padrao)

        # Estado inicial.
        atualizar_marcas_camadas()

        indice_inicial = 1 if combo_camada.count() > 1 else 0

        ultimo_layer_id = self._ultima_camada_config_3d.get(tipo)

        if ultimo_layer_id is not None:
            indice_encontrado = combo_camada.findData(ultimo_layer_id)

            if indice_encontrado >= 0:
                indice_inicial = indice_encontrado

        combo_camada.blockSignals(True)
        combo_camada.setCurrentIndex(indice_inicial)
        combo_camada.blockSignals(False)

        carregar_item(indice_inicial)

        # OK / Cancelar
        button_box = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel, dlg)
        button_box.setCenterButtons(True)
        button_box.accepted.connect(dlg.accept)
        button_box.rejected.connect(dlg.reject)

        layout.addWidget(button_box)

        def finalizar_dialogo(resultado):
            """
            Finaliza o diálogo não modal preservando o comportamento
            original de OK e Cancelar.
            """
            try:
                if resultado == int(
                    QDialog.DialogCode.Accepted):

                    if tipo == "linhas":
                        finalizar_previa_linhas_pendente()

                    elif tipo == "raster":
                        finalizar_previa_opacidade_raster_pendente()
                        finalizar_previa_expansao_raster_pendente()

                    else:
                        salvar_item_atual()

                        self._config_3d_padrao[tipo] = (copy.deepcopy(padrao_rascunho))
                        self._config_3d_camadas[tipo] = (copy.deepcopy(camadas_rascunho))

                    return

                if tipo == "linhas":
                    timer_previa_linhas.stop()

                if tipo == "pontos":
                    timer_previa_pontos.stop()

                if tipo == "raster":
                    timer_previa_expansao_raster.stop()
                    timer_previa_opacidade_raster.stop()

                # Cancelar ou fechar no X restaura a configuração anterior.
                self._config_3d_padrao[tipo] = padrao_original
                self._config_3d_camadas[tipo] = camadas_original

                if (tipo == "raster"
                    and self.check_sobreposicao.isChecked()
                    and self._sobrepor_rasters):

                    self._atualizar_sobreposicoes()

                if (tipo == "linhas"
                    and self.check_sobreposicao.isChecked()
                    and self._sobrepor_linhas):

                    self._camadas_linhas_sobreposicao = self._obter_linhas_sobre_mdt()
                    self._atualizar_linhas_sobreposicao()

                if (tipo == "poligonos"
                    and self.check_sobreposicao.isChecked()
                    and self._sobrepor_poligonos):

                    self._camadas_poligonos_sobreposicao = self._obter_poligonos_sobre_mdt()
                    self._atualizar_poligonos_sobreposicao()

                if (tipo == "pontos"
                    and self.check_sobreposicao.isChecked()
                    and self._sobrepor_pontos):

                    self._camadas_pontos_sobreposicao = self._obter_pontos_sobre_mdt()
                    self._atualizar_pontos_sobreposicao()

                QCoreApplication.processEvents()

            finally:
                if self._dialogos_config_sobreposicao_3d.get(tipo) is dlg:

                    self._dialogos_config_sobreposicao_3d.pop(tipo, None)

                dlg.deleteLater()

        dlg.finished.connect(finalizar_dialogo)

        self._dialogos_config_sobreposicao_3d[tipo] = dlg
        deslocamento_y = 12
        dlg_sobreposicao = self._dialogo_sobreposicao_3d

        if dlg_sobreposicao is not None:
            try:
                if dlg_sobreposicao.isVisible():
                    deslocamento_y = (dlg_sobreposicao.height() + 45)

            except RuntimeError:
                pass  # nosec B110

        self._mostrar_dialogo_auxiliar_3d(dlg, deslocamento_y)

    def _abrir_dialogo_sobreposicao(self):
        """
        Configura os tipos de sobreposição com pré-visualização em tempo real.
        Cada tipo possui um botão próprio para configurações 3D.
        """

        dlg_existente = self._dialogo_sobreposicao_3d

        if dlg_existente is not None:
            try:
                if dlg_existente.isVisible():
                    dlg_existente.show()
                    dlg_existente.raise_()
                    dlg_existente.activateWindow()
                    return

            except RuntimeError:
                self._dialogo_sobreposicao_3d = None

        estado_anterior = (self._sobrepor_rasters,
            self._sobrepor_linhas,
            self._sobrepor_poligonos,
            self._sobrepor_pontos)

        config_padrao_anterior = copy.deepcopy(self._config_3d_padrao)
        config_camadas_anterior = copy.deepcopy(self._config_3d_camadas)

        dlg = QDialog(self)
        dlg.setWindowTitle(self.tr("Configurar Sobreposições"))
        dlg.setMinimumWidth(300)

        layout = QVBoxLayout(dlg)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)

        frame = QFrame(dlg)
        frame.setFrameShape(QFrame.Shape.Box)
        frame.setFrameShadow(QFrame.Shadow.Sunken)
        frame.setLineWidth(1)

        frame_layout = QVBoxLayout(frame)
        frame_layout.setContentsMargins(10, 10, 10, 10)
        frame_layout.setSpacing(6)

        label = QLabel(self.tr("Tipos de camadas exibidos sobre o MDT:"), frame)
        frame_layout.addWidget(label)

        check_raster = QCheckBox(self.tr("Raster"), frame)
        check_linhas = QCheckBox(self.tr("Linhas"), frame)
        check_poligonos = QCheckBox(self.tr("Polígonos"), frame)
        check_pontos = QCheckBox(self.tr("Pontos"), frame)

        check_raster.setChecked(self._sobrepor_rasters)
        check_linhas.setChecked(self._sobrepor_linhas)
        check_poligonos.setChecked(self._sobrepor_poligonos)
        check_pontos.setChecked(self._sobrepor_pontos)

        push_raster = QPushButton("⚙", frame)
        push_linhas = QPushButton("⚙", frame)
        push_poligonos = QPushButton("⚙", frame)
        push_pontos = QPushButton("⚙", frame)

        for botao in (push_raster, push_linhas, push_poligonos, push_pontos):
            botao.setStyleSheet("font-size: 18px;")
            botao.setFixedSize(20, 20)

        for botao in (push_raster, push_linhas, push_poligonos, push_pontos):
            botao.setFixedWidth(34)

        push_raster.setToolTip(self.tr("Configurar aparência 3D dos rasters"))
        push_linhas.setToolTip(self.tr("Configurar aparência 3D das linhas"))
        push_poligonos.setToolTip(self.tr("Configurar aparência 3D dos polígonos"))
        push_pontos.setToolTip(self.tr("Configurar aparência 3D dos pontos"))

        def adicionar_linha(check, botao):
            linha_layout = QHBoxLayout()
            linha_layout.setContentsMargins(0, 0, 0, 0)
            linha_layout.setSpacing(6)
            linha_layout.addWidget(check)
            linha_layout.addStretch()
            linha_layout.addWidget(botao)
            frame_layout.addLayout(linha_layout)

        adicionar_linha(check_raster, push_raster)
        adicionar_linha(check_linhas, push_linhas)
        adicionar_linha(check_poligonos, push_poligonos)
        adicionar_linha(check_pontos, push_pontos)

        layout.addWidget(frame)

        aviso = QLabel(self.tr("As alterações de visibilidade são exibidas imediatamente. Use a engrenagem para configurar individualmente cada tipo de camada."), dlg)

        aviso.setWordWrap(True)
        layout.addWidget(aviso)

        def atualizar_estado_botoes():
            push_raster.setEnabled(check_raster.isChecked())
            push_linhas.setEnabled(check_linhas.isChecked())
            push_poligonos.setEnabled(check_poligonos.isChecked())
            push_pontos.setEnabled(check_pontos.isChecked())

        def aplicar_previa_raster(marcado):
            self._sobrepor_rasters = bool(marcado)

            atualizar_estado_botoes()

            if not self.check_sobreposicao.isChecked():
                return

            raster_principal_estava_com_textura = (
                bool(self._camadas_raster_sobreposicao)
                and self._cores_imagem_sobreposicao is not None)

            self._remover_mdts_secundarios_3d()

            self._camadas_raster_sobreposicao = []
            self._camadas_mdt_secundario_3d = []
            self._cores_imagem_sobreposicao = None

            if self._sobrepor_rasters:
                camadas_raster = self._obter_rasters_sobre_mdt()

                camadas_sobreposicao, camadas_superficie_3d = (
                    self._separar_rasters_por_modo_3d(camadas_raster))

                self._camadas_raster_sobreposicao = list(camadas_sobreposicao)

                self._camadas_mdt_secundario_3d = list(camadas_superficie_3d)

                if self._camadas_raster_sobreposicao:
                    try:
                        self._cores_imagem_sobreposicao = (
                            self._renderizar_rasters_sobre_mdt(
                                self._camadas_raster_sobreposicao))

                    except Exception:
                        self._cores_imagem_sobreposicao = None

            else:
                self._remover_expansao_raster()
                self._remover_mdts_secundarios_3d()

            raster_ativo = (self._sobrepor_rasters
                and bool(self._camadas_raster_sobreposicao)
                and self._cores_imagem_sobreposicao is not None)

            self._atualizar_estado_controles_cores(raster_ativo)

            if (raster_ativo
                or raster_principal_estava_com_textura):

                self._atualizar_geometria()

            else:
                if (self._sobrepor_rasters
                    and self._camadas_mdt_secundario_3d):

                    self._atualizar_mdts_secundarios_3d()

                self.view.update()

            self._atualizar_expansao_raster()

            QCoreApplication.processEvents()

        def aplicar_previa_linhas(marcado):
            self._sobrepor_linhas = bool(marcado)

            atualizar_estado_botoes()

            if not self.check_sobreposicao.isChecked():
                return

            if self._sobrepor_linhas:
                self._camadas_linhas_sobreposicao = self._obter_linhas_sobre_mdt()
            else:
                self._camadas_linhas_sobreposicao = []

            self._atualizar_linhas_sobreposicao(usar_cache=True)

            QCoreApplication.processEvents()

        def aplicar_previa_poligonos(marcado):
            self._sobrepor_poligonos = bool(marcado)

            atualizar_estado_botoes()

            if not self.check_sobreposicao.isChecked():
                return

            if self._sobrepor_poligonos:
                self._camadas_poligonos_sobreposicao = self._obter_poligonos_sobre_mdt()
            else:
                self._camadas_poligonos_sobreposicao = []

            self._atualizar_poligonos_sobreposicao(usar_cache=True)

            QCoreApplication.processEvents()

        def aplicar_previa_pontos(marcado):
            self._sobrepor_pontos = bool(marcado)

            atualizar_estado_botoes()

            if not self.check_sobreposicao.isChecked():
                return

            if self._sobrepor_pontos:
                self._camadas_pontos_sobreposicao = self._obter_pontos_sobre_mdt()
            else:
                self._camadas_pontos_sobreposicao = []

            self._atualizar_pontos_sobreposicao(usar_cache=True)

            QCoreApplication.processEvents()

        check_raster.toggled.connect(aplicar_previa_raster)
        check_linhas.toggled.connect(aplicar_previa_linhas)
        check_poligonos.toggled.connect(aplicar_previa_poligonos)
        check_pontos.toggled.connect(aplicar_previa_pontos)

        push_raster.clicked.connect(lambda: self._abrir_configuracao_sobreposicao_tipo("raster"))
        push_linhas.clicked.connect(lambda: self._abrir_configuracao_sobreposicao_tipo("linhas"))
        push_poligonos.clicked.connect(lambda: self._abrir_configuracao_sobreposicao_tipo("poligonos"))
        push_pontos.clicked.connect(lambda: self._abrir_configuracao_sobreposicao_tipo("pontos"))

        atualizar_estado_botoes()

        button_box = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel, dlg)
        button_box.setCenterButtons(True)
        button_box.accepted.connect(dlg.accept)
        button_box.rejected.connect(dlg.reject)

        layout.addWidget(button_box)

        def finalizar_dialogo_geral(resultado):
            """
            Finaliza o diálogo geral de sobreposições.
            """
            aceito = (resultado == int(QDialog.DialogCode.Accepted))

            # Fecha também eventuais janelas específicas ainda abertas.
            dialogos_tipo = list(self._dialogos_config_sobreposicao_3d.values())

            for dlg_tipo in dialogos_tipo:
                if dlg_tipo is None:
                    continue

                try:
                    if aceito:
                        dlg_tipo.accept()
                    else:
                        dlg_tipo.reject()

                except RuntimeError:
                    pass  # nosec B110

            if aceito:
                nenhum_tipo_ativo = not (
                    self._sobrepor_rasters
                    or self._sobrepor_linhas
                    or self._sobrepor_poligonos
                    or self._sobrepor_pontos)

                if (nenhum_tipo_ativo
                    and self.check_sobreposicao.isChecked()):

                    self.check_sobreposicao.setChecked(False)

            if not aceito:
                # Cancelar ou fechar no X restaura o estado anterior.
                (self._sobrepor_rasters,
                    self._sobrepor_linhas,
                    self._sobrepor_poligonos,
                    self._sobrepor_pontos) = estado_anterior

                self._config_3d_padrao = config_padrao_anterior
                self._config_3d_camadas = config_camadas_anterior

                if self.check_sobreposicao.isChecked():
                    self._atualizar_sobreposicoes()

                QCoreApplication.processEvents()

            if self._dialogo_sobreposicao_3d is dlg:
                self._dialogo_sobreposicao_3d = None

            dlg.deleteLater()

        dlg.finished.connect(finalizar_dialogo_geral)

        self._dialogo_sobreposicao_3d = dlg
        self._mostrar_dialogo_auxiliar_3d(dlg, 12)

    def _camadas_visiveis_ordem_qgis(self):
        """
        Retorna as camadas visíveis seguindo exatamente a ordem
        apresentada na árvore de camadas do QGIS, de cima para baixo.
        """
        if self.ui_manager is None:
            return []

        iface = getattr(self.ui_manager, "iface", None)

        if iface is None:
            return []

        ids_visiveis = {layer.id()
            for layer in iface.mapCanvas().layers()
            if layer is not None}

        camadas = []
        raiz = QgsProject.instance().layerTreeRoot()

        def percorrer_no(no):
            for filho in no.children():
                if isinstance(filho,
                    QgsLayerTreeLayer):
                    layer = filho.layer()

                    if (layer is not None
                        and layer.id() in ids_visiveis):
                        camadas.append(layer)

                elif hasattr(filho, "children"):
                    percorrer_no(filho)

        percorrer_no(raiz)

        return camadas

    def _registrar_erro_sobreposicao_3d(self, contexto, erro):
        """Registra falhas não críticas do visualizador 3D sem interromper o processamento."""
        QgsMessageLog.logMessage(f"{contexto}: {erro}", "Tempo Salvo Tools", level=Qgis.MessageLevel.Warning)

    def _obter_rasters_sobre_mdt(self):
        """
        Retorna os rasters visíveis que interceptam a extensão do MDT,
        seguindo a ordem da lista de camadas do QGIS.
        """
        if not self._sobrepor_rasters:
            return []

        crs_mdt = self.raster_layer.crs()
        extensao_mdt = self.raster_layer.extent()

        rasters = []

        for layer in self._camadas_visiveis_ordem_qgis():
            if not isinstance(layer, QgsRasterLayer):
                continue

            if not layer.isValid():
                continue

            if layer.id() == self.raster_layer.id():
                continue

            try:
                extensao_layer = layer.extent()

                if (layer.crs().isValid()
                    and crs_mdt.isValid()
                    and layer.crs() != crs_mdt):
                    transformacao = QgsCoordinateTransform(
                        layer.crs(),
                        crs_mdt,
                        QgsProject.instance())

                    extensao_layer = (transformacao.transformBoundingBox(extensao_layer))

                if extensao_layer.intersects(extensao_mdt):
                    rasters.append(layer)

            except Exception as e:
                self._registrar_erro_sobreposicao_3d(self.tr("Falha ao verificar a extensão da camada sobre o MDT"), e)
                continue

        return rasters

    def _dimensoes_textura_raster_3d(self, camadas):
        """
        Define a resolução da textura independentemente da grade do MDT.
        Mantém a proporção espacial da extensão do raster principal.
        """
        limite = 0

        for layer in camadas:
            config = self._obter_config_3d_camada("raster", layer)
            qualidade = config.get("qualidade_textura", "auto")

            if qualidade == "auto":
                if self._raster_e_servico_online(layer):
                    candidato = 4096
                else:
                    try:
                        candidato = max(
                            int(layer.width()),
                            int(layer.height()))

                        candidato = max(512, min(4096, candidato))

                    except Exception:
                        candidato = 4096

            else:
                try:
                    candidato = int(qualidade)
                except Exception:
                    candidato = 4096

            limite = max(limite, candidato)

        limite = max(512, min(8192, limite or 4096))

        extensao = self.raster_layer.extent()
        largura_real = abs(float(extensao.width()))
        altura_real = abs(float(extensao.height()))

        if largura_real <= 0.0 or altura_real <= 0.0:
            return limite, limite

        proporcao = largura_real / altura_real

        if proporcao >= 1.0:
            largura = limite
            altura = max(2, int(round(limite / proporcao)))
        else:
            altura = limite
            largura = max(2, int(round(limite * proporcao)))

        return largura, altura

    def _renderizar_camada_raster_qimage(self, layer, extensao, largura, altura):
        """
        Renderiza uma única camada raster para QImage utilizando
        a simbologia atual do QGIS.
        """
        imagem = QImage(largura, altura, QImage.Format.Format_ARGB32_Premultiplied)
        imagem.fill(QColor(0, 0, 0, 0))

        map_settings = QgsMapSettings()
        map_settings.setLayers([layer])
        map_settings.setExtent(extensao)
        map_settings.setDestinationCrs(self.raster_layer.crs())
        map_settings.setOutputSize(QSize(largura, altura))
        map_settings.setBackgroundColor(QColor(0, 0, 0, 0))
        map_settings.setTransformContext(QgsProject.instance().transformContext())

        painter = QPainter(imagem)

        try:
            job = QgsMapRendererCustomPainterJob(map_settings, painter)
            job.start()
            job.waitForFinished()
        finally:
            painter.end()

        return imagem

    def _renderizar_textura_rasters_sobre_mdt(self, camadas):
        """
        Compõe os rasters de sobreposição em uma textura
        de alta resolução independente da grade 3D.
        """
        if not camadas:
            return None

        largura, altura = self._dimensoes_textura_raster_3d(camadas)

        if largura <= 0 or altura <= 0:
            return None

        extensao = self.raster_layer.extent()

        imagem_final = QImage(
            largura,
            altura,
            QImage.Format.Format_ARGB32_Premultiplied)

        imagem_final.fill(QColor(0, 0, 0, 0))

        desenhou = False

        # A lista chega de cima para baixo.
        # As camadas inferiores são pintadas primeiro.
        for layer in reversed(camadas):
            config = self._obter_config_3d_camada( "raster", layer)

            if config.get("modo", "sobreposicao") != "sobreposicao":
                continue

            opacidade = max(0.0, min(100.0,
                    float(config.get("opacidade", 100.0)))) / 100.0

            if opacidade <= 0.0:
                continue

            imagem_layer = self._renderizar_camada_raster_qimage(
                layer,
                extensao,
                largura,
                altura)

            painter = QPainter(imagem_final)

            try:
                painter.setOpacity(opacidade)
                painter.drawImage(0, 0, imagem_layer)
            finally:
                painter.end()

            desenhou = True

        if not desenhou:
            return None

        return imagem_final

    def _renderizar_rasters_sobre_mdt(self, camadas):
        """
        Renderiza os rasters em alta resolução e mantém
        temporariamente o caminho antigo por cores de vértices.
        """
        largura_grade = int(self._grade_x)
        altura_grade = int(self._grade_y)

        if largura_grade <= 0 or altura_grade <= 0:
            raise RuntimeError(self.tr("A grade 3D do MDT é inválida."))

        self._imagem_textura_sobreposicao = None

        imagem_textura = self._renderizar_textura_rasters_sobre_mdt(camadas)

        if imagem_textura is None:
            return None

        # Guarda a imagem original em alta resolução.
        self._imagem_textura_sobreposicao = imagem_textura

        # Fallback atual:
        # reduz apenas uma cópia para continuar alimentando vertexColors.
        imagem_grade = imagem_textura.scaled(
            largura_grade,
            altura_grade,
            Qt.AspectRatioMode.IgnoreAspectRatio,
            Qt.TransformationMode.SmoothTransformation)

        imagem_grade = imagem_grade.convertToFormat(
            QImage.Format.Format_RGBA8888)

        ponteiro = imagem_grade.bits()
        ponteiro.setsize(imagem_grade.sizeInBytes())

        rgba = np.array(
            ponteiro,
            dtype=np.uint8).reshape(
                altura_grade,
                largura_grade,
                4).copy()

        rgba = rgba.reshape(-1, 4).astype(np.float32) / 255.0

        alpha = rgba[:, 3:4]

        if not np.any(alpha > 0.001):
            self._imagem_textura_sobreposicao = None
            return None

        cores_base = self._gerar_cores_vertices_suaves()

        if rgba.shape[0] != cores_base.shape[0]:
            raise RuntimeError(self.tr("A imagem renderizada não coincide com a grade 3D do MDT."))

        cores_finais = cores_base.copy()

        cores_finais[:, :3] = (
            rgba[:, :3] * alpha
            + cores_base[:, :3] * (1.0 - alpha))

        cores_finais[:, 3] = cores_base[:, 3]

        return cores_finais.astype(np.float32)

    def _raster_pode_ser_sobreposicao_imagem(self, layer):
        """
        Define se o raster pode ser utilizado como imagem sobreposta
        à superfície do MDT principal.

        Regras:
        - serviços online podem ser sobreposição;
        - rasters locais RGB/RGBA podem ser sobreposição;
        - rasters locais com menos de 3 bandas são tratados como
          superfícies de elevação.
        """
        if layer is None:
            return False

        if self._raster_e_servico_online(layer):
            return True

        try:
            return int(layer.bandCount()) >= 3
        except Exception:
            return False

    def _raster_e_servico_online(self, layer):
        """
        Identifica rasters provenientes de serviços online utilizados
        normalmente como mapas-base e imagens de satélite.
        """
        if layer is None or not isinstance(layer, QgsRasterLayer):
            return False

        try:
            provider = layer.providerType().lower()
        except Exception:
            provider = ""

        if provider in (
            "wms",
            "xyz",
            "arcgismapserver"):
            return True

        try:
            source = layer.source().lower()
        except Exception:
            source = ""

        if ("type=xyz" in source
            or "service=wms" in source
            or "arcgismapserver" in source):
            return True

        return False

    def _raster_pode_ter_diferenca_3d(self, layer):
        """
        A diferença entre MDTs só é permitida para rasters locais
        de elevação.
        """
        if layer is None:
            return False

        if self._raster_e_servico_online(layer):
            return False

        try:
            return int(layer.bandCount()) < 3
        except Exception:
            return False

    def _modo_inicial_raster_3d(self, layer):
        """
        Define o modo inicial de um raster que ainda não possui
        configuração individual no visualizador 3D.

        Regras:
        - serviços online -> Sobreposição;
        - raster local com uma banda -> Superfície 3D;
        - raster local multibanda -> Sobreposição.
        """
        if layer is None:
            return "sobreposicao"

        if self._raster_e_servico_online(layer):
            return "sobreposicao"

        try:
            if int(layer.bandCount()) == 1:
                return "superficie_3d"
        except Exception:
            pass  # nosec B110

        return "sobreposicao"

    def _obter_config_3d_camada(self, tipo, layer):
        """
        Retorna a configuração efetiva da camada.

        Para rasters ainda sem configuração individual:
        - serviço online -> Sobreposição;
        - raster local de uma banda -> Superfície 3D;
        - raster local multibanda -> Sobreposição.
        """
        config = copy.deepcopy(self._config_3d_padrao.get(tipo, {}))

        if layer is not None:
            config_individual = (self._config_3d_camadas.get(tipo, {}).get(layer.id()))

            if config_individual:
                config.update(config_individual)

            elif tipo == "raster":
                config["modo"] = (self._modo_inicial_raster_3d(layer))

        if (tipo == "raster"
            and layer is not None):

            if self._raster_e_servico_online(layer):
                config["modo"] = "sobreposicao"
                config["habilitar_diferenca"] = False
                config["mostrar_cores_diferenca"] = False

            elif not self._raster_pode_ter_diferenca_3d(layer):
                config["modo"] = "sobreposicao"
                config["habilitar_diferenca"] = False
                config["mostrar_cores_diferenca"] = False

            elif bool(
                config.get("habilitar_diferenca", False)):
                config["modo"] = "superficie_3d"

            else:
                config["mostrar_cores_diferenca"] = False

        return config

    def _separar_rasters_por_modo_3d(self, camadas):
        """
        Separa os rasters conforme o modo escolhido pelo usuário.

        Regras:
        - serviços online permanecem sempre como sobreposição;
        - rasters locais podem ser Sobreposição ou Superfície 3D.
        """
        camadas_sobreposicao = []
        camadas_superficie_3d = []

        for layer in camadas:
            if layer is None:
                continue

            config = self._obter_config_3d_camada("raster", layer)

            modo = str(config.get("modo", self._modo_inicial_raster_3d(layer)))

            if self._raster_e_servico_online(layer):
                camadas_sobreposicao.append(layer)

            elif modo == "superficie_3d":
                camadas_superficie_3d.append(layer)

            else:
                camadas_sobreposicao.append(layer)

        return (camadas_sobreposicao, camadas_superficie_3d)

    def _chave_cache_geometria_mdt_secundario_3d(self, layer):
        """
        Retorna uma chave para reaproveitar a geometria do MDT secundário.
        """
        limite = int(getattr(self, "_limite_grade_aplicado", self.LIMITE_GRADE))

        crs = (layer.crs().authid()
            if layer.crs().isValid()
            else "")

        return (layer.id(), limite, crs, layer.source())

    def _preparar_geometria_mdt_secundario_3d(self, layer):
        """
        Lê um raster local de elevação e cria sua geometria base
        no mesmo sistema espacial utilizado pelo MDT principal.

        O MDT secundário usa:
        - o próprio Z;
        - o X/Y do próprio raster;
        - o centro X/Y/Z do MDT principal.
        """
        chave = self._chave_cache_geometria_mdt_secundario_3d(layer)
        cache = self._cache_geometria_mdt_secundario_3d.get(chave)

        if cache is not None:
            return cache

        dataset, pasta_temporaria = (self._abrir_raster_3d_com_gdal(layer))

        if dataset is None:
            raise RuntimeError(self.tr("Não foi possível abrir o MDT secundário '{nome}'.").format(nome=layer.name()))

        band = dataset.GetRasterBand(1)

        if band is None:
            dataset = None

            raise RuntimeError(self.tr("O MDT secundário '{nome}' não possui banda de elevação válida.").format(nome=layer.name()))

        largura = int(dataset.RasterXSize)
        altura = int(dataset.RasterYSize)

        limite_grade = int(getattr(self, "_limite_grade_aplicado", self.LIMITE_GRADE))

        passo = max(1, int(math.ceil(max(largura, altura) / limite_grade)))

        grade_x = max(2, int(math.ceil(largura / passo)))
        grade_y = max(2, int(math.ceil(altura / passo)))

        dados = band.ReadAsArray(0, 0, largura, altura, grade_x, grade_y)

        if dados is None:
            dataset = None

            raise RuntimeError(self.tr("Não foi possível ler as cotas do MDT secundário '{nome}'.").format(nome=layer.name()))

        dados = np.asarray(dados, dtype=np.float64)
        nodata = band.GetNoDataValue()

        validos = np.isfinite(dados)

        if (nodata is not None
            and np.isfinite(nodata)):

            validos &= ~np.isclose(dados, float(nodata), rtol=0.0, atol=max(1e-12, abs(float(nodata)) * 1e-12))

        if not np.any(validos):
            dataset = None

            raise RuntimeError(self.tr("O MDT secundário '{nome}' não possui cotas válidas.").format(nome=layer.name()))

        gt = dataset.GetGeoTransform(can_return_null=True)

        if gt is None:
            extent = layer.extent()

            gt = (extent.xMinimum(), extent.width() / largura, 0.0, extent.yMaximum(), 0.0, -extent.height() / altura)

        dataset = None

        if pasta_temporaria is not None:
            shutil.rmtree(pasta_temporaria, ignore_errors=True)

        # Distribui os vértices até as bordas reais do raster.
        # Assim MDTs adjacentes não ficam recuados meia célula
        # para dentro da própria extensão.
        colunas_pixel = np.linspace(0.0, float(largura), grade_x, dtype=np.float64)

        linhas_pixel = np.linspace(0.0, float(altura), grade_y, dtype=np.float64)

        col_grid, row_grid = np.meshgrid(colunas_pixel, linhas_pixel)

        x_real = (gt[0] + col_grid * gt[1] + row_grid * gt[2])
        y_real = (gt[3] + col_grid * gt[4] + row_grid * gt[5])

        # Se necessário, transforma as coordenadas para o SRC do MDT principal.
        if (layer.crs().isValid()
            and self.raster_layer.crs().isValid()
            and layer.crs() != self.raster_layer.crs()):

            src_srs = osr.SpatialReference()
            dst_srs = osr.SpatialReference()

            src_srs.ImportFromWkt(layer.crs().toWkt())
            dst_srs.ImportFromWkt(self.raster_layer.crs().toWkt())

            if hasattr(osr, "OAMS_TRADITIONAL_GIS_ORDER"):

                src_srs.SetAxisMappingStrategy(osr.OAMS_TRADITIONAL_GIS_ORDER)

                dst_srs.SetAxisMappingStrategy(osr.OAMS_TRADITIONAL_GIS_ORDER)

            transformacao = osr.CoordinateTransformation(src_srs, dst_srs)

            pontos = np.column_stack((x_real.ravel(), y_real.ravel()))

            transformados = np.asarray(transformacao.TransformPoints(pontos.tolist()), dtype=np.float64)

            x_real = transformados[:, 0].reshape(grade_y, grade_x)
            y_real = transformados[:, 1].reshape(grade_y, grade_x)

        validos &= (np.isfinite(x_real)
            & np.isfinite(y_real))

        if not np.any(validos):
            dataset = None

            raise RuntimeError(self.tr("Não foi possível posicionar o MDT secundário '{nome}' no SRC do MDT principal.").format(nome=layer.name()))

        # IMPORTANTE:
        # usa o centro Z DO MDT PRINCIPAL.
        z_seguro = np.where(validos, dados, self._z_centro)

        vertices = np.column_stack((
            (x_real - self._x_centro).ravel(),
            (y_real - self._y_centro).ravel(),
            (z_seguro - self._z_centro).ravel())).astype( np.float32)

        indices = np.arange(grade_y * grade_x, dtype=np.int32).reshape(grade_y, grade_x)

        celulas_validas = (
            validos[:-1, :-1]
            & validos[:-1, 1:]
            & validos[1:, :-1]
            & validos[1:, 1:])

        a = indices[:-1, :-1][celulas_validas]
        b = indices[:-1, 1:][celulas_validas]
        c = indices[1:, :-1][celulas_validas]
        d = indices[1:, 1:][celulas_validas]

        faces_1 = np.column_stack((a, b, c))
        faces_2 = np.column_stack((b, d, c))
        faces = np.vstack((faces_1, faces_2)).astype(np.uint32)

        dataset = None

        if faces.size == 0:
            raise RuntimeError(self.tr("Não foi possível criar a superfície 3D do MDT secundário '{nome}'.").format(nome=layer.name()))

        cache = {
            "vertices": vertices,
            "faces": faces,
            "grade_x": grade_x,
            "grade_y": grade_y,
            "validos": validos.ravel()}

        self._cache_geometria_mdt_secundario_3d[chave] = cache

        return cache

    def _remover_mdts_secundarios_3d(self):
        """
        Remove apenas os objetos OpenGL dos MDTs secundários.
        O cache da geometria permanece disponível.
        """
        for item in list(self._itens_mdt_secundario_3d):

            if item is None:
                continue

            try:
                if item in self.view.items:
                    self.view.removeItem(item)

            except Exception:
                pass  # nosec B110

        self._itens_mdt_secundario_3d = []

    def _gerar_cores_qgis_mdt_secundario_3d(self, layer, geometria, opacidade):
        """
        Renderiza a própria simbologia QGIS do MDT secundário
        na mesma resolução utilizada pela malha 3D.

        Retorna uma cor RGBA para cada vértice da superfície.
        """
        grade_x = int(geometria["grade_x"])
        grade_y = int(geometria["grade_y"])

        if grade_x <= 0 or grade_y <= 0:
            return None

        imagem = QImage(grade_x, grade_y,
            QImage.Format.Format_ARGB32_Premultiplied)

        imagem.fill(QColor(0, 0, 0, 0))

        map_settings = QgsMapSettings()
        map_settings.setLayers([layer])
        map_settings.setExtent(layer.extent())

        if layer.crs().isValid():
            map_settings.setDestinationCrs(layer.crs())

        map_settings.setOutputSize(QSize(grade_x, grade_y))
        map_settings.setBackgroundColor(QColor(0, 0, 0, 0))
        map_settings.setTransformContext(QgsProject.instance().transformContext())

        painter = QPainter(imagem)

        try:
            job = QgsMapRendererCustomPainterJob(map_settings, painter)

            job.start()
            job.waitForFinished()

        finally:
            painter.end()

        imagem = imagem.convertToFormat(
            QImage.Format.Format_RGBA8888)

        ponteiro = imagem.bits()
        ponteiro.setsize(imagem.sizeInBytes())

        rgba = np.array(ponteiro,
            dtype=np.uint8).reshape(
                grade_y,
                grade_x,
                4).copy()

        rgba = rgba.reshape(-1, 4).astype(np.float32) / 255.0

        # Aplica a opacidade definida no diálogo do visualizador.
        rgba[:, 3] *= float(opacidade)

        # Mantém NoData completamente transparente.
        validos = geometria.get("validos")

        if validos is not None:
            validos = np.asarray(validos, dtype=bool)

            if validos.size == rgba.shape[0]:
                rgba[~validos, 3] = 0.0

        return rgba.astype(np.float32)

    def _atualizar_mdts_secundarios_3d(self):
        """
        Reconstrói as superfícies 3D independentes.

        Quando 'Habilitar diferença entre MDTs' estiver marcado,
        aquela camada não gera um GLMeshItem separado.
        Ela passa a deformar diretamente o MDT principal.
        """
        self._remover_mdts_secundarios_3d()

        if not self.check_sobreposicao.isChecked():
            return

        if not self._sobrepor_rasters:
            return

        if not self._camadas_mdt_secundario_3d:
            return

        exagero = float(
            self.spin_exagero.value())

        for layer in self._camadas_mdt_secundario_3d:
            try:
                config = self._obter_config_3d_camada("raster", layer)

                # Diferença:
                # não cria segunda superfície.
                # O MDT principal já foi deformado.
                if bool(config.get("habilitar_diferenca", False)):

                    continue

                geometria = (self._preparar_geometria_mdt_secundario_3d(layer))

                vertices = (geometria["vertices"].copy())

                faces = geometria["faces"]

                vertices[:, 2] *= exagero

                opacidade = max(0.0, min(100.0,
                        float(config.get("opacidade", 100.0)))) / 100.0

                if opacidade <= 0.0:
                    continue

                cores_vertices = (
                    self._gerar_cores_qgis_mdt_secundario_3d(
                        layer,
                        geometria,
                        opacidade))

                if (cores_vertices is None
                    or len(cores_vertices) != len(vertices)):

                    continue

                mesh_data = gl.MeshData(
                    vertexes=vertices,
                    faces=faces,
                    vertexColors=cores_vertices)

                item = gl.GLMeshItem(
                    meshdata=mesh_data,
                    smooth=True,
                    computeNormals=False,
                    drawFaces=True,
                    drawEdges=self.check_linhas.isChecked(),
                    edgeColor=self._cor_linhas_superficie(),
                    shader=None)

                if opacidade < 0.999:
                    item.setGLOptions("translucent")
                else:
                    item.setGLOptions("opaque")

                item._tempo_salvo_layer_id = (layer.id())
                item._tempo_salvo_tipo = ("mdt_secundario")

                self.view.addItem(item)
                self._itens_mdt_secundario_3d.append(item)

            except Exception as e:
                self._registrar_erro_sobreposicao_3d(self.tr("Falha ao criar MDT secundário 3D"), e)

        self.view.update()

    def _obter_linhas_sobre_mdt(self):
        """
        Retorna as camadas vetoriais de linhas visíveis que interceptam
        a extensão do MDT, respeitando a ordem da árvore do QGIS.
        """
        if not self._sobrepor_linhas:
            return []

        crs_mdt = self.raster_layer.crs()
        extensao_mdt = self.raster_layer.extent()
        camadas = []

        for layer in self._camadas_visiveis_ordem_qgis():
            if not isinstance(layer, QgsVectorLayer):
                continue

            if not layer.isValid():
                continue

            if layer.geometryType() != Qgis.GeometryType.Line:
                continue

            if crs_mdt.isValid() and not layer.crs().isValid():
                continue

            try:
                extensao_layer = layer.extent()

                if (crs_mdt.isValid()
                    and layer.crs().isValid()
                    and layer.crs() != crs_mdt):

                    transformacao = QgsCoordinateTransform(layer.crs(), crs_mdt, QgsProject.instance())

                    extensao_layer = (transformacao.transformBoundingBox(extensao_layer))

                if extensao_layer.intersects(extensao_mdt):
                    camadas.append(layer)

            except Exception as e:
                self._registrar_erro_sobreposicao_3d(self.tr("Falha ao verificar a extensão da camada sobre o MDT"), e)
                continue

        return camadas

    def _obter_poligonos_sobre_mdt(self):
        """
        Retorna as camadas vetoriais de polígonos visíveis que interceptam
        a extensão do MDT, respeitando a ordem da árvore do QGIS.
        """
        if not self._sobrepor_poligonos:
            return []

        crs_mdt = self.raster_layer.crs()
        extensao_mdt = self.raster_layer.extent()
        camadas = []

        for layer in self._camadas_visiveis_ordem_qgis():
            if not isinstance(layer, QgsVectorLayer):
                continue

            if not layer.isValid():
                continue

            if layer.geometryType() != Qgis.GeometryType.Polygon:
                continue

            if crs_mdt.isValid() and not layer.crs().isValid():
                continue

            try:
                extensao_layer = layer.extent()

                if (crs_mdt.isValid()
                    and layer.crs().isValid()
                    and layer.crs() != crs_mdt):
                    transformacao = QgsCoordinateTransform(layer.crs(), crs_mdt, QgsProject.instance())
                    extensao_layer = transformacao.transformBoundingBox(extensao_layer)

                if extensao_layer.intersects(extensao_mdt):
                    camadas.append(layer)

            except Exception as e:
                self._registrar_erro_sobreposicao_3d(self.tr("Falha ao verificar a extensão da camada sobre o MDT"), e)
                continue

        return camadas

    def _obter_pontos_sobre_mdt(self):
        """
        Retorna as camadas vetoriais de pontos visíveis que interceptam
        a extensão do MDT, respeitando a ordem da árvore do QGIS.
        """
        if not self._sobrepor_pontos:
            return []

        crs_mdt = self.raster_layer.crs()
        extensao_mdt = self.raster_layer.extent()
        camadas = []

        for layer in self._camadas_visiveis_ordem_qgis():
            if not isinstance(layer, QgsVectorLayer):
                continue

            if not layer.isValid():
                continue

            if layer.geometryType() != Qgis.GeometryType.Point:
                continue

            if crs_mdt.isValid() and not layer.crs().isValid():
                continue

            try:
                extensao_layer = layer.extent()

                if (crs_mdt.isValid()
                    and layer.crs().isValid()
                    and layer.crs() != crs_mdt):
                    transformacao = QgsCoordinateTransform(layer.crs(), crs_mdt, QgsProject.instance())
                    extensao_layer = transformacao.transformBoundingBox(extensao_layer)

                if extensao_layer.intersects(extensao_mdt):
                    camadas.append(layer)

            except Exception as e:
                self._registrar_erro_sobreposicao_3d(self.tr("Falha ao verificar a extensão da camada sobre o MDT"), e)
                continue

        return camadas

    def _remover_expansao_raster(self):
        """
        Remove os planos texturizados utilizados pela expansão lateral.
        """
        if not self._itens_raster_expansao:
            return

        contexto_ativo = False

        try:
            self.view.makeCurrent()
            contexto_ativo = True

            for item in list(self._itens_raster_expansao):
                try:
                    cleanup = getattr(item, "cleanup", None)

                    if callable(cleanup):
                        cleanup()
                except Exception:
                    pass  # nosec B110

                try:
                    if item in self.view.items:
                        self.view.removeItem(item)
                except Exception:
                    pass  # nosec B110

        finally:
            if contexto_ativo:
                try:
                    self.view.doneCurrent()
                except Exception:
                    pass  # nosec B110

        self._itens_raster_expansao.clear()

    def _remover_pontos_sobreposicao(self):
        """
        Remove definitivamente pontos, hastes e rótulos,
        incluindo os objetos armazenados em cache.
        """
        self._invalidar_cache_pontos_3d()

    def _ocultar_pontos_cache_ativos(self):
        """
        Oculta os objetos de pontos atualmente ativos sem destruí-los.
        """
        for item in self._itens_pontos_sobreposicao:
            try:
                item.hide()
            except Exception:
                pass  # nosec B110

        for item in self._itens_hastes_pontos_sobreposicao:
            try:
                item.hide()
            except Exception:
                pass  # nosec B110

        for item in self._itens_rotulos_pontos_sobreposicao:
            try:
                item.hide()
            except Exception:
                pass  # nosec B110

        self._itens_pontos_sobreposicao = []
        self._itens_hastes_pontos_sobreposicao = []
        self._itens_rotulos_pontos_sobreposicao = []
        self._chave_cache_pontos_ativa = None

    def _chave_cache_pontos_3d(self, camadas=None):
        """
        Retorna a chave correspondente à cena atual dos pontos.
        """
        if camadas is None:
            camadas = self._camadas_pontos_sobreposicao

        limite = int(getattr(self, "_limite_grade_aplicado", self.LIMITE_GRADE))
        exagero = round(float(self.spin_exagero.value()), 6)

        ids_camadas = tuple(layer.id()
            for layer in camadas)

        return (limite, exagero, ids_camadas)

    def _ativar_cache_pontos_3d(self, camadas):
        """
        Reativa pontos, hastes e rótulos já preparados para
        a qualidade atual do terreno.
        """
        chave = self._chave_cache_pontos_3d(camadas)

        cache = self._cache_pontos_3d.get(chave)

        if cache is None:
            return False

        # Não reutiliza uma qualidade cuja configuração
        # visual ficou desatualizada.
        estilos_atuais = self._snapshot_estilo_pontos_3d(camadas)

        if cache.get("estilos") != estilos_atuais:
            return False

        if self._chave_cache_pontos_ativa == chave:
            return True

        self._ocultar_pontos_cache_ativos()

        self._itens_pontos_sobreposicao = list(cache["pontos"])
        self._itens_hastes_pontos_sobreposicao = list(cache["hastes"])
        self._itens_rotulos_pontos_sobreposicao = list(cache["rotulos"])

        for item in self._itens_pontos_sobreposicao:
            try:
                item.show()
            except Exception:
                pass  # nosec B110

        for item in self._itens_hastes_pontos_sobreposicao:
            try:
                item.show()
            except Exception:
                pass  # nosec B110

        for item in self._itens_rotulos_pontos_sobreposicao:
            try:
                item.show()
            except Exception:
                pass  # nosec B110

        self._chave_cache_pontos_ativa = chave

        return True

    def _salvar_cache_pontos_3d(self, camadas):
        """
        Guarda os objetos OpenGL recém-criados dos pontos.
        """
        chave = self._chave_cache_pontos_3d(camadas)

        self._cache_pontos_3d[chave] = {
            "pontos": list(self._itens_pontos_sobreposicao),
            "hastes": list(self._itens_hastes_pontos_sobreposicao),
            "rotulos": list(self._itens_rotulos_pontos_sobreposicao),
            "estilos": self._snapshot_estilo_pontos_3d(camadas)}

        self._chave_cache_pontos_ativa = chave

    def _invalidar_cache_pontos_3d(self):
        """
        Remove definitivamente todos os objetos armazenados
        no cache dos pontos.
        """
        itens = []

        itens.extend(self._itens_pontos_sobreposicao)
        itens.extend(self._itens_hastes_pontos_sobreposicao)
        itens.extend(self._itens_rotulos_pontos_sobreposicao)

        for cache in self._cache_pontos_3d.values():
            itens.extend(cache.get("pontos", []))
            itens.extend(cache.get("hastes", []))
            itens.extend(cache.get("rotulos", []))

        vistos = set()

        for item in itens:
            if item is None:
                continue

            identificador = id(item)

            if identificador in vistos:
                continue

            vistos.add(identificador)

            try:
                self.view.removeItem(item)
            except Exception:
                pass  # nosec B110

        self._cache_pontos_3d.clear()

        self._itens_pontos_sobreposicao = []
        self._itens_hastes_pontos_sobreposicao = []
        self._itens_rotulos_pontos_sobreposicao = []
        self._chave_cache_pontos_ativa = None

