    def _obter_indice_faces_poligono(self):
        """
        Cria um índice direto entre cada célula válida da grade do MDT
        e o par de triângulos correspondente em self._faces.

        O índice é calculado uma única vez por qualidade do terreno.
        """
        if (self._validos_grade is None
            or self._faces is None
            or self._grade_x < 2
            or self._grade_y < 2):
            return None

        limite = int(getattr(self, "_limite_grade_aplicado", self.LIMITE_GRADE))

        chave = (limite,
            int(self._grade_x),
            int(self._grade_y),
            int(len(self._faces)))

        cache = self._cache_indice_faces_poligono.get(chave)

        if cache is not None:
            return cache

        celulas_validas = (
            self._validos_grade[:-1, :-1]
            & self._validos_grade[:-1, 1:]
            & self._validos_grade[1:, :-1]
            & self._validos_grade[1:, 1:])

        mapa_faces = np.full(celulas_validas.shape, -1, dtype=np.int32)

        celulas_flat = np.flatnonzero(celulas_validas)
        quantidade = int(len(celulas_flat))

        if quantidade == 0:
            return None

        mapa_flat = mapa_faces.ravel()

        mapa_flat[celulas_flat] = np.arange(quantidade, dtype=np.int32)

        cache = {"mapa": mapa_faces, "quantidade": quantidade}
        self._cache_indice_faces_poligono[chave] = cache

        return cache

    def _intervalo_grade_bbox_poligono(self, bbox):
        """
        Converte o bounding box de um polígono em um intervalo
        conservador de células da grade 3D.
        """
        if (bbox is None
            or self._geo_transform is None
            or self._raster_largura <= 0
            or self._raster_altura <= 0):
            return None

        gt = self._geo_transform

        determinante = (gt[1] * gt[5] - gt[2] * gt[4])

        if abs(determinante) < 1e-20:
            return None

        cantos = (
            (bbox.xMinimum(), bbox.yMinimum()),
            (bbox.xMinimum(), bbox.yMaximum()),
            (bbox.xMaximum(), bbox.yMinimum()),
            (bbox.xMaximum(), bbox.yMaximum()))

        valores_x = []
        valores_y = []

        for x, y in cantos:
            dx = float(x) - gt[0]
            dy = float(y) - gt[3]

            coluna = (gt[5] * dx - gt[2] * dy) / determinante
            linha = (-gt[4] * dx + gt[1] * dy) / determinante

            gx = (coluna * self._grade_x / self._raster_largura - 0.5)
            gy = (linha * self._grade_y / self._raster_altura - 0.5)

            valores_x.append(gx)
            valores_y.append(gy)

        # Margem de uma célula para garantir que nenhum triângulo
        # tocando o limite do polígono seja descartado.
        coluna_min = max(0, int(math.floor(min(valores_x))) - 1)

        coluna_max = min(self._grade_x - 2, int(math.floor(max(valores_x))) + 1)

        linha_min = max(0, int(math.floor(min(valores_y))) - 1)

        linha_max = min(self._grade_y - 2, int(math.floor(max(valores_y))) + 1)

        if (coluna_min > coluna_max
            or linha_min > linha_max):
            return None

        return (linha_min, linha_max, coluna_min, coluna_max)

    def _indices_faces_bbox_poligono(self, bbox):
        """
        Retorna somente os índices das faces do MDT que pertencem
        às células interceptadas pelo bounding box do polígono.
        """
        cache = self._obter_indice_faces_poligono()

        if cache is None:
            return np.empty(0, dtype=np.int32)

        intervalo = self._intervalo_grade_bbox_poligono(bbox)

        if intervalo is None:
            return np.empty(0, dtype=np.int32)

        (linha_min, linha_max, coluna_min, coluna_max) = intervalo

        mapa = cache["mapa"]
        quantidade = cache["quantidade"]

        indices_base = mapa[linha_min:linha_max + 1, coluna_min:coluna_max + 1].ravel()

        indices_base = indices_base[indices_base >= 0]

        if indices_base.size == 0:
            return np.empty(0, dtype=np.int32)

        # self._faces foi criada como:
        # todas as faces_1 seguidas de todas as faces_2.
        return np.concatenate((indices_base, indices_base + quantidade)).astype(np.int32, copy=False)

    def _renderizar_expansao_rasters(self, camadas):
        """
        Cria uma continuação plana das imagens raster além da extensão
        do MDT, sem alterar nem deformar a superfície principal.
        """
        self._remover_expansao_raster()

        if not camadas:
            return

        extensao_mdt = self.raster_layer.extent()
        exagero = float(self.spin_exagero.value())

        # Plano ligeiramente abaixo do ponto mais baixo do terreno.
        amplitude_z = abs(self._z_max - self._z_min) * exagero
        folga_z = max(0.10, amplitude_z * 0.01)
        z_plano = (self._z_min - self._z_centro) * exagero - folga_z

        for ordem, layer in enumerate(reversed(camadas)):
            # Expansão lateral é exclusiva de serviços raster online.
            if not self._raster_e_servico_online(layer):
                continue

            config = self._obter_config_3d_camada("raster", layer)

            if config.get("modo", "sobreposicao") != "sobreposicao":
                continue

            expansao = max(0.0, float(config.get("expansao_lateral", 0.0)))

            if expansao <= 0.0:
                continue

            extensao = QgsRectangle(extensao_mdt)
            extensao.grow(expansao)

            proporcao = (extensao.width() / max(extensao.height(), 1e-12))

            # Resolução própria da expansão.
            # Independente da qualidade da textura aplicada ao MDT.
            limite = 8192

            if proporcao >= 1.0:
                largura = limite
                altura = max(2, int(round(limite / proporcao)))
            else:
                altura = limite
                largura = max(2, int(round(limite * proporcao)))

            imagem = self._renderizar_camada_raster_qimage(layer, extensao, largura, altura)
            imagem = imagem.convertToFormat(QImage.Format.Format_RGBA8888)

            ponteiro = imagem.bits()
            ponteiro.setsize(imagem.sizeInBytes())

            rgba = np.array(ponteiro, dtype=np.uint8).reshape(altura, largura, 4).copy()

            if not np.any(rgba[:, :, 3] > 0):
                continue

            imagem_textura = QImage(rgba.data, largura, altura,
                int(rgba.strides[0]),
                QImage.Format.Format_RGBA8888).copy()

            x_min = float(extensao.xMinimum() - self._x_centro)
            x_max = float(extensao.xMaximum() - self._x_centro)

            y_min = float(extensao.yMinimum() - self._y_centro)
            y_max = float(extensao.yMaximum() - self._y_centro)

            vertices = np.array([
                [x_min, y_min, z_plano],
                [x_max, y_min, z_plano],
                [x_max, y_max, z_plano],
                [x_min, y_max, z_plano]], dtype=np.float32)

            faces = np.array([
                [0, 1, 2],
                [0, 2, 3]], dtype=np.uint32)

            uv = np.array([
                [0.0, 0.0],
                [1.0, 0.0],
                [1.0, 1.0],
                [0.0, 1.0]], dtype=np.float32)

            item = GLMalhaTexturizadaItem(vertices, faces, uv, imagem_textura)

            # Expansão abaixo da superfície principal.
            item.setDepthValue(-100.0 + ordem)

            item._tempo_salvo_layer_id = layer.id()
            item._tempo_salvo_expansao = expansao

            self.view.addItem(item)
            self._itens_raster_expansao.append(item)

    def _atualizar_expansao_raster(self):
        """
        Atualiza somente a expansão lateral dos rasters online.
        """
        self._remover_expansao_raster()

        if not self.check_sobreposicao.isChecked():
            return

        if not self._sobrepor_rasters:
            return

        if not self._camadas_raster_sobreposicao:
            return

        self._renderizar_expansao_rasters(self._camadas_raster_sobreposicao)

        self.view.update()

    def _estilo_ponto_3d(self, simbolo):
        """
        Converte aproximadamente a cor, transparência e tamanho
        do símbolo QGIS para o GLScatterPlotItem.
        """
        cor = QColor(255, 0, 0)
        tamanho = 10.0
        opacidade = 1.0

        if simbolo is not None:
            try:
                cor = QColor(simbolo.color())
            except Exception:
                pass  # nosec B110

            try:
                opacidade = float(simbolo.opacity())
            except Exception:
                opacidade = 1.0

            try:
                tamanho_qgis = float(simbolo.size())
                tamanho = max(4.0, min(24.0, tamanho_qgis * 2.5))
            except Exception:
                tamanho = 10.0

        alpha = max(0.0, min(1.0, cor.alphaF() * opacidade))
        rgba = (cor.redF(), cor.greenF(), cor.blueF(), alpha)

        return rgba, tamanho

    def _mascara_faces_poligono_3d(self, geometria):
        """
        Retorna quais triângulos da própria superfície do MDT pertencem
        à geometria do polígono.

        A geometria serve somente como máscara espacial. O preenchimento
        final continua sendo formado pelos triângulos reais do terreno.
        """
        if geometria is None or geometria.isEmpty():
            return None

        largura = int(self._grade_x)
        altura = int(self._grade_y)

        if largura <= 0 or altura <= 0 or self._faces is None:
            return None

        gt = self._geo_transform

        if gt is None:
            return None

        determinante = gt[1] * gt[5] - gt[2] * gt[4]

        if abs(determinante) < 1e-20:
            return None

        if geometria.isMultipart():
            poligonos = geometria.asMultiPolygon()
        else:
            poligono = geometria.asPolygon()
            poligonos = [poligono] if poligono else []

        if not poligonos:
            return None

        caminho = QPainterPath()
        caminho.setFillRule(Qt.FillRule.OddEvenFill)

        for poligono in poligonos:
            for anel in poligono:
                if not anel:
                    continue

                primeiro = True

                for ponto in anel:
                    dx = float(ponto.x()) - gt[0]
                    dy = float(ponto.y()) - gt[3]

                    coluna = (gt[5] * dx - gt[2] * dy) / determinante
                    linha = (-gt[4] * dx + gt[1] * dy) / determinante

                    gx = coluna * largura / self._raster_largura
                    gy = linha * altura / self._raster_altura

                    if primeiro:
                        caminho.moveTo(gx, gy)
                        primeiro = False
                    else:
                        caminho.lineTo(gx, gy)

                caminho.closeSubpath()

        imagem = QImage(largura, altura, QImage.Format.Format_RGBA8888)
        imagem.fill(QColor(0, 0, 0, 0))

        painter = QPainter(imagem)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, False)
        painter.fillPath(caminho, QColor(255, 255, 255, 255))
        painter.end()

        ponteiro = imagem.bits()
        ponteiro.setsize(imagem.sizeInBytes())

        mascara_pixels = np.array(ponteiro, dtype=np.uint8).reshape(altura, largura, 4)[:, :, 3]

        faces = self._faces.astype(np.int64)
        colunas_faces = faces % largura
        linhas_faces = faces // largura

        centros_x = np.mean(colunas_faces, axis=1)
        centros_y = np.mean(linhas_faces, axis=1)

        pixel_x = np.clip(np.floor(centros_x + 0.5).astype(np.int64), 0, largura - 1)
        pixel_y = np.clip(np.floor(centros_y + 0.5).astype(np.int64), 0, altura - 1)

        return mascara_pixels[pixel_y, pixel_x] > 0

    def _estilo_poligono_preenchimento_3d(self, simbolo):
        """
        Obtém a cor principal e a transparência do preenchimento
        do símbolo de polígono utilizado no QGIS.
        """
        cor = QColor(255, 165, 0)
        opacidade = 1.0

        if simbolo is not None:
            try:
                opacidade = float(simbolo.opacity())
            except Exception:
                opacidade = 1.0

            try:
                camada_simbolo = simbolo.symbolLayer(0) if simbolo.symbolLayerCount() > 0 else None
            except Exception:
                camada_simbolo = None

            if camada_simbolo is not None:
                try:
                    cor = QColor(camada_simbolo.fillColor())
                except Exception:
                    try:
                        cor = QColor(camada_simbolo.color())
                    except Exception:
                        try:
                            cor = QColor(simbolo.color())
                        except Exception:
                            pass  # nosec B110
            else:
                try:
                    cor = QColor(simbolo.color())
                except Exception:
                    pass  # nosec B110

        alpha = max(0.0, min(1.0, cor.alphaF() * opacidade))
        return (cor.redF(), cor.greenF(), cor.blueF(), alpha)

    def _poligonos_de_geometria(self, geometria):
        """
        Retorna uma lista de polígonos no formato do QGIS:
        [ [anel_externo, anel_interno1, ...], ... ]
        """
        if geometria is None or geometria.isEmpty():
            return []

        tipo = QgsWkbTypes.geometryType(geometria.wkbType())

        if tipo != Qgis.GeometryType.Polygon:
            return []

        if geometria.isMultipart():
            return [pol for pol in geometria.asMultiPolygon() if pol]

        poligono = geometria.asPolygon()
        return [poligono] if poligono else []

    def _triangulos_da_geometria(self, geometria):
        """
        Tenta triangular uma geometria poligonal resultante da interseção.
        Primeiro tenta triangulação restrita do QGIS.
        Se não funcionar, usa fan triangulation apenas para polígonos simples
        sem furos.
        """
        triangulos = []

        if geometria is None or geometria.isEmpty():
            return triangulos

        triangulada = None

        try:
            triangulada = geometria.constrainedDelaunayTriangulation()
        except Exception:
            triangulada = None

        if triangulada is not None and not triangulada.isEmpty():
            for poligono in self._poligonos_de_geometria(triangulada):
                if not poligono or not poligono[0]:
                    continue

                anel = poligono[0]
                if len(anel) >= 4:
                    pontos = anel[:-1] if anel[0] == anel[-1] else anel

                    if len(pontos) == 3:
                        triangulos.append(pontos)

            if triangulos:
                return triangulos

        for poligono in self._poligonos_de_geometria(geometria):
            if not poligono or not poligono[0]:
                continue

            if len(poligono) > 1:
                continue

            anel = poligono[0]
            pontos = anel[:-1] if anel[0] == anel[-1] else anel

            if len(pontos) < 3:
                continue

            p0 = pontos[0]

            for i in range(1, len(pontos) - 1):
                triangulos.append([p0, pontos[i], pontos[i + 1]])

        return triangulos

    def _xy_para_grade_poligono(self, x, y):
        """
        Converte X/Y do SRC do MDT para coordenadas fracionárias
        da grade utilizada no visualizador 3D.
        """
        if (self._geo_transform is None
            or self._raster_largura <= 0
            or self._raster_altura <= 0):
            return None

        gt = self._geo_transform
        determinante = gt[1] * gt[5] - gt[2] * gt[4]

        if abs(determinante) < 1e-20:
            return None

        dx = float(x) - gt[0]
        dy = float(y) - gt[3]

        coluna = (gt[5] * dx - gt[2] * dy) / determinante
        linha = (-gt[4] * dx + gt[1] * dy) / determinante

        gx = coluna * self._grade_x / self._raster_largura - 0.5
        gy = linha * self._grade_y / self._raster_altura - 0.5

        return float(gx), float(gy)

    def _mascara_pontos_anel_numpy(self, x, y, anel):
        """
        Teste ponto-em-polígono vetorizado para um único anel.
        X e Y podem ser matrizes NumPy.
        """
        resultado = np.zeros(np.shape(x), dtype=bool)

        if not anel or len(anel) < 3:
            return resultado

        pontos = list(anel)

        if (len(pontos) >= 2
            and pontos[0].x() == pontos[-1].x()
            and pontos[0].y() == pontos[-1].y()):
            pontos = pontos[:-1]

        if len(pontos) < 3:
            return resultado

        xs = np.asarray([float(p.x()) for p in pontos], dtype=np.float64)
        ys = np.asarray([float(p.y()) for p in pontos], dtype=np.float64)

        x_anterior = xs[-1]
        y_anterior = ys[-1]

        for x_atual, y_atual in zip(xs, ys):
            cruza = ((y_atual > y) != (y_anterior > y))
            denominador = y_anterior - y_atual

            if abs(denominador) > 1e-30:
                x_intersecao = ((x_anterior - x_atual) * (y - y_atual) / denominador + x_atual)

                resultado ^= cruza & (x < x_intersecao)

            x_anterior = x_atual
            y_anterior = y_atual

        return resultado

    def _mascara_pontos_poligonos_numpy(self, x, y, poligonos):
        """
        Teste vetorizado para Polygon/MultiPolygon, incluindo furos.
        """
        resultado = np.zeros(np.shape(x), dtype=bool)

        for poligono in poligonos:
            if not poligono or not poligono[0]:
                continue

            mascara = self._mascara_pontos_anel_numpy(x, y, poligono[0])

            for anel_interno in poligono[1:]:
                mascara &= ~self._mascara_pontos_anel_numpy(x, y, anel_interno)

            resultado |= mascara

        return resultado

    def _mascara_borda_poligono_grade(self, poligonos, intervalo):
        """
        Marca uma faixa conservadora de células atravessadas pelas bordas
        externas ou internas do polígono.

        Somente estas células precisarão do recorte QgsGeometry exato.
        """
        (linha_min, linha_max, coluna_min, coluna_max) = intervalo

        altura = linha_max - linha_min + 1
        largura = coluna_max - coluna_min + 1
        mascara = np.zeros((altura, largura), dtype=bool)

        for poligono in poligonos:
            for anel in poligono:
                if not anel or len(anel) < 2:
                    continue

                pontos = list(anel)

                if (pontos[0].x() != pontos[-1].x()
                    or pontos[0].y() != pontos[-1].y()):
                    pontos.append(pontos[0])

                for i in range(len(pontos) - 1):
                    inicio = self._xy_para_grade_poligono(pontos[i].x(), pontos[i].y())

                    fim = self._xy_para_grade_poligono(pontos[i + 1].x(), pontos[i + 1].y())

                    if inicio is None or fim is None:
                        continue

                    gx0, gy0 = inicio
                    gx1, gy1 = fim

                    distancia_grade = max(abs(gx1 - gx0), abs(gy1 - gy0))

                    quantidade = max(2, int(math.ceil(distancia_grade * 2.0)) + 1)

                    t = np.linspace(0.0, 1.0, quantidade)
                    colunas = np.floor(gx0 + (gx1 - gx0) * t).astype(np.int32)

                    linhas = np.floor(gy0 + (gy1 - gy0) * t).astype(np.int32)

                    # Uma célula de margem evita deixar escapar
                    # cruzamentos que ocorram exatamente em vértices.
                    for deslocamento_linha in (-1, 0, 1):
                        for deslocamento_coluna in (-1, 0, 1):
                            rr = linhas + deslocamento_linha - linha_min
                            cc = colunas + deslocamento_coluna - coluna_min

                            validos = (
                                (rr >= 0)
                                & (rr < altura)
                                & (cc >= 0)
                                & (cc < largura))

                            mascara[
                                rr[validos],
                                cc[validos]] = True

        return mascara

    def _classificar_faces_poligono_grade(self, geometria):
        """
        Separa as faces candidatas em:

        - faces internas: podem ser copiadas diretamente do MDT;
        - faces de borda: precisam do recorte geométrico exato.
        """
        vazio = np.empty(0, dtype=np.int32)

        if geometria is None or geometria.isEmpty():
            return vazio, vazio

        poligonos = self._poligonos_de_geometria(geometria)

        if not poligonos:
            return vazio, vazio

        intervalo = self._intervalo_grade_bbox_poligono(geometria.boundingBox())

        if intervalo is None:
            return vazio, vazio

        cache = self._obter_indice_faces_poligono()

        if cache is None:
            return vazio, vazio

        (linha_min, linha_max, coluna_min, coluna_max) = intervalo

        mapa_local = cache["mapa"][linha_min:linha_max + 1, coluna_min:coluna_max + 1]

        mascara_valida = mapa_local >= 0

        if not np.any(mascara_valida):
            return vazio, vazio

        x_grade = self._x_real.reshape(self._grade_y, self._grade_x)
        y_grade = self._y_real.reshape(self._grade_y, self._grade_x)

        x00 = x_grade[linha_min:linha_max + 1, coluna_min:coluna_max + 1]

        x01 = x_grade[linha_min:linha_max + 1, coluna_min + 1:coluna_max + 2]

        x10 = x_grade[linha_min + 1:linha_max + 2, coluna_min:coluna_max + 1]

        x11 = x_grade[linha_min + 1:linha_max + 2, coluna_min + 1:coluna_max + 2]

        y00 = y_grade[linha_min:linha_max + 1, coluna_min:coluna_max + 1]

        y01 = y_grade[linha_min:linha_max + 1, coluna_min + 1:coluna_max + 2]

        y10 = y_grade[ linha_min + 1:linha_max + 2, coluna_min:coluna_max + 1]

        y11 = y_grade[linha_min + 1:linha_max + 2, coluna_min + 1:coluna_max + 2]

        x_centro = (x00 + x01 + x10 + x11) * 0.25
        y_centro = (y00 + y01 + y10 + y11) * 0.25

        mascara_dentro = self._mascara_pontos_poligonos_numpy(x_centro, y_centro, poligonos)

        mascara_borda = self._mascara_borda_poligono_grade(poligonos, intervalo)

        mascara_interna = (mascara_valida
            & mascara_dentro
            & ~mascara_borda)

        mascara_borda &= mascara_valida

        bases_internas = mapa_local[
            mascara_interna].astype(np.int32, copy=False)

        bases_borda = mapa_local[mascara_borda].astype(np.int32, copy=False)

        quantidade = int(cache["quantidade"])

        if bases_internas.size:
            faces_internas = np.concatenate((bases_internas,
                bases_internas + quantidade)).astype(np.int32,
                    copy=False)
        else:
            faces_internas = vazio

        if bases_borda.size:
            faces_borda = np.concatenate((bases_borda,
                bases_borda + quantidade)).astype(np.int32,
                    copy=False)
        else:
            faces_borda = vazio

        return faces_internas, faces_borda

    def _indices_faces_preenchimento_rapido(self, geometria):
        """
        Retorna rapidamente as faces do MDT cujo centroide está dentro
        do polígono.

        Não realiza recorte geométrico das bordas. Cada triângulo da
        malha é incluído ou descartado por inteiro.
        """
        vazio = np.empty(0, dtype=np.int32)

        if geometria is None or geometria.isEmpty():
            return vazio

        poligonos = self._poligonos_de_geometria(geometria)

        if not poligonos:
            return vazio

        intervalo = self._intervalo_grade_bbox_poligono(geometria.boundingBox())

        if intervalo is None:
            return vazio

        cache = self._obter_indice_faces_poligono()

        if cache is None:
            return vazio

        (linha_min,
            linha_max,
            coluna_min,
            coluna_max) = intervalo

        mapa_local = cache["mapa"][linha_min:linha_max + 1, coluna_min:coluna_max + 1]

        mascara_valida = mapa_local >= 0

        if not np.any(mascara_valida):
            return vazio

        x_grade = self._x_real.reshape(self._grade_y, self._grade_x)
        y_grade = self._y_real.reshape(self._grade_y, self._grade_x)

        x00 = x_grade[linha_min:linha_max + 1, coluna_min:coluna_max + 1]
        x01 = x_grade[linha_min:linha_max + 1, coluna_min + 1:coluna_max + 2]
        x10 = x_grade[linha_min + 1:linha_max + 2, coluna_min:coluna_max + 1]
        x11 = x_grade[linha_min + 1:linha_max + 2, coluna_min + 1:coluna_max + 2]
        y00 = y_grade[linha_min:linha_max + 1, coluna_min:coluna_max + 1]
        y01 = y_grade[linha_min:linha_max + 1, coluna_min + 1:coluna_max + 2]
        y10 = y_grade[linha_min + 1:linha_max + 2, coluna_min:coluna_max + 1]
        y11 = y_grade[linha_min + 1:linha_max + 2, coluna_min + 1:coluna_max + 2]

        # Centroide da primeira face da célula: a, b, c.
        centro_x_1 = (x00 + x01 + x10) / 3.0
        centro_y_1 = (y00 + y01 + y10) / 3.0

        # Centroide da segunda face da célula: b, d, c.
        centro_x_2 = (x01 + x11 + x10) / 3.0
        centro_y_2 = (y01 + y11 + y10) / 3.0

        mascara_face_1 = (mascara_valida
            & self._mascara_pontos_poligonos_numpy(
                centro_x_1,
                centro_y_1,
                poligonos))

        mascara_face_2 = (mascara_valida
            & self._mascara_pontos_poligonos_numpy(
                centro_x_2,
                centro_y_2,
                poligonos))

        bases_face_1 = mapa_local[mascara_face_1].astype(np.int32, copy=False)
        bases_face_2 = mapa_local[mascara_face_2].astype(np.int32, copy=False)

        quantidade = int(cache["quantidade"])

        partes = []

        if bases_face_1.size:
            partes.append(bases_face_1)

        if bases_face_2.size:
            partes.append(bases_face_2 + quantidade)

        if not partes:
            return vazio

        return np.concatenate(partes).astype(np.int32, copy=False)

    def _caminho_poligono_grade_pintura(self, geometria):
        """
        Converte Polygon/MultiPolygon para QPainterPath nas coordenadas
        da grade 3D atualmente utilizada pelo MDT.
        """
        if (geometria is None
            or geometria.isEmpty()
            or self._geo_transform is None):
            return None

        poligonos = self._poligonos_de_geometria(geometria)

        if not poligonos:
            return None

        gt = self._geo_transform
        determinante = gt[1] * gt[5] - gt[2] * gt[4]

        if abs(determinante) < 1e-20:
            return None

        largura = int(self._grade_x)
        altura = int(self._grade_y)

        caminho = QPainterPath()
        caminho.setFillRule(Qt.FillRule.OddEvenFill)

        for poligono in poligonos:
            for anel in poligono:
                if not anel:
                    continue

                primeiro = True

                for ponto in anel:
                    dx = float(ponto.x()) - gt[0]
                    dy = float(ponto.y()) - gt[3]

                    coluna = (gt[5] * dx - gt[2] * dy) / determinante

                    linha = (-gt[4] * dx + gt[1] * dy) / determinante

                    gx = (coluna * largura / self._raster_largura)
                    gy = (linha * altura / self._raster_altura)

                    if primeiro:
                        caminho.moveTo(gx, gy)
                        primeiro = False

                    else:
                        caminho.lineTo(gx, gy)

                caminho.closeSubpath()

        if caminho.isEmpty():
            return None

        return caminho

    def _pixels_centros_faces_pintura(self):
        """
        Retorna o pixel da grade correspondente ao centroide de cada
        triângulo do MDT.

        O resultado é calculado somente uma vez por qualidade.
        """
        if self._faces is None:
            return None

        largura = int(self._grade_x)
        altura = int(self._grade_y)

        limite = int(getattr(self, "_limite_grade_aplicado", self.LIMITE_GRADE))

        chave = (limite, largura, altura, int(len(self._faces)))

        cache = self._cache_pixels_faces_pintura.get(chave)

        if cache is not None:
            return cache

        faces = self._faces

        colunas_faces = faces % largura
        linhas_faces = faces // largura

        centros_x = (colunas_faces[:, 0] + colunas_faces[:, 1] + colunas_faces[:, 2]) / 3.0
        centros_y = (linhas_faces[:, 0] + linhas_faces[:, 1] + linhas_faces[:, 2]) / 3.0

        pixel_x = np.clip(np.floor(centros_x + 0.5).astype(np.int32), 0, largura - 1)
        pixel_y = np.clip(np.floor(centros_y + 0.5).astype(np.int32), 0, altura - 1)

        cache = (pixel_x, pixel_y)

        self._cache_pixels_faces_pintura[chave] = cache

        return cache

    def _renderizar_pintura_poligonos_camada(self, layer, ordem, config, contexto):
        """
        Renderiza todos os polígonos de uma camada como uma pintura rápida
        sobre a malha do MDT.

        As geometrias são rasterizadas em uma única QImage e convertidas
        para um único GLMeshItem.
        """
        if (layer is None
            or self._faces is None
            or self._vertices_base is None):
            return

        largura = int(self._grade_x)
        altura = int(self._grade_y)

        if (largura <= 0
            or altura <= 0):
            return

        opacidade_config = max(0.0, min(100.0, float(config.get( "opacidade", 100.0)))) / 100.0

        if opacidade_config <= 0.0:
            return

        altura_sobre_terreno = float(config.get("altura", 0.0))
        exagero = float(self.spin_exagero.value())
        altura_3d = (altura_sobre_terreno * exagero)
        folga_z = max(0.002, abs(self._z_max - self._z_min) * exagero * 0.00002)

        imagem = QImage(largura, altura, QImage.Format.Format_RGBA8888)
        imagem.fill(QColor(0, 0, 0, 0))

        painter = QPainter(imagem)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, False)

        transformacao = None

        if (layer.crs().isValid()
            and self.raster_layer.crs().isValid()
            and layer.crs() != self.raster_layer.crs()):

            transformacao = QgsCoordinateTransform(layer.crs(), self.raster_layer.crs(), QgsProject.instance())

        renderer = layer.renderer()

        if renderer is not None:
            try:
                renderer.startRender(contexto, layer.fields())

            except Exception:
                renderer = None

        try:
            for feature in layer.getFeatures():
                geometria = feature.geometry()

                if (geometria is None
                    or geometria.isEmpty()):
                    continue

                if transformacao is not None:
                    try:
                        geometria.transform(transformacao)

                    except Exception as e:
                        self._registrar_erro_sobreposicao_3d(self.tr("Falha ao transformar a geometria para o CRS do MDT"), e)
                        continue

                try:
                    objeto_geometria = geometria.constGet()

                    if (objeto_geometria is not None
                        and objeto_geometria.hasCurvedSegments()):

                        geometria = geometria.segmentize()

                except Exception:
                    pass  # nosec B110

                caminho = self._caminho_poligono_grade_pintura(geometria)

                if caminho is None:
                    continue

                simbolo = None

                if renderer is not None:
                    try:
                        simbolo = renderer.symbolForFeature(feature, contexto)

                    except Exception:
                        simbolo = None

                    if simbolo is None:
                        try:
                            simbolo = renderer.symbol()

                        except Exception:
                            simbolo = None

                    if simbolo is None:
                        continue

                cor = self._estilo_poligono_preenchimento_3d(simbolo)

                alpha = max(0.0, min(1.0, float(cor[3]) * opacidade_config))

                if alpha <= 0.0:
                    continue

                cor_qt = QColor.fromRgbF(
                    float(cor[0]),
                    float(cor[1]),
                    float(cor[2]),
                    alpha)

                painter.fillPath(caminho, cor_qt)

        finally:
            painter.end()

            if renderer is not None:
                try:
                    renderer.stopRender(contexto)

                except Exception:
                    pass  # nosec B110

        ponteiro = imagem.bits()
        ponteiro.setsize(imagem.sizeInBytes())

        rgba = np.array(ponteiro, dtype=np.uint8).reshape(altura, largura, 4)

        pixels_faces = self._pixels_centros_faces_pintura()

        if pixels_faces is None:
            return

        pixel_x, pixel_y = pixels_faces
        cores_faces = rgba[pixel_y, pixel_x]
        mascara = cores_faces[:, 3] > 0

        if not np.any(mascara):
            return

        faces_selecionadas = self._faces[mascara]

        cores_selecionadas = (cores_faces[mascara].astype(np.float32) / 255.0)

        # Mantém somente os vértices realmente utilizados pela pintura.
        vertices_usados, faces_locais = np.unique(faces_selecionadas.reshape(-1), return_inverse=True)

        vertices = self._vertices_base[vertices_usados].astype(np.float32, copy=True)
        vertices[:, 2] = (vertices[:, 2] * exagero + altura_3d + folga_z)

        faces_locais = faces_locais.reshape(-1, 3).astype(np.uint32, copy=False)

        mesh_data = gl.MeshData(
            vertexes=vertices,
            faces=faces_locais,
            faceColors=cores_selecionadas)

        item = gl.GLMeshItem(
            meshdata=mesh_data,
            smooth=False,
            computeNormals=False,
            drawFaces=True,
            drawEdges=False,
            shader=None)

        item.setGLOptions("translucent")
        item.setDepthValue(5.0 + ordem)

        item._tempo_salvo_layer_id = layer.id()
        item._tempo_salvo_altura = altura_sobre_terreno
        item._tempo_salvo_modo_preenchimento = "pintura"

        self.view.addItem(item)
        self._itens_poligonos_sobreposicao.append(item)

    def _renderizar_preenchimento_poligonos_sobre_mdt(self, camadas):
        """
        Renderiza o preenchimento dos polígonos usando método híbrido:

        - faces internas são copiadas diretamente do MDT;
        - somente faces próximas às bordas passam pelo recorte QgsGeometry;
        - feições de mesmo estilo são agrupadas em um único GLMeshItem.
        """
        if not camadas or self._faces is None:
            return

        exagero = float(self.spin_exagero.value())

        folga_z = max(0.002, abs(self._z_max - self._z_min) * exagero * 0.00002)

        if self.ui_manager is not None:
            contexto = QgsRenderContext.fromMapSettings(self.ui_manager.iface.mapCanvas().mapSettings())
        else:
            contexto = QgsRenderContext()

        faces_base = self._faces

        for ordem, layer in enumerate(reversed(camadas)):
            config = self._obter_config_3d_camada("poligonos", layer)

            altura = float(config.get("altura", 0.05))

            mostrar_preenchimento = bool(config.get( "preenchimento", True))

            recorte_preciso = bool(config.get("recorte_preciso", False))
            opacidade_config = max(0.0, min(100.0, float(config.get("opacidade", 100.0)))) / 100.0
            modo_preenchimento = str(config.get("modo_preenchimento", "pintura"))

            if (not mostrar_preenchimento
                or opacidade_config <= 0.0):
                continue

            if modo_preenchimento == "pintura":
                self._renderizar_pintura_poligonos_camada(layer, ordem, config, contexto)
                continue

            altura_3d = altura * exagero
            transformacao = None

            if (layer.crs().isValid()
                and self.raster_layer.crs().isValid()
                and layer.crs() != self.raster_layer.crs()):
                transformacao = QgsCoordinateTransform(
                    layer.crs(),
                    self.raster_layer.crs(),
                    QgsProject.instance())

            renderer = layer.renderer()
            grupos_estilo = {}

            if renderer is not None:
                try:
                    renderer.startRender(contexto, layer.fields())
                except Exception:
                    renderer = None

            try:
                for feature in layer.getFeatures():
                    geometria = feature.geometry()

                    if (geometria is None
                        or geometria.isEmpty()):
                        continue

                    if transformacao is not None:
                        try:
                            geometria.transform(transformacao)
                        except Exception as e:
                            self._registrar_erro_sobreposicao_3d(self.tr("Falha ao transformar a geometria para o CRS do MDT"), e)
                            continue

                    try:
                        objeto_geometria = geometria.constGet()

                        if (objeto_geometria is not None
                            and objeto_geometria.hasCurvedSegments()):
                            geometria = geometria.segmentize()

                    except Exception:
                        pass  # nosec B110

                    simbolo = None

                    if renderer is not None:
                        try:
                            simbolo = renderer.symbolForFeature(
                                feature,
                                contexto)
                        except Exception:
                            simbolo = None

                        if simbolo is None:
                            try:
                                simbolo = renderer.symbol()
                            except Exception:
                                simbolo = None

                        if simbolo is None:
                            continue

                    cor_qgis = self._estilo_poligono_preenchimento_3d(simbolo)

                    cor = (cor_qgis[0],
                        cor_qgis[1],
                        cor_qgis[2],
                        max(0.0, min( 1.0, cor_qgis[3] * opacidade_config)))

                    chave_estilo = tuple(round(float(valor), 6)
                        for valor in cor)

                    grupo = grupos_estilo.setdefault(chave_estilo,
                        {"vertices": [],
                            "faces": [],
                            "quantidade_vertices": 0,
                            "features": []})

                    if modo_preenchimento == "preciso":
                        (faces_internas, faces_borda) = self._classificar_faces_poligono_grade(geometria)

                    else:
                        # Superfície 3D:
                        # usa faces completas sem recortar a borda.
                        faces_internas = self._indices_faces_preenchimento_rapido(geometria)

                        faces_borda = np.empty(0, dtype=np.int32)

                    # 1. Miolo do polígono:
                    # copia diretamente os triângulos do próprio MDT.

                    if faces_internas.size:
                        indices_vertices = faces_base[faces_internas]

                        vertices_internos = self._vertices_base[indices_vertices].astype(np.float32, copy=True)

                        vertices_internos[:, :, 2] = (
                            vertices_internos[:, :, 2]
                            * exagero
                            + altura_3d
                            + folga_z)

                        vertices_internos = vertices_internos.reshape(-1, 3)

                        faces_internas_local = np.arange(
                            len(vertices_internos),
                            dtype=np.uint32).reshape( -1, 3)

                        deslocamento = grupo["quantidade_vertices"]
                        grupo["vertices"].append(vertices_internos)
                        grupo["faces"].append(faces_internas_local + deslocamento)
                        grupo["quantidade_vertices"] += len(vertices_internos)

                    # 2. Borda:
                    # mantém exatamente o recorte geométrico anterior.
                    vertices_borda = []
                    faces_borda_local = []

                    for indice_face in faces_borda:
                        idx0, idx1, idx2 = faces_base[indice_face]

                        p0 = QgsPointXY(
                            float(self._x_real[idx0]),
                            float(self._y_real[idx0]))

                        p1 = QgsPointXY(
                            float(self._x_real[idx1]),
                            float(self._y_real[idx1]))

                        p2 = QgsPointXY(
                            float(self._x_real[idx2]),
                            float(self._y_real[idx2]))

                        triangulo_geom = QgsGeometry.fromPolygonXY([[p0, p1, p2, p0]])

                        try:
                            if geometria.contains(triangulo_geom):
                                triangulos = [[p0, p1, p2]]

                            elif not geometria.intersects(triangulo_geom):
                                continue

                            else:
                                intersecao = geometria.intersection(triangulo_geom)

                                if (intersecao is None
                                    or intersecao.isEmpty()):
                                    continue

                                triangulos = self._triangulos_da_geometria(intersecao)

                        except Exception as e:
                            self._registrar_erro_sobreposicao_3d(self.tr("Falha ao processar a interseção do polígono com a malha 3D"), e)
                            continue

                        if not triangulos:
                            continue

                        for tri in triangulos:
                            if len(tri) != 3:
                                continue

                            coords_3d = []
                            valido = True

                            for ponto in tri:
                                x = float(ponto.x())
                                y = float( ponto.y())
                                z = self._amostrar_cota_mdt(x, y)

                                if z is None:
                                    valido = False
                                    break

                                coords_3d.append((
                                    x - self._x_centro,
                                    y - self._y_centro,
                                    (z - self._z_centro)
                                    * exagero
                                    + altura_3d
                                    + folga_z))

                            if not valido:
                                continue

                            base = len(vertices_borda)

                            vertices_borda.extend(coords_3d)

                            faces_borda_local.append((base, base + 1, base + 2))

                    if faces_borda_local:
                        vertices_borda_np = np.asarray(vertices_borda, dtype=np.float32)

                        faces_borda_np = np.asarray(faces_borda_local, dtype=np.uint32)

                        deslocamento = grupo["quantidade_vertices"]
                        grupo["vertices"].append(vertices_borda_np)
                        grupo["faces"].append(faces_borda_np + deslocamento)
                        grupo["quantidade_vertices"] += len(vertices_borda_np)

                    if (faces_internas.size
                        or faces_borda_local):
                        grupo["features"].append(feature.id())

            finally:
                if renderer is not None:
                    try:
                        renderer.stopRender(
                            contexto)
                    except Exception:
                        pass  # nosec B110

            # Um GLMeshItem por estilo, em vez de um por feição.
            # 
            for chave_estilo, grupo in grupos_estilo.items():
                if (not grupo["vertices"]
                    or not grupo["faces"]):
                    continue

                vertices_np = np.vstack(grupo["vertices"]).astype(np.float32, copy=False)

                faces_np = np.vstack(grupo["faces"]).astype(np.uint32, copy=False)

                cor = tuple(float(valor)
                    for valor in chave_estilo)

                mesh_data = gl.MeshData(vertexes=vertices_np, faces=faces_np)

                item = gl.GLMeshItem(
                    meshdata=mesh_data,
                    smooth=False,
                    drawFaces=True,
                    drawEdges=False,
                    color=cor,
                    shader="shaded")

                item.setGLOptions("translucent")

                item.setDepthValue(5.0 + ordem)

                item._tempo_salvo_layer_id = layer.id()
                item._tempo_salvo_feature_ids = tuple(
                    grupo["features"])
                item._tempo_salvo_altura = altura

                if len(grupo["features"]) == 1:
                    item._tempo_salvo_feature_id = grupo[ "features"][0]

                self.view.addItem(item)

                self._itens_poligonos_sobreposicao.append(item)

    def _estilo_poligono_contorno_3d(self, simbolo):
        """
        Retorna a cor e a espessura aproximadas do contorno
        do símbolo de polígono do QGIS.
        """
        cor = QColor(30, 30, 30)
        largura = 2.0
        opacidade = 1.0

        if simbolo is not None:
            try:
                opacidade = float(simbolo.opacity())
            except Exception:
                opacidade = 1.0

            try:
                camada_simbolo = simbolo.symbolLayer(0) if simbolo.symbolLayerCount() > 0 else None
            except Exception:
                camada_simbolo = None

            if camada_simbolo is not None:
                try:
                    cor = QColor(camada_simbolo.strokeColor())
                except Exception:
                    try:
                        cor = QColor(simbolo.color())
                    except Exception:
                        pass  # nosec B110

                try:
                    largura_qgis = float(camada_simbolo.strokeWidth())
                    largura = max(1.5, min(8.0, largura_qgis * 2.5))
                except Exception:
                    largura = 2.0

        rgba = (cor.redF(), cor.greenF(), cor.blueF(), max(0.0, min(1.0, cor.alphaF() * opacidade)))

        return rgba, largura

    def _cor_rotulo_poligono_qgis(self, layer):
        """
        Usa a cor configurada para os rótulos da camada no QGIS.
        Quando não for possível reconhecê-la, utiliza branco.
        """
        return self._cor_rotulo_linha_qgis(layer)

    def _cor_rotulo_ponto_qgis(self, layer):
        """
        Usa a cor configurada para os rótulos da camada no QGIS.
        Se não for possível reconhecê-la, utiliza branco.
        """
        return self._cor_rotulo_linha_qgis(layer)

    def _posicao_rotulo_poligono_3d(self, geometria, altura_poligono, altura_rotulo):
        """
        Posiciona o rótulo dentro do polígono.

        A altura final é:
        terreno + altura do polígono + altura própria do rótulo.
        """
        if geometria is None or geometria.isEmpty():
            return None

        try:
            geometria_ponto = geometria.pointOnSurface()
        except Exception:
            return None

        if geometria_ponto is None or geometria_ponto.isEmpty():
            return None

        try:
            ponto = geometria_ponto.asPoint()
            x = float(ponto.x())
            y = float(ponto.y())
        except Exception:
            return None

        z_terreno = self._amostrar_cota_mdt(x, y)

        if z_terreno is None:
            return None

        exagero = float(self.spin_exagero.value())

        z = ((z_terreno - self._z_centro) * exagero
            + float(altura_poligono) * exagero
            + float(altura_rotulo) * exagero)

        return np.asarray((
            x - self._x_centro,
            y - self._y_centro,
            z), dtype=np.float32)

    def _renderizar_paredes_poligonos_sobre_mdt(self, camadas):
        """
        Renderiza paredes verticais entre o polígono elevado
        e a superfície original do MDT.
        """
        if not camadas:
            return

        if self.ui_manager is not None:
            contexto = QgsRenderContext.fromMapSettings(
                self.ui_manager.iface.mapCanvas().mapSettings())
        else:
            contexto = QgsRenderContext()

        for ordem, layer in enumerate(reversed(camadas)):
            config = self._obter_config_3d_camada("poligonos", layer)

            altura = float(config.get("altura", 0.05))
            mostrar_caixa = bool(config.get("caixa", False))
            opacidade_config = max(0.0, min(100.0, float(config.get("opacidade", 100.0)))) / 100.0

            if not mostrar_caixa:
                continue

            if abs(altura) <= 1e-9:
                continue

            if opacidade_config <= 0.0:
                continue

            transformacao = None

            if (layer.crs().isValid()
                and self.raster_layer.crs().isValid()
                and layer.crs() != self.raster_layer.crs()):
                transformacao = QgsCoordinateTransform(
                    layer.crs(),
                    self.raster_layer.crs(),
                    QgsProject.instance())

            renderer = layer.renderer()

            if renderer is not None:
                try:
                    renderer.startRender(contexto, layer.fields())
                except Exception:
                    renderer = None

            try:
                for feature in layer.getFeatures():
                    geometria = feature.geometry()

                    if (geometria is None
                        or geometria.isEmpty()):
                        continue

                    if transformacao is not None:
                        try:
                            geometria.transform(transformacao)
                        except Exception as e:
                            self._registrar_erro_sobreposicao_3d(self.tr("Falha ao transformar a geometria para o CRS do MDT"), e)
                            continue

                    try:
                        objeto_geometria = geometria.constGet()

                        if (objeto_geometria is not None
                            and objeto_geometria.hasCurvedSegments()):
                            geometria = geometria.segmentize()

                    except Exception:
                        pass  # nosec B110

                    if geometria.isMultipart():
                        poligonos = geometria.asMultiPolygon()
                    else:
                        poligono = geometria.asPolygon()
                        poligonos = [poligono] if poligono else []

                    simbolo = None

                    if renderer is not None:
                        try:
                            simbolo = renderer.symbolForFeature(feature, contexto)
                        except Exception:
                            simbolo = None

                        if simbolo is None:
                            try:
                                simbolo = renderer.symbol()
                            except Exception:
                                simbolo = None

                        if simbolo is None:
                            continue

                    cor_qgis = self._estilo_poligono_preenchimento_3d(simbolo)

                    cor_parede = (
                        cor_qgis[0],
                        cor_qgis[1],
                        cor_qgis[2],
                        max(0.0, min(1.0, cor_qgis[3] * opacidade_config)))

                    vertices_total = []
                    faces_total = []

                    for poligono in poligonos:
                        for anel in poligono:
                            if not anel or len(anel) < 2:
                                continue

                            pontos_anel = list(anel)

                            if (pontos_anel[0].x() != pontos_anel[-1].x()
                                or pontos_anel[0].y() != pontos_anel[-1].y()):
                                pontos_anel.append(pontos_anel[0])

                            segmentos = self._segmentos_linha_3d(pontos_anel, altura)

                            for segmento in segmentos:
                                vertices, faces = self._criar_parede_poligono_3d(segmento, altura)

                                if (vertices is None
                                    or faces is None):
                                    continue

                                deslocamento = len(vertices_total)

                                vertices_total.extend(vertices)
                                faces_total.extend(faces + deslocamento)

                    if not faces_total:
                        continue

                    vertices_np = np.asarray(vertices_total, dtype=np.float32)

                    faces_np = np.asarray(faces_total, dtype=np.uint32)
                    mesh_data = gl.MeshData(vertexes=vertices_np, faces=faces_np)

                    item = gl.GLMeshItem(
                        meshdata=mesh_data,
                        smooth=False,
                        computeNormals=False,
                        drawFaces=True,
                        drawEdges=False,
                        color=cor_parede,
                        shader=None)

                    item.setGLOptions("translucent")
                    item.setDepthValue(4.0 + ordem)

                    item._tempo_salvo_layer_id = layer.id()
                    item._tempo_salvo_feature_id = feature.id()
                    item._tempo_salvo_altura = altura

                    self.view.addItem(item)
                    self._itens_poligonos_sobreposicao.append(item)

            finally:
                if renderer is not None:
                    try:
                        renderer.stopRender(contexto)
                    except Exception:
                        pass  # nosec B110

    def _pares_arestas_verticais_poligono_3d(self, pontos_anel, altura_sobre_terreno):
        """
        Cria os segmentos verticais das arestas da caixa do polígono.

        Usa os vértices do anel para ligar a base (sobre o MDT)
        ao topo elevado do polígono.
        """
        if not pontos_anel or len(pontos_anel) < 2:
            return None

        exagero = float(self.spin_exagero.value())
        altura_3d = float(altura_sobre_terreno) * exagero

        if abs(altura_3d) <= 1e-9:
            return None

        folga_z = max(0.002, abs(self._z_max - self._z_min) * exagero * 0.00002)

        vertices = []
        pontos_base = list(pontos_anel)

        # Remove o último ponto se ele repetir o primeiro.
        if len(pontos_base) >= 2:
            p0 = pontos_base[0]
            p_last = pontos_base[-1]

            if (p0.x() == p_last.x()
                and p0.y() == p_last.y()):
                pontos_base = pontos_base[:-1]

        for ponto in pontos_base:
            x = float(ponto.x())
            y = float(ponto.y())

            z = self._amostrar_cota_mdt(x, y)

            if z is None:
                continue

            z_base = (z - self._z_centro) * exagero + folga_z
            z_topo = z_base + altura_3d

            vertices.append((x - self._x_centro, y - self._y_centro, z_base))
            vertices.append((x - self._x_centro, y - self._y_centro, z_topo))

        if not vertices:
            return None

        return np.asarray(vertices, dtype=np.float32)

    def _renderizar_contornos_poligonos_sobre_mdt(self, camadas):
        """
        Renderiza os anéis externos e internos dos polígonos
        acompanhando a superfície e a altura configurada do polígono.

        Quando "caixa" estiver habilitado, desenha também:
        - o contorno inferior;
        - as arestas verticais.
        """
        if not camadas:
            return

        if self.ui_manager is not None:
            contexto = QgsRenderContext.fromMapSettings(self.ui_manager.iface.mapCanvas().mapSettings())
        else:
            contexto = QgsRenderContext()

        for ordem, layer in enumerate(reversed(camadas)):
            config = self._obter_config_3d_camada("poligonos", layer)

            altura = float(config.get("altura", 0.05))
            mostrar_caixa = bool(config.get("caixa", False))
            mostrar_contorno = bool(config.get("contorno", True))
            espessura_contorno = max(0.10, float(config.get("espessura_contorno", 2.0)))

            if not mostrar_contorno:
                continue

            transformacao = None

            if (layer.crs().isValid()
                and self.raster_layer.crs().isValid()
                and layer.crs() != self.raster_layer.crs()):
                transformacao = QgsCoordinateTransform(
                    layer.crs(),
                    self.raster_layer.crs(),
                    QgsProject.instance())

            renderer = layer.renderer()
            grupos_estilo = {}

            if renderer is not None:
                try:
                    renderer.startRender(contexto, layer.fields())
                except Exception:
                    renderer = None

            try:
                for feature in layer.getFeatures():
                    geometria = feature.geometry()

                    if (geometria is None
                        or geometria.isEmpty()):
                        continue

                    if transformacao is not None:
                        try:
                            geometria.transform(transformacao)
                        except Exception as e:
                            self._registrar_erro_sobreposicao_3d(self.tr("Falha ao transformar a geometria para o CRS do MDT"), e)
                            continue

                    try:
                        objeto_geometria = geometria.constGet()

                        if (objeto_geometria is not None
                            and objeto_geometria.hasCurvedSegments()):
                            geometria = geometria.segmentize()

                    except Exception:
                        pass  # nosec B110

                    if geometria.isMultipart():
                        poligonos = geometria.asMultiPolygon()
                    else:
                        poligono = geometria.asPolygon()
                        poligonos = [poligono] if poligono else []

                    simbolo = None

                    if renderer is not None:
                        try:
                            simbolo = renderer.symbolForFeature(feature, contexto)
                        except Exception:
                            simbolo = None

                        if simbolo is None:
                            try:
                                simbolo = renderer.symbol()
                            except Exception:
                                simbolo = None

                        if simbolo is None:
                            continue

                    cor_qgis, _ = self._estilo_poligono_contorno_3d(simbolo)

                    cor = cor_qgis
                    largura = espessura_contorno

                    chave = (tuple(round(valor, 5) for valor in cor), round(largura, 2))

                    blocos = grupos_estilo.setdefault(chave, [])

                    for poligono in poligonos:
                        for anel in poligono:
                            if not anel or len(anel) < 2:
                                continue

                            pontos_anel = list(anel)

                            if (pontos_anel[0].x() != pontos_anel[-1].x()
                                or pontos_anel[0].y() != pontos_anel[-1].y()):
                                pontos_anel.append(pontos_anel[0])

                            # Contorno superior
                            for segmento in self._segmentos_linha_3d(pontos_anel, altura):
                                if len(segmento) < 2:
                                    continue

                                pares = np.empty(((len(segmento) - 1) * 2, 3), dtype=np.float32)

                                pares[0::2] = segmento[:-1]
                                pares[1::2] = segmento[1:]

                                blocos.append(pares)

                            if mostrar_caixa and abs(altura) > 1e-9:
                                # Contorno inferior
                                for segmento_base in self._segmentos_linha_3d(pontos_anel, 0.0):
                                    if len(segmento_base) < 2:
                                        continue

                                    pares_base = np.empty(
                                        ((len(segmento_base) - 1) * 2, 3),
                                        dtype=np.float32)

                                    pares_base[0::2] = segmento_base[:-1]
                                    pares_base[1::2] = segmento_base[1:]

                                    blocos.append(pares_base)

                                # Arestas verticais
                                pares_verticais = self._pares_arestas_verticais_poligono_3d(
                                    pontos_anel,
                                    altura)

                                if pares_verticais is not None and len(pares_verticais) >= 2:
                                    blocos.append(pares_verticais)

            finally:
                if renderer is not None:
                    try:
                        renderer.stopRender(contexto)
                    except Exception:
                        pass  # nosec B110

            for chave, blocos in grupos_estilo.items():
                if not blocos:
                    continue

                cor, largura = chave
                posicoes = np.vstack(blocos)

                item = gl.GLLinePlotItem(
                    pos=posicoes,
                    color=cor,
                    width=largura,
                    antialias=True,
                    mode="lines")

                item.setGLOptions("translucent")
                item.setDepthValue(20.0 + ordem)

                # Identificação para atualização incremental.
                item._tempo_salvo_layer_id = layer.id()
                item._tempo_salvo_tipo_poligono = "contorno"

                self.view.addItem(item)
                self._itens_poligonos_sobreposicao.append(item)

    def _criar_rotulo_poligono_3d(self, texto, posicao, cor, tamanho, ordem):
        """
        Cria um rótulo associado a uma feição de polígono.
        """
        if not texto or posicao is None:
            return None

        fonte = QFont()
        fonte.setPointSize(max(6, int(tamanho)))

        try:
            item = gl.GLTextItem(
                pos=posicao,
                color=cor,
                text=texto,
                font=fonte)
        except Exception:
            return None

        try:
            item.setDepthValue(35.0 + ordem)
        except Exception:
            pass  # nosec B110

        self.view.addItem(item)
        self._itens_rotulos_poligonos_sobreposicao.append(item)

        return item

    def _renderizar_rotulos_poligonos_sobre_mdt(self, camadas):
        """
        Renderiza um rótulo por feição de polígono.
        """
        if not camadas:
            return

        for ordem, layer in enumerate(reversed(camadas)):
            config = self._obter_config_3d_camada("poligonos", layer)

            mostrar_rotulo = bool(config.get("rotulo", False))
            altura = float(config.get("altura", 0.05))
            altura_rotulo = max(0.0, float(config.get("altura_rotulo", 2.0)))
            tamanho_rotulo = max(6, int(config.get("tamanho_rotulo", 10)))
            campo_rotulo = config.get("campo_rotulo")

            if (not mostrar_rotulo
                or not campo_rotulo):
                continue

            cor_rotulo = self._cor_rotulo_poligono_qgis(layer)
            transformacao = None

            if (layer.crs().isValid()
                and self.raster_layer.crs().isValid()
                and layer.crs() != self.raster_layer.crs()):
                transformacao = QgsCoordinateTransform(
                    layer.crs(),
                    self.raster_layer.crs(),
                    QgsProject.instance())

            for feature in layer.getFeatures():
                geometria = feature.geometry()

                if (geometria is None
                    or geometria.isEmpty()):
                    continue

                if transformacao is not None:
                    try:
                        geometria.transform(transformacao)
                    except Exception as e:
                        self._registrar_erro_sobreposicao_3d(self.tr("Falha ao transformar a geometria para o CRS do MDT"), e)
                        continue

                texto = self._texto_rotulo_feature(feature, campo_rotulo)

                if not texto:
                    continue

                posicao = self._posicao_rotulo_poligono_3d(geometria, altura, altura_rotulo)

                if posicao is None:
                    continue

                item_rotulo = self._criar_rotulo_poligono_3d(texto, posicao, cor_rotulo, tamanho_rotulo, ordem)

                self._registrar_rotulo_oclusao(item_rotulo, "poligonos", layer, posicao)

    def _snapshot_estilo_poligonos_3d(self, camadas=None):
        """
        Registra as configurações dos polígonos para
        validar o cache e identificar mudanças visuais.
        """
        if camadas is None:
            camadas = self._camadas_poligonos_sobreposicao

        return {layer.id(): self._obter_config_3d_camada("poligonos", layer)
            for layer in camadas}

    def _atualizar_apenas_espessura_poligonos_3d(self):
        """
        Atualiza somente a espessura dos contornos dos
        polígonos, sem reconstruir preenchimentos,
        paredes ou rótulos.
        """
        chave = self._chave_cache_poligonos_ativa

        if chave is None:
            return False

        cache = self._cache_poligonos_3d.get(chave)

        if cache is None:
            return False

        anterior = cache.get("estilos")
        atual = self._snapshot_estilo_poligonos_3d()

        if anterior is None or anterior.keys() != atual.keys():
            return False

        alteracoes = {}

        for layer_id, config_atual in atual.items():
            config_anterior = anterior[layer_id]

            outros_anteriores = {k: v
                for k, v in config_anterior.items()
                if k != "espessura_contorno"}

            outros_atuais = {k: v
                for k, v in config_atual.items()
                if k != "espessura_contorno"}

            if outros_anteriores != outros_atuais:
                return False

            antiga = max(0.10, float(config_anterior.get( "espessura_contorno", 2.0)))

            nova = max(0.10, float(config_atual.get( "espessura_contorno", 2.0)))

            if abs(nova - antiga) > 1e-9:
                alteracoes[layer_id] = nova

        if not alteracoes:
            return False

        itens = self._itens_poligonos_sobreposicao

        # Confirma se os objetos pertencem ao cache ativo.
        itens_cache = cache.get("itens", [])

        if (len(itens) != len(itens_cache)
            or any(item not in itens_cache
                for item in itens)):
            return False

        # Verifica todos os objetos antes de alterar algum.
        for item in itens:
            if getattr(item, "_tempo_salvo_tipo_poligono", None) != "contorno":
                continue

            if not isinstance(item, gl.GLLinePlotItem):
                return False

            if getattr(item, "_tempo_salvo_layer_id", None) is None:
                return False

        try:
            for item in itens:
                if getattr(item, "_tempo_salvo_tipo_poligono", None) != "contorno":
                    continue

                layer_id = getattr(item, "_tempo_salvo_layer_id", None)

                if layer_id not in alteracoes:
                    continue

                item.setData(width=alteracoes[layer_id])

        except (RuntimeError, TypeError, ValueError):
            return False

        cache["estilos"] = copy.deepcopy(atual)

        self.view.update()
        return True

    def _atualizar_poligonos_sobreposicao(self, usar_cache=False):
        """
        Atualiza preenchimento, paredes, contorno e rótulos dos polígonos.

        Quando usar_cache=True, reutiliza os objetos OpenGL já preparados
        para a qualidade atual do terreno.
        """
        if not self.check_sobreposicao.isChecked():
            self._ocultar_poligonos_cache_ativos()
            self.view.update()
            return

        if not self._sobrepor_poligonos:
            self._ocultar_poligonos_cache_ativos()
            self.view.update()
            return

        if not self._camadas_poligonos_sobreposicao:
            self._ocultar_poligonos_cache_ativos()
            self.view.update()
            return

        # Mudança apenas de qualidade/visibilidade:
        # tenta reutilizar os objetos já preparados.
        if (usar_cache
            and self._ativar_cache_poligonos_3d(
                self._camadas_poligonos_sobreposicao)):

            self.view.update()
            self._solicitar_atualizacao_oclusao_rotulos()
            return

        if usar_cache:
            # Nova qualidade ainda não preparada.
            self._ocultar_poligonos_cache_ativos()

        else:
            # Tenta atualizar somente a espessura do contorno.
            if self._atualizar_apenas_espessura_poligonos_3d():
                return

            # Outras alterações continuam utilizando
            # a reconstrução original.
            self._invalidar_cache_poligonos_3d()

        self._renderizar_preenchimento_poligonos_sobre_mdt(self._camadas_poligonos_sobreposicao)

        self._renderizar_paredes_poligonos_sobre_mdt(self._camadas_poligonos_sobreposicao)

        self._renderizar_contornos_poligonos_sobre_mdt(self._camadas_poligonos_sobreposicao)

        self._renderizar_rotulos_poligonos_sobre_mdt(self._camadas_poligonos_sobreposicao)

        # Guarda o resultado completo desta qualidade.
        self._salvar_cache_poligonos_3d(
            self._camadas_poligonos_sobreposicao)

        self.view.update()
        self._solicitar_atualizacao_oclusao_rotulos()

    def _atualizar_sobreposicoes_vetoriais_cache(self):
        """
        Atualiza linhas, polígonos e pontos sem reconstruir
        a malha principal do MDT.
        """
        if not self.check_sobreposicao.isChecked():
            return

        if self._sobrepor_linhas:
            self._camadas_linhas_sobreposicao = self._obter_linhas_sobre_mdt()
        else:
            self._camadas_linhas_sobreposicao = []
            self._ocultar_linhas_cache_ativas()

        if self._sobrepor_poligonos:
            self._camadas_poligonos_sobreposicao = self._obter_poligonos_sobre_mdt()
        else:
            self._camadas_poligonos_sobreposicao = []
            self._ocultar_poligonos_cache_ativos()

        if self._sobrepor_pontos:
            self._camadas_pontos_sobreposicao = self._obter_pontos_sobre_mdt()
        else:
            self._camadas_pontos_sobreposicao = []
            self._ocultar_pontos_cache_ativos()

        self._atualizar_linhas_sobreposicao(usar_cache=True)
        self._atualizar_poligonos_sobreposicao(usar_cache=True)
        self._atualizar_pontos_sobreposicao(usar_cache=True)

    def _atualizar_sobreposicoes(self):
        """
        Atualiza raster, linhas, polígonos e pontos habilitados.
        Cada tipo mantém seu próprio ciclo de renderização.
        """
        raster_principal_estava_com_textura = (
            bool(self._camadas_raster_sobreposicao)
            and self._cores_imagem_sobreposicao is not None)

        diferenca_estava_ativa = bool(getattr(self, "_diferenca_mdt_aplicada", False))

        # Remove qualquer superfície 3D secundária existente antes de reconstruir o estado dos rasters.
        # Isso é fundamental ao trocar:
        # Superfície 3D -> Sobreposição

        # A nova representação será criada novamente abaixo, somente se o modo atual continuar sendo Superfície 3D.
        self._remover_mdts_secundarios_3d()

        self._camadas_raster_sobreposicao = []
        self._camadas_linhas_sobreposicao = []
        self._camadas_poligonos_sobreposicao = []
        self._camadas_pontos_sobreposicao = []
        self._cores_imagem_sobreposicao = None

        camadas_sobreposicao = []
        camadas_superficie_3d = []
        diferenca_ativa = False

        if not self.check_sobreposicao.isChecked():
            self._remover_expansao_raster()

            self._remover_mdts_secundarios_3d()
            self._camadas_mdt_secundario_3d = []

            self._ocultar_linhas_cache_ativas()
            self._ocultar_poligonos_cache_ativos()
            self._ocultar_pontos_cache_ativos()
            self._atualizar_estado_controles_cores(False)

            # Ao desligar Inserir Sobreposição,
            # remove também qualquer deformação aplicada ao MDT principal.
            self._diferenca_mdt_aplicada = False

            self._atualizar_geometria()
            return

        # Raster permanece associado somente à malha principal.
        if self._sobrepor_rasters:
            camadas_raster = self._obter_rasters_sobre_mdt()

            camadas_sobreposicao, camadas_superficie_3d = (
                self._separar_rasters_por_modo_3d(camadas_raster))

            # Somente os rasters realmente em modo Sobreposição
            # podem alterar a textura do MDT principal.
            self._camadas_raster_sobreposicao = list(camadas_sobreposicao)

            # Os rasters em modo Superfície 3D viram malhas independentes.
            self._camadas_mdt_secundario_3d = list(camadas_superficie_3d)

            diferenca_ativa = any(
                bool(self._obter_config_3d_camada("raster",layer).get("habilitar_diferenca", False))
                for layer in self._camadas_mdt_secundario_3d)

            self._diferenca_mdt_aplicada = (
                diferenca_ativa)

            if self._camadas_raster_sobreposicao:
                try:
                    self._cores_imagem_sobreposicao = (
                        self._renderizar_rasters_sobre_mdt(
                            self._camadas_raster_sobreposicao))

                except Exception as e:
                    self._cores_imagem_sobreposicao = None

                    if self.ui_manager is not None:
                        self.ui_manager.mostrar_mensagem(self.tr("Não foi possível criar a sobreposição raster: {erro}").format(erro=str(e)), "Erro")

        raster_ativo = (self._sobrepor_rasters
            and bool(self._camadas_raster_sobreposicao)
            and self._cores_imagem_sobreposicao is not None)

        self._atualizar_estado_controles_cores(raster_ativo)

        # Linhas são objetos OpenGL independentes.
        if self._sobrepor_linhas:
            self._camadas_linhas_sobreposicao = self._obter_linhas_sobre_mdt()

        # Polígonos são objetos OpenGL independentes.
        if self._sobrepor_poligonos:
            self._camadas_poligonos_sobreposicao = self._obter_poligonos_sobre_mdt()

        # Pontos são objetos OpenGL independentes.
        if self._sobrepor_pontos:
            self._camadas_pontos_sobreposicao = self._obter_pontos_sobre_mdt()

        # O MDT principal só precisa ser reconstruído quando:
        # 1. existe uma textura raster real sendo aplicada; ou
        # 2. havia uma textura antes e agora ela precisa ser removida.

        # Um MDT secundário em modo Superfície 3D é independente e não deve provocar qualquer alteração na malha principal.
        if (raster_ativo
            or raster_principal_estava_com_textura
            or diferenca_ativa
            or diferenca_estava_ativa):

            self._atualizar_geometria()

        else:
            # Mantém exatamente o mesmo GLMeshItem do MDT principal.
            # Atualiza somente as superfícies 3D secundárias.
            if (self._sobrepor_rasters
                and self._camadas_mdt_secundario_3d):

                self._atualizar_mdts_secundarios_3d()

            self.view.update()

        if (raster_ativo
            and not diferenca_ativa):

            self._salvar_cache_raster_sobreposto_3d(self._camadas_raster_sobreposicao)

        # A expansão raster é um objeto separado da superfície principal.
        self._atualizar_expansao_raster()

        # Sobreposições vetoriais são adicionadas depois da superfície.
        self._atualizar_poligonos_sobreposicao(usar_cache=True)
        self._atualizar_linhas_sobreposicao(usar_cache=True)
        self._atualizar_pontos_sobreposicao(usar_cache=True)

    def _amostrar_cota_mdt(self, x, y):
        """
        Obtém a elevação interpolada do MDT para uma coordenada X/Y.

        A coordenada é convertida para posição de pixel e depois
        interpolada sobre a grade atualmente utilizada no 3D.
        """
        if (self._dados_grade is None
            or self._validos_grade is None
            or self._geo_transform is None):
            return None

        gt = self._geo_transform

        determinante = (gt[1] * gt[5] - gt[2] * gt[4])

        if abs(determinante) < 1e-20:
            return None

        dx = float(x) - gt[0]
        dy = float(y) - gt[3]

        coluna = (gt[5] * dx - gt[2] * dy) / determinante

        linha = (-gt[4] * dx + gt[1] * dy) / determinante

        if (coluna < 0.0
            or linha < 0.0
            or coluna > self._raster_largura
            or linha > self._raster_altura):
            return None

        gx = (coluna * self._grade_x / self._raster_largura - 0.5)
        gy = (linha * self._grade_y / self._raster_altura - 0.5)

        gx = float(np.clip(gx, 0.0, self._grade_x - 1.0))
        gy = float(np.clip(gy, 0.0, self._grade_y - 1.0))

        x0 = int(math.floor(gx))
        y0 = int(math.floor(gy))
        x1 = min(x0 + 1, self._grade_x - 1)
        y1 = min(y0 + 1, self._grade_y - 1)

        tx = gx - x0
        ty = gy - y0

        indices = ((y0, x0), (y0, x1), (y1, x0), (y1, x1))

        pesos = np.array(((1.0 - tx) * (1.0 - ty), tx * (1.0 - ty), (1.0 - tx) * ty, tx * ty), dtype=np.float64)

        valores = np.array([self._dados_grade[iy, ix]
             for iy, ix in indices], dtype=np.float64)

        mascara = np.array([self._validos_grade[iy, ix]
             for iy, ix in indices], dtype=bool)

        mascara &= np.isfinite(valores)

        if not np.any(mascara):
            return None

        pesos_validos = pesos[mascara]
        valores_validos = valores[mascara]
        soma_pesos = float(np.sum(pesos_validos))

        if soma_pesos <= 1e-12:
            return None

        return float(np.dot(valores_validos, pesos_validos) / soma_pesos)

    def _amostrar_cotas_grade_principal(self, x, y):
        """
        Amostra, de forma vetorizada, a cota do MDT principal
        em vários pontos X/Y.
        """
        if (self._dados_grade is None
            or self._validos_grade is None
            or self._geo_transform is None):
            return None

        x = np.asarray(x, dtype=np.float64)
        y = np.asarray(y, dtype=np.float64)

        if x.shape != y.shape:
            raise ValueError(self.tr("As matrizes X e Y devem possuir o mesmo formato."))

        gt = self._geo_transform
        determinante = (gt[1] * gt[5] - gt[2] * gt[4])

        if abs(determinante) < 1e-20:
            return None

        dx = x - gt[0]
        dy = y - gt[3]

        coluna = (gt[5] * dx - gt[2] * dy) / determinante

        linha = (-gt[4] * dx + gt[1] * dy) / determinante

        dentro = ((coluna >= 0.0)
            & (linha >= 0.0)
            & (coluna <= self._raster_largura)
            & (linha <= self._raster_altura))

        resultado = np.full(x.shape, np.nan, dtype=np.float64)

        if not np.any(dentro):
            return resultado

        gx = (coluna * self._grade_x / self._raster_largura - 0.5)
        gy = (linha * self._grade_y / self._raster_altura - 0.5)

        gx = np.clip(gx, 0.0, self._grade_x - 1.0)
        gy = np.clip(gy, 0.0, self._grade_y - 1.0)

        x0 = np.floor(gx).astype(np.int32)
        y0 = np.floor(gy).astype(np.int32)
        x1 = np.minimum(x0 + 1, self._grade_x - 1)
        y1 = np.minimum(y0 + 1, self._grade_y - 1)

        tx = gx - x0
        ty = gy - y0

        w00 = (1.0 - tx) * (1.0 - ty)
        w10 = tx * (1.0 - ty)
        w01 = (1.0 - tx) * ty
        w11 = tx * ty

        v00 = self._dados_grade[y0, x0]
        v10 = self._dados_grade[y0, x1]
        v01 = self._dados_grade[y1, x0]
        v11 = self._dados_grade[y1, x1]

        m00 = (dentro
            & self._validos_grade[y0, x0]
            & np.isfinite(v00))

        m10 = (dentro
            & self._validos_grade[y0, x1]
            & np.isfinite(v10))

        m01 = (dentro
            & self._validos_grade[y1, x0]
            & np.isfinite(v01))

        m11 = (dentro
            & self._validos_grade[y1, x1]
            & np.isfinite(v11))

        soma_pesos = (
            np.where(m00, w00, 0.0)
            + np.where(m10, w10, 0.0)
            + np.where(m01, w01, 0.0)
            + np.where(m11, w11, 0.0))

        mascara = soma_pesos > 1e-12

        if not np.any(mascara):
            return resultado

        numerador = (np.where(m00, v00 * w00, 0.0)
            + np.where(m10, v10 * w10, 0.0)
            + np.where(m01, v01 * w01, 0.0)
            + np.where(m11, v11 * w11, 0.0))

        resultado[mascara] = (numerador[mascara] / soma_pesos[mascara])

        return resultado

    def _obter_camadas_diferenca_mdt_ativas(self):
        """
        Retorna os MDTs secundários que devem deformar
        temporariamente a superfície principal.
        """
        if not self.check_sobreposicao.isChecked():
            return []

        if not self._sobrepor_rasters:
            return []

        camadas = []

        for layer in self._camadas_mdt_secundario_3d:
            if layer is None:
                continue

            config = self._obter_config_3d_camada("raster", layer)

            if not bool(config.get("habilitar_diferenca", False)):

                continue

            if not self._raster_pode_ter_diferenca_3d(layer):

                continue

            camadas.append(layer)

        return camadas

    def _chave_cache_grade_diferenca_mdt(self, layer):
        """
        Chave do MDT secundário reamostrado sobre
        a grade atual do MDT principal.
        """
        extent = self.raster_layer.extent()

        crs = (self.raster_layer.crs().authid()
            if self.raster_layer.crs().isValid()
            else "")

        return (
            layer.id(),
            layer.source(),
            int(self._grade_x),
            int(self._grade_y),
            crs,
            round(float(extent.xMinimum()), 6),
            round(float(extent.yMinimum()), 6),
            round(float(extent.xMaximum()), 6),
            round(float(extent.yMaximum()), 6))

    def _abrir_raster_3d_com_gdal(self, layer):
        """
        Abre uma camada raster para uso pelo GDAL.

        Para rasters físicos compatíveis com GDAL:
        - abre diretamente.

        Para rasters virtuais/calculados do QGIS:
        - materializa temporariamente os valores reais
          fornecidos pelo provider do QGIS em GeoTIFF;
        - abre o GeoTIFF temporário com GDAL.

        Retorna:
            dataset, pasta_temporaria

        pasta_temporaria será None quando não houver
        necessidade de materialização.
        """
        if layer is None:
            raise RuntimeError(self.tr("Camada raster inválida."))

        source = layer.source()

        if source:
            source_gdal = source.split("|", 1)[0]

            if source_gdal.startswith("file://"):
                source_gdal = QUrl(source_gdal).toLocalFile()

            try:
                dataset = gdal.Open(source_gdal, gdal.GA_ReadOnly)

            except Exception:
                dataset = None

            if dataset is not None:
                return dataset, None

        # O GDAL não reconheceu a origem.
        # Materializa o provider do QGIS.
        pasta_temporaria = tempfile.mkdtemp(prefix="tempo_salvo_raster_3d_")

        caminho_temporario = os.path.join(pasta_temporaria, "raster_materializado.tif")

        try:
            provider = layer.dataProvider()

            if provider is None:
                raise RuntimeError(self.tr("A camada '{nome}' não possui provedor raster válido.").format(nome=layer.name()))

            pipe = QgsRasterPipe()

            provider_clone = provider.clone()

            if (provider_clone is None
                or not pipe.set(provider_clone)):

                raise RuntimeError(self.tr("Não foi possível preparar o provider da camada '{nome}'.").format(nome=layer.name()))

            writer = QgsRasterFileWriter(caminho_temporario)

            resultado = writer.writeRaster(pipe,
                int(layer.width()),
                int(layer.height()),
                layer.extent(),
                layer.crs())

            if (resultado
                != QgsRasterFileWriter.WriterError.NoError):

                raise RuntimeError(self.tr("Não foi possível materializar temporariamente o raster '{nome}'.").format(nome=layer.name()))

            dataset = gdal.Open(caminho_temporario, gdal.GA_ReadOnly)

            if dataset is None:
                raise RuntimeError(self.tr("O raster temporário '{nome}' não pôde ser aberto pelo GDAL.").format(nome=layer.name()))

            return (dataset, pasta_temporaria)

        except Exception:
            shutil.rmtree(pasta_temporaria, ignore_errors=True)

            raise

    def _obter_grade_mdt_secundario_no_principal(self, layer):
        """
        Reamostra o MDT secundário exatamente sobre a grade
        utilizada atualmente pelo MDT principal.

        O resultado possui exatamente:
            self._grade_y x self._grade_x

        Assim cada valor secundário corresponde diretamente
        a um vértice da malha principal.
        """
        chave = self._chave_cache_grade_diferenca_mdt(layer)
        cache = self._cache_grade_diferenca_mdt.get(chave)

        if cache is not None:
            return cache

        dataset, pasta_temporaria = (self._abrir_raster_3d_com_gdal(layer))

        band = dataset.GetRasterBand(1)

        if band is None:
            dataset = None

            raise RuntimeError(self.tr("O MDT secundário '{nome}' não possui banda de elevação válida.").format(nome=layer.name()))

        extent = self.raster_layer.extent()

        opcoes = {"format": "MEM",
            "outputBounds": (
                float(extent.xMinimum()),
                float(extent.yMinimum()),
                float(extent.xMaximum()),
                float(extent.yMaximum())),
            "width": int(self._grade_x),
            "height": int(self._grade_y),
            "resampleAlg": gdal.GRA_Bilinear,
            "outputType": gdal.GDT_Float32,
            "dstNodata": float("nan"),
            "multithread": True}

        if layer.crs().isValid():
            opcoes["srcSRS"] = (layer.crs().toWkt())

        if self.raster_layer.crs().isValid():
            opcoes["dstSRS"] = (self.raster_layer.crs().toWkt())

        nodata = band.GetNoDataValue()

        if (nodata is not None
            and np.isfinite(nodata)):

            opcoes["srcNodata"] = float(nodata)

        warp_options = gdal.WarpOptions(**opcoes)

        dataset_alinhado = gdal.Warp("", dataset, options=warp_options)

        if dataset_alinhado is None:
            dataset = None

            if pasta_temporaria is not None:
                shutil.rmtree(pasta_temporaria, ignore_errors=True)

            raise RuntimeError(self.tr("Não foi possível alinhar o MDT secundário '{nome}'.").format(nome=layer.name()))

        band_alinhada = dataset_alinhado.GetRasterBand(1)
        dados = band_alinhada.ReadAsArray()

        # O bilinear pode gerar uma fina borda NoData junto
        # ao limite do raster. Usa vizinho mais próximo apenas
        # para preencher esses pixels de borda, sem alterar
        # os valores bilineares já válidos.
        if dados is not None:
            dados = np.asarray(dados, dtype=np.float64)

            faltantes = ~np.isfinite(dados)

            if np.any(faltantes):
                opcoes_nearest = dict(opcoes)
                opcoes_nearest["resampleAlg"] = gdal.GRA_NearestNeighbour

                warp_nearest = gdal.WarpOptions(**opcoes_nearest)

                dataset_nearest = gdal.Warp("", dataset, options=warp_nearest)

                if dataset_nearest is not None:
                    band_nearest = (dataset_nearest.GetRasterBand(1))

                    dados_nearest = (band_nearest.ReadAsArray())

                    if dados_nearest is not None:
                        dados_nearest = np.asarray(dados_nearest, dtype=np.float64)

                        preencher = (faltantes
                            & np.isfinite(dados_nearest))

                        dados[preencher] = (dados_nearest[preencher])

                    dataset_nearest = None

        dataset_alinhado = None
        dataset = None

        if pasta_temporaria is not None:
            shutil.rmtree(
                pasta_temporaria,
                ignore_errors=True)

        if dados is None:
            raise RuntimeError(self.tr("Não foi possível ler a grade alinhada do MDT secundário '{nome}'.").format( nome=layer.name()))

        dados = np.asarray(dados, dtype=np.float64)
        validos = np.isfinite(dados)

        resultado = {"dados": dados, "validos": validos}

        self._cache_grade_diferenca_mdt[chave] = resultado

        return resultado

    def _deformar_vertices_principais_com_diferenca(self, vertices):
        """
        Deforma temporariamente a malha principal usando:

            Zvisual = Zprincipal + ΔZ
        """
        diferencas, mascara = (self._calcular_diferencas_vertices_principais())

        if (diferencas is None
            or mascara is None):

            return vertices

        vertices = vertices.copy()

        vertices[mascara, 2] += diferencas[mascara].astype(np.float32)

        return vertices

    def _gerar_cores_corte_aterro_vertices(self):
        """
        Gera as cores de corte e aterro somente na área
        correspondente ao MDT secundário.

        Fora da área do MDT secundário:
        - mantém as cores normais do MDT principal.

        Dentro da área do MDT secundário:
        - vermelho -> corte;
        - branco   -> sem modificação;
        - azul     -> aterro.
        """
        camadas = []

        for layer in (self._obter_camadas_diferenca_mdt_ativas()):
            config = self._obter_config_3d_camada("raster", layer)

            if bool(config.get("mostrar_cores_diferenca", False)):
                camadas.append(layer)

        if not camadas:
            return None

        diferencas, mascara = (self._calcular_diferencas_vertices_principais(camadas))

        if (diferencas is None
            or mascara is None):

            return None

        # Começa usando exatamente as cores normais
        # do MDT principal.
        cores = (self._gerar_cores_vertices_suaves())

        if cores is None:
            return None

        cores = np.asarray(cores, dtype=np.float32).copy()

        # Tolerância para considerar que não houve
        # modificação significativa.
        tolerancia = 0.01

        corte = (mascara
            & (diferencas < -tolerancia))

        aterro = ( mascara
            & (diferencas > tolerancia))

        sem_modificacao = (mascara
            & ~corte
            & ~aterro)

        # Corte = vermelho.
        cores[corte, 0] = 1.0
        cores[corte, 1] = 0.0
        cores[corte, 2] = 0.0
        cores[corte, 3] = 1.0

        # Aterro = azul.
        cores[aterro, 0] = 0.0
        cores[aterro, 1] = 0.0
        cores[aterro, 2] = 1.0
        cores[aterro, 3] = 1.0

        # Sem modificação = branco.
        cores[sem_modificacao, 0] = 1.0
        cores[sem_modificacao, 1] = 1.0
        cores[sem_modificacao, 2] = 1.0
        cores[sem_modificacao, 3] = 1.0

        return cores

    def _calcular_diferencas_vertices_principais(self, camadas=None):
        """
        Calcula:

            ΔZ = Zsecundário - Zprincipal

        diretamente sobre os vértices da grade principal.

        Retorna:
            diferencas
            mascara
        """
        if (self._vertices_base is None
            or self._z_valores is None
            or self._validos is None):

            return None, None

        if camadas is None:
            camadas = (self._obter_camadas_diferenca_mdt_ativas())

        if not camadas:
            return None, None

        quantidade = len(self._vertices_base)

        diferencas = np.zeros(quantidade, dtype=np.float64)

        mascara_final = np.zeros(quantidade, dtype=bool)

        z_principal = np.asarray(self._z_valores, dtype=np.float64)

        validos_principal = np.asarray(self._validos, dtype=bool)

        for layer in camadas:
            grade = (self._obter_grade_mdt_secundario_no_principal(layer))

            dados_secundario = np.asarray(grade["dados"], dtype=np.float64).ravel()

            validos_secundario = np.asarray(grade["validos"], dtype=bool).ravel()

            if dados_secundario.size != quantidade:
                continue

            mascara = (validos_principal
                & validos_secundario
                & np.isfinite(z_principal)
                & np.isfinite(dados_secundario))

            if not np.any(mascara):
                continue

            diferencas[mascara] = ( dados_secundario[mascara] - z_principal[mascara])

            mascara_final[mascara] = True

        if not np.any(mascara_final):
            return None, None

        return (diferencas, mascara_final)

    def _gerar_cores_diferenca_mdt_3d(self, z_diferenca, mascara_diff, opacidade):
        """
        Gera uma rampa divergente para a diferença entre MDTs.

        Negativo -> vermelho
        Zero     -> branco
        Positivo -> azul
        """
        diferenca = np.asarray(z_diferenca, dtype=np.float64)

        mascara = (np.asarray(mascara_diff, dtype=bool)
            & np.isfinite(diferenca))

        cores = np.zeros((len(diferenca), 4), dtype=np.float32)

        if not np.any(mascara):
            return cores

        max_abs = float(np.max(np.abs(diferenca[mascara])))

        if max_abs <= 1e-12:
            cores[mascara] = (1.0, 1.0, 1.0, opacidade)

            return cores

        intensidade = np.zeros(len(diferenca), dtype=np.float64)

        intensidade[mascara] = np.clip(np.abs( diferenca[mascara]) / max_abs, 0.0, 1.0)

        negativos = (mascara
            & (diferenca < 0.0))

        positivos = (mascara
            & (diferenca > 0.0))

        zeros = ( mascara
            & np.isclose(diferenca, 0.0, atol=1e-12))

        # Negativo:
        # branco -> vermelho.
        cores[negativos, 0] = 1.0

        cores[negativos, 1] = (1.0 - intensidade[negativos])
        cores[negativos, 2] = (1.0 - intensidade[negativos])

        # Positivo:
        # branco -> azul.
        cores[positivos, 0] = ( 1.0 - intensidade[positivos])
        cores[positivos, 1] = (1.0 - intensidade[positivos])
        cores[positivos, 2] = 1.0

        # Diferença zero.
        cores[zeros, 0] = 1.0
        cores[zeros, 1] = 1.0
        cores[zeros, 2] = 1.0

        cores[mascara, 3] = float(opacidade)

        return cores

    def _amostrar_cota_malha_3d(self, x, y):
        """
        Obtém a cota exatamente sobre a superfície triangular exibida no 3D.

        Diferente da interpolação bilinear usada por _amostrar_cota_mdt(),
        esta função respeita a mesma divisão em dois triângulos utilizada
        para construir o GLMeshItem do terreno.
        """
        if (self._dados_grade is None
            or self._validos_grade is None
            or self._geo_transform is None):
            return None

        gt = self._geo_transform
        determinante = (gt[1] * gt[5] - gt[2] * gt[4])

        if abs(determinante) < 1e-20:
            return None

        dx = float(x) - gt[0]
        dy = float(y) - gt[3]

        coluna = (gt[5] * dx - gt[2] * dy) / determinante
        linha = (-gt[4] * dx + gt[1] * dy) / determinante

        if (coluna < 0.0
            or linha < 0.0
            or coluna > self._raster_largura
            or linha > self._raster_altura):
            return None

        gx = (coluna * self._grade_x / self._raster_largura - 0.5)
        gy = (linha * self._grade_y / self._raster_altura - 0.5)
        gx = float(np.clip(gx, 0.0, self._grade_x - 1.0))
        gy = float(np.clip(gy, 0.0, self._grade_y - 1.0))

        x0 = int(math.floor(gx))
        y0 = int(math.floor(gy))

        x1 = min(x0 + 1, self._grade_x - 1)
        y1 = min(y0 + 1, self._grade_y - 1)

        if (x0 == x1
            or y0 == y1):
            if not self._validos_grade[y0, x0]:
                return None

            return float(self._dados_grade[y0, x0])

        if not (self._validos_grade[y0, x0]
            and self._validos_grade[y0, x1]
            and self._validos_grade[y1, x0]
            and self._validos_grade[y1, x1]):
            return None

        z00 = float(self._dados_grade[y0, x0])
        z01 = float(self._dados_grade[y0, x1])
        z10 = float(self._dados_grade[y1, x0])
        z11 = float(self._dados_grade[y1, x1])

        tx = gx - x0
        ty = gy - y0

        # Mesmo triângulo (a, b, c) usado na malha.
        if tx + ty <= 1.0:
            return (z00 + tx * (z01 - z00) + ty * (z10 - z00))

        # Mesmo triângulo (b, d, c) usado na malha.
        return (z11 + (1.0 - ty) * (z01 - z11) + (1.0 - tx) * (z10 - z11))

    def _amostrar_z_visual_malha_3d(self, x, y, z_grade=None):
        """
        Obtém o Z da superfície exatamente como ela está
        sendo exibida no visualizador.

        Se z_grade for fornecido, reutiliza a geometria
        já preparada, evitando reconstruir toda a malha
        durante a procura da coordenada.
        """
        if (self._vertices_base is None
            or self._validos_grade is None
            or self._geo_transform is None):

            return None

        gt = self._geo_transform

        determinante = (gt[1] * gt[5] - gt[2] * gt[4])

        if abs(determinante) < 1e-20:
            return None

        dx = float(x) - gt[0]
        dy = float(y) - gt[3]

        coluna = (gt[5] * dx - gt[2] * dy) / determinante
        linha = (-gt[4] * dx + gt[1] * dy) / determinante

        if (coluna < 0.0
            or linha < 0.0
            or coluna > self._raster_largura
            or linha > self._raster_altura):

            return None

        gx = (coluna * self._grade_x / self._raster_largura - 0.5)
        gy = (linha * self._grade_y / self._raster_altura - 0.5)

        gx = float(np.clip(gx, 0.0, self._grade_x - 1.0))
        gy = float(np.clip(gy, 0.0, self._grade_y - 1.0))

        x0 = int(math.floor(gx))
        y0 = int(math.floor(gy))

        x1 = min(x0 + 1, self._grade_x - 1)
        y1 = min(y0 + 1,self._grade_y - 1)

        # Só reconstrói a geometria quando nenhuma
        # grade pronta tiver sido fornecida.
        if z_grade is None:
            vertices = (self._vertices_com_exagero())

            z_grade = (vertices[:, 2].reshape( self._grade_y, self._grade_x))

        if (x0 == x1
            or y0 == y1):

            if not self._validos_grade[y0, x0]:

                return None

            return float(z_grade[y0, x0])

        if not (self._validos_grade[y0, x0]
            and self._validos_grade[y0, x1]
            and self._validos_grade[y1, x0]
            and self._validos_grade[y1, x1]):

            return None

        z00 = float(z_grade[y0, x0])
        z01 = float(z_grade[y0, x1])

        z10 = float(z_grade[y1, x0])
        z11 = float(z_grade[y1, x1])

        tx = gx - x0
        ty = gy - y0

        if tx + ty <= 1.0:
            return (z00 + tx * (z01 - z00) + ty * (z10 - z00))

        return (z11 + (1.0 - ty) * (z01 - z11) + (1.0 - tx) * (z10 - z11))
        
    def _densificar_parte_linha(self, pontos):
        """
        Acrescenta pontos intermediários para a linha acompanhar
        corretamente as variações do terreno.
        """
        if not pontos or len(pontos) < 2:
            return []

        extensao = self.raster_layer.extent()

        passo_x = abs(extensao.width() / max(self._grade_x - 1, 1))
        passo_y = abs(extensao.height() / max(self._grade_y - 1, 1))

        passos_validos = [valor
            for valor in (passo_x, passo_y)
            if valor > 0.0]

        passo = (min(passos_validos) * 0.75
            if passos_validos
            else 1.0)

        passo = max(passo, 1e-9)
        resultado = []

        for indice in range(len(pontos) - 1):
            p1 = pontos[indice]
            p2 = pontos[indice + 1]

            x1 = float(p1.x())
            y1 = float(p1.y())
            x2 = float(p2.x())
            y2 = float(p2.y())

            distancia = math.hypot(x2 - x1, y2 - y1)

            quantidade = max(1, min(2000, int(math.ceil(distancia / passo))))

            for passo_indice in range(quantidade):
                fator = (passo_indice / quantidade)

                resultado.append((x1 + (x2 - x1) * fator, y1 + (y2 - y1) * fator))

        ultimo = pontos[-1]

        resultado.append((float(ultimo.x()), float(ultimo.y())))

        return resultado

    def _simbolos_feature_3d(self, renderer, feature, contexto):
        """
        Retorna todos os símbolos aplicáveis à feição.

        Suporta renderizadores simples, categorizados,
        graduados e baseados em regras, inclusive quando
        mais de uma regra é válida para a mesma feição.
        """
        if renderer is None:
            return [None]

        try:
            simbolos = list(renderer.symbolsForFeature(feature, contexto) or [])
        except Exception:
            try:
                simbolo = renderer.symbolForFeature(feature, contexto)
                simbolos = [simbolo] if simbolo is not None else []
            except Exception:
                simbolos = []

        return [simbolo for simbolo in simbolos if simbolo is not None]

    def _estilo_linha_3d(self, simbolo):
        """
        Converte a cor e a espessura do símbolo QGIS para valores
        utilizados pelo GLLinePlotItem.
        """
        cor = QColor(255, 0, 0)
        largura = 2.0
        opacidade = 1.0

        if simbolo is not None:
            try:
                cor = QColor(simbolo.color())
            except Exception:
                pass  # nosec B110

            try:
                opacidade = float(simbolo.opacity())
            except Exception:
                opacidade = 1.0

            try:
                largura_qgis = float(simbolo.width())
                largura = max(1.5, min( 8.0, largura_qgis * 2.5))
            except Exception:
                largura = 2.0

        rgba = (cor.redF(), cor.greenF(), cor.blueF(),max(0.0, min(1.0, cor.alphaF() * opacidade)))

        return rgba, largura

    def _cor_rotulo_linha_qgis(self, layer, feature=None, contexto=None):
        """
        Obtém a cor real do rótulo da camada QGIS.

        Respeita:
        - cor fixa do QgsTextFormat;
        - cor definida por expressão;
        - cor definida por campo;
        - demais overrides data-defined suportados pelo QGIS.
        """
        cor_padrao = QColor(255, 255, 255, 255)

        if layer is None:
            return cor_padrao

        try:
            if not layer.labelsEnabled():
                return cor_padrao
        except Exception:
            return cor_padrao

        try:
            labeling = layer.labeling()

            if labeling is None:
                return cor_padrao

            settings = labeling.settings()

            if settings is None:
                return cor_padrao

            formato = settings.format()

            if formato is not None:
                cor_base = QColor(formato.color())
            else:
                cor_base = QColor(cor_padrao)

            if not cor_base.isValid():
                cor_base = QColor(cor_padrao)

            # Sem feição/contexto, retorna apenas o estilo fixo.
            if feature is None or contexto is None:
                return cor_base

            expression_context = contexto.expressionContext()
            expression_context.setFields(layer.fields())
            expression_context.setFeature(feature)
            propriedades = settings.dataDefinedProperties()

            if propriedades.isActive(QgsPalLayerSettings.Property.Color):

                cor = propriedades.valueAsColor(QgsPalLayerSettings.Property.Color, expression_context, cor_base)

                if cor.isValid():
                    return cor

            return cor_base

        except Exception:
            return cor_padrao

    def _texto_rotulo_feature(self, feature, campo):
        """
        Obtém o texto de rótulo a partir do campo selecionado.
        Remove apenas o decimal .0 de valores numéricos inteiros.
        """
        if feature is None or not campo:
            return ""

        try:
            valor = feature[campo]
        except Exception:
            return ""

        if valor is None:
            return ""

        if isinstance(valor, (float, np.floating)):
            valor_float = float(valor)

            if (np.isfinite(valor_float)
                and valor_float.is_integer()):

                return str(int(valor_float))

        texto = str(valor).strip()

        if not texto:
            return ""

        return texto

    def _posicao_rotulo_linha_3d(self, geometria, altura_linha, altura_rotulo):
        """
        Obtém a posição 3D do rótulo aproximadamente no centro da linha.

        A altura do rótulo é relativa à altura da própria linha.
        """
        if geometria is None or geometria.isEmpty():
            return None

        try:
            comprimento = float(geometria.length())
        except Exception:
            return None

        if comprimento <= 0.0:
            return None

        try:
            geometria_ponto = geometria.interpolate(comprimento * 0.5)
        except Exception:
            return None

        if geometria_ponto is None or geometria_ponto.isEmpty():
            return None

        try:
            ponto = geometria_ponto.asPoint()
            x = float(ponto.x())
            y = float(ponto.y())
        except Exception:
            return None

        z_terreno = self._amostrar_cota_mdt(x, y)

        if z_terreno is None:
            return None

        exagero = float(self.spin_exagero.value())

        z = (
            (z_terreno - self._z_centro) * exagero
            + float(altura_linha) * exagero
            + float(altura_rotulo) * exagero)

        return np.asarray((
            x - self._x_centro,
            y - self._y_centro,
            z), dtype=np.float32)

    def _criar_rotulo_linha_3d(self, texto, posicao, cor, tamanho, ordem):
        """
        Cria um rótulo de texto na cena 3D.
        """
        if not texto or posicao is None:
            return None

        fonte = QFont()
        fonte.setPointSize(max(6, int(tamanho)))

        try:
            item = gl.GLTextItem(
                pos=posicao,
                color=cor,
                text=texto,
                font=fonte)
        except Exception:
            return None

        try:
            item.setDepthValue(40.0 + ordem)
        except Exception:
            pass  # nosec B110

        self.view.addItem(item)
        self._itens_rotulos_linhas_sobreposicao.append(item)

        return item

    def _criar_rotulo_ponto_3d(self, texto, posicao, cor, tamanho, ordem):
        """
        Cria um rótulo associado a um ponto.
        """
        if not texto or posicao is None:
            return None

        fonte = QFont()
        fonte.setPointSize(max(6, int(tamanho)))

        try:
            item = gl.GLTextItem(
                pos=posicao,
                color=cor,
                text=texto,
                font=fonte)
        except Exception:
            return None

        try:
            item.setDepthValue(40.0 + ordem)
        except Exception:
            pass  # nosec B110

        self.view.addItem(item)
        self._itens_rotulos_pontos_sobreposicao.append(item)

        return item

    def _registrar_rotulo_oclusao(self, item, tipo, layer, posicao):
        """
        Armazena no GLTextItem as informações necessárias para
        verificar sua oclusão sem reconstruir o rótulo.
        """
        if item is None or layer is None or posicao is None:
            return

        item._tempo_salvo_tipo_rotulo = tipo
        item._tempo_salvo_layer_id = layer.id()
        item._tempo_salvo_posicao_rotulo = np.asarray(
            posicao,
            dtype=np.float64)

    def _solicitar_atualizacao_oclusao_rotulos(self):
        """
        Agenda a atualização da oclusão.
        """
        self._timer_oclusao_rotulos.start()

    def _preparar_atualizacao_oclusao_rotulos(self):
        """
        Prepara a leitura do depth buffer no próximo frame.
        """
        self._oclusao_rotulos_pendente = True
        self.view.update()

    def _todos_rotulos_3d(self):
        """
        Retorna todos os GLTextItem atualmente presentes na cena.
        """
        return (
            list(self._itens_rotulos_linhas_sobreposicao)
            + list(self._itens_rotulos_poligonos_sobreposicao)
            + list(self._itens_rotulos_pontos_sobreposicao))

    def _config_rotulo_oclusao_ativa(self, item):
        """
        Consulta dinamicamente a configuração atual da camada.

        Isso permite marcar/desmarcar 'Ocultar rótulos encobertos'
        sem recriar o GLTextItem.
        """
        tipo = getattr(item, "_tempo_salvo_tipo_rotulo", None)

        layer_id = getattr(item, "_tempo_salvo_layer_id", None)

        if tipo not in ("linhas", "poligonos", "pontos"):
            return False

        if not layer_id:
            return False

        layer = QgsProject.instance().mapLayer(layer_id)

        if layer is None:
            return False

        config = self._obter_config_3d_camada(tipo, layer)

        return bool(config.get("ocultar_rotulo_encoberto", False))

    def _definir_visibilidade_rotulo_3d(self, item, visivel):
        """
        Altera a visibilidade somente quando necessário,
        evitando atualizações OpenGL redundantes.
        """
        try:
            visivel_atual = bool(item.visible())

            if visivel_atual == bool(visivel):
                return

        except Exception:
            pass  # nosec B110

        try:
            item.setVisible(bool(visivel))
        except Exception:
            pass  # nosec B110

    def _profundidade_rotulo_visivel(self, item, matriz_mvp, viewport):
        """
        Compara a profundidade da âncora do rótulo com o depth buffer.

        Usa o viewport OpenGL real e uma janela 3 x 3 para
        reduzir oscilações junto às bordas.
        """
        posicao = getattr(item, "_tempo_salvo_posicao_rotulo", None)

        if posicao is None or len(posicao) < 3:
            return True

        x_view, y_view, largura, altura = viewport

        if largura <= 0 or altura <= 0:
            return True

        try:
            vetor = QVector4D(
                float(posicao[0]),
                float(posicao[1]),
                float(posicao[2]),
                1.0)

            clip = matriz_mvp * vetor

            w = float(clip.w())

            if abs(w) <= 1e-12:
                return False

            ndc_x = float(clip.x()) / w
            ndc_y = float(clip.y()) / w
            ndc_z = float(clip.z()) / w

        except Exception:
            return True

        if (ndc_x < -1.0
            or ndc_x > 1.0
            or ndc_y < -1.0
            or ndc_y > 1.0
            or ndc_z < -1.0
            or ndc_z > 1.0):
            return False

        x_pixel = (x_view + int(round((ndc_x + 1.0) * 0.5 * max(0, largura - 1))))
        y_pixel = (y_view + int(round((ndc_y + 1.0) * 0.5 * max(0, altura - 1))))

        profundidade_rotulo = (ndc_z + 1.0) * 0.5

        x_min = x_view
        y_min = y_view
        x_max = x_view + largura - 1
        y_max = y_view + altura - 1

        x0 = max(x_min, x_pixel - 1)
        y0 = max(y_min, y_pixel - 1)

        x1 = min(x_max, x_pixel + 1)
        y1 = min(y_max, y_pixel + 1)

        largura_leitura = x1 - x0 + 1
        altura_leitura = y1 - y0 + 1

        if (largura_leitura <= 0
            or altura_leitura <= 0):
            return True

        try:
            dados = GL.glReadPixels(
                x0,
                y0,
                largura_leitura,
                altura_leitura,
                GL.GL_DEPTH_COMPONENT,
                GL.GL_FLOAT)

            if isinstance(
                dados,
                (bytes, bytearray, memoryview)):

                profundidades = np.frombuffer(dados, dtype=np.float32)

            else:
                profundidades = np.asarray(dados, dtype=np.float32).reshape(-1)

        except Exception as e:
            self._log_oclusao(f"ERRO glReadPixels: {repr(e)}", Qgis.MessageLevel.Critical)

            return True

        if profundidades.size == 0:
            return True

        profundidades = profundidades[np.isfinite(profundidades)]

        if profundidades.size == 0:
            return True

        # Maior valor da vizinhança cria uma pequena tolerância
        # quando a âncora tangencia uma borda.
        profundidade_cena = float(np.median(profundidades))

        if profundidade_cena >= 0.999999:
            return True

        tolerancia = 1.0e-5

        return not (profundidade_rotulo > profundidade_cena + tolerancia)

    def _log_oclusao(self, mensagem, nivel=None):
        """
        Envia mensagens de diagnóstico da oclusão
        para o painel de Log do QGIS.
        """
        if nivel is None:
            nivel = Qgis.MessageLevel.Info

        QgsMessageLog.logMessage(str(mensagem), "Tempo Salvo 3D - Oclusão", nivel)

    def _atualizar_oclusao_rotulos(self):
        """
        Atualiza a visibilidade dos rótulos usando o depth buffer da cena.
        Com MSAA ativo, a profundidade é resolvida antes para um FBO auxiliar.
        """
        if not self._oclusao_rotulos_pendente:
            return

        self._oclusao_rotulos_pendente = False
        itens = self._todos_rotulos_3d()

        if not itens:
            return

        itens_ativos = []

        for item in itens:
            if item is None:
                continue

            if self._config_rotulo_oclusao_ativa(item):
                itens_ativos.append(item)
            else:
                self._definir_visibilidade_rotulo_3d(item, True)

        if not itens_ativos:
            return

        depth_preparado = False

        try:
            depth_preparado = self.view.preparar_depth_para_leitura()

            if not depth_preparado:
                self._log_oclusao("Não foi possível preparar o depth buffer para a oclusão.", Qgis.MessageLevel.Warning)

                for item in itens_ativos:
                    self._definir_visibilidade_rotulo_3d(item, True)

                return

            viewport = self.view.obter_viewport_depth_leitura()

            if viewport is None:
                return

            try:
                modelview = self.view.viewMatrix()

                try:
                    projection = self.view.projectionMatrix()

                except TypeError:
                    viewport_view = self.view.getViewport()
                    projection = self.view.projectionMatrix(viewport_view, viewport_view)

                matriz_mvp = (projection * modelview)

            except Exception as e:
                self._log_oclusao(f"ERRO ao montar matriz MVP: {repr(e)}", Qgis.MessageLevel.Critical)
                return

            for item in itens_ativos:
                visivel = self._profundidade_rotulo_visivel(item, matriz_mvp, viewport)

                self._definir_visibilidade_rotulo_3d(item, visivel)

        except Exception as e:
            self._log_oclusao(f"ERRO ao atualizar oclusão dos rótulos: {repr(e)}", Qgis.MessageLevel.Critical)

            for item in itens_ativos:
                self._definir_visibilidade_rotulo_3d(item, True)

        finally:
            self.view.restaurar_framebuffer_padrao()

    def _segmentos_linha_3d(self, pontos, altura_sobre_terreno=0.05):
        """
        Converte uma parte de linha em segmentos 3D aderidos ao MDT.

        A altura_sobre_terreno é dada nas unidades verticais do MDT
        e também acompanha o exagero vertical da cena.
        """
        pontos_densos = self._densificar_parte_linha(pontos)

        if not pontos_densos:
            return []

        exagero = float(self.spin_exagero.value())
        altura_3d = float(altura_sobre_terreno) * exagero

        # Folga exclusivamente visual para impedir z-fighting
        # entre a linha e a superfície triangular do MDT.
        folga_z = max(0.02, abs(self._z_max - self._z_min) * exagero * 0.0001)

        segmentos = []
        segmento_atual = []

        for x, y in pontos_densos:
            z = self._amostrar_cota_malha_3d(x, y)

            if z is None:
                if len(segmento_atual) >= 2:
                    segmentos.append(np.asarray(segmento_atual, dtype=np.float32))

                segmento_atual = []
                continue

            z_3d = (z - self._z_centro) * exagero + altura_3d + folga_z
            segmento_atual.append((x - self._x_centro, y - self._y_centro, z_3d))

        if len(segmento_atual) >= 2:
            segmentos.append(np.asarray(segmento_atual, dtype=np.float32))

        return segmentos

    def _criar_parede_poligono_3d(self, segmento, altura_sobre_terreno):
        """
        Cria uma parede vertical entre o contorno elevado do polígono
        e sua posição original sobre o MDT.

        Funciona tanto para elevação positiva quanto negativa.
        """
        if segmento is None or len(segmento) < 2:
            return None, None

        exagero = float(self.spin_exagero.value())
        altura_3d = float(altura_sobre_terreno) * exagero

        if abs(altura_3d) <= 1e-9:
            return None, None

        topo = np.asarray(segmento, dtype=np.float32)
        base = topo.copy()

        # Retorna cada vértice à posição original sobre o terreno.
        base[:, 2] -= altura_3d

        vertices = []
        faces = []

        for indice in range(len(topo) - 1):
            p_base_1 = base[indice]
            p_base_2 = base[indice + 1]
            p_topo_1 = topo[indice]
            p_topo_2 = topo[indice + 1]

            inicio = len(vertices)

            vertices.extend((
                p_base_1,
                p_base_2,
                p_topo_2,
                p_topo_1))

            faces.extend((
                (inicio, inicio + 1, inicio + 2),
                (inicio, inicio + 2, inicio + 3)))

        if not vertices or not faces:
            return None, None

        return (
            np.asarray(vertices, dtype=np.float32),
            np.asarray(faces, dtype=np.uint32))

    def _criar_parede_segmento_linha(self, segmento, altura_sobre_terreno):
        """
        Cria vértices e faces da parede vertical compreendida entre
        a linha elevada e sua projeção sobre o terreno.
        """
        if segmento is None or len(segmento) < 2:
            return None, None

        exagero = float(self.spin_exagero.value())
        altura_3d = float(altura_sobre_terreno) * exagero

        if altura_3d <= 1e-9:
            return None, None

        topo = np.asarray(segmento, dtype=np.float32)
        base = topo.copy()
        base[:, 2] -= altura_3d

        vertices = []
        faces = []

        for indice in range(len(topo) - 1):
            base_1 = base[indice]
            base_2 = base[indice + 1]
            topo_1 = topo[indice]
            topo_2 = topo[indice + 1]

            inicio = len(vertices)

            vertices.extend((base_1, base_2, topo_2, topo_1))

            faces.extend((
                (inicio, inicio + 1, inicio + 2),
                (inicio, inicio + 2, inicio + 3)))

        if not vertices or not faces:
            return None, None

        return (
            np.asarray(vertices, dtype=np.float32),
            np.asarray(faces, dtype=np.uint32))

    def _criar_malha_hastes_verticais(self, segmentos, espessura, lados=8):
        """
        Cria uma única malha 3D contendo hastes verticais.

        A espessura é definida em unidades da cena,
        portanto acompanha naturalmente o zoom.
        """
        if not segmentos:
            return None, None

        raio = max(0.0001, float(espessura) * 0.5)
        lados = max(4, int(lados))

        vertices = []
        faces = []

        for indice in range(0,len(segmentos) - 1, 2):

            p0 = np.asarray(segmentos[indice], dtype=np.float64)
            p1 = np.asarray(segmentos[indice + 1], dtype=np.float64)

            if (p0.shape[0] < 3
                or p1.shape[0] < 3):

                continue

            x = float((p0[0] + p1[0]) * 0.5)
            y = float((p0[1] + p1[1]) * 0.5)

            z0 = float(p0[2])
            z1 = float(p1[2])

            if abs(z1 - z0) <= 1e-12:
                continue

            inicio = len(vertices)

            for i in range(lados):
                angulo = (2.0 * math.pi * i / lados)

                dx = (math.cos(angulo) * raio)
                dy = (math.sin(angulo) * raio)

                vertices.append((x + dx, y + dy, z0))
                vertices.append((x + dx, y + dy, z1))

            centro_inferior = len(vertices)
            vertices.append((x, y, z0))

            centro_superior = len(vertices)
            vertices.append((x, y, z1))

            for i in range(lados):
                proximo = ((i + 1) % lados)

                b0 = inicio + i * 2
                t0 = b0 + 1

                b1 = inicio + proximo * 2
                t1 = b1 + 1

                # Laterais.
                faces.append((b0, b1, t1))
                faces.append((b0, t1, t0))

                # Base.
                faces.append((centro_inferior, b1, b0))

                # Topo.
                faces.append((centro_superior, t0, t1))

        if not vertices or not faces:
            return None, None

        return (np.asarray(vertices,dtype=np.float32), np.asarray(faces, dtype=np.uint32))

    def _renderizar_pontos_sobre_mdt(self, camadas):
        """
        Renderiza os pontos sobre o MDT respeitando configuração
        individual por camada.

        Permite controlar:
        - altura do ponto;
        - tamanho do ponto;
        - exibição da haste;
        - altura da haste;
        - espessura da haste.

        A cor continua vindo da simbologia do QGIS.
        """
        if not camadas:
            return

        exagero = float(self.spin_exagero.value())
        folga_z = max(0.002, abs(self._z_max - self._z_min) * exagero * 0.00002)

        if self.ui_manager is not None:
            contexto = QgsRenderContext.fromMapSettings(self.ui_manager.iface.mapCanvas().mapSettings())
        else:
            contexto = QgsRenderContext()

        for ordem, layer in enumerate(reversed(camadas)):
            config = self._obter_config_3d_camada("pontos", layer)

            altura = float(config.get("altura", 0.05))
            tamanho_config = max(1.0, float(config.get("tamanho", 7.0)))
            mostrar_haste = bool(config.get("haste", False))
            altura_haste = max(0.0, float(config.get("altura_haste", 5.0)))

            espessura_haste = max(0.10, float(config.get("espessura_haste", 1.0)))
            mostrar_rotulo = bool(config.get("rotulo", False))

            altura_rotulo = max(0.0, float(config.get("altura_rotulo", 0.5)))
            tamanho_rotulo = max(6, int(config.get("tamanho_rotulo", 10)))
            campo_rotulo = config.get("campo_rotulo")
            cor_rotulo = self._cor_rotulo_ponto_qgis(layer)

            altura_3d = altura * exagero
            altura_haste_3d = altura_haste * exagero
            altura_rotulo_3d = altura_rotulo * exagero

            transformacao = None

            if (layer.crs().isValid()
                and self.raster_layer.crs().isValid()
                and layer.crs() != self.raster_layer.crs()):

                transformacao = QgsCoordinateTransform(layer.crs(), self.raster_layer.crs(), QgsProject.instance())

            renderer = layer.renderer()

            grupos_pontos = {}
            grupos_hastes = {}

            if renderer is not None:
                try:
                    renderer.startRender(contexto, layer.fields())
                except Exception:
                    renderer = None

            try:
                for feature in layer.getFeatures():
                    geometria = feature.geometry()

                    if (geometria is None
                        or geometria.isEmpty()):
                        continue

                    if transformacao is not None:
                        try:
                            geometria.transform(transformacao)
                        except Exception as e:
                            self._registrar_erro_sobreposicao_3d(self.tr("Falha ao transformar a geometria para o CRS do MDT"), e)
                            continue

                    if geometria.isMultipart():
                        pontos = geometria.asMultiPoint()
                    else:
                        ponto = geometria.asPoint()
                        pontos = [ponto] if ponto else []

                    if not pontos:
                        continue

                    simbolo = None

                    if renderer is not None:
                        try:
                            simbolo = renderer.symbolForFeature(feature, contexto)
                        except Exception:
                            simbolo = None

                        if simbolo is None:
                            try:
                                simbolo = renderer.symbol()
                            except Exception:
                                simbolo = None

                        if simbolo is None:
                            continue

                    cor, _ = self._estilo_ponto_3d(simbolo)

                    chave_ponto = (tuple(round(valor, 5) for valor in cor), round(tamanho_config, 2))

                    posicoes = grupos_pontos.setdefault(chave_ponto, [])

                    chave_haste = (tuple(round(valor, 5) for valor in cor), round(espessura_haste, 2))

                    hastes = grupos_hastes.setdefault(chave_haste, [])

                    texto_rotulo = ""

                    if (mostrar_rotulo
                        and campo_rotulo):

                        texto_rotulo = self._texto_rotulo_feature(feature, campo_rotulo)

                    for ponto in pontos:
                        x = float(ponto.x())
                        y = float(ponto.y())

                        z = self._amostrar_cota_mdt(x, y)

                        if z is None:
                            continue

                        x_3d = x - self._x_centro
                        y_3d = y - self._y_centro

                        z_ponto = ((z - self._z_centro) * exagero + altura_3d + folga_z)

                        posicoes.append((x_3d, y_3d, z_ponto))

                        if (mostrar_haste
                            and altura_haste_3d > 1e-9):

                            z_topo = (z_ponto + altura_haste_3d)

                            hastes.extend(((x_3d, y_3d, z_ponto), (x_3d, y_3d, z_topo)))

                        if texto_rotulo:
                            z_base_rotulo = z_ponto

                            if (mostrar_haste
                                and altura_haste_3d > 1e-9):
                                z_base_rotulo += altura_haste_3d

                            z_rotulo = (z_base_rotulo + altura_rotulo_3d)

                            posicao_rotulo = np.asarray((x_3d, y_3d, z_rotulo), dtype=np.float32)

                            item_rotulo = self._criar_rotulo_ponto_3d(
                                texto_rotulo,
                                posicao_rotulo,
                                cor_rotulo,
                                tamanho_rotulo,
                                ordem)

                            self._registrar_rotulo_oclusao(
                                item_rotulo,
                                "pontos",
                                layer,
                                posicao_rotulo)

            finally:
                if renderer is not None:
                    try:
                        renderer.stopRender(contexto)
                    except Exception:
                        pass  # nosec B110

            # Hastes são desenhadas primeiro.
            if mostrar_haste:
                for chave, posicoes_hastes in grupos_hastes.items():
                    if not posicoes_hastes:
                        continue

                    cor, espessura = chave

                    vertices_haste, faces_haste = (
                        self._criar_malha_hastes_verticais(
                            posicoes_hastes,
                            espessura,
                            lados=8))

                    if (vertices_haste is None
                        or faces_haste is None):

                        continue

                    mesh_data_haste = gl.MeshData(vertexes=vertices_haste, faces=faces_haste)

                    item_haste = gl.GLMeshItem(
                        meshdata=mesh_data_haste,
                        color=cor,
                        smooth=False,
                        computeNormals=False,
                        drawFaces=True,
                        drawEdges=False)

                    item_haste.setGLOptions("translucent")
                    item_haste.setDepthValue(29.0 + ordem)
                    item_haste._tempo_salvo_layer_id = (layer.id())
                    item_haste._tempo_salvo_altura = (altura)
                    item_haste._tempo_salvo_altura_haste = (altura_haste)
                    item_haste._tempo_salvo_espessura = (espessura)

                    self.view.addItem(item_haste)
                    self._itens_hastes_pontos_sobreposicao.append(item_haste)

            # Pontos são desenhados depois das hastes.
            for chave, posicoes in grupos_pontos.items():
                if not posicoes:
                    continue

                cor, tamanho = chave

                posicoes_np = np.asarray(posicoes, dtype=np.float32)

                item = gl.GLScatterPlotItem(pos=posicoes_np, color=cor, size=tamanho, pxMode=False)

                item.setGLOptions("translucent")

                item.setDepthValue(30.0 + ordem)

                item._tempo_salvo_layer_id = layer.id()
                item._tempo_salvo_altura = altura
                item._tempo_salvo_tamanho = tamanho

                self.view.addItem(item)

                self._itens_pontos_sobreposicao.append(item)

    def _renderizar_linhas_sobre_mdt(self, camadas):
        """
        Renderiza linhas sobre o MDT respeitando configuração individual
        de altura, espessura, opacidade e parede vertical.
        """
        if not camadas:
            return

        if self.ui_manager is not None:
            map_settings = self.ui_manager.iface.mapCanvas().mapSettings()
            contexto = QgsRenderContext.fromMapSettings(map_settings)
        else:
            contexto = QgsRenderContext()

        # A lista chega de cima para baixo.
        # Invertemos para desenhar as camadas inferiores primeiro.
        for ordem, layer in enumerate(reversed(camadas)):
            config = self._obter_config_3d_camada("linhas", layer)

            altura = max(0.0, float(config.get("altura", 0.05)))
            espessura = max(0.10, float(config.get("espessura", 2.0)))
            opacidade_config = max(0.0, min(100.0, float(config.get("opacidade", 100.0)))) / 100.0
            mostrar_parede = bool(config.get("parede", False))
            opacidade_parede = max(0.0, min(100.0, float(config.get("opacidade_parede", 60.0)))) / 100.0

            mostrar_rotulo = bool(config.get("rotulo", False))
            altura_rotulo = max(0.0, float(config.get("altura_rotulo", 2.0)))
            tamanho_rotulo = max(6, int(config.get("tamanho_rotulo", 10)))
            campo_rotulo = config.get("campo_rotulo")

            transformacao = None

            if (layer.crs().isValid()
                and self.raster_layer.crs().isValid()
                and layer.crs() != self.raster_layer.crs()):
                transformacao = QgsCoordinateTransform(layer.crs(), self.raster_layer.crs(), QgsProject.instance())

            renderer = layer.renderer()
            grupos_estilo = {}

            # Prepara o contexto para renderizadores baseados em
            # campos e expressões, como as Curvas de Nível 3D.
            try:
                contexto.expressionContext().setFields(
                    layer.fields())
            except Exception:
                pass  # nosec B110

            if renderer is not None:
                try:
                    renderer.startRender(contexto, layer.fields())
                except Exception:
                    renderer = None

            try:
                for feature in layer.getFeatures():
                    # Necessário para renderizadores categorizados cuja classificação é definida por expressão.
                    try:
                        contexto.expressionContext().setFeature(feature)
                    except Exception:
                        pass  # nosec B110

                    geometria = feature.geometry()

                    if (geometria is None
                        or geometria.isEmpty()):
                        continue

                    if transformacao is not None:
                        try:
                            geometria.transform(transformacao)
                        except Exception as e:
                            self._registrar_erro_sobreposicao_3d(self.tr("Falha ao transformar a geometria para o CRS do MDT"), e)
                            continue

                    try:
                        objeto_geometria = geometria.constGet()

                        if (objeto_geometria is not None
                            and objeto_geometria.hasCurvedSegments()):
                            geometria = geometria.segmentize()

                    except Exception:
                        pass  # nosec B110

                    if (mostrar_rotulo
                        and campo_rotulo):

                        texto_rotulo = self._texto_rotulo_feature(feature, campo_rotulo)

                        if texto_rotulo:
                            cor_rotulo = self._cor_rotulo_linha_qgis(layer, feature, contexto)

                            posicao_rotulo = self._posicao_rotulo_linha_3d(geometria, altura, altura_rotulo)

                            if posicao_rotulo is not None:
                                item_rotulo = self._criar_rotulo_linha_3d(texto_rotulo, posicao_rotulo, cor_rotulo, tamanho_rotulo, ordem)

                                if item_rotulo is not None:
                                    self._registrar_rotulo_oclusao(item_rotulo, "linhas", layer, posicao_rotulo)

                    if geometria.isMultipart():
                        partes = geometria.asMultiPolyline()
                    else:
                        parte = geometria.asPolyline()
                        partes = [parte] if parte else []

                    simbolo = None

                    simbolos = self._simbolos_feature_3d(renderer, feature, contexto)

                    if not simbolos:
                        continue

                    segmentos_feature = []

                    for parte in partes:
                        for segmento in self._segmentos_linha_3d(parte, altura):
                            if len(segmento) >= 2:
                                segmentos_feature.append(segmento)

                    if not segmentos_feature:
                        continue

                    for simbolo in simbolos:
                        cor_qgis, _ = self._estilo_linha_3d(simbolo)

                        cor_linha = (
                            cor_qgis[0],
                            cor_qgis[1],
                            cor_qgis[2],
                            max(0.0, min(1.0, cor_qgis[3] * opacidade_config)))

                        cor_parede = (
                            cor_linha[0],
                            cor_linha[1],
                            cor_linha[2],
                            max(0.0, min(1.0, cor_linha[3] * opacidade_parede)))

                        chave = (
                            tuple(round(valor, 5) for valor in cor_linha),
                            tuple(round(valor, 5) for valor in cor_parede),
                            round(espessura, 2))

                        grupo = grupos_estilo.setdefault(chave,
                            {"linhas": [], "vertices_parede": [], "faces_parede": []})

                        for segmento in segmentos_feature:
                            pares = np.empty(
                                ((len(segmento) - 1) * 2, 3),
                                dtype=np.float32)

                            pares[0::2] = segmento[:-1]
                            pares[1::2] = segmento[1:]

                            grupo["linhas"].append(pares)

                            if (mostrar_parede
                                and altura > 0.0):

                                vertices_parede, faces_parede = self._criar_parede_segmento_linha(
                                    segmento,
                                    altura)

                                if (vertices_parede is not None
                                    and faces_parede is not None):

                                    deslocamento_indices = sum(
                                        len(vertices)
                                        for vertices in grupo["vertices_parede"])

                                    grupo["vertices_parede"].append(vertices_parede)

                                    grupo["faces_parede"].append(
                                        faces_parede + deslocamento_indices)

            finally:
                if renderer is not None:
                    try:
                        renderer.stopRender(contexto)
                    except Exception:
                        pass  # nosec B110

            for chave, grupo in grupos_estilo.items():
                cor_linha, cor_parede, espessura_grupo = chave

                # Parede é desenhada primeiro.
                if grupo["vertices_parede"] and grupo["faces_parede"]:
                    vertices_parede = np.vstack(grupo["vertices_parede"])
                    faces_parede = np.vstack(grupo["faces_parede"])

                    mesh_data = gl.MeshData(
                        vertexes=vertices_parede,
                        faces=faces_parede)

                    item_parede = gl.GLMeshItem(
                        meshdata=mesh_data,
                        smooth=False,
                        computeNormals=False,
                        drawFaces=True,
                        drawEdges=False,
                        color=cor_parede,
                        shader=None)

                    item_parede.setGLOptions("translucent")
                    item_parede.setDepthValue(9.0 + ordem)

                    self.view.addItem(item_parede)
                    self._itens_paredes_linhas_sobreposicao.append(item_parede)

                # Linha elevada é desenhada depois da parede.
                if grupo["linhas"]:
                    posicoes = np.vstack(grupo["linhas"])

                    item_linha = gl.GLLinePlotItem(
                        pos=posicoes,
                        color=cor_linha,
                        width=espessura_grupo,
                        antialias=True,
                        mode="lines")

                    item_linha.setGLOptions("translucent")
                    item_linha.setDepthValue(10.0 + ordem)

                    # Identifica a camada e a espessura efetiva.
                    # Necessário para atualizações incrementais.
                    item_linha._tempo_salvo_layer_id = layer.id()
                    item_linha._tempo_salvo_espessura = float(espessura_grupo)

                    self.view.addItem(item_linha)
                    self._itens_linhas_sobreposicao.append(item_linha)

    def _snapshot_estilo_pontos_3d(self, camadas=None):
        """
        Captura as configurações efetivas das camadas de pontos.
        Usado para verificar se o cache continua válido.
        """
        if camadas is None:
            camadas = self._camadas_pontos_sobreposicao

        return {layer.id(): self._obter_config_3d_camada("pontos", layer)
            for layer in camadas}

    def _atualizar_apenas_tamanho_pontos_3d(self):
        """
        Atualiza diretamente o tamanho dos marcadores existentes.

        Não modifica cotas, posições, hastes ou rótulos.
        Retorna False se alguma outra configuração mudou.
        """
        chave = self._chave_cache_pontos_ativa

        if chave is None:
            return False

        cache = self._cache_pontos_3d.get(chave)

        if cache is None:
            return False

        anterior = cache.get("estilos")
        atual = self._snapshot_estilo_pontos_3d()

        if anterior is None or anterior.keys() != atual.keys():
            return False

        alteracoes = {}

        for layer_id, config_atual in atual.items():
            config_anterior = anterior[layer_id]

            # Somente o parâmetro "tamanho" pode ter mudado.
            outros_anteriores = {k: v for k, v in config_anterior.items()
                if k != "tamanho"}

            outros_atuais = {k: v for k, v in config_atual.items()
                if k != "tamanho"}

            if outros_anteriores != outros_atuais:
                return False

            tamanho_anterior = float(config_anterior.get("tamanho", 7.0))
            tamanho_atual = float(config_atual.get("tamanho", 7.0))

            if abs(tamanho_atual - tamanho_anterior) > 1e-9:
                alteracoes[layer_id] = max(1.0, tamanho_atual)

        if not alteracoes:
            return False

        itens = self._itens_pontos_sobreposicao

        # Confirma que os objetos ainda são os do cache ativo.
        if (len(itens) != len(cache.get("pontos", []))
            or any(item not in cache["pontos"]
                for item in itens )):
            return False

        try:
            for item in itens:
                layer_id = getattr(item, "_tempo_salvo_layer_id", None)

                if layer_id not in alteracoes:
                    continue

                novo_tamanho = alteracoes[layer_id]

                item.setData(size=novo_tamanho)
                item._tempo_salvo_tamanho = novo_tamanho

        except (RuntimeError, TypeError, ValueError):
            # A rotina original fará a reconstrução necessária.
            return False

        # Atualiza a referência de estilo do cache ativo.
        cache["estilos"] = copy.deepcopy(atual)

        self.view.update()
        return True

    def _atualizar_pontos_sobreposicao(self, usar_cache=False):
        """
        Atualiza somente os pontos sobre o MDT.

        Quando usar_cache=True, tenta reutilizar pontos, hastes
        e rótulos já preparados para a qualidade atual.
        """
        if not self.check_sobreposicao.isChecked():
            self._ocultar_pontos_cache_ativos()
            self.view.update()
            return

        if not self._sobrepor_pontos:
            self._ocultar_pontos_cache_ativos()
            self.view.update()
            return

        if not self._camadas_pontos_sobreposicao:
            self._ocultar_pontos_cache_ativos()
            self.view.update()
            return

        if (usar_cache
            and self._ativar_cache_pontos_3d(self._camadas_pontos_sobreposicao)):

            self.view.update()
            self._solicitar_atualizacao_oclusao_rotulos()
            return

        if usar_cache:
            # Nova qualidade ou conjunto de camadas ainda não preparado.
            self._ocultar_pontos_cache_ativos()

        else:
            # Tenta modificar apenas o tamanho dos marcadores, sem reconstruir pontos, hastes ou rótulos.
            if self._atualizar_apenas_tamanho_pontos_3d():
                return

            # Outras alterações continuam usando a reconstrução completa original.
            self._invalidar_cache_pontos_3d()

        self._renderizar_pontos_sobre_mdt(self._camadas_pontos_sobreposicao)

        self._salvar_cache_pontos_3d(self._camadas_pontos_sobreposicao)

        self.view.update()
        self._solicitar_atualizacao_oclusao_rotulos()

    def _atualizar_estado_controles_cores(self, sobreposicao_ativa):
        """
        Desabilita os controles de cores do MDT enquanto uma
        sobreposição raster estiver ativa.
        """
        habilitar_cores = not sobreposicao_ativa
        self.frame_cores.setEnabled(habilitar_cores)
        self.label_rampa_cores.setEnabled(habilitar_cores)
        self.combo_rampa.setEnabled(habilitar_cores)
        self.label_faixas.setEnabled(habilitar_cores)
        self.spin_faixas.setEnabled(habilitar_cores)
        self.check_inverter.setEnabled(habilitar_cores)

    def _alternar_sobreposicao(self, ativar):
        """
        Habilita ou desabilita todas as sobreposições.
        """
        self.pushButtonSobreposicao.setEnabled(ativar)

        if ativar:
            QTimer.singleShot(0, self._atualizar_sobreposicoes)

            return

        raster_estava_ativo = (self._cores_imagem_sobreposicao is not None)

        self._camadas_raster_sobreposicao = []
        self._camadas_linhas_sobreposicao = []
        self._camadas_poligonos_sobreposicao = []
        self._camadas_pontos_sobreposicao = []
        self._cores_imagem_sobreposicao = None

        self._remover_expansao_raster()
        self._ocultar_linhas_cache_ativas()
        self._ocultar_poligonos_cache_ativos()
        self._ocultar_pontos_cache_ativos()

        self._remover_mdts_secundarios_3d()
        self._camadas_mdt_secundario_3d = []

        self._atualizar_estado_controles_cores(False)

        if raster_estava_ativo:
            self._atualizar_geometria()
        else:
            self.view.update()

    def _obter_imagem_visivel_sobre_mdt(self):
        """
        Retorna a primeira camada raster visível que:

        - não seja o próprio MDT;
        - represente uma imagem RGB/RGBA ou serviço online;
        - intercepte a extensão espacial do MDT.
        """
        if self.ui_manager is None:
            return None

        iface = getattr(self.ui_manager, "iface", None)

        if iface is None:
            return None

        camadas_visiveis = (iface.mapCanvas().layers())

        crs_mdt = self.raster_layer.crs()
        extensao_mdt = self.raster_layer.extent()

        provedores_online = ("wms", "xyz", "arcgismapserver")

        for layer in camadas_visiveis:
            if not isinstance(layer, QgsRasterLayer):
                continue

            if not layer.isValid():
                continue

            if layer.id() == self.raster_layer.id():
                continue

            provider_online = (
                layer.providerType().lower()
                in provedores_online)

            # Evita usar outro MDT de uma banda como imagem.
            if (layer.bandCount() < 3
                and not provider_online):
                continue

            try:
                extensao_imagem = layer.extent()

                if (layer.crs().isValid()
                    and crs_mdt.isValid()
                    and layer.crs() != crs_mdt):
                    transformacao = QgsCoordinateTransform(
                        layer.crs(),
                        crs_mdt,
                        QgsProject.instance())

                    extensao_imagem = transformacao.transformBoundingBox(extensao_imagem)

            except Exception as e:
                self._registrar_erro_sobreposicao_3d(self.tr("Falha ao verificar a extensão da imagem sobre o MDT"), e)
                extensao_imagem = None

            if extensao_imagem is None:
                continue

            if extensao_imagem.intersects(extensao_mdt):
                return layer

    def _renderizar_imagem_sobre_mdt(self, layer):
        """
        Renderiza a camada de imagem exatamente na extensão e na
        resolução da grade 3D do MDT.

        Onde a imagem não tiver cobertura, mantém a cor original
        de elevação da superfície.
        """
        largura = int(self._grade_x)
        altura = int(self._grade_y)

        if largura <= 0 or altura <= 0:
            raise RuntimeError(self.tr("A grade 3D do MDT é inválida."))

        map_settings = QgsMapSettings()
        map_settings.setLayers([layer])
        map_settings.setExtent(self.raster_layer.extent())
        map_settings.setDestinationCrs(self.raster_layer.crs())
        map_settings.setOutputSize(QSize(largura, altura))
        map_settings.setBackgroundColor(QColor(0, 0, 0, 0))

        imagem = QImage(largura, altura, QImage.Format.Format_RGBA8888)
        imagem.fill(QColor(0, 0, 0, 0))
        painter = QPainter(imagem)

        job = QgsMapRendererCustomPainterJob(map_settings, painter)
        job.start()
        job.waitForFinished()
        painter.end()

        imagem = imagem.convertToFormat(QImage.Format.Format_RGBA8888)

        ponteiro = imagem.bits()
        ponteiro.setsize(imagem.sizeInBytes())

        rgba = np.array(ponteiro, dtype=np.uint8).reshape(altura, largura, 4).copy()
        rgba = (rgba.reshape(-1, 4).astype(np.float32) / 255.0)
        cores_base = (self._gerar_cores_vertices_suaves())

        if rgba.shape[0] != cores_base.shape[0]:
            raise RuntimeError(self.tr("A imagem renderizada não coincide com a grade 3D do MDT."))

        # Alpha da imagem renderizada.
        alpha_imagem = rgba[:, 3:4]

        cores_finais = cores_base.copy()

        # Mescla a imagem com as cores de elevação.
        cores_finais[:, :3] = (rgba[:, :3] * alpha_imagem + cores_base[:, :3] * (1.0 - alpha_imagem))

        # Mantém a máscara NoData do MDT.
        cores_finais[:, 3] = (cores_base[:, 3])

        return cores_finais.astype(np.float32)

    def _gerar_cores_vertices_suaves(self):
        """
        Gera cores classificadas por vértice, respeitando a quantidade
        de faixas, mas mantendo a interpolação visual suave da superfície.
        """
        valores = self._z_valores.copy()
        intervalo = self._z_max - self._z_min

        if intervalo <= 0.0:
            normalizado = np.zeros_like(valores, dtype=np.float64)
        else:
            normalizado = (valores - self._z_min) / intervalo

        normalizado = np.clip(normalizado, 0.0, 1.0)

        # Quantidade definida no controle de faixas.
        quantidade = max(1, int(self.spin_faixas.value()))

        # Impede que NaN e infinitos sejam convertidos em índices inteiros.
        normalizado = np.nan_to_num(normalizado, nan=0.0, posinf=1.0, neginf=0.0)

        # Mantém os valores dentro do intervalo esperado.
        normalizado = np.clip(normalizado, 0.0, 1.0)

        # Calcula os índices sem ultrapassar a quantidade de faixas.
        indices = np.floor(normalizado * quantidade).astype(np.int32)
        indices = np.clip(indices, 0, quantidade - 1)

        # Usa a posição central de cada faixa para definir a cor.
        normalizado_faixas = (indices.astype(np.float64) + 0.5) / quantidade

        if self.check_inverter.isChecked():
            normalizado_faixas = (1.0 - normalizado_faixas)

        modo = self.combo_rampa.currentData()

        if modo == "map":
            valores_consulta = (self._z_min + normalizado_faixas * intervalo)

            cores = self._interpolar_cores_renderer_qgis(valores_consulta)

            if cores is not None:
                cores[:, 3] = 1.0

                if self._validos is not None:
                    cores[~self._validos, 3] = 0.0

                return cores.astype(np.float32)

            modo = "gray"

        if modo == "gray":
            cores = np.column_stack((
                normalizado_faixas,
                normalizado_faixas,
                normalizado_faixas,
                np.ones_like(normalizado_faixas)))

        else:
            cores = self._interpolar_rampa_predefinida(modo, normalizado_faixas)

            if cores is None:
                cores = self._interpolar_rampa_predefinida("Classic", normalizado_faixas)

        if self._validos is not None:
            cores[~self._validos, 3] = 0.0

        return cores.astype(np.float32)

    def _chave_cache_raster_sobreposto_3d(self, camadas=None):
        """
        Retorna a chave da malha do MDT com raster sobreposto.
        """
        if camadas is None:
            camadas = self._camadas_raster_sobreposicao

        limite = int(getattr(self, "_limite_grade_aplicado", self.LIMITE_GRADE))

        exagero = round(float(self.spin_exagero.value()), 6)
        mostrar_linhas = bool(self.check_linhas.isChecked())
        fundo_preto = bool(self.radio_fundo_preto.isChecked())

        try:
            rampa = self.combo_rampa.currentData()

            if rampa is None:
                rampa = self.combo_rampa.currentText()

        except Exception:
            rampa = ""

        faixas = int(self.spin_faixas.value())

        inverter = bool(self.check_inverter.isChecked())

        configuracoes = []

        for layer in camadas:
            config = self._obter_config_3d_camada("raster", layer)

            modo = str(config.get("modo", "sobreposicao"))
            opacidade = round(float(config.get("opacidade", 100.0)), 3)

            qualidade_textura = config.get("qualidade_textura", "auto")

            configuracoes.append((layer.id(), modo, opacidade, str(qualidade_textura)))

            configuracoes.append((layer.id(), modo, opacidade))

        return (
            limite,
            exagero,
            mostrar_linhas,
            fundo_preto,
            str(rampa),
            faixas,
            inverter,
            tuple(configuracoes))

    def _ativar_cache_raster_sobreposto_3d(self, camadas):
        """
        Reativa uma malha com raster sobreposto quando ela
        já tiver sido preparada anteriormente.
        """
        chave = self._chave_cache_raster_sobreposto_3d(camadas)

        cache = self._cache_raster_sobreposto_3d.get(chave)

        if cache is None:
            return False

        item = cache.get("mesh")
        cores = cache.get("cores")

        if item is None or cores is None:
            return False

        if (self.mesh_item is not None
            and self.mesh_item is not item):

            try:
                self.mesh_item.hide()
            except Exception:
                pass  # nosec B110

        self.mesh_item = item

        try:
            if item not in self.view.items:
                self.view.addItem(item)

            item.show()

        except Exception:
            return False

        self._cores_imagem_sobreposicao = cores
        self._camadas_raster_sobreposicao = list(camadas)
        self._chave_cache_raster_sobreposto_ativa = chave

        self.view.update()

        return True

    def _salvar_cache_raster_sobreposto_3d(self, camadas):
        """
        Guarda a malha e as cores já preparadas do raster sobreposto.
        """
        if (self.mesh_item is None
            or self._cores_imagem_sobreposicao is None
            or not camadas):

            return

        chave = self._chave_cache_raster_sobreposto_3d(
            camadas)

        self._cache_raster_sobreposto_3d[chave] = {"mesh": self.mesh_item, "cores": self._cores_imagem_sobreposicao}

        self._chave_cache_raster_sobreposto_ativa = chave

    def _invalidar_cache_raster_sobreposto_3d(self):
        """
        Remove as malhas raster armazenadas em cache.

        A malha atualmente ativa é preservada porque poderá ser
        substituída normalmente por _atualizar_geometria().
        """
        for cache in self._cache_raster_sobreposto_3d.values():
            item = cache.get("mesh")

            if (item is None
                or item is self.mesh_item):

                continue

            try:
                if item in self.view.items:
                    self.view.removeItem(item)

            except Exception:
                pass  # nosec B110

        self._cache_raster_sobreposto_3d.clear()
        self._chave_cache_raster_sobreposto_ativa = None

    def _invalidar_cache_malhas_qualidade(self):
        """
        Remove as malhas de outras qualidades mantidas em cache.
        A malha atualmente ativa é preservada.
        """
        cache = getattr(self, "_cache_malhas_qualidade", {})

        for item in list(cache.values()):
            if item is None or item is self.mesh_item:
                continue

            try:
                if item in self.view.items:
                    self.view.removeItem(item)

            except Exception:
                pass  # nosec B110

        cache.clear()

    def _sincronizar_exagero_malha_cache_3d(self, item):
        """
        Atualiza os vértices de uma malha armazenada em cache
        quando seu exagero difere do valor atual.

        Preserva cores, faces e o GLMeshItem existente.
        """
        if item is None:
            return False

        qualidade_item = getattr(item, "_tempo_salvo_qualidade", None)

        qualidade_atual = int(
            getattr(self, "_limite_grade_aplicado",  self.LIMITE_GRADE))

        if (qualidade_item is None
            or int(qualidade_item) != qualidade_atual):
            return False

        exagero_atual = float(self.spin_exagero.value())
        exagero_item = getattr(item, "_tempo_salvo_exagero", None)

        if (exagero_item is not None
            and abs(float(exagero_item) - exagero_atual) < 1e-9):
            return True

        try:
            mesh_anterior = item.opts.get("meshdata")

            if mesh_anterior is None:
                return False

            vertices = np.asarray(self._vertices_com_exagero(), dtype=np.float32)
            faces = np.asarray(self._faces, dtype=np.int32)

            if vertices.shape[0] != mesh_anterior.vertexes().shape[0]:
                return False

            if faces.shape != mesh_anterior.faces().shape:
                return False

            cores_vertices = mesh_anterior.vertexColors()
            cores_faces = mesh_anterior.faceColors()

            if cores_vertices is not None:
                nova_malha = gl.MeshData(
                    vertexes=vertices,
                    faces=faces,
                    vertexColors=cores_vertices)

            elif cores_faces is not None:
                nova_malha = gl.MeshData(
                    vertexes=vertices,
                    faces=faces,
                    faceColors=cores_faces)

            else:
                return False

            item.setMeshData(meshdata=nova_malha)
            item._tempo_salvo_exagero = exagero_atual

            return True

        except (RuntimeError, ValueError, TypeError) as erro:
            QgsMessageLog.logMessage(self.tr("Não foi possível sincronizar o exagero da malha armazenada: {erro}").format(erro=str(erro)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)

            return False

    def _sincronizar_cores_malha_cache_3d(self, item):
        """
        Atualiza as cores de uma malha em cache quando
        sua versão é diferente da rampa atual.

        Preserva vértices, faces, exagero e GLMeshItem.
        """
        if item is None:
            return False

        versao_atual = int(self._versao_cores_terreno_3d)

        versao_item = getattr(item, "_tempo_salvo_versao_cores", None)

        if versao_item == versao_atual:
            return True

        # Cenas especiais continuam utilizando o caminho original de reconstrução.
        config_solar = getattr(self, "_config_sombreamento_3d", {}) or {}

        if config_solar.get("iluminacao_ativa", False):
            return False

        if self._obter_camadas_diferenca_mdt_ativas():
            return False

        usar_imagem = (self.check_sobreposicao.isChecked()
            and self._sobrepor_rasters
            and bool(self._camadas_raster_sobreposicao)
            and self._cores_imagem_sobreposicao is not None)

        if usar_imagem:
            return False

        try:
            mesh_data = item.opts.get("meshdata")

            if mesh_data is None:
                return False

            if mesh_data.hasFaceColor():
                cores = np.ascontiguousarray(
                    self._gerar_cores_faces(),
                    dtype=np.float32)

                if cores.shape != (mesh_data.faceCount(), 4):
                    return False

                mesh_data.setFaceColors(cores)

            elif mesh_data.hasVertexColor():
                cores = np.ascontiguousarray(
                    self._gerar_cores_vertices_suaves(),
                    dtype=np.float32)

                if cores.shape != (mesh_data.vertexes().shape[0], 4):
                    return False

                mesh_data.setVertexColors(cores)

            else:
                return False

            # Atualiza os dados OpenGL do objeto existente.
            item.meshDataChanged()

            # Só marca a versão após a atualização.
            item._tempo_salvo_versao_cores = versao_atual

            return True

        except (AttributeError, RuntimeError,
                TypeError, ValueError) as erro:

            QgsMessageLog.logMessage(self.tr("Não foi possível sincronizar as cores da malha armazenada: {erro}").format(erro=str(erro)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)

            return False

    def _ativar_malha_cache_qualidade(self, limite_atual, novo_limite):
        """
        Mantém a malha atual em memória/GPU e reutiliza a malha da
        qualidade destino quando ela já tiver sido renderizada.

        Retorna True quando houve reaproveitamento da malha.
        """
        limite_atual = int(limite_atual)
        novo_limite = int(novo_limite)

        item_anterior = self.mesh_item

        if item_anterior is not None:
            self._cache_malhas_qualidade[limite_atual] = item_anterior
            item_anterior.hide()

        item_cache = self._cache_malhas_qualidade.get(novo_limite)

        if item_cache is not None:

            # A grade da qualidade destino já deve ter sido carregada por _carregar_superficie_raster().
            exagero_ok = (self._sincronizar_exagero_malha_cache_3d(item_cache))
            cores_ok = False

            if exagero_ok:
                cores_ok = (self._sincronizar_cores_malha_cache_3d(item_cache))

            if exagero_ok and cores_ok:
                self.mesh_item = item_cache
                self.mesh_item.show()
                self.view.update()
                return True

            # Se não foi possível sincronizar, descarta apenas esta entrada incompatível, nunca todo o cache.
            self._cache_malhas_qualidade.pop(novo_limite, None)

            try:
                if item_cache in self.view.items:
                    self.view.removeItem(item_cache)
            except (RuntimeError, ValueError):
                pass

        self.mesh_item = None

        try:
            self._criar_item_malha()

        except Exception:
            self.mesh_item = item_anterior

            if item_anterior is not None:
                item_anterior.show()

            raise

        self._cache_malhas_qualidade[novo_limite] = self.mesh_item

        return False

    def _alterar_qualidade_terreno(self):
        """
        Altera a qualidade do terreno reutilizando tanto a grade
        quanto o GLMeshItem quando disponíveis em cache.
        """
        if self._vertices_base is None:
            return

        novo_limite = self.combo_qualidade_terreno.currentData()

        if novo_limite is None:
            return

        novo_limite = int(novo_limite)
        limite_atual = getattr(self, "_limite_grade_aplicado", self.LIMITE_GRADE)

        if novo_limite == limite_atual:
            return

        indice_anterior = self.combo_qualidade_terreno.findData(limite_atual)

        self.combo_qualidade_terreno.setEnabled(False)
        self._mostrar_progresso_3d(self.tr("Processando terreno..."))
        QGuiApplication.setOverrideCursor(QCursor(Qt.CursorShape.WaitCursor))

        try:
            self._carregar_superficie_raster()
            sobreposicao_ativa = self.check_sobreposicao.isChecked()

            camadas_raster = []
            camadas_sobreposicao = []
            camadas_superficie_3d = []

            if (sobreposicao_ativa
                and self._sobrepor_rasters):

                camadas_raster = self._obter_rasters_sobre_mdt()

                camadas_sobreposicao, camadas_superficie_3d = (self._separar_rasters_por_modo_3d(camadas_raster))

            self._camadas_mdt_secundario_3d = list(camadas_superficie_3d)

            diferenca_ativa = any(
                bool(self._obter_config_3d_camada("raster", layer).get("habilitar_diferenca", False))
                for layer in self._camadas_mdt_secundario_3d)

            self._diferenca_mdt_aplicada = (diferenca_ativa)

            raster_sobreposto_ativo = bool(camadas_sobreposicao)

            if raster_sobreposto_ativo:
                self._camadas_raster_sobreposicao = list(
                    camadas_sobreposicao)

                # Primeiro tenta recuperar a superfície raster
                # já totalmente preparada nesta qualidade.
                cache_encontrado = False

                if not diferenca_ativa:
                    cache_encontrado = (self._ativar_cache_raster_sobreposto_3d(camadas_sobreposicao))

                if not cache_encontrado:
                    item_anterior_raster = self.mesh_item

                    if item_anterior_raster is not None:
                        try:
                            item_anterior_raster.hide()
                        except Exception:
                            pass  # nosec B110

                    try:
                        self._cores_imagem_sobreposicao = (
                            self._renderizar_rasters_sobre_mdt(
                                camadas_sobreposicao))

                        self.mesh_item = None
                        self._criar_item_malha()

                        if (self._cores_imagem_sobreposicao is not None
                            and not diferenca_ativa):

                            self._salvar_cache_raster_sobreposto_3d(camadas_sobreposicao)

                    except Exception:
                        self.mesh_item = item_anterior_raster

                        if item_anterior_raster is not None:
                            try:
                                item_anterior_raster.show()
                            except Exception:
                                pass  # nosec B110

                        raise

                self._atualizar_estado_controles_cores(
                    self._cores_imagem_sobreposicao is not None)

                self._atualizar_expansao_raster()

                if sobreposicao_ativa:
                    self._atualizar_sobreposicoes_vetoriais_cache()

            else:
                # Não existe raster que deva alterar a textura do MDT principal.
                self._cores_imagem_sobreposicao = None
                self._camadas_raster_sobreposicao = []

                if diferenca_ativa:
                    # Não reutiliza uma malha normal em cache,
                    # porque agora a geometria deve ser deformada.
                    self._invalidar_cache_malhas_qualidade()

                    if self.mesh_item is not None:
                        try:
                            if self.mesh_item in self.view.items:
                                self.view.removeItem(self.mesh_item)

                        except Exception:
                            pass  # nosec B110

                    self.mesh_item = None

                    self._criar_item_malha()

                else:
                    self._ativar_malha_cache_qualidade(limite_atual, novo_limite)

                # Sincroniza os controles uma única vez.
                self._atualizar_estado_controles_cores(False)

                # Reaproveita os objetos vetoriais da qualidade atual.
                if sobreposicao_ativa:
                    self._atualizar_sobreposicoes_vetoriais_cache()

            # O MDT secundário é reconstruído separadamente,
            # utilizando a nova qualidade da grade.
            if (sobreposicao_ativa
                and self._sobrepor_rasters):

                self._atualizar_mdts_secundarios_3d()

            QCoreApplication.processEvents()

            # Atualiza a legenda sem modificar o enquadramento 3D.
            # Preserva zoom, rotação, inclinação e deslocamento (PAN).
            self._atualizar_legenda_cores()
            self.view.update()
            self._solicitar_atualizacao_oclusao_rotulos()

        except Exception as e:
            # Restaura também os dados da qualidade anterior.
            self._aplicar_cache_qualidade_terreno(limite_atual)

            item_anterior = self._cache_malhas_qualidade.get(
                int(limite_atual))

            if item_anterior is not None:
                if (self.mesh_item is not None
                    and self.mesh_item is not item_anterior):
                    self.mesh_item.hide()

                self.mesh_item = item_anterior
                self.mesh_item.show()
                self.view.update()

            if indice_anterior >= 0:
                self.combo_qualidade_terreno.blockSignals(True)
                self.combo_qualidade_terreno.setCurrentIndex(indice_anterior)
                self.combo_qualidade_terreno.blockSignals(False)

            if self.ui_manager is not None:
                self.ui_manager.mostrar_mensagem(self.tr("Não foi possível alterar a qualidade do terreno: {erro}").format(erro=str(e)), "Erro")
        finally:
            QGuiApplication.restoreOverrideCursor()
            self.combo_qualidade_terreno.setEnabled(True)
            self._ocultar_progresso_3d()

    def _reposicionar_aviso_crs_3d(self):
        if not hasattr(self, "label_aviso_crs_3d"):
            return

        if not self.label_aviso_crs_3d.isVisible():
            return

        margem = 12

        largura = min(750, max(300, self.view.width() - 2 * margem))

        self.label_aviso_crs_3d.setFixedWidth(largura)

        x = max(margem,(self.view.width() - largura) // 2)

        self.label_aviso_crs_3d.move(x, margem)
        self.label_aviso_crs_3d.raise_()

    def _reposicionar_progresso_3d(self):
        """
        Posiciona o indicador no canto inferior direito da área 3D.
        """
        if not hasattr(self, "frame_progresso_3d"):
            return

        margem = 12

        x = max(margem, self.view.width() - self.frame_progresso_3d.width() - margem)
        y = max(margem, self.view.height() - self.frame_progresso_3d.height() - margem)

        self.frame_progresso_3d.move(x, y)

    def _mostrar_progresso_3d(self, texto=None):
        """
        Exibe o indicador de processamento sobre a visualização 3D.
        """
        if not hasattr(self, "frame_progresso_3d"):
            return

        if texto:
            self.label_progresso_3d.setText(texto)

        self.progress_progresso_3d.setRange(0, 0)
        self.progress_progresso_3d.setTextVisible(False)

        self._reposicionar_progresso_3d()

        self.frame_progresso_3d.raise_()
        self.frame_progresso_3d.show()

        QCoreApplication.processEvents()

    def _atualizar_progresso_exportacao_web(self, valor, texto=None):
        """
        Atualiza o progresso percentual da
        exportação da visualização Web.
        """
        if not hasattr(self, "frame_progresso_3d"):

            return

        valor = int(max(0, min(100, valor)))

        if texto:
            self.label_progresso_3d.setText(texto)

        self.progress_progresso_3d.setRange(0, 100)
        self.progress_progresso_3d.setTextVisible(True)
        self.progress_progresso_3d.setFormat("%p%")
        self.progress_progresso_3d.setValue(valor)

        self._reposicionar_progresso_3d()

        self.frame_progresso_3d.raise_()
        self.frame_progresso_3d.show()

        QCoreApplication.processEvents()

    def _finalizar_progresso_exportacao_web(self, sucesso=True):
        """
        Finaliza o indicador da exportação Web.
        """
        if not hasattr(self, "frame_progresso_3d"):

            return

        if sucesso:
            self.label_progresso_3d.setText(self.tr("Exportação Web concluída."))

            self.progress_progresso_3d.setRange(0, 100)
            self.progress_progresso_3d.setValue(100)
            self.progress_progresso_3d.setTextVisible(True)

            QCoreApplication.processEvents()

        self.frame_progresso_3d.hide()

    def _ocultar_progresso_3d(self):
        """
        Oculta o indicador de processamento.
        """
        if not hasattr(self, "frame_progresso_3d"):
            return

        self.frame_progresso_3d.hide()

    def _salvar_cache_qualidade_terreno(self, limite_grade):
        """
        Guarda a grade atualmente calculada para reutilização posterior.
        Os arrays são mantidos por referência, evitando cópias desnecessárias.
        """
        limite_grade = int(limite_grade)

        self._cache_qualidades_terreno[limite_grade] = {
            nome: getattr(self, nome)
            for nome in self.ATRIBUTOS_CACHE_TERRENO}

    def _aplicar_cache_qualidade_terreno(self, limite_grade):
        """
        Restaura uma grade já calculada.
        Retorna True quando a qualidade foi encontrada no cache.
        """
        limite_grade = int(limite_grade)
        cache = self._cache_qualidades_terreno.get(limite_grade)

        if cache is None:
            return False

        for nome, valor in cache.items():
            setattr(self, nome, valor)

        self._limite_grade_aplicado = limite_grade

        self.label_intervalo.setText(f"{self._z_min:.3f} – {self._z_max:.3f}")

        self.label_amostragem.setText(f"{self._grade_x} × {self._grade_y}")

        return True

    def _carregar_superficie_raster(self):
        # Determina primeiro a qualidade desejada.
        limite_grade = self.LIMITE_GRADE

        if hasattr(self, "combo_qualidade_terreno"):
            valor_combo = self.combo_qualidade_terreno.currentData()

            if valor_combo is not None:
                limite_grade = int(valor_combo)

        # Se essa qualidade já foi calculada, não relê nem reconstrói o MDT.
        if self._aplicar_cache_qualidade_terreno(limite_grade):
            return

        source = self.raster_layer.source().split("|", 1)[0]

        if source.startswith("file://"):
            source = QUrl(source).toLocalFile()

        dataset = gdal.Open(source, gdal.GA_ReadOnly)

        if dataset is None:
            raise RuntimeError(self.tr("Não foi possível abrir o raster com o GDAL."))

        band = dataset.GetRasterBand(1)

        if band is None:
            raise RuntimeError(self.tr("Não foi possível acessar a banda 1 do raster."))

        largura = dataset.RasterXSize
        altura = dataset.RasterYSize

        passo = max(1, int(math.ceil(max(largura, altura) / limite_grade)))

        grade_x = max(2, int(math.ceil(largura / passo)))

        grade_y = max(2, int(math.ceil(altura / passo)))

        dados = band.ReadAsArray(0, 0, largura, altura, grade_x, grade_y)
        if dados is None:
            raise RuntimeError(self.tr("Falha ao ler os valores do raster."))

        dados = np.asarray(dados, dtype=np.float64)
        nodata = band.GetNoDataValue()
        validos = np.isfinite(dados)
        if nodata is not None and np.isfinite(nodata):
            validos &= ~np.isclose(dados, float(nodata), rtol=0.0, atol=max(1e-12, abs(float(nodata)) * 1e-12))

        if not np.any(validos):
            raise RuntimeError(self.tr("O raster não possui valores de elevação válidos na banda 1."))

        gt = dataset.GetGeoTransform(can_return_null=True)
        if gt is None:
            extent = self.raster_layer.extent()
            gt = (
                extent.xMinimum(), extent.width() / largura, 0.0,
                extent.yMaximum(), 0.0, -extent.height() / altura)

        colunas_pixel = (np.arange(grade_x, dtype=np.float64) + 0.5) * (largura / grade_x)
        linhas_pixel = (np.arange(grade_y, dtype=np.float64) + 0.5) * (altura / grade_y)
        col_grid, row_grid = np.meshgrid(colunas_pixel, linhas_pixel)

        x_real = gt[0] + col_grid * gt[1] + row_grid * gt[2]
        y_real = gt[3] + col_grid * gt[4] + row_grid * gt[5]

        x_centro = float((np.nanmin(x_real) + np.nanmax(x_real)) / 2.0)
        y_centro = float((np.nanmin(y_real) + np.nanmax(y_real)) / 2.0)
        z_centro = float(np.nanmedian(dados[validos]))

        z_seguro = np.where(validos, dados, z_centro)
        vertices = np.column_stack((
            (x_real - x_centro).ravel(),
            (y_real - y_centro).ravel(),
            (z_seguro - z_centro).ravel())).astype(np.float32)

        indices = np.arange(grade_y * grade_x, dtype=np.int32).reshape(grade_y, grade_x)
        celulas_validas = validos[:-1, :-1] & validos[:-1, 1:] & validos[1:, :-1] & validos[1:, 1:]

        a = indices[:-1, :-1][celulas_validas]
        b = indices[:-1, 1:][celulas_validas]
        c = indices[1:, :-1][celulas_validas]
        d = indices[1:, 1:][celulas_validas]

        faces_1 = np.column_stack((a, b, c))
        faces_2 = np.column_stack((b, d, c))
        faces = np.vstack((faces_1, faces_2)).astype(np.uint32)

        if faces.size == 0:
            raise RuntimeError(self.tr("Não foi possível formar triângulos válidos a partir do raster."))

        self._dataset = dataset
        self._vertices_base = vertices
        self._faces = faces
        self._z_valores = dados.ravel()
        self._validos = validos.ravel()
        self._x_real = x_real.ravel()
        self._y_real = y_real.ravel()
        self._z_centro = z_centro
        self._grade_x = grade_x
        self._grade_y = grade_y

        # Dados necessários para encaixar vetores na superfície.
        self._dados_grade = dados
        self._validos_grade = validos
        self._geo_transform = tuple(gt)
        self._raster_largura = largura
        self._raster_altura = altura
        self._x_centro = x_centro
        self._y_centro = y_centro

        self._limite_grade_aplicado = limite_grade

        z_min = float(np.nanmin(dados[validos]))
        z_max = float(np.nanmax(dados[validos]))
        self._z_min = z_min
        self._z_max = z_max

        # Guarda esta qualidade para as próximas trocas.
        self._salvar_cache_qualidade_terreno(limite_grade)

        self.label_intervalo.setText(f"{z_min:.3f} – {z_max:.3f}")
        self.label_amostragem.setText(f"{grade_x} × {grade_y}")

    def _cor_linhas_superficie(self):
        """
        Retorna uma cor de linha adequada ao fundo selecionado.
        """
        if self.radio_fundo_preto.isChecked():
            return (1.0, 1.0, 1.0, 1.0)

        return (0.0, 0.0, 0.0, 0.85)

    def _coordenadas_uv_textura_3d(self):
        """
        Calcula as coordenadas UV dos vértices usando
        as coordenadas reais da grade do MDT.
        """
        if (self._x_real is None
            or self._y_real is None):

            return None

        extensao = self.raster_layer.extent()

        largura = float(extensao.width())
        altura = float(extensao.height())

        if largura <= 0.0 or altura <= 0.0:
            return None

        u = (np.asarray(self._x_real, dtype=np.float64)
            - extensao.xMinimum()) / largura

        v = (np.asarray(self._y_real, dtype=np.float64)
            - extensao.yMinimum()) / altura

        uv = np.column_stack(( np.clip(u, 0.0, 1.0), np.clip(v, 0.0, 1.0)))

        return np.ascontiguousarray(uv, dtype=np.float32)

    def _remover_textura_sobreposicao_3d(self):
        item = getattr(self, "_item_textura_sobreposicao", None)

        if item is None:
            return

        contexto_ativo = False

        try:
            self.view.makeCurrent()
            contexto_ativo = True

            item.cleanup()

        except Exception:
            pass  # nosec B110

        try:
            if item in self.view.items:
                self.view.removeItem(item)

        except Exception:
            pass  # nosec B110

        if contexto_ativo:
            try:
                self.view.doneCurrent()
            except Exception:
                pass  # nosec B110

        self._item_textura_sobreposicao = None

    def _criar_textura_sobreposicao_3d(self, vertices):
        self._remover_textura_sobreposicao_3d()

        imagem = getattr(self, "_imagem_textura_sobreposicao", None)

        if imagem is None or imagem.isNull():
            return

        if self._faces is None or len(self._faces) == 0:
            return

        uv = self._coordenadas_uv_textura_3d()

        if uv is None or len(uv) != len(vertices):
            return

        item = GLMalhaTexturizadaItem(
            vertices,
            self._faces,
            uv,
            imagem,
            fatores_luz=getattr(self, "_fatores_luz_vertices_3d", None))

        # O terreno principal permanece embaixo.
        item.setDepthValue(1.0)

        self.view.addItem(item)

        self._item_textura_sobreposicao = item

    def _gerar_cores_overlay_corte_aterro(self, opacidade=0.65):
        """
        Gera somente vermelho/azul para sobrepor raster/ortofoto.

        Corte = vermelho.
        Aterro = azul.
        Sem alteração e fora do MDT secundário = transparente.
        """
        camadas = []

        for layer in self._obter_camadas_diferenca_mdt_ativas():
            config = self._obter_config_3d_camada("raster", layer)

            if bool(config.get("mostrar_cores_diferenca", False)):
                camadas.append(layer)

        if not camadas:
            return None

        diferencas, mascara = self._calcular_diferencas_vertices_principais(camadas)

        if (diferencas is None
            or mascara is None):

            return None

        tolerancia = 0.01

        corte = (mascara
            & (diferencas < -tolerancia))

        aterro = (mascara
            & (diferencas > tolerancia))

        if not np.any(corte | aterro):
            return None

        cores = np.zeros(
            (len(self._vertices_base), 4),
            dtype=np.float32)

        cores[corte] = (1.0, 0.0, 0.0, float(opacidade))
        cores[aterro] = (0.0, 0.0, 1.0, float(opacidade))

        return cores

    def _remover_overlay_corte_aterro_3d(self):
        item = getattr(self, "_item_overlay_corte_aterro", None)

        if item is None:
            return

        try:
            if item in self.view.items:
                self.view.removeItem(item)
        except Exception:
            pass  # nosec B110

        self._item_overlay_corte_aterro = None

    def _criar_overlay_corte_aterro_3d(self, vertices):
        self._remover_overlay_corte_aterro_3d()

        cores = self._gerar_cores_overlay_corte_aterro(opacidade=0.65)

        if cores is None:
            return

        vertices_overlay = np.asarray(vertices, dtype=np.float32).copy()

        escala_xy = max(
            float(np.ptp(vertices_overlay[:, 0])),
            float(np.ptp(vertices_overlay[:, 1])),
            1.0)

        # Pequena folga para evitar z-fighting com a textura.
        folga = max(0.01, escala_xy * 0.000005)

        vertices_overlay[:, 2] += folga

        mesh_data = gl.MeshData(
            vertexes=vertices_overlay,
            faces=self._faces,
            vertexColors=cores)

        item = gl.GLMeshItem(
            meshdata=mesh_data,
            smooth=False,
            computeNormals=True,
            drawFaces=True,
            drawEdges=False,
            shader="shaded")

        item.setGLOptions("translucent")
        item.setDepthValue(2.0)

        self.view.addItem(item)

        self._item_overlay_corte_aterro = item

    def _criar_item_malha(self):
        """
        Cria a superfície 3D do raster.

        Prioridade visual:
        1. cores de corte e aterro;
        2. sobreposição raster;
        3. cores por face com linhas;
        4. cores suaves por vértice.
        """
        self._remover_textura_sobreposicao_3d()
        self._remover_overlay_corte_aterro_3d()

        vertices = self._vertices_com_exagero()

        cores_diferenca = (self._gerar_cores_corte_aterro_vertices())

        usar_imagem = (getattr(self, "check_sobreposicao",
                None) is not None
            and self.check_sobreposicao.isChecked()
            and getattr(self, "_sobrepor_rasters", False)
            and bool(getattr(self, "_camadas_raster_sobreposicao", []))
            and getattr(self, "_cores_imagem_sobreposicao",
                None) is not None)

        # Sem raster, mantém o comportamento tradicional
        # vermelho/branco/azul na própria superfície.
        if (cores_diferenca is not None
            and not usar_imagem):
            mesh_data = gl.MeshData(
                vertexes=vertices,
                faces=self._faces,
                vertexColors=cores_diferenca)

            self.mesh_item = gl.GLMeshItem(
                meshdata=mesh_data,
                smooth=False,
                computeNormals=True,
                drawFaces=True,
                drawEdges=self.check_linhas.isChecked(),
                edgeColor=self._cor_linhas_superficie(),
                shader="shaded")

        # Raster / ortofoto sobreposto.
        elif usar_imagem:
            mesh_data = gl.MeshData(
                vertexes=vertices,
                faces=self._faces,
                vertexColors=self._cores_imagem_sobreposicao)

            self.mesh_item = gl.GLMeshItem(
                meshdata=mesh_data,
                smooth=True,
                computeNormals=False,
                drawFaces=True,
                drawEdges=self.check_linhas.isChecked(),
                edgeColor=self._cor_linhas_superficie(),
                shader=None)

        # Superfície com linhas.
        elif self.check_linhas.isChecked():
            self._cores_faces = (self._gerar_cores_faces())

            mesh_data = gl.MeshData(
                vertexes=vertices,
                faces=self._faces,
                faceColors=self._cores_faces)

            self.mesh_item = gl.GLMeshItem(
                meshdata=mesh_data,
                smooth=False,
                drawFaces=True,
                drawEdges=True,
                edgeColor=self._cor_linhas_superficie(),
                shader="shaded")

        # Superfície normal com cores suaves.
        else:
            self._cores_vertices = (self._gerar_cores_vertices_suaves())

            mesh_data = gl.MeshData(
                vertexes=vertices,
                faces=self._faces,
                vertexColors=self._cores_vertices)

            self.mesh_item = gl.GLMeshItem(
                meshdata=mesh_data,
                smooth=True,
                drawFaces=True,
                drawEdges=False,
                shader="shaded")

        self._erro_iluminacao_solar_3d = None

        # Sem iluminação ativa, a textura recebe fator neutro.
        self._fatores_luz_vertices_3d = None

        config_solar = getattr(self, "_config_sombreamento_3d", {})

        if config_solar.get("iluminacao_ativa", False):
            try:
                if self._obter_camadas_diferenca_mdt_ativas():
                    raise ValueError(self.tr("O sombreamento desta etapa utiliza somente o relevo do MDT principal. Desative a comparação com MDTs secundários."))

                self._iluminar_malha_solar_3d(mesh_data)

            except Exception as erro:
                self._erro_iluminacao_solar_3d = str(erro)
                self._fatores_luz_vertices_3d = None

                QgsMessageLog.logMessage(self.tr("Não foi possível aplicar a iluminação solar: {erro}").format(erro=str(erro)), "Tempo Salvo Tools", Qgis.MessageLevel.Warning)

        self.view.addItem(self.mesh_item)

        # Identifica o exagero utilizado na geometria.
        self.mesh_item._tempo_salvo_exagero = float(self.spin_exagero.value())

        # Registra a versão das cores presentes na malha.
        self.mesh_item._tempo_salvo_versao_cores = int(self._versao_cores_terreno_3d)

        self.mesh_item._tempo_salvo_qualidade = int(getattr(self, "_limite_grade_aplicado", self.LIMITE_GRADE))

        if (usar_imagem
            and self._imagem_textura_sobreposicao is not None):
            self._criar_textura_sobreposicao_3d(vertices)

        if (usar_imagem
            and cores_diferenca is not None):
            self._criar_overlay_corte_aterro_3d(vertices)

        if (getattr(self, "check_base_mdt", None) is not None
            and self.check_base_mdt.isChecked()):
            self._criar_base_mdt()

    def _remover_base_mdt(self):
        """
        Remove a base visual do MDT, caso exista.
        """
        item = getattr(self, "_item_base_mdt", None)

        if item is None:
            return

        try:
            if item in self.view.items:
                self.view.removeItem(item)
        except Exception:
            pass  # nosec B110

        self._item_base_mdt = None

    def _alternar_base_mdt(self, ativo):
        """
        Exibe ou remove a base automática do MDT.
        """
        if ativo:
            self._criar_base_mdt()
        else:
            self._remover_base_mdt()

        self.view.update()

    def _criar_base_mdt(self):
        """
        Cria uma base cinza fechada sob o MDT.

        A altura é determinada automaticamente a partir
        da amplitude vertical e da dimensão horizontal
        da malha, evitando bases muito altas ou muito baixas.
        """
        self._remover_base_mdt()

        if self._vertices_base is None:
            return

        if self._faces is None:
            return

        vertices_topo = np.asarray(self._vertices_com_exagero(), dtype=np.float32)

        faces_topo = np.asarray(self._faces, dtype=np.int32)

        if (vertices_topo.ndim != 2
            or vertices_topo.shape[0] < 3
            or faces_topo.size == 0):
            return

        # Dimensão horizontal do MDT.
        largura_x = float(np.ptp(vertices_topo[:, 0]))
        largura_y = float(np.ptp(vertices_topo[:, 1]))

        escala_xy = max(largura_x, largura_y, 1.0)

        # Amplitude vertical já considerando o exagero.
        z_min = float(np.min(vertices_topo[:, 2]))
        z_max = float(np.max(vertices_topo[:, 2]))

        amplitude_z = max(z_max - z_min, 1.0)

        # Altura visual automática.
        # Usa:
        # - 15% da amplitude vertical;
        # - pelo menos 1% da dimensão horizontal;
        # - mínimo absoluto de 10;
        # - máximo absoluto de 50.
        altura_base = max(amplitude_z * 0.15, escala_xy * 0.01, 10.0)
        altura_base = min(altura_base, 50.0)

        z_base = (z_min - altura_base)

        quantidade_vertices = (vertices_topo.shape[0])

        # Cópia achatada da malha para formar o fundo.
        vertices_fundo = (vertices_topo.copy())
        vertices_fundo[:, 2] = (z_base)

        # Junta os vértices superiores e inferiores.
        vertices_base = np.vstack([vertices_topo, vertices_fundo]).astype(np.float32)

        faces_base = []

        # Fundo.
        # Ordem invertida para a normal apontar para baixo.
        for face in faces_topo:
            a, b, c = map(int, face)

            faces_base.append([
                quantidade_vertices + c,
                quantidade_vertices + b,
                quantidade_vertices + a])

        # Descobre as bordas externas da malha.
        contagem_arestas = {}

        for face in faces_topo:
            a, b, c = map(int, face)

            for u, v in ((a, b), (b, c),(c, a)):
                chave = (min(u, v), max(u, v))

                contagem_arestas[chave] = (contagem_arestas.get(chave, 0) + 1)

        # Arestas que aparecem apenas uma vez
        # pertencem ao contorno externo.
        bordas = [aresta
            for aresta, quantidade
            in contagem_arestas.items()
            if quantidade == 1]

        # Cria as paredes verticais.
        for a, b in bordas:

            a_inf = (quantidade_vertices + a)
            b_inf = (quantidade_vertices + b)

            faces_base.append([a, b, b_inf])
            faces_base.append([a, b_inf, a_inf])

        if not faces_base:
            return

        faces_base = np.asarray(faces_base, dtype=np.int32)

        mesh_data_base = gl.MeshData(vertexes=vertices_base, faces=faces_base)

        item_base = gl.GLMeshItem(
            meshdata=mesh_data_base,
            smooth=False,
            computeNormals=True,
            drawFaces=True,
            drawEdges=False,
            color=(0.60, 0.60, 0.60, 1.0),
            shader=None)

        item_base.setGLOptions("opaque")
        item_base.setDepthValue(-1.0)
        self.view.addItem(item_base)
        self._item_base_mdt = (item_base)

    def _vertices_com_exagero(self):
        vertices = self._vertices_base.copy()

        if (self.check_sobreposicao.isChecked()
            and self._sobrepor_rasters):

            vertices = (self._deformar_vertices_principais_com_diferenca(vertices))

        vertices[:, 2] *= float(self.spin_exagero.value())

        return vertices

    def _obter_rampa_renderer_qgis(self):
        """
        Obtém a rampa atualmente aplicada ao raster no QGIS.

        Retorna:
            valores, cores RGBA e método de interpolação.

        Retorna None quando o renderizador não puder ser reconhecido.
        """
        renderer = self.raster_layer.renderer()

        if not isinstance(renderer, QgsSingleBandPseudoColorRenderer):
            return None

        try:
            shader = renderer.shader()
            if shader is None:
                return None

            shader_fn = shader.rasterShaderFunction()
            if not isinstance(shader_fn, QgsColorRampShader):
                return None

            itens = shader_fn.colorRampItemList()
            if not itens:
                return None

            valores = []
            cores = []

            for item in itens:
                cor = item.color

                if not cor.isValid():
                    continue

                valores.append(float(item.value))
                cores.append((
                    cor.redF(),
                    cor.greenF(),
                    cor.blueF(),
                    cor.alphaF()))

            if len(valores) < 2:
                return None

            valores = np.asarray(valores, dtype=np.float64)
            cores = np.asarray(cores, dtype=np.float64)

            ordem = np.argsort(valores)
            valores = valores[ordem]
            cores = cores[ordem]

            return valores, cores, shader_fn.colorRampType()

        except Exception:
            return None

